// Tantra 3 — verses 549-883 — scraped from tamilnation.org/mp009a
export const VERSES_T3: Verse[] = [
  {
    id: 550, tantraId: 3, verseNumber: 549,
    tamil: `உரைத்தன வற்கரி ஒன்று மூடிய
நிரைத்த இராசி நிரைமுறை எண்ணிப்
பிரச்சதம் எட்டும் பேசியே நந்தி
நிரைத்த இயமம் நியமஞ்செய் தானே`,
    transliteration: `uraittaṉa vaṟkari oṉṟu mūṭiya
niraitta irāci niraimuṟai eṇṇip
piraccatam eṭṭum pēciyē nanti
niraitta iyamam niyamañcey tāṉē`,
    english: `549: Difficult to Expound is Science of Yoga
Of difficult vast to expound
Is the Science of Breath;
Closing nostril alternate
And counting time in measure appropriate
Thus did Nandi reveal at length
The eight-fold science of yoga great--
Iyama, Niyama and the rest.`,
    elaborationEnglish: `The science of yoga is a vast subject. It is eight-limbed, that is of cight organic parts; and so is known as ashtanga yoga. _ The secret of yoga was revealed by: Nandi (Sadasiva) initially _ to the four sages, Sanaka, Sanatana, Sanatkumara and _ Sanzntana.

Yoga Includes Kavacha, and Mudra

The ways of Yama and Niyama,

The secret of Kavacha, and Mudra

The paths to reach the Samadhi State;

And how Kundalini Sakti courses upward

ag And reaches the thousand petailed lotus in the cranium.

Kk teaches about kavacha, mudra aiid the coursing of ne kundalini energy ‘roi the muladhara to sahasrara in the _ cranium peak through the six adharas within the body. “It is mot enough that there be devotion and an attitude of < to the Deity within oneself, in the heart and the d. It is a significant part of worship to express it bodily for the body too is a participant in the sadhana. For thi there are a number of gestures by movements a F the limbs of the body, as they are termed. These

external movements of the physical body, with hands and fingers, emphasize and affirm the intention of the heart and

‘mind of the worshipper and by constant repetition establish

the idea in the very physical matter of the body. The mudras

are the language in which the body speaks to the ‘Deity.”’

— “Lights on Tantra’’ by M.P. Pandit.`,
    elaborationTamil: `குருநாதராகிய சிவபெருமான் அட்டங்க யோகத்தை அருளத் திருவுள்ளங் கொண்டு தீமையைப் போக்குவதற்கும் (இயமம்) நன்மையைப் பெறுவதற்கும் (நியமம்) வழிவகை செய்தருளி பிராணாயாமம் மூலம் மூச்சுக் காற்றை இழுக்கவும் அடக்கி வைக்கவும் விடவும் வேண்டிய அளவு பன்னிரண்டங்குலம் முதலான பலவகைகளை முறைப்படுத்தி அவற்றை எட்டு அங்கங்களைக் கொண்ட யோகங்களாக அமைத்து அருளினான்.`,
  },
  {
    id: 551, tantraId: 3, verseNumber: 550,
    tamil: `செய்த இயம நியமஞ் சமாதிசென்
றுய்யப் பராசக்தி உத்தர பூருவ
மெய்த கவச நியாசங்கள் முத்திரை
எய்த வுரைசெய்வன் இந்நிலை தானே`,
    transliteration: `ceyta iyama niyamañ camāticeṉ
ṟuyyap parācakti uttara pūruva
meyta kavaca niyācaṅkaḷ muttirai
eyta vuraiceyvaṉ innilai tāṉē`,
    english: `550: Yoga Includes Kavacha Nyasa and Mudra
I shall reveal herein,
The ways of Iyama and Niyama,
The secret of Kavacha, Nyasa and Mudra
The paths to reach the Samadhi State;
To course Kundalini Sakti upward,
And to reach Parasakti at Cranium high.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-550-Third-Tantra-1.-Eight-Parts-of-Yoga.mp3',
    elaborationTamil: `உயிர்கள் தீயவற்றை போக்கி நன்மை தரக்கூடியவற்றே செய்து இறை நினைப்பில் தன்னையே மறந்து சமாதி நிலையை அடைந்து ஆதியிலிருந்தே பரம்பொருளாக இருக்கும் இறைவனை அடைவதற்கு துணையாக கவசம், நியாசம், முத்திரை ஆகிய மூன்று யோகங்கள் முன்னும் பின்னும் பாதுகாப்பாக உடன் வரும். இந்த உயர்ந்த நிலையை உயிர்கள் அடைய வேண்டும் என்பதற்காக இந்த யோக வழிகளைப் பற்றி யாம் கூறுவோம். கவசம் – சமாதி நிலையில் உயிர்களுக்குப் பாதுகாப்பாக உடலை மூடியிருக்கும் கோசங்களை மந்திர ஜபம் செய்து அடக்கியாள்வது. நியாசம் – தமது உடல் உறுப்புகளையே இறைவனது உறுப்புகளாக பாவனை செய்வது. முத்திரை – கை விரல்கள் மூலம் முத்திரைகளை (யோக நிலை எண்ணங்களை கை விரல்கள் மூலம் அபிநயம் செய்து காட்டுதல்) செய்யும் யோக நிலை.`,
  },
  {
    id: 552, tantraId: 3, verseNumber: 551,
    tamil: `அந்நெறி இந்நெறி என்னாதட் டாங்கத்
தன்னெறி சென்று சமாதியி லேநின்மின்
நன்னெறி செல்வார்க்கு ஞானத்தி லேகலாம்
புன்னெறி யாகத்திற் போக்கில்லை யாகுமே`,
    transliteration: `anneṟi inneṟi eṉṉātaṭ ṭāṅkat
taṉṉeṟi ceṉṟu camātiyi lēniṉmiṉ
naṉṉeṟi celvārkku ñāṉatti lēkalām
puṉṉeṟi yākattiṟ pōkkillai yākumē`,
    english: `551: Ashtanga Yoga Leads to Samadhi and to Jnana
Waver not, this way and that
Follow the way of eight-limbed Yoga
And reach Samadhi State;
They who tread that blessed path
Shall reach Jnana's peak;
No more are they in this vile flesh born.`,
    elaborationEnglish: `Yoga is the sure path to jnana or enlightenment. The

enlightened are born no more. Att karmas are forever ended.

Mular identifies samadhi with jnana’ This is similar to Buddhism, where the ultimate which is to be realised in Samadhi is prajna, at which duality disappears and jnana, the essence of the individual merges in the essences of the Universal.`,
    elaborationTamil: `இறைவனை அடைய நாம் செல்லும் வழி நன்றானதா இல்லை வேறு வழி நன்றானதா என்று சந்தேகப் படாமல் எந்த வழிக்கும் தேவைப்படுகின்ற அட்டாங்க யோகங்களின் வழியிலே சென்று சமாதி நிலையில் (இறைவனை நினைத்து தன்னை மறந்திருக்கும் நிலை) இருங்கள். இத்தகைய நல்ல வழியில் செல்பவர்களுக்கு ஞான யோகம் கைகூடிச் சிவப்பேறு அடைவது மட்டுமில்லாமல் அந்த ஞானத்தின் பயனாக இனிப் பிறவி என்பது இல்லை.`,
  },
  {
    id: 553, tantraId: 3, verseNumber: 552,
    tamil: `இயம நியமமே எண்ணிலா ஆதனம்
நயமுறு பிராணாயா மம் பிரத்தி யாகாரஞ்
சயமிகு தாரணை தியானஞ் சமாதி
அயமுறும் அட்டாங்க மாவது மாமே`,
    transliteration: `iyama niyamamē eṇṇilā ātaṉam
nayamuṟu pirāṇāyā mam piratti yākārañ
cayamiku tāraṇai tiyāṉañ camāti
ayamuṟum aṭṭāṅka māvatu māmē`,
    english: `552: Eight Limbs of Yoga
Iyama, Niyama, and Asana numberless
Pranayama wholesome and Pratyahara alike,
Dharana, Dhyana and Samadhi to triumph
--These eight are the steely limbs of Yoga.`,
    elaborationEnglish: `is a preparation for the next. Yoga holds the key to the

attainment of samadhi or the unitive trance.`,
    elaborationTamil: `இமயம், நியமம், மற்றும் பலவகையான ஆசனங்களும், நன்மையைத் தரும் பிராணாயாமமும், பிரத்தியாகாரம், வெற்றி மிக்க தாரணையும், தியானமும், சமாதியும், ஆகிய எட்டுவகைப் பகுதிகளைக் கொண்ட அட்டாங்க யோக வழி முறைகள் நல்வினை உள்ளவர்களுக்குக் கிடைக்கும் நல்வழியாகும். எட்டுப் பகுதிகளைக் கொண்ட அட்டாங்க யோகத்தின் விளக்கம்: முதலாவது இயமம்: தீமைகளைப் போக்குவது. இதில் ஐந்து பிரிவுகள் உள்ளன: மனதாலும், பேச்சாலும், செயலினாலும் எந்த உயிரையும் துன்புறுத்தாமை. மனதாலும், பேச்சாலும், செயலினாலும் பிறர் பொருளைக் களவாடாமை. மனதாலும், பேச்சாலும், செயலினாலும் முழு பிரம்மச்சரியம் கடைப்பிடித்தல். மனதாலும், பேச்சாலும், செயலினாலும் உண்மையைப் பின்பற்றுதல். பிறர் கொடுக்கும் பரிசுகளைப் பெற்றுக் கொள்ளாமை. (ஆசைப் படாமலிருத்தல்) இதனைக் கடைபிடித்தால் நம்மிடமுள்ள அனைத்து தீமைகளும் விலகும். இரண்டாவது நியமம்: நன்மைகளைப் பெறுவது. தவம், ஜபம், சந்தோஷம், தெய்வ நம்பிக்கை, தானம், சிவ விரதம், சித்தாந்தக் கேள்வி, சிவ பூசை, ஞான அறிவு, நாணம், ஆகிய பத்துக் காரியங்களையும் தவறாது மேற்கொள்ளுதல் நியமம் ஆகும். இவற்றை மேற்கொள்ளும்போது ஒளியாகிய சிவத்தையும் அந்த ஒளியின் ஆற்றலாகிய சத்தியை தியானித்தலும் நியமம் ஆகும். மூன்றாவது ஆசனம்: உடலை அமர்த்தும் நிலை. இடுப்பு, தோள்கள், தலை இவற்றை நேராக வைத்து, முதுகுத் தண்டுக்குத் தொந்தரவு கொடுக்காமல் அதற்கு விடுதலை அளித்தல். நான்காவது பிராணாயாமம்: மூச்சைச் சரிவர அடக்கியாளுதல் (பிராணன் என்னும் உயிர்ச் சக்தியை அடக்கியாள்வது) ஐந்தாவது பிரத்தியாகாரம்: மனதை வெளியே புலன்கள் வழி செல்லாது தடுத்து (கண்கள் வழியே தவறானவற்றைப் பார்க்காமலும், காது வழியே தவறானவற்றைக் கேட்காமலும், வாய் வழியாகத் தவறான வார்த்தைகளைப் பேசாமலும், நாக்கின் மூலம் பாதகமான உணவுகளை ருசிக்காமலும், உடல் வழியே தவறானவற்றைச் செய்யாமலும்), மனதை உள்முகமாகத் திருப்பி மனதில் உள்ள அரும்பொருளை அறியச் சிந்தித்தல். ஆறாவது தாரணை: ஒரு பொருளின் மீது மனத்தைக் குவித்தல். தன்னைத்தானே உணர்வது. ஏழாவது தியானம்: மனதை ஒருமுகப்படுத்தி இடைவிடாது சிந்தித்தல். எட்டாவது சமாதி: நமது முயற்சிகள் அனைத்திற்கும் குறிக்கோளான ஞான ஒளியைப் பெறுதல். கடவுளை அடைய விரும்புகின்றவன் உடலாலும், மனத்தாலும், அறத்தாலும் (நற்குணங்களாலும்), ஞானத்தாலும் வலிமை பெற்று இருக்க வேண்டுவது.`,
  },
  {
    id: 554, tantraId: 3, verseNumber: 553,
    tamil: `எழுந்துநீர் பெய்யினும் எட்டுத் திசையுஞ்
செழுந்த ணியமங்கள் செய்மினென் றண்ணல்
கொழுந்தண் பவளக் குளிர்சடை யோடே
அழுந்திய நால்வர்க் கருள்புரிந் தானே`,
    transliteration: `eḻuntunīr peyyiṉum eṭṭut ticaiyuñ
ceḻunta ṇiyamaṅkaḷ ceymiṉeṉ ṟaṇṇal
koḻuntaṇ pavaḷak kuḷircaṭai yōṭē
aḻuntiya nālvark karuḷpurin tāṉē`,
    english: `553: Perform Niyamas Always
"The heavens may torrents pour
In directions eight;
Yet perform the holy niyamas"
--Thus spake the Lord of matted locks, cool and coral hued
To the Sages Four, in devotion immersed.`,
    elaborationEnglish: `1) Santana, Sanatanam, Sanatkumara, Santana—the four rishis taught by Siva in His aspect as Dakshinamurthi (Southward-looking form). The Agamas descended to them from Nandi. They received the title, Nandi, and were included among the nathas (masters).`,
    elaborationTamil: `பவளம் போல் ஜொலிக்கும் குளிர்ந்த சடையுடைய இறைவனை முழுமையாக உணர்ந்த சனகர், சதானந்தர், சனாநந்தர் மற்றும் சனத்குமாரர் ஆகிய நால்வர்களுக்கும் எட்டுத்திசையிலும் சூழ்ந்து மூழ்கும் அளவிற்கு பெருமழை பெய்தாலும் செழுமையான குளிர்ந்த இயமங்களை (பாடல் #552 இல் இயமத்தின் விளக்கம் காண்க) தவறாமல் செய்யுங்கள் என்று இறைவன் கூறினார்.`,
  },
  {
    id: 555, tantraId: 3, verseNumber: 554,
    tamil: `கொல்லான்பொய் கூறான் களவிலான் எண்குணன்
நல்லான் அடக்க முடையான் நடுச்செய்ய
வல்லான் பகுந்துண்பான் மாசிலான் கட்காமம்
இல்லான் இயமத் திடையில்நின் றானே`,
    transliteration: `kollāṉpoy kūṟāṉ kaḷavilāṉ eṇkuṇaṉ
nallāṉ aṭakka muṭaiyāṉ naṭucceyya
vallāṉ pakuntuṇpāṉ mācilāṉ kaṭkāmam
illāṉ iyamat tiṭaiyilniṉ ṟāṉē`,
    english: `554: Ways of Niyama
He does not kill, he does not lie, he does not steal;
Of marked virtues is he; good, meek and just;
He shares his joys, he knows no blemish
Neither drinks nor lusts
--This the man who in Niyama's ways stands.`,
    elaborationEnglish: `The way of iyama consists in number of ‘do’s and

dont’s’—non-killing, not not drinking, not lusting, possessing marked virtues, being good, being just, sharing the good things of life with others, and knowing no blemish. Iyama is the background, the ethical preparation for the onward march on the yoga path.

1) Nachinarkiniyar, the - celebrated commentator of Tholkappiyam, the great classic Tamil grammar, describes the elements of iyamam as five in the foliowing sutra:`,
    elaborationTamil: `எவருக்கும் மனதளவிலும் தீங்கு நினைக்காதவன், பொய் கூறாதவன், களவு (திருடு) செய்யாதவன், எட்டு குணங்களை கொண்டவன் (1. அன்பு, 2. அமைதி, 3. பொறாமையின்மை, 4. சுத்தமாக இருத்தல், 5. மனதினால் சிரமப்படாமல் எதையும் சுலபமாக எடுத்துக் கொள்ளுதல், 6. ஆனந்தத்தைக் கொடுப்பது, 7. தர்ம சிந்தனை, 8. ஆசையின்மை), நன்மை மட்டுமே நினைப்பவன், பணிவுடையவன், நீதி தவறாமல் இருக்கக் கூடியவன், பகிர்ந்து கொடுத்து உண்பவன், குற்றம் இல்லாதவன், கள், காமம் இல்லாத தன்மையுடையவன், ஆகிய இவர்கள் இயம ஒழுக்கத்தின்படி இருப்பவர்கள் ஆவார்கள்.`,
  },
  {
    id: 556, tantraId: 3, verseNumber: 555,
    tamil: `ஆதியை வேதத்தின் அப்பொரு ளானைச்
சோதியை ஆங்கே சுடுகின்ற அங்கியைப்
பாதியுள் மன்னும் பரசக்தி யோடுடன்
நீதி யுணர்ந்து நியமத்த னாமே`,
    transliteration: `ātiyai vētattiṉ apporu ḷāṉaic
cōtiyai āṅkē cuṭukiṉṟa aṅkiyaip
pātiyuḷ maṉṉum paracakti yōṭuṭaṉ
nīti yuṇarntu niyamatta ṉāmē`,
    english: `555: Way of Niyama
The Being First,
The Meaning-Central of Vedas all,
The Light Divine,
The Fire within that Light
He who shares Himself
Half-and-Half with His Sakti
And the Divine Justice thereof
--Them, he in Niyama's path knows.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-555-Third-Tantra-3.-Yoga-of-Penance.mp3',
    elaborationEnglish: `He’ who stands in niyama should have firm faith that the Supreme Being is the First Cause, that He is the central meaning of all Vedas, that He is the Light Divine, that He is the kundalini fire within that Light, and that He and Sakti are inseparable and indivisible, and that there is divine justice in that act of Siva/Sakti oneness.`,
    elaborationTamil: `ஆதியாய் முதற் பொருளானவனை, வேதத்தின் பொருளாக உள்ளவனை, அக்கினி சொரூபமானவனை, அக்கினியின் வெப்பமானவனை, திருமேனியில் சரிபாதியாக பராசத்தியோடு இருக்கும் இறைவனை உணர்ந்து சத்தியத்தை கடைபிடிப்பவனே நியமத்தைக் கடைபிடிப்பவன் ஆவான்.`,
  },
  {
    id: 557, tantraId: 3, verseNumber: 556,
    tamil: `தூய்மை அருளூண் சுருக்கம் பொறைசெவ்வை
வாய்மை நிலைமை வளர்த்தலே மற்றிவை
காமங் களவு கொலையெனக் காண்பவை
நேமியீ ரைந்து நியமத்த னாமே`,
    transliteration: `tūymai aruḷūṇ curukkam poṟaicevvai
vāymai nilaimai vaḷarttalē maṟṟivai
kāmaṅ kaḷavu kolaiyeṉak kāṇpavai
nēmiyī raintu niyamatta ṉāmē`,
    english: `556: Ten Virtues of Niyama
Purity, compassion, frugal food and patience
Forthrightness, truth and steadfastness
--These he ardently cherishes;
Killing, stealing and lusting, He abhors
--Thus stands with virtues ten
The one who Niyama's ways observes.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-556-Third-Tantra-3.-Yoga-of-Penance.mp3',
    elaborationTamil: `தூய்மையாக இருத்தல் 2. இறையருளோடு இருத்தல் 3. அளவான உணவு 4. பொறுமையோடு இருத்தல் 5. நேர்மையுடன் இருத்தல் 6. பொய் பேசாது சத்தியத்தைக் கடைபிடித்தல் 7. சத்தியத்திற்காக வைராக்கியத்தை வளர்த்தல், 8. காமத்தை எண்ணாதிருத்தல் 9. களவு (திருடு) எண்ணாமலிருத்தல் 10. கொலை எண்ணாமலிருத்தல் ஆகிய பத்து குணங்களையும் கொண்டவரே நியமத்தின் வழியின்படி இருப்பவர்.`,
  },
  {
    id: 558, tantraId: 3, verseNumber: 557,
    tamil: `தவஞ்செபஞ் சந்தோடம் ஆத்திகந் தானஞ்
சிவன்றன் விரதமே சித்தாந்தக் கேள்வி
மகஞ்சிவ பூசையொண் மதிசொல்லீர் ஐந்து
நிவம்பல செய்யின் நியமத்த னாமே`,
    transliteration: `tavañcepañ cantōṭam āttikan tāṉañ
civaṉṟaṉ viratamē cittāntak kēḷvi
makañciva pūcaiyoṇ maticollīr aintu
nivampala ceyyiṉ niyamatta ṉāmē`,
    english: `557: Further Ten Attributes of Niyama
Tapas, meditation, serenity, and holiness
Charity, vows in Saiva Way and Siddhanta learning
Sacrifice, Siva puja and thoughts pure
--With these ten, the one in Niyama perfects his Ways.`,
    elaborationTamil: `தவம் செய்தல், 2. ஜெபித்தல், 3. பேரின்பம் அடைதல், 4. தெய்வ நம்பிக்கையோடிருத்தல், 5. தானம் செய்தல், 6. சிவ விரதம் கடைபிடித்தல், 7. ஞானத்தைப் பற்றிய உண்மையைக் கேட்டறிதல், 8. யாகம் செய்தல், 9. சிவ பூஜை செய்தல், 10. எண்ணத்தையும் இறைவனையும் இரண்டறக் கலத்தல் ஆகிய பத்தையும் உணர்ந்து பிறருக்குக் அறியக் கூறவும் செய்பவனே நியமத்தின் வழி நடப்பவனாவான்.`,
  },
  {
    id: 559, tantraId: 3, verseNumber: 558,
    tamil: `பங்கய மாதி பரந்தபல் ஆதனம்
அங்குள வாம்இரு நாலும் அவற்றினுள்
சொங்கில்லை யாகச் சுவத்திக மெனமிகத்
தங்க இருப்பத் தலைவனு மாமே`,
    transliteration: `paṅkaya māti parantapal ātaṉam
aṅkuḷa vāmiru nālum avaṟṟiṉuḷ
coṅkillai yākac cuvattika meṉamikat
taṅka iruppat talaivaṉu māmē`,
    english: `558: Prominent Asanas
Numerous are the asanas
With Padmasana to commence;
Six among them are rated high
With Svastika as faultless seventh
He who postures on these asanas seven,
Verily becomes Master, for sure.`,
    elaborationEnglish: `The next step is the practice of asana or bodily postures. These asanas are numerous. But seven among them are basic. These seven are: 2)gomukha; 3)padma; 4)simha; 5)swastika; 6)vira; and 7)sukha. He who perfects these postures verily becomes the master. The four following mantras describe four of the asanas in detail. Asanas are postures practised for “’health and lightness of body.”’ They give ‘”drdhata or strength” — vide Hatha Yoga Pradipika, i.ii.

Tholkappiyam: Nachinarkiniyar commentary’, op. cit. Svastikasana is described thus in Siva Samhita, 95- Place the soles of the feet completely under the thighs, the body straight and sit at ease.....”” This is also called asana (the easy posture).

Compare Gheranda Samhita, ii, 13: ‘Drawing the legs on thighs together and placing the feet-between them, the body

in its easy condition and sitting straight. This posture is called

Compare Hatha Yoga Pradipika, i, 21: “’Having kept the feet between the knees and the thighs, with body straight when one sits calmly, it is called svastikasana.”’`,
    elaborationTamil: `பத்மாசனம் முதல் பல ஆசனங்கள் உள்ளன. அவற்றுள் எட்டு ஆசனங்கள் முக்கியமானவை ஆகும். அந்த எட்டில் முதலானது சுவத்திகாசனம் ஆகும் (இதை சுகாசனம் என்றும் கூறுவர்). இதைத் தவறாமல் தினம் செய்து உணர்ந்து இருப்பவர் எட்டு ஆசனங்களின் தலைவராவார்.`,
  },
  {
    id: 560, tantraId: 3, verseNumber: 559,
    tamil: `ஓரணை யப்பத மூருவின் மேலேறிட்
டார வலித்ததன் மேல்வைத் தழகுறச்
சீர்திகழ் கைகள் அதனைத்தன் மேல்வைக்கப்
பார்திகழ் பத்மா சனமென லாகுமே`,
    transliteration: `ōraṇai yappata mūruviṉ mēlēṟiṭ
ṭāra valittataṉ mēlvait taḻakuṟac
cīrtikaḻ kaikaḷ ataṉaittaṉ mēlvaikkap
pārtikaḻ patmā caṉameṉa lākumē`,
    english: `559: Padmasana--Lotus Posture
Sit cross-legged with soles of feet upturned
Close draw the feet on thighs opposite,
Stretch then the hands afore on feet
That Padmasana is, famed far on earth.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-559-Third-Tantra-4.-Yoga-of-Poses.mp3',
    elaborationTamil: `ஒரு பக்க காலை எடுத்து மறு பக்க காலின் மேல் அணைத்து வைத்து அது போலவே இன்னொரு பக்க காலையும் செய்து அமர்ந்து அழகாக கைகள் இரண்டையும் மேல் நோக்கி மலர்த்தி இரு தொடைகளின் மேல் வைத்து அமர்ந்திருப்பதே உலகம் புகழும் பத்மாசனம் ஆகும். பாடலில் உள்ளவாறு பத்மாசனம் செய்யும் முறை: முதுகை நேராக வைத்துத் தரையில் இரண்டு கால்களையும் நீட்டி அமர்ந்து கொள்ளவும். இடது காலை மடக்கி இடது பாதத்தை வலது தொடையின் மேல் வைக்கவும். வலது காலை மடக்கி வலது பாதத்தை இடது தொடையின் மேல் வைக்கவும். இரண்டு கைகளையும் நேராக நீட்டி இரண்டு கால்களின் மடங்கிய முட்டியின் மேல் வைக்கவும். உள்ளங்கைகள் இரண்டையும் மேல் நோக்கித் திருப்பி ஆட்காட்டி விரலை மடக்கி கட்டை விரலால் பிடித்துக்கொள்ளவும்.`,
  },
  {
    id: 561, tantraId: 3, verseNumber: 560,
    tamil: `துரிசில் வலக்காலைத் தோன்றவே மேல்வைத்து
அரிய முழந்தாளி லங்கையை நீட்டி
உருசி யொடுமுடல் செவ்வே யிருத்திப்
பரிசு பெறுமது பத்திரா சனமே`,
    transliteration: `turicil valakkālait tōṉṟavē mēlvaittu
ariya muḻantāḷi laṅkaiyai nīṭṭi
uruci yoṭumuṭal cevvē yiruttip
paricu peṟumatu pattirā caṉamē`,
    english: `560: Bhadrasana--Happy Posture
Place the right leg over the left
Stretch the hands over calf of leg
Sit in posture firm and erect
That indeed is Bhadrasana.`,
    elaborationEnglish: `Compare Hatha Yoga Pradipika, i, 55-7: ‘’Place the heels on either side seam of the scrotum, keeping the left hecl on the left side, and the right on the right side; hold the feet firmly joined to’ one another with both the hands. This bhadrasana is the destroyer of all diseases.”

Compare Gheranda Samhita, ii,9-10: ‘’Place the heels crosswise under the testes attentively; cross the hands behind the back and take hold of the toes of the feet. Fix the gaze on the tip of the nose....’’`,
    elaborationTamil: `குற்றமில்லாத வலது காலை மேலே தெரியும்படி வைத்து அருமையான கால் முட்டிகளில் இரண்டு கைகளையும் நீட்டி வைத்து தளர்ந்து இருக்கும் உடம்பை நேராக்கி நிமிர்ந்து அமர்ந்து அதனால் ஏற்படும் பயன்களைப் பெறுவதே பத்திராசனம் ஆகும். பத்திராசனம் செய்யும் முறை: முதலில் கால்களை நீட்டி அமரவும். பின்னர் முடிந்தளவு கால்களை அகட்டி கைகளை முன் பக்கம் ஊன்றி அப்படியே குதிகால்களில் அமர்ந்து கால் விரல்களை உயர்த்திக் கொள்ளவும். பத்திராசனத்தின் பயன்கள்: மனதை ஒருமுகப்படுவதற்கு இந்த ஆசனம் உதவும். தியானம் பழக ஏற்ற ஆசனம் இது.`,
  },
  {
    id: 562, tantraId: 3, verseNumber: 561,
    tamil: `ஒக்க அடியிணை யூருவில் ஏறிட்டு
முக்கி யுடலை முழங்கை தனில்ஏற்றித்
தொக்க அறிந்து துளங்கா திருந்திடிற்
குக்குட ஆசனங் கொள்ளலு மாமே`,
    transliteration: `okka aṭiyiṇai yūruvil ēṟiṭṭu
mukki yuṭalai muḻaṅkai taṉilēṟṟit
tokka aṟintu tuḷaṅkā tiruntiṭiṟ
kukkuṭa ācaṉaṅ koḷḷalu māmē`,
    english: `561: Kukkudasana--Cock Posture
Lift the feet on to the thighs,
Control breath and on elbows raise your body
Thus seated firm and immobile,
Thou do reach the Kukkudasana.`,
    elaborationEnglish: `Kukkudasana is the ‘cock’ posture. The feet are lifted onto

the thighs, -and controlling the breath, the body: is raised on the elbows; and a firm, immobile sitting position is taken. (This asana, however, is not included by Tirumular in his list of seven important asanas. Istead he mentions the gomukha asana. However he describes the kukudasana, - but hot the gomukha asana.)

Compare Hatha Yoga Pradipika, i, 25: “Taking the posture of padmasana and carrying the hands between the knee and the thighs, when the yogi raises himself above the ground, with palms resting on the ground, it becomes kukudasana.”’

Compare Gheranda Samhita, ii,31; ‘‘Sitting on the ground, cross the legs in the padmasana posture, thrust down the hands the thighs and the knees, stand on the hands, supporting the body on the elbows. This is called the kukudasana.”’

Although Tirumular describes this asana, he does not refer to it as one of the seven important asanas. There instead he mentions ‘gomukha,’ which he does not describe.`,
    elaborationTamil: `பத்மாசனத்தில் உள்ளது போல் பாதங்கள் இரண்டையும் தொடையின் மேல் மாற்றி வைத்து கைகள் இரண்டையும் அத்தொடைகளின் இடைவெளியில் நுழைத்துத் தரையில் ஊன்றி முக்கிக் கொண்டு உடம்பின் பாரத்தைக் கைகளில் தாங்கி உடலைத் தூக்கி நிறுத்தி அசையாமல் இருப்பதே குக்குட ஆசனம் செய்யும் முறை ஆகும். குக்குட ஆசனத்தின் பலன்கள்: தியானம் மற்றும் யோக வழிகளில் செல்பவர்களுக்கு ஏற்படும் செரிமானப் பிரச்சினைகளை சரிசெய்து வயிற்றில் ஏற்படும் சூட்டையும் தணிக்க குக்குட ஆசனம் உதவும்.`,
  },
  {
    id: 563, tantraId: 3, verseNumber: 562,
    tamil: `பாத முழந்தாளிற் பாணி களைநீட்டி
ஆதர வோடும்வாய் அங்காந் தழகுறக்
கோதில் நயனங் கொடிமூக்கி லேயுறச்
சீர்திகழ் சிங்கா தனமெனச் செப்புமே`,
    transliteration: `pāta muḻantāḷiṟ pāṇi kaḷainīṭṭi
ātara vōṭumvāy aṅkān taḻakuṟak
kōtil nayaṉaṅ koṭimūkki lēyuṟac
cīrtikaḻ ciṅkā taṉameṉac ceppumē`,
    english: `562: Simhasana-Lion Posture
Stretch the hands over the calf of leg,
Lift the mouth upward,
Fix thy gaze on tip of nose,
Thus do thou Simhasana posture.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-562-Third-Tantra-4.-Yoga-of-Poses.mp3',
    elaborationEnglish: `Simhasana is the ‘lion’ posture. The hands are stretched over the calves of the legs, the chin is lifted upward, and the gaze is fixed on the tip of the nose.

Compare. Hatha Yoga Pradipika, i, 52-54: ‘‘Press the heels on both sides of the seam of the scrotum in such a. away that the left heel touches the right side, and the right heel touches the left side. Place the hands on the knees, with stretched fingers and keeping the mouth open and the mind

collected, gaze on the tip of the nose. This is simhasana, held sacred by the best of yogis.”

Compare Gheranda Samhita, ii, 14-15: two heels to be placed under the scrotum contrariwise, and turned upwards, the knees to be placed on the ground, and the hands placed on the knees, mouth to be kept open..... and gaze fixed on the nose. This is simhasana, destroyer of all diseases.”`,
    elaborationTamil: `பாத நுனிகள் தரையில் அழுந்தும்படி வைத்து முழந்தாளிட்டு காலின் மேல் அமர்ந்து கைகளை பின்புறமாக பாதங்களில் படும்படி நீட்டி வைத்து ஆதரவாக இருக்க வாயை ஆவெனப் பிளந்து கொண்டு அழகாக கண்களை வேறெங்கும் சுழற்றாமல் மூக்கின் நுனியை நோக்கி பார்த்துக் கொண்டு இருப்பது புகழ் பெற்ற சிங்காசனம் என்று கூறப்படும். சிங்காசனம் ஆசனத்தின் பயன்கள்: நன்கு பசியெடுக்கும். முகதாடை நாக்கு தொண்டையை ஒட்டிய நாக்கின் தொடக்கப்பகுதி ஆகியவற்றிற்கு நன்கு பயிற்சி கிடைக்கிறது. கண்களுக்கு நல்ல கூர்மையான நோக்கும் சக்தி கிடைக்கிறது. காது, மூக்கு தொண்டைக்கு ஆரோக்கியம் கிடைக்கிறது. வயிற்றில் ஜீரண சுரப்பிகள் வேலை செய்யும். நாக்கை வெளியில் இழுப்பதால் தொண்டை மூக்கில் சுத்த ரத்தம் பாயும். உணவு நன்கு ஜீரணமாகும். நாக்கை வெளியில் நீட்டுவதால் நரம்புகள் இழுக்கப்பட்டு தாடைகள் இறுக்கம் குறைந்து பலப்படுகின்றன. விக்கல் வியாதி தடுக்கப்படுகிறது. சிங்காசனத்தை தொடர்ந்து செய்து பழகிய பின் முழங்கால் தொடை சதைபிடிப்பு நீங்கி பலமுள்ளதாக ஆகின்றன. தன்னுள் சிங்கத்தின் பலம் வருவது போல பாவனை செய்தால் எல்லா அங்கங்களும் வலிமை பெற்றுவிடும். இவ்வாறு தியானம் செய்தால் மன உறுதி கிடைக்கும். சக்தி பெருகும்.`,
  },
  {
    id: 564, tantraId: 3, verseNumber: 563,
    tamil: `பத்திரங் கோமுகம் பங்கயங் கேசரி
சொத்திரம் வீரஞ் சுகாதனம் ஓரேழு
முத்தம மாமுது ஆசனம் எட்டெட்டுப்
பத்தொடு நூறு பலஆ சனமே`,
    transliteration: `pattiraṅ kōmukam paṅkayaṅ kēcari
cottiram vīrañ cukātaṉam ōrēḻu
muttama māmutu ācaṉam eṭṭeṭṭup
pattoṭu nūṟu palaā caṉamē`,
    english: `563: Important Asanas are Seven
Bhadra, Gomukha, Padma and Simha,
Svastika, Veera, and Sukha
These seven are asanas eminent and ancient;
Numerous as, eight, eighty and hundred, however,
Are asanas in all reckoned.`,
    elaborationTamil: `பத்திரம் (பத்திராசனம்) 2. கோமுகம் (கோமுகாசனம்) 3. பங்கயம் (பத்மாசனம்) 4. கேசரி (சிங்காசனம்) 5. சொத்திரம் (குக்குட ஆசனம்) 6. வீரம் (வீராசனம்) 7. சுகாதனம் ஆகிய ஏழு ஆசனங்களோடு மிகவும் சிறப்பான சுவத்திகாசனம் சேர்த்து எட்டு ஆசனங்கள் இறைவனை அடைய உதவும் அட்டங்க யோகத்திற்கு முக்கியமானவை ஆகும். மற்ற ஆசனங்கள் எட்டும் சேர்ந்து பதினாறு அவற்றோடு நூற்றிப் பத்தும் சேர்ந்து மொத்தம் 126 ஆசனங்கள் உள்ளது.`,
  },
  {
    id: 565, tantraId: 3, verseNumber: 564,
    tamil: `ஐவர்க்கு நாயகன் அவ்வூர்த் தலைமகன்
உய்யக்கொண்டேறுங் குதிரைமற் றொன்றுண்டு
மெய்யர்க்குப்பற்றுக்கொடுக்குங் கொடாதுபோய்ப்
பொய்யரைத் துள்ளி விழுத்திடுந் தானே`,
    transliteration: `aivarkku nāyakaṉ avvūrt talaimakaṉ
uyyakkoṇṭēṟuṅ kutiraimaṟ ṟoṉṟuṇṭu
meyyarkkuppaṟṟukkoṭukkuṅ koṭātupōyp
poyyarait tuḷḷi viḻuttiṭun tāṉē`,
    english: `564: Master the Steed of Breath
The Jiva is the master of senses five;
He is the head of the body habitat;
There is a steed he rides to his destined goal;
The masterly one the steed carries,
The feeble one it throws away
--That steed the Prana breath is.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-564-Third-Tantra-5.-Yoga-of-Breath-Control.mp3',
    elaborationTamil: `உடலின் ஐம்புலன்களான 1. பார்த்தல், 2. கேட்டல், 3. முகர்தல், 4. சுவைத்தல், 5. தொடு உணர்ச்சி ஆகிய ஐந்து புலன்களையும் வைத்துள்ள உடம்பின் தலைவனாக இருக்கக்கூடிய ஆத்மாவானது இறைவனை அடைய மேல் நிலைக்கு செல்ல மனதுடன் மூச்சுக்காற்று ஒன்று உள்ளது, அந்த மூச்சுக்காற்று பயிற்சி செய்து உண்மையான இறைவனை அடைய எண்ணம் கொண்டோர்க்கு மனதை ஒருநிலைப்படுத்த நன்கு உதவும். இறைவுணர்வு இல்லாமல் தேவையில்லாதவறை நினைத்துக் கொண்டு இருப்பவர்களுக்கு மூச்சுக்காற்று அடங்காமல் அவர்களை கீழ் நிலைக்கு கொண்டு செல்லும்.`,
  },
  {
    id: 566, tantraId: 3, verseNumber: 565,
    tamil: `ஆரிய னல்லன் குதிரை இரண்டுள
வீசிப் பிடிக்கும் விரகறி வாரில்லை
கூரிய நாதன் குருவின் அருள்பெற்றால்
வாரிப் பிடிக்க வசப்படுந் தானே`,
    transliteration: `āriya ṉallaṉ kutirai iraṇṭuḷa
vīcip piṭikkum virakaṟi vārillai
kūriya nātaṉ kuruviṉ aruḷpeṟṟāl
vārip piṭikka vacappaṭun tāṉē`,
    english: `565: Control of Inhalation and Exhalation
A goodly one is Jiva
He has steeds two,
But he knows not how to master them
If the lordly Guru lends His Grace,
The steeds will tame become.`,
    elaborationEnglish: `In fact, he has two steeds to master, the idakala and pingla

breaths that run in the left and right nostrils. It is by the grace of the Guru that he can attain mastery over them.`,
    elaborationTamil: `மனம் என்னும் ஆரியன் மிகவும் நல்லவன் அவனிடம் இடகலை ( மூக்கின் இடது நாசி துவாரத்தின் வழியே நடைபெறும் சுவாசம் இடகலை எனப்படும்) பிங்கலை (மூக்கின் வலதுநாசி துவாரத்தின் வழியே நடைபெறும் சுவாசம் பிங்கலை எனப்படும்) என இரண்டு சுவாசங்கள் உள்ளது. அந்த சுவாசத்தை வெளியே விட்டு உள்ளே நிறுத்தி வைக்கும் திறமையை அறிபவர் யாரும் இல்லை. சீடனைப் பற்றி அனைத்தும் அறிந்த குருவின் அருள் பெற்றால் இடகலை, பிங்கலை ஆகிய இரண்டு சுவாசங்களையும் அடக்கி மனதை ஒருநிலைப்படுத்தி நிலையாக வைக்கலாம்.`,
  },
  {
    id: 567, tantraId: 3, verseNumber: 566,
    tamil: `புள்ளினும் மிக்க புரவியை மேற்கொண்டாற்
கள்ளுண்ண வேண்டாந் தானே களிதருந்
துள்ளி நடப்பிக்குஞ் சோம்பு தவிர்ப்பிக்கும்
உள்ளது சொன்னோம் உணர்வுடை யோருக்கே`,
    transliteration: `puḷḷiṉum mikka puraviyai mēṟkoṇṭāṟ
kaḷḷuṇṇa vēṇṭān tāṉē kaḷitarun
tuḷḷi naṭappikkuñ cōmpu tavirppikkum
uḷḷatu coṉṉōm uṇarvuṭai yōrukkē`,
    english: `566: Breath Control Activates Body
Faster than bird that steed flies,
Far headier than wine the pleasure it gives;
It infuses vigour, dispells laziness
True we say this, let the wise listen.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-566-Third-Tantra-5.-Yoga-of-Breath-Control.mp3',
    elaborationTamil: `பறவையை விட வேகமாகச் செல்லக்கூடிய சுவாசத்தை பிராணாயாம் செய்து தலையிலுள்ள சகஸ்ரதளத்தை நோக்கி எடுத்துச் சென்றால் கள் (போதைப்பொருள்) அருந்தாமலேயை மனம் மகிழ்ச்சி (தன்னை மறந்த நிலை) அடையும். உடல் சுறுசுறுப்புடன் இருக்கும். உடல் சோர்வு நீங்கும். இறைவனை உணர வேண்டும் என்ற எண்ணம் உள்ளவர்களுக்கே இந்த உண்மையை கூறுகிறோம்.`,
  },
  {
    id: 568, tantraId: 3, verseNumber: 567,
    tamil: `பிராணன் மனத்தொடும் பேரா தடங்கிப்
பிராண னிருக்கிற் பிறப்பிறப் பில்லை
பிராணன் மடைமாறிப் பேச்சறி வித்துப்
பிராண னடைபேறு பெற்றுண்டீர் நீரே`,
    transliteration: `pirāṇaṉ maṉattoṭum pērā taṭaṅkip
pirāṇa ṉirukkiṟ piṟappiṟap pillai
pirāṇaṉ maṭaimāṟip pēccaṟi vittup
pirāṇa ṉaṭaipēṟu peṟṟuṇṭīr nīrē`,
    english: `567: Breath Control Yields Life-Nectar
Let Prana merge in Mind
And together the two be stilled
Then no more shall birth and death be;
Therefore, learn to direct breath
In streams alternating left and right
Then shall you taste the nectar of life.`,
    elaborationEnglish: `In streams alternating left -and right Then shall you taste the nectar of life.`,
    elaborationTamil: `பிராணாயாமத்தின் மூலமாக சுவாசத்தையும் மனத்தையும் ஒன்றாக சேர்த்து ஒரு நிலைப்படுத்தி மூச்சுக்காற்றை இடகலை பிங்கலை ஆகிய இரண்டு சுவாசத்தின் வழியாகச் செலுத்தி சமாதி நிலையை (தன்னை மறந்த நிலை) அடைந்தால் இனி வேறு பிறப்பின்றி பிராணாயாமத்தினால் அடையக்கூடிய பலன்கள் அனைத்தையும் பெற்று இன்புற்று இருப்பீர்கள். குறிப்பு: மூக்கின் இடது நாசி துவாரத்தின் வழியே நடைபெறும் சுவாசம் இடகலை எனப்படும். மூக்கின் வலதுநாசி துவாரத்தின் வழியே நடைபெறும் சுவாசம் பிங்கலை எனப்படும்.`,
  },
  {
    id: 569, tantraId: 3, verseNumber: 568,
    tamil: `ஏறுதல் பூரகம் ஈரெட்டு வாமத்தால்
ஆறுதல் கும்பம் அறுபத்து நாலதில்
ஊறுதல் முப்பத் திரண்டதி ரேசகம்
மாறுதல் ஒன்றின்கண் வஞ்சக மாமே`,
    transliteration: `ēṟutal pūrakam īreṭṭu vāmattāl
āṟutal kumpam aṟupattu nālatil
ūṟutal muppat tiraṇṭati rēcakam
māṟutal oṉṟiṉkaṇ vañcaka māmē`,
    english: `568: Puraka Kumbhaka Resaka Alternated--Cleansing of Nadis
Purakam is to inhale by left nostril matras six and ten
Kumbhakam is to retain that breath for matras four and sixty
Resakam is to exhale thereafter for matras two and thirty
Thus alternate from left to right and right to left
With Kumbhakam in between.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-568-Third-Tantra-5.-Yoga-of-Breath-Control.mp3',
    elaborationEnglish: `Inhalation of 16 matras of breath by the left nostril is

purakam. Retention of 64 mantras of breath thus inhaled is kumbakam. Exhalation of 32 matras is rechakam. Thus in pranayama the breath is inhaled and exhaled from left to right and back from right-to left with retention in between. A matra is a specific time duration.

1)Matra is a measure in time approximating a second, Vachaspati in his gloss on ‘‘Yoga Sutras of Patanjali’’ says, “A matra is the time which is taken up by thrice turning up one’s hand over one’s knee, and then snapping the fingers once.."— “Yoga Sutras of Patanjali,’’ ii, as quoted in ‘Hatha Yoga, *’ by Theos Bernard, p.56 n.

2}According to Yogacharya Shantikumar, this is one of the two methods for cleaning. the subtle channels of breath—through bija. The aspirant should adopt the lotus posture and concentrate on vayu-bija which has the colour of smoke. He should then breathe in through the left nostril for 16 counts, and hold the breath for 64 counts. Then he should exhale through the right nostril for 32 counts. Then he should meditate on fire-bija and breath in through the Tight nostril and go through the round as-he did previously with the left. Thus he should alternate breathing through left and right.

Breath Control Makes Body Light as Carpenter -Bee

Tf you control the breath within,

Young and crystal-hard it turns

And with the goodly Guru’s benign Grace, Well may you become lighter than air.`,
    elaborationTamil: `ஒரு மடங்கு அளவு (பதினாறு வினாடிகள்) காற்றை இடது மூக்குத்துவாரத்தின் வழியாக இழுத்தல் பூரகம் ஆகும். அந்த மூச்சுக்காற்றை உள்ளுக்குள்ளேயே நான்கு மடங்கு அளவு (அறுபத்து நான்கு வினாடிகள்) அடக்கி வைத்திருத்தல் கும்பகம் ஆகும். அப்படி அடக்கிய மூச்சுக்காற்றை இரண்டு மடங்கு அளவு (முப்பத்து இரண்டு வினாடிகள்) வலது மூக்குத்துவாரத்தின் வழியாக மெல்ல வெளியே விடுதல் இரேசகம் ஆகும். இவ்வாறு செய்வதே பிராணாயமம் செய்யும் வழிமுறையாகும். பிராணாயாமத்தை இவ்வாறு சரியாகச் செய்வதால் உடல் தூய்மை பெற்று ஆற்றல் மிகுந்து நற்பண்புகள் கைகூடும். இவ்வாறு செய்யாமல் வலது மூக்குத்துவாரத்தின் வழியாக முதலில் இழுத்து இடது மூக்குத்துவாரத்தின் வழியாக மாற்றி விடுதல் கெடுதல் ஆகும். குறிப்பு: பிராணாயாமம் செய்ய ஆரம்பிக்கும் போது முதலில் இடது பக்கம் முதலில் மூச்சுக் காற்றை இழுத்து வலது பக்கம் மூக்குத் துவாரத்தின் வழியாக மாற்றி விட்டு பயிற்சி செய்ய வேண்டும். முதலில் வலது பக்கம் முதலில் மூச்சுக் காற்றை இழுத்து இடது பக்கம் மூக்குத்துவாரத்தின் வழியாக மாற்றி விட்டு பயிற்சி செய்தால் உடலுக்கு தீங்கு உண்டாகும்.`,
  },
  {
    id: 570, tantraId: 3, verseNumber: 569,
    tamil: `வளியினை வாங்கி வயத்தில் அடக்கில்
பளிங்கொத்துக் காயம் பழுக்கினும் பிஞ்சாந்
தௌியக் குருவின் திருவருள் பெற்றால்
வளியினும் வேட்டு வளியனு மாமே`,
    transliteration: `vaḷiyiṉai vāṅki vayattil aṭakkil
paḷiṅkottuk kāyam paḻukkiṉum piñcān
tauiyak kuruviṉ tiruvaruḷ peṟṟāl
vaḷiyiṉum vēṭṭu vaḷiyaṉu māmē`,
    english: `569: Breath Control Makes Body Light as a Carpenter-Bee
If you control the breath within,
However old your body,
Young and crystal-hard it turns
And with the goodly Guru's benign Grace,
Well may you wing your way in heaven
As unto a carpenter-bee.`,
    elaborationTamil: `பாடல் #568 இல் உள்ள பிராணாயம முறைப்படி மூச்சுக்காற்றை வயிற்றில் அடக்கி வைத்திருந்தால் உடம்புக்கு அதன் வயதுக்கு ஏற்ப ஏற்படும் முதுமை வெளியே தெரிந்தாலும் உள்ளே முதுமைத் தன்மை சிறிதும் இல்லாமல் இளமையாக பளிங்கு போன்ற வலிமைப் பெற்று இருக்கும். அந்த உணர்வு தெளிவை பெற்று ஞான குருவின் அருளையும் பெற்றுவிட்டால் காற்றைவிட இலேசாகி மிதக்கும் நிலையை உடல் பெற்றுவிடும்.`,
  },
  {
    id: 571, tantraId: 3, verseNumber: 570,
    tamil: `எங்கே இருக்கினும் பூரி இடத்திலே
அங்கே யதுசெய்ய ஆக்கைக் கழிவில்லை
அங்கே பிடித்தது விட்டள வுஞ்செல்லச்
சங்கே குறிக்கத் தலைவனு மாமே`,
    transliteration: `eṅkē irukkiṉum pūri iṭattilē
aṅkē yatuceyya ākkaik kaḻivillai
aṅkē piṭittatu viṭṭaḷa vuñcellac
caṅkē kuṟikkat talaivaṉu māmē`,
    english: `570: Breath Control Gives Supreme Strength
Wherever you be, there control breath
The body then will perish not
As you inhale, control and exhale in measure prescribed,
Well may you become a trimphant Lord
With the conch of victory,
Your achievement heralding.`,
    elaborationEnglish: `Practise pranayama in prescribed measure wherever you are. The body will not perish. You will become a triumphant lord, the conch of victory heralding your achievement.`,
    elaborationTamil: `எந்த இடத்தில் இருந்தாலும் அந்த இடத்திலேயே பிராணாயாம முறைப்படி (பாடல் #568 இல் உள்ளபடி) இடது மூக்குத்துவாரத்தின் வழியாக மூச்சுக்காற்றை இழுத்து பூரகத்தை செய்தால் உடலுக்கு அழிவு இல்லை. அப்படி இழுத்த மூச்சுக்காற்றை கும்பக முறைப்படி அடக்கி வைத்து இரேசக முறைப்படி அளவாக வெளியே விட்டால் உள்ளுக்குள் ஓங்காரமாகிய ஓம் எனும் ஒலி கேட்டு மேன்மையை அடையலாம்.`,
  },
  {
    id: 572, tantraId: 3, verseNumber: 571,
    tamil: `ஏற்றி இறக்கி இருகாலும் பூரிக்குங்
காற்றைப் பிடிக்குங் கணக்கறி வாரில்லை
காற்றைப் பிடிக்குங் கணக்கறி வாளர்க்குக்
கூற்றை யுதைக்குங் குறியது வாமே`,
    transliteration: `ēṟṟi iṟakki irukālum pūrikkuṅ
kāṟṟaip piṭikkuṅ kaṇakkaṟi vārillai
kāṟṟaip piṭikkuṅ kaṇakkaṟi vāḷarkkuk
kūṟṟai yutaikkuṅ kuṟiyatu vāmē`,
    english: `571: Knowledge of Science of Breath Leads to Immortality
Inhalation, Exhalation, and Retention both ways
The Science of Breath thus consisting
They know not;
They who know the Science of Breath
Are destined to spurn the God of Death.`,
    elaborationTamil: `பிராணாயம முறைப்படி (பாடல் #568 இல் உள்ளபடி) பூரக முறையில் மூச்சுக்காற்றை இடது மூக்குத்துவாரத்தின் வழியாக இழுத்து இரேசக முறையில் வலது மூக்குத்துவாரத்தின் வழியாக மெல்ல வெளியே விட்டு கும்பக முறையில் வயிற்றில் அடக்கி வைத்திருக்கும் அளவுகளைத் தெரிந்தவர்கள் யாரும் இல்லை. அவ்வாறு மூன்று முறைகளின்படி மூச்சுக்காற்றை இழுத்து அடக்கி வெளியே விடும் அளவுகளைத் தெரிந்தவர்களுக்கு எமனையே காலால் எட்டி உதைக்கும் ஆற்றல் உண்டாகும்.`,
  },
  {
    id: 573, tantraId: 3, verseNumber: 572,
    tamil: `மேல்கீழ் நடுப்பக்க மிக்குறப் பூரித்துப்
பாலாம் இரேசகத் தாலுட் பதிவித்து
மாலாகி யுந்தியுட் கும்பித்து வாங்கவே
ஆலாலம் உண்டான் அருள்பெற லாமே`,
    transliteration: `mēlkīḻ naṭuppakka mikkuṟap pūrittup
pālām irēcakat tāluṭ pativittu
mālāki yuntiyuṭ kumpittu vāṅkavē
ālālam uṇṭāṉ aruḷpeṟa lāmē`,
    english: `572: Effect of Puraka, Kumbhaka Resaka
In Purakam inhale breath deep
To pervade up, down and middle
In Kumbhakam retain it around the navel center;
In Resakam it is absorbed within in due measure
They who practise the Science of Breath thus
Reach the Grace of Lord
Who consumed poison deadly.`,
    elaborationEnglish: `The purakam breath is inhaled deeply so that it pervades the

upper, lower and middle regions of the body within. In kumbhakam, it is retained around the navel centre. In rechakam, it is absorbed within in due measure. Those who practise pranayama thus reach the grace of the Lord who swallowed the deadly poison.`,
    elaborationTamil: `தலை, கண், காதுகள், கழுத்து வரை உள்ளவை மேல் பகுதியாகும். 2. கழுத்திலிருந்து அடிவயிறு வரை, நெஞ்சு, தொப்புள் முதலானவை நடுப் பகுதியாகும். 3. அடிவயிறு முதல் கால் பெருவிரல் வரை உள்ளவை கீழ் பகுதியாகும். பிராணாயாம முறைப்படி (பாடல் #568 இல் உள்ளபடி) மூச்சுக்காற்றை பூரக முறைப்படி உள்ளிழுத்து அந்தக் காற்றை கும்பக முறைப்படி உள்ளே அடக்கிவைத்து மேலே கூறிய மூன்று பகுதிகளுக்கும் அந்த மூச்சுக்காற்றைச் செலுத்தி அந்த மூன்று பகுதிகளுக்குள் வியாபிக்க (நிறைத்து) வைத்திருந்தால் நாம் செய்யும் தீய செயல்களால் வரும் கர்ம வினையாகிய நஞ்சை அழித்து நம்மைக் காப்பாற்றும். சிவபெருமானின் அருளைப் பெறலாம்.`,
  },
  {
    id: 574, tantraId: 3, verseNumber: 573,
    tamil: `வாமத்தில் ஈரெட்டு மாத்திரை பூரித்தே
ஏமுற்ற முப்பத் திரண்டும் இரேசித்துக்
காமுற்ற பிங்கலைக் கண்ணாக இவ்விரண்
டோ மத்தால் எட்டெட்டுக் கும்பிக்க உண்மையே`,
    transliteration: `vāmattil īreṭṭu māttirai pūrittē
ēmuṟṟa muppat tiraṇṭum irēcittuk
kāmuṟṟa piṅkalaik kaṇṇāka ivviraṇ
ṭō mattāl eṭṭeṭṭuk kumpikka uṇmaiyē`,
    english: `573: Time Duration of Inhaling Retaining and Exhaling Breath
Inhaling six and ten matras by left nostril
Retaining four and sixty in the navel
Exhaling two and thirty by the right nostril,
They who control breath thus, chanting Aum
Have verily seen the Light of Truth.`,
    elaborationTamil: `இடகலை (மூக்கின் இடது நாசி துவாரத்தின் வழியே நடைபெறும் சுவாசம் இடகலை எனப்படும்) வழியாக பூரக முறைப்படி ஒரு பங்கு (பதினாறு வினாடிகள்) அளவிற்கு மூச்சுக்காற்றை உள்ளிழுத்து கும்பக முறைப்படி நான்கு பங்கு (அறுபத்து நான்கு வினாடிகள்) அளவிற்கு மூச்சுக்காற்றை அடக்கிவைத்து பிங்கலை (மூக்கின் வலதுநாசி துவாரத்தின் வழியே நடைபெறும் சுவாசம் பிங்கலை எனப்படும்) வழியாக இரேசக முறைப்படி இரண்டு பங்கு (முப்பத்து இரண்டு வினாடிகள்) அளவிற்கு மூச்சுக்காற்றை மெதுவாக வெளியே விடுவதன் மூலம் பாதுகாப்பான பிராணாயாமத்தின் உண்மை கூறப்படுகின்றது. கும்பக முறை 64 வினாடிகள் வரை மட்டுமே பாதுகாப்பானது. அதற்கு மேல் செய்தால் மூளைக்குச் செல்லும் பிராண வாயுவின் அளவு குறைந்து தலைச் சுற்றல் மயக்கம் போன்றவை ஏற்படக்கூடும். எனவே எக்காரணம் கொண்டும் 64 வினாடி நேரத்திற்கு மேல் கும்பகம் செய்யக்கூடாது என்பதையே இப்பாடல் விளக்குகின்றது. பிராணாயமத்தைக் கற்றுக்கொள்ளும் முறை: மூச்சுப் பயிற்சி செய்யத் துவங்கும் ஆரம்ப கால கட்டங்களில் இந்த 16:64:32 என்ற காலக் கணக்கில் பயிற்சி செய்வது இயலாத காரியமாக இருக்கும். தொடர்ந்த பயிற்சிகளின் மூலமே இது கைகூடும். பயிற்சியைத் துவங்கும்போது 8:32:16 என்ற கால அளவில் துவங்கி படிப்படி யாக நேரத்தை அதிகரிக்கலாம். திருமூலர் கூறும் 16:64:32 என்ற கால அளவை எட்டிப் பிடிக்க குறைந்த பட்சம் ஆறு மாதங்கள் முதல் ஒரு வருடம் வரையில் ஆகலாம். ஒரு குருவின் மேற்பார்வையில் இந்த பயிற்சியைத் துவங்கினால் எளிதில் கைகூடும்.`,
  },
  {
    id: 575, tantraId: 3, verseNumber: 574,
    tamil: `இட்ட தவ்வீ டிளகா திரேசித்துப்
புட்டிப் படத்தச நாடியும் பூரித்துக்
கொட்டிப் பிராணன் அபானனுங் கும்பித்து
நட்டம் இருக்க நமனில்லை நமக்கே`,
    transliteration: `iṭṭa tavvī ṭiḷakā tirēcittup
puṭṭip paṭattaca nāṭiyum pūrittuk
koṭṭip pirāṇaṉ apāṉaṉuṅ kumpittu
naṭṭam irukka namaṉillai namakkē`,
    english: `574: How to Practise Pranayama
Inhale deep and steady,
That prana fills the nadis ten;
Exhale slow
That the body does not stir;
Retain prana breath
And downward move Apana breath
Thus sit erect and vanquish Death.`,
    elaborationTamil: `இறைவன் வழங்கிய இந்த உடல் சோர்வாக இல்லாத போது இரேசக முறைப்படி (பாடல் #568 இல் உள்ளபடி) மூச்சுக்காற்றை வெளியே விட்டுவிட்டு பத்து நாடிகளும் (1. இடகலை – (இடப்பக்க நரம்பு), 2. பிங்கலை – (வலப்பக்க நரம்பு), 3. சுமுழுனை – (நடுநரம்பு), 4. சிகுவை – (உள்நாக்கு நரம்பு), 5. புருடன் – (வலக்கண் நரம்பு), 6. காந்தாரி – (இடக்கண் நரம்பு), 7. அத்தி – ( வலச்செவி நரம்பு), 8. அலம்புடை – (இடச்செவி நரம்பு), 9. சங்கினி – (கருவாய் நரம்பு), 10. குகு – (மலவாய் நரம்பு)) நிரம்புமாறு மூச்சுக்காற்றை உள்ளிழுத்து அந்த மூச்சை அடக்கி மலவாயையும் சுருக்கி அக்காற்றை கும்பக முறைப்படி (பாடல் #568 இல் உள்ளபடி) வைத்து உடலை நேராக நிமிர்த்தி வைத்திருந்தால் இறப்பு என்றும் இல்லை.`,
  },
  {
    id: 576, tantraId: 3, verseNumber: 575,
    tamil: `புறப்பட்டுப் புக்குத் திரிகின்ற வாயுவை
நெறிப்பட வுள்ளே நின்மல மாக்கில்
உறுப்புச் சிவக்கும் உரோமங் கறுக்கும்
புறப்பட்டுப் போகான் புரிசடை யோனே`,
    transliteration: `puṟappaṭṭup pukkut tirikiṉṟa vāyuvai
neṟippaṭa vuḷḷē niṉmala mākkil
uṟuppuc civakkum urōmaṅ kaṟukkum
puṟappaṭṭup pōkāṉ puricaṭai yōṉē`,
    english: `575: Purify Body By Breath Control
The breath within rises
And wanders as it lists;
Control that and purify within;
Then shall your limbs glow red
Your hair turn dark
And God within shall leave you never.`,
    elaborationEnglish: `Purification of the breath by control is an impostant element of the pranayama exercise. When breath that wanders as it lists is regulated, the limbs grow red, the hair turns dark, and the body does not decay.`,
    elaborationTamil: `வெளியில் சுற்றித் திரியும் பிராணவாயுவை பிராணாயாம முறைப்படி (பாடல் #568 இல் உள்ளபடி) உள்ளே இழுத்து வைத்திருந்தால் அந்தக் காற்று உள்ளே சுத்தமாகி விடும். உடலுறுப்புக்கள் சிவப்பாகி முடிகள் கருப்பாகி அழகாக விளங்குவதோடு மட்டுமின்றி முறைப்படி பிராணாயாமத்தைச் செய்பவரின் உள்ளத்திலிருக்கும் கயிறு போல் முறுக்கிய சடையணிந்த சிவபெருமான் வெளியே செல்லாமல் இருப்பான்.`,
  },
  {
    id: 577, tantraId: 3, verseNumber: 576,
    tamil: `கூடம் எடுத்துக் குடிபுக்க மங்கையர்
ஓடுவர் மீளுவர் பன்னிரண் டங்குலம்
நீடுவர் எண்விரல் கண்டிப்பர் நால்விரல்
கூடிக் கொளிற்கோல அஞ்செழுத் தாமே`,
    transliteration: `kūṭam eṭuttuk kuṭipukka maṅkaiyar
ōṭuvar mīḷuvar paṉṉiraṇ ṭaṅkulam
nīṭuvar eṇviral kaṇṭippar nālviral
kūṭik koḷiṟkōla añceḻut tāmē`,
    english: `576: Inhale 12 Matras; Retain 4 Matras
The Prana breath
That is damsel within body-house
Runs in and out constant;
If twelve matras inhaled
Eight matras exhaled,
The four matras retained
Shall make you divine in Siva.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-576-Third-Tantra-5.-Yoga-of-Breath-Control.mp3',
    elaborationTamil: `முறைப்படி பிராணாயாமம் செய்பவர்களின் ஆரம்பகாலத்தில் உடலை இடமாகக் கொண்டிருக்கும் இடகலை பிங்கலை (பாடல் #567 இல் உள்ளபடி) ஆகிய பிராண சக்திகள் பன்னிரண்டு அங்குல அளவிற்கு உள்ளுக்குள் வந்தும் வெளியே சென்றும் இருக்கும். பிற்காலத்தில் அந்த சக்திகள் இரண்டும் தொண்டைக்குழியிலிருந்து தலை உச்சிவரை இருக்கின்ற நான்கு அங்குல அளவிற்குச் செல்லாமல் கழுத்துக்குக் கீழே எட்டு அங்குல அளவிற்கு மட்டுமே சென்றுகொண்டு இருக்கும். தொண்டைக்குழியிலிருந்து தலை உச்சிவரை உள்ள இடத்துக்குச் செல்லாமல் இருக்கும் மூச்சுக்காற்றை அந்த இடத்திற்கும் செல்லுமாறு மொத்தம் பன்னிரண்டு அங்குல அளவிற்கும் பிராணாயாமம் செய்பவர்கள் பஞ்சாக்கர மந்திரத்தின் (நமசிவாய) வடிவாக மாறுவார்கள்.`,
  },
  {
    id: 578, tantraId: 3, verseNumber: 577,
    tamil: `பன்னிரண் டானை பகலஇர வுள்ளது
பன்னிரண் டானையைப் பாகன் அறிகிலன்
பன்னிரண் டானையைப் பாகன் அறிந்தபின்
பன்னிரண் டானைக்குப் பகல்இர வில்லையே`,
    transliteration: `paṉṉiraṇ ṭāṉai pakalaira vuḷḷatu
paṉṉiraṇ ṭāṉaiyaip pākaṉ aṟikilaṉ
paṉṉiraṇ ṭāṉaiyaip pākaṉ aṟintapiṉ
paṉṉiraṇ ṭāṉaikkup pakalira villaiyē`,
    english: `577: Learn to Control Breath and Master Death
The elephant that is twelve-matra breath
Is awake night and day;
The mahout (Jiva) knows not elephant;
When mahout learns to control elephant
The elephant knows not night and day;
(In eternity it exists.)`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-577-Third-Tantra-5.-Yoga-of-Breath-Control.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `நமது உடலின் மூக்குத்துவாரத்திலிருந்து அடிவயிறு வரை பன்னிரண்டு அங்குல அளவிற்குச் சென்று வரும் மூச்சுக்காற்று உள்ளே வருவதும் வெளியே செல்லுவதுமாகிய இரண்டு செயல்களை மட்டுமே செய்து வருகின்றது. இச்செயல்களை ஆன்மா அறியவில்லை. மூக்கிலிருந்து வயிற்றை நோக்கிக் கீழ்ச் செல்லும் மூச்சுக்காற்றை மூக்கிலிருந்து தலை உச்சி நோக்கி மேலே செல்ல பிராணாயாமத்தின் மூலம் முயற்சித்தால் நமது உடலுக்கு இறப்பும் பிறப்பும் இல்லை.`,
  },
  {
    id: 579, tantraId: 3, verseNumber: 578,
    tamil: `கண்டுகண் டுள்ளே கருத்துற வாங்கிடிற்
கொண்டுகொண் டுள்ளே குணம்பல காணலாம்
பண்டுகந் தெங்கும் பழமறை தேடியை
இன்றுகண் டிங்கே இருக்கலு மாமே`,
    transliteration: `kaṇṭukaṇ ṭuḷḷē karuttuṟa vāṅkiṭiṟ
koṇṭukoṇ ṭuḷḷē kuṇampala kāṇalām
paṇṭukan teṅkum paḻamaṟai tēṭiyai
iṉṟukaṇ ṭiṅkē irukkalu māmē`,
    english: `578: Blessings of Mind Withdrawal
Step by step, practise mind's withdrawal
And look inward;
One by one many the good you see within;
And may you then meet the Lord,
Now and here below
Whom the ancient Vedas still searches
Everywhere.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-578-Third-Tantra-6.-Yoga-of-Detachment.mp3',
    elaborationEnglish: `The next step in yoga is pratyahara or withdrawing the mind and looking inward. This should be practised step by step. Many blessings will follow from this practice.

1) Pratyahara is the restraint of, and subjection of the senses of the mind, which is thereby steadied. The mind is withdrawn

from the objects of the senses. Vide Serpent Power’’

by Sir John Woodroffe, p.193. See also, Gaeranda Samhita, fourth Upadesa; Sandilya Upadesa, Chpt.1, etc; the Sarada Tilaka defines pratyahara as “‘the forcible obstruction of the senses wandering over their objects’’; quoted in ‘‘The Serpent Power’ op.cit— Steadiness is the aim and result of pratyahara.`,
    elaborationTamil: `வெளியே சென்று ஓடுகின்ற மனதை உள்ளே ஒரு நிலைப்படுத்தி விட்டால் இறைவனுடைய எட்டுவித குணங்களை நமக்குள்ளே உணரலாம். அவ்வாறு உள்ளே மனதை ஒரு நிலைப்படுத்தி வைத்து இருந்தால் ஆதிகாலம் முதல் பழமையான வேதங்களைக் கற்றறிந்தவர்களால் தமக்குள் தேடப்பட்ட இறைவனை அப்பொழுதே நமக்குள் கண்டு உணரலாம். இறைவனின் எட்டுவித குணங்கள்: 1. தன்வயத்தன் ஆதல், 2. தூய உடம்புடைமை, 3. அளவிலா ஆற்றல் உடைமை, 4. பாசங்களில் இருந்து நீங்கியிருப்பது, 5. பேரருள் உடைமை, 6. இயற்கை உணர்வு கொண்டிருத்தல், 7. முக்காலத்தையும் உணர்ந்திருத்தல், 8. அளவிலா ஆனந்தம் உடைமை)`,
  },
  {
    id: 580, tantraId: 3, verseNumber: 579,
    tamil: `நாபிக்குக் கீழே பன்னிரெண் டங்குலந்
தாபிக்கு மந்திரந் தன்னை அறிகிலர்
தாபிக்கு மந்திரந் தன்னை அறிந்தபின்
கூவிக்கொண் டீசன் குடியிருந் தானே`,
    transliteration: `nāpikkuk kīḻē paṉṉireṇ ṭaṅkulan
tāpikku mantiran taṉṉai aṟikilar
tāpikku mantiran taṉṉai aṟintapiṉ
kūvikkoṇ ṭīcaṉ kuṭiyirun tāṉē`,
    english: `579: Retain Breath Below Navel Region
They know not the divine art
Of fixing breath twelve matra long,
Below the navel region;
Once they learn that art
The Lord enters within, shouting in joy.`,
    elaborationEnglish: `Pratyahara helps in the act of breath retention below the navel region. It is a rare art that helps the practitioner to advance on the yoga path.`,
    elaborationTamil: `தொப்புளுக்குக் கீழே பன்னிரண்டு அங்குலம் தூரத்தில் உள்ள மூலாதாரத்தில் இருக்கும் ஓம் எனும் மந்திரத்தை அறிந்தவர்கள் யாருமில்லை. அந்த ஓம் என்னும் மந்திரத்தை உணர்ந்துவிட்டால் அந்த மந்திர ஒலியாய் இருக்கும் சிவபெருமானை நமக்குள் உணரலாம்.`,
  },
  {
    id: 581, tantraId: 3, verseNumber: 580,
    tamil: `மூலத் திருவிரல் மேலுக்கு முன்நின்ற
பாலித்த யோனிக் கிருவிரற் கீழ்நின்ற
கோலித்த குண்டலி யுள்ளேழுஞ் செஞ்சுடர்
ஞாலத்து நாபிக்கு நால்விரற் கீழதே`,
    transliteration: `mūlat tiruviral mēlukku muṉniṉṟa
pālitta yōṉik kiruviraṟ kīḻniṉṟa
kōlitta kuṇṭali yuḷḷēḻuñ ceñcuṭar
ñālattu nāpikku nālviraṟ kīḻatē`,
    english: `580: Where Kundalini Is
Two finger length above the anus,
Two finger length below the sex organ
Four finger length below the navel visible,
There within is Kundalini
A flaming fire lambent.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-580-Third-Tantra-6.-Yoga-of-Detachment.mp3',
    elaborationTamil: `மூலாதாரத்திலிருந்து இரண்டு அங்குலம் அளவிற்கு மேலும் பிறப்பு உறுப்பிலிருந்து இரண்டு அங்குலம் அளவிற்குக் கீழும் உள்ள இடத்தில் வட்ட வடிவமாக இருக்கும் குண்டலினி சக்தியின் மையப்புள்ளி உள்ளது. அந்த குண்டலினி சக்தியிலிருந்து வெளிப்படும் செம்மையான ஒளி தொப்புள் குழியிலிருந்து நான்கு அங்குலம் அளவிற்குக் கீழே இருக்கும் இடம் வரை பரவியுள்ளது.`,
  },
  {
    id: 582, tantraId: 3, verseNumber: 581,
    tamil: `நாசிக் கதோமுகம் பன்னிரண் டங்குலம்
நீசித்தம் வைத்து நினையவும் வல்லையேல்
மாசித்த மாயோகம் வந்து தலைப்பெய்துந்
தேகத்துக் கென்றுஞ் சிதைவில்லை யாமே`,
    transliteration: `nācik katōmukam paṉṉiraṇ ṭaṅkulam
nīcittam vaittu niṉaiyavum vallaiyēl
mācitta māyōkam vantu talaippeytun
tēkattuk keṉṟuñ citaivillai yāmē`,
    english: `581: Breath Control for Maha Siddha Yoga
If below the nose-tip
You look twelve-finger length,
And then concentrate and meditate (on navel centre),
The mighty Siddha yoga shall yours be
And imperishable shall your body be.`,
    elaborationTamil: `மூக்கிலிருந்து பன்னிரண்டு அங்குலம் அளவிற்குக் கீழே உள்ள இடத்தில் வைத்து (நான்காவது சக்கரமான அநாகதம் இருக்கும் இடமான நெஞ்சுக் குழி) நிர்மூலமாக இறைவனை தியானிக்கும் சக்தியுள்ளவர்களுக்கு எட்டு வகையான சித்திகளையும் கொடுக்கும் மாபெரும் யோகங்களும் வந்து சேரும். அப்படி சேர்ந்தபின் உடம்பிற்கு எப்போதும் அழிவு என்பது இல்லை.`,
  },
  {
    id: 583, tantraId: 3, verseNumber: 582,
    tamil: `சோதி இரேகைச் சுடரொளி தோன்றிடிற்
கோதில் பரானந்தம் என்றே குறிக்கொண்மின்
நேர்திகழ் கண்டத்தே நிலவொளி எய்தினால்
ஓதுவ துன்னுடல் உன்மத்த மாமே`,
    transliteration: `cōti irēkaic cuṭaroḷi tōṉṟiṭiṟ
kōtil parāṉantam eṉṟē kuṟikkoṇmiṉ
nērtikaḻ kaṇṭattē nilavoḷi eytiṉāl
ōtuva tuṉṉuṭal uṉmatta māmē`,
    english: `582: When Light Appears
If thus meditating,
Luminescence you glimpse at the Eye-brow centre
Know you are destined for bliss unalloyed;
If at the Throat's Center
Lunar light you behold,
Then will your body,
In divine joy intoxicated be.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-582-Third-Tantra-6.-Yoga-of-Detachment.mp3',
    elaborationTamil: `மூலாதாரத்தில் இருக்கும் குண்டலினி சக்தி தலை உச்சிக்குச் சென்றபின் பிராகாசமான ஒளி தோன்றி அந்த ஒளிக்கதிர் உடலெங்கும் பரவி பேரின்பம் கிடைக்கும் என்று மனதை ஒருமுகப்படுத்தி தியானம் செய்து, தலை உச்சிக்கு நேராகக் கீழே இருக்கும் கழுத்தில் அந்த ஒளிக் கதிர் தெரியும் நிலையை அடைந்தால் அவ்வாறு தியானித்த உடல் தன்னை மறந்த நிலையில் பேரானந்தமாக இருக்கும்.`,
  },
  {
    id: 584, tantraId: 3, verseNumber: 583,
    tamil: `மூலத் துவாரத்தை முக்கார மிட்டிரு
மேலைத் துவாரத்தின் மேல்மனம் வைத்திரு
வேலொத்த கண்ணை வௌியில் விழித்திரு
காலத்தை வெல்லுங் கருத்திது தானே`,
    transliteration: `mūlat tuvārattai mukkāra miṭṭiru
mēlait tuvārattiṉ mēlmaṉam vaittiru
vēlotta kaṇṇai vauiyil viḻittiru
kālattai velluṅ karuttitu tāṉē`,
    english: `583: What Kundalini Yoga is
Close the Muladhara orifice below
Center your thought on Sahasrara orifice above
And on that meditate in oneness;
Fix your dagger like vision on that Void Vast;
Thus practising Yoga,
You shall vanquish Time.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-583-Third-Tantra-6.-Yoga-of-Detachment.mp3',
    elaborationTamil: `மூலாதாரத்திலிருக்கும் துளையை (மலத்துவாரம்) சதைகளால் இறுக்கி அடைத்துக் கொண்டு புருவங்களுக்கு நடுவில் இருக்கும் இடத்தில் (ஆக்ஞா சக்கரம் இருக்கும் இடம்) மனதை வைத்து உடல் உணர்வுகளை மறந்த நிலையில் தியானித்து இருப்பதே இறவாமல் இருக்கும் வழியாகும்.`,
  },
  {
    id: 585, tantraId: 3, verseNumber: 584,
    tamil: `எருவிடும் வாசற் கிருவிரன் மேலே
கருவிடும் வாசற் கிருவிரற் கீழே
உருவிடுஞ் சோதியை உள்கவல் லார்க்குக்
கருவிடுஞ் சோதி கலந்துநின் றானே`,
    transliteration: `eruviṭum vācaṟ kiruviraṉ mēlē
karuviṭum vācaṟ kiruviraṟ kīḻē
uruviṭuñ cōtiyai uḷkaval lārkkuk
karuviṭuñ cōti kalantuniṉ ṟāṉē`,
    english: `584: Kundalini Yoga Destroys Birth
Two finger length above the anus
Two finger length below the sex organ,
Lies the Kundalini Fire
If you can meditate on the light
That burns there,
You shall be one with Lord,
Who all births destroys.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-584-Third-Tantra-6.-Yoga-of-Detachment.mp3',
    elaborationTamil: `மலதுவாரத்திற்கு இரண்டு அங்குலம் மேலும் பிறப்புறுப்புக்கு இரண்டு அங்குலம் கீழும் உள்ள இடத்தில் இருக்கும் ஜோதியை (குண்டலினி சக்தி) உணர்ந்து தியானிக்க முடிந்தவர்களோடு உடலுக்கு உயிர் கொடுக்கும் இறைவன் கலந்து நிற்பான்.`,
  },
  {
    id: 586, tantraId: 3, verseNumber: 585,
    tamil: `ஒருக்கால் உபாதியை ஒண்சோதி தன்னைப்
பிரித்துணர் வந்த உபாதிப் பிரிவை
கரைத்துணர் வுன்னல் கரைதலுள் நோக்கல்
பிரத்தியா காரப் பெருமையது ஆமே`,
    transliteration: `orukkāl upātiyai oṇcōti taṉṉaip
pirittuṇar vanta upātip pirivaik
karaittuṇar vuṉṉal karaitaluḷ nōkkal
pirattiyā kārap perumaiya tāmē`,
    english: `585: Pratyahara
By thought concentrated,
Know clearly apart
Pasa and Pati Luminescent,
Then destroy that Pasa;
Melt in your heart for Lord,
Attain and contemplate on Jnana,
And look inward toward Him;
These the precious Ways of Pratiyahara are.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-585-Third-Tantra-6.-Yoga-of-Detachment.mp3',
    elaborationEnglish: `Then arise awareness,’ contemplation and loss of

ego . Which constitute the glory of Pratyahara.`,
    elaborationTamil: `பிரத்தியாகாரத்தின் மூலம் மிகவும் கடினத்துடன் மனதை ஒருநிலைப்படுத்தி கர்மாவினால் உண்டான உடலின் தொடக்கத்தையும் ஆன்மாவின் அறிவையும் பிரித்துப் பார்க்கும் திறனை அடைவதும், தனித்தனியாகப் பார்க்கும் பல இறை உருவங்களை மெல்ல மறந்து அறிவு வடிவாகிய ஒரே இறைவனை உணர்வதும் அந்த உணர்வினால் இறைவனின் மேல் அன்பு அதிகமாவதும் அவ்வாறு அதிகமாகிய அன்பினால் இறைவனை எப்பொதும் மறக்காமல் இருப்பதும் ஆகிய இவையே பிரத்தியாகாரத்தால் அடையும் பெரும் பயன்களாம்.`,
  },
  {
    id: 587, tantraId: 3, verseNumber: 586,
    tamil: `புறப்பட்ட வாயுப் புகவிடா வண்ணந்
திறப்பட்டு நிச்சயஞ் சேர்ந்துடன் நின்றால்
உறப்பட்டு நின்றது உள்ளமும் அங்கே
புறப்பட்டுப் போகான் பெருந்தகை யானே`,
    transliteration: `puṟappaṭṭa vāyup pukaviṭā vaṇṇan
tiṟappaṭṭu niccayañ cērntuṭaṉ niṉṟāl
uṟappaṭṭu niṉṟatu uḷḷamum aṅkē
puṟappaṭṭup pōkāṉ peruntakai yāṉē`,
    english: `586: Pranayama Helps Pratyahara
If breath that is exhaled
Is contained within
The thoughts too are contained there
And the Lord shall leave you not.`,
    elaborationEnglish: `Pranayama aids the practice of pratyahara. If breath that is exhaled is contained within, the thoughts too are contained within. Then the Lord leaves you not.`,
    elaborationTamil: `உள்ளிழுத்து வெளியே விட்ட மூச்சுக்காற்றை மீண்டும் உள்ளிழுக்காமல் ஒரு குறிப்பிட்ட கால அளவு (தியான முறைப்படி) மன உறுதியுடன் இருந்தால் உள்ளம் இறைவனின் மேல் ஈர்க்கப்பட்டு இருக்கும். அவ்வாறு ஈர்க்கப்பட்டு இருக்கும் உள்ளத்துடன் பெருங் கருணையுடைய இறைவன் எப்போதும் கலந்தே இருப்பான்.`,
  },
  {
    id: 588, tantraId: 3, verseNumber: 587,
    tamil: `குறிப்பினின் உள்ளே குவலயந் தோன்றும்
வெறுப்பிருள் நங்கி விகிர்தனை நாடுங்
சிறப்புறு சிந்தையைச் சிக்கென் றுணரில்
அறிப்புறு காட்சி அமரரு மாமே`,
    transliteration: `kuṟippiṉiṉ uḷḷē kuvalayan tōṉṟum
veṟuppiruḷ naṅki vikirtaṉai nāṭuṅ
ciṟappuṟu cintaiyaic cikkeṉ ṟuṇaril
aṟippuṟu kāṭci amararu māmē`,
    english: `587: What Pratyhara Can Lead to
In the act of concentrated meditation
All world will be visioned;
Be rid of the despicable darkness
And seek Lord,
If your thoughts be centered firm
You shall Divine Light see
And immortal thereafter be.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-587-Third-Tantra-6.-Yoga-of-Detachment.mp3',
    elaborationTamil: `பிரத்தியாகாரம் கூறும் மூன்று சக்கர இடங்களில் (மூலாதாரம், சுவாதிஷ்டானம், மணிப்பூரகம்) மனதை ஒருமுகப்படுத்துவன் உலகம் தோன்றிய நாள் முதல் இறைவனை அடையத் தடையாக இருக்கும் மாயை எனும் அறியாமையாகிய இருளை அகற்றி இறைவனை தேடிச் செல்லலாம். அவ்வாறு இறைவனை விரும்பித் தேட வேண்டும் என்ற எண்ணத்தில் உறுதியாக இருந்தால் காணக் கிடைக்காத அரிய இறைக் காட்சியைக் கண்டு அழிவில்லாத நிலையை அடையலாம்.`,
  },
  {
    id: 589, tantraId: 3, verseNumber: 588,
    tamil: `கோணா மனத்தைக் குறிக்கொண்டு கீழ்க்கட்டி
வீணாத்தண் டூடே வௌியுறத் தானோக்கிக்
காணாக்கண் கேளாச் செவியென் றிருப்பார்க்கு
வாணாள் அடைக்கும் வழியது வாமே`,
    transliteration: `kōṇā maṉattaik kuṟikkoṇṭu kīḻkkaṭṭi
vīṇāttaṇ ṭūṭē vauiyuṟat tāṉōkkik
kāṇākkaṇ kēḷāc ceviyeṉ ṟiruppārkku
vāṇāḷ aṭaikkum vaḻiyatu vāmē`,
    english: `588: How to Practise Dharana
Let unswerving be your thought
Bind it to Muladhara fast
Look into the Void Inside through spinal shaft
See and yet see not;
Hear and yet hear not;
Thus in meditation sit;
That the sure Way to bar death's way.`,
    elaborationEnglish: `Control the mind from getting diverted towards the senses

Concenirate on the Chidakasa within the spinal column,

The eyes must not see nor the ears hear,

This is the way to life eternal.`,
    elaborationTamil: `பிரத்தியாகாரம் மூலம் உள்ளே ஒருநிலைப்படுத்திய மனதை மீண்டும் முன்பு இருந்தபடி அலைபாயவிடாமல் வைத்து மனக் கண்ணை முதுகெலும்பின் வழியே செல்லும் சுழுமுனை சென்றுசேரும் இடமாகிய தலை உச்சிக்குச் சிறிது மேலே (தோராயமாக 9 அங்குலம் அளவு) உள்ள வெற்று இடத்தில் வைத்து கண்ணால் காணும் காட்சிகளும் காதால் கேட்கும் ஒலிகளும் மனதை பாதிக்காத வண்ணம் உணர்வில்லாமல் இருந்தால் இந்தப் பிறவியின் ஆயுள் முடியாமல் இருக்கலாம்.`,
  },
  
  {
    id: 590, tantraId: 3, verseNumber: 589,
    tamil: `மலையார் சிரத்திடை வானீர் அருவி
நிலையாரப் பாயும் நெடுநாடி யூடே
சிலையார் பொதுவில் திருநட மாடுந்
தொலையாத ஆனந்தச் சோதிகண் டேனே`,
    transliteration: `malaiyār cirattiṭai vāṉīr aruvi
nilaiyārap pāyum neṭunāṭi yūṭē
cilaiyār potuvil tirunaṭa māṭun
tolaiyāta āṉantac cōtikaṇ ṭēṉē`,
    english: `589: Lord Dances in Sahasrara
From the peaks of Cranium ranges
The heavenly waterfall
Unceasing cascades
Coursing prana through the spinal channel;
There on the stony arena (of Mount Meru within)
The Lord performs His timeless dance;
That unending Bliss Light,
I witnessed.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-589-Third-Tantra-7.-Yoga-of-Concentration.mp3',
    elaborationTamil: `மலை போன்ற தலையின் உச்சியில் வானத்திலிருந்து வரும் மழை போல அமிர்தம் எப்போதும் பொழிந்துகொண்டு இருக்கின்ற சுழுமுனை நாடியின் வழியாக மனதைச் செலுத்தி அம்பலத்தில் ஆடும் சிவபெருமானின் என்றும் தெவிட்டாத பேரின்பம் தரும் ஆனந்தக் கூத்தைக் கண்டேன்.`,
  },
{
    id: 591, tantraId: 3, verseNumber: 590,
    tamil: `மேலை நிலத்தினாள் வேதகப் பெண்பிள்ளை
மூல நிலத்தில் எழுகின்ற மூர்த்தியை
ஏல எழுப்பி இவளுடன் சந்திக்கப்
பாலனும் ஆவான் பராநந்தி ஆணையே`,
    transliteration: `mēlai nilattiṉāḷ vētakap peṇpiḷḷai
mūla nilattil eḻukiṉṟa mūrttiyai
ēla eḻuppi ivaḷuṭaṉ cantikkap
pālaṉum āvāṉ parānanti āṇaiyē`,
    english: `590: Kundalini in Reverse
She is the Damsel of the Vedas;
She belongs to the astral land of Cranium;
He is the bridal lord;
He sleeps in the land of Muladhara;
Gently rouse Him,
And make Him meet Her,
You shall then be forever young
Upon lordly Nandi I avow,
This true forever and ever.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-590-Third-Tantra-7.-Yoga-of-Concentration.mp3',
    elaborationTamil: `மூலாதாரத்தில் இருக்கும் குண்டலினியாகிய இறைவனை சுழுமுனை வழியே மேல் நோக்கி எடுத்துச் சென்று தலை உச்சியிலிருக்கும் சகஸ்ரதளத்தில் இருக்கும் சக்தியுடன் சேர்த்துவிட்டால் அமுதம் சுரந்து அதன் விளைவாக வயதானவரும் வாலிபனாக மாறி என்றும் இளமையுடன் இருப்பார். இது உலகாளும் நந்தியின் ஆணை.`,
  },
  {
    id: 592, tantraId: 3, verseNumber: 591,
    tamil: `கடைவாச லைக்கட்டிக் காலை எழுப்பி
இடைவாசல் நோக்கி இனிதுள் இருத்தி
மடைவாயிற் கொக்குப்போல் வந்தித் திருப்பார்க்
குடையாமல் ஊழி இருக்கலு மாமே`,
    transliteration: `kaṭaivāca laikkaṭṭik kālai eḻuppi
iṭaivācal nōkki iṉituḷ irutti
maṭaivāyiṟ kokkuppōl vantit tiruppārk
kuṭaiyāmal ūḻi irukkalu māmē`,
    english: `591: Practice of Kundalini Yoga
Bind the Muladhara
Raise the Prana breath upward
Through the spinal hollow course it
And within in aptness retain,
And like a stork at stream's head
Sit calm
In singleness of thought;
Well may you live forever and ever.`,
    elaborationTamil: `மூலாதாரத்திலிருக்கும் துவாரமாகிய மலத்துவாரத்தை இறுக்கி வைத்து உள்ளே இழுத்த மூச்சுக்காற்றை முதுகெலும்பின் வழியே செல்லும் சுழுமுனை வழியே செலுத்தி தொப்புளுக்குக் கீழே இருக்கும் மூன்று சக்கரங்களின் நடுவில் மனதை வைத்து இறையருளால் கிடைக்கும் ஒளியை அடையும் வரை இறைவனை வணங்கி இருப்பவர்களுக்கு உலகம் அழியும் காலம் வரை உடல் அழிவின்றி இருக்க முடியும்.`,
  },
  {
    id: 593, tantraId: 3, verseNumber: 592,
    tamil: `கலந்த உயிருடன் காலம் அறியில்
கலந்த உயிரது காலின் நெருக்கங்
கலந்த உயிரது காலது கட்டிற்
கலந்த உயிருடல் காலமும் நிற்குமே`,
    transliteration: `kalanta uyiruṭaṉ kālam aṟiyil
kalanta uyiratu kāliṉ nerukkaṅ
kalanta uyiratu kālatu kaṭṭiṟ
kalanta uyiruṭal kālamum niṟkumē`,
    english: `592: Practice Breath Control in Proper Time-Measure
When Pranayama is in proper time-measure practised
Breath retention will appropriate with Prana stand;
He who trains breath that is Prana,
With him shall Time and Life inseparate remain.`,
    elaborationEnglish: `With him shal! Time and Life inseparate remain.`,
    elaborationTamil: `உயிருடன் கலந்த உடலினுள்ளே செல்லும் மூச்சுக்காற்றைத் தெரிந்துகொண்டு அந்த மூச்சுக்காற்றுடன் உயிருக்கும் உடலுடக்கும் நெருக்கத்தை ஏற்படுத்தி அந்த மூச்சுக்காற்றை வெளியே சென்றுவிடாமல் அடக்கி வைத்திருந்தால் அந்த மூச்சுக்காற்று உயிருடன் கலந்த உடலோடு எப்போதும் கலந்து இருக்கும்.`,
  },
  {
    id: 594, tantraId: 3, verseNumber: 593,
    tamil: `வாய்திற வாதார் மனத்திலோர் மாடுண்டு
வாய்திறப் பாரே வளியிட்டுப் பாய்ச்சுவர்
வாய்திற வாதார் மதியிட்டு மூட்டுவர்
கோய்திற வாவிடிற் கோழையுமாமே`,
    transliteration: `vāytiṟa vātār maṉattilōr māṭuṇṭu
vāytiṟap pārē vaḷiyiṭṭup pāyccuvar
vāytiṟa vātār matiyiṭṭu mūṭṭuvar
kōytiṟa vāviṭiṟ kōḻaiyumāmē`,
    english: `593: Practise Breath Control in Silentness
A bull there is,
In the thoughts of those
Who silentness observe;
They who open their mouth wide
Drive it away wind-ward;
But they who are in silentness wrapped
Drive it to the Lunar Peak;
There with its horns it knocks;
And if the Gates of the Cave do not open,
It turns tail in fear.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-593-Third-Tantra-7.-Yoga-of-Concentration.mp3',
    elaborationTamil: `பேசாமல் மெளன நிலையில் இருப்பவர்களின் மனதில் பிராணன் என்னும் பெரும் செல்வம் உள்ளது. அவ்வாறு மெளன நிலையில் இல்லாமல் பேசிக்கொண்டே இருப்பவர்கள் அந்தப் பிராணனாகிய செல்வத்தை வீணாக்குகின்றார்கள். பேசாமல் மெளன நிலையில் இருப்பவர்கள் தங்கள் அறிவை அந்தப் பிராணனாகிய செல்வத்தின் மீது செலுத்தி அதை சுழுமுனை வழியாகத் தலை உச்சியிலிருக்கும் சகஸ்ரதளத்திற்கு கொண்டு சென்று அந்தச் செல்வத்தை அடைவார்கள். அவ்வாறு பிராணனாகிய செல்வத்தை சுழுமுனை வழியாக மேலே உள்ள சகஸ்ரதளத்திற்குக் கொண்டு செல்லும் பயிற்சியை செய்யாமல், பெரும் செல்வத்தை மட்டும் அடைய நினைப்பவர்கள் கோழையாவார்கள்.`,
  },
  {
    id: 595, tantraId: 3, verseNumber: 594,
    tamil: `வாழலு மாம்பல காலும் மனத்திடைப்
போழ்கின்ற வாயு புறம்படாப் பாய்ச்சுறில்
எழுசா லேகம் இரண்டு பெருவாய்தல்
பாழி பெரியதோர் பள்ளி அறையே`,
    transliteration: `vāḻalu māmpala kālum maṉattiṭaip
pōḻkiṉṟa vāyu puṟampaṭāp pāyccuṟil
eḻucā lēkam iraṇṭu peruvāytal
pāḻi periyatōr paḷḷi aṟaiyē`,
    english: `594: Longevity Gained by Breath Control
If breath that is forked in and out,
Is on mind directed and centered,
Well may you sleep
In the spacious bed chamber
Of the Body Cave
That has doors two and windows seven.
And long, long may you live there too.`,
    elaborationTamil: `உள்ளிழுத்த மூச்சுக்காற்றை வெளியே விட்டுவிடாமல் மனதை ஒருமுகப்படுத்தி சுழுமுனை வழியாக அந்த மூச்சுக்காற்றை மேலே ஏற்றி தலை உச்சியிலுள்ள சகஸ்ரதளத்திற்குக் கொண்டு சென்றுவிட்டால் ஒன்பது துவாரங்களைக் கொண்ட இந்த உடம்பில் நீண்ட காலம் அழியாமல் பேரானந்த நிலையில் இருக்கலாம்.`,
  },
  {
    id: 596, tantraId: 3, verseNumber: 595,
    tamil: `நிரம்பிய ஈரைந்தில் ஐந்திவை போனால்
இரங்கி விழித்திருந் தென்செய்வை பேதாய்
வரம்பினைக் கோலி வழிசெய்கு வார்க்குக்
குரங்கினைக் கொட்டை பொதியலு மாமே`,
    transliteration: `nirampiya īraintil aintivai pōṉāl
iraṅki viḻittirun teṉceyvai pētāy
varampiṉaik kōli vaḻiceyku vārkkuk
kuraṅkiṉaik koṭṭai potiyalu māmē`,
    english: `595: Mind Control Through Breath Control
If of the ten Vayus that fill the body
Five by exhalation leave,
What avails you fool!
What though you wake and pray?
They who control breath in measure ordained,
Will sure imprison mind-monkey
Within the body-fortress.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-595-Third-Tantra-7.-Yoga-of-Concentration.mp3',
    elaborationEnglish: `If out of the ten vayus that fill the body, five leave by exhalation, nothing is achieved by waking and praying. Only breath control can imprison the mind-monkey.`,
    elaborationTamil: `உடம்பில் உள்ள பத்துவித வாயுக்களில் முக்கியமான ஐந்து வாயுக்களை பிராணாயாம முறைப்படி கட்டுப்படுத்தி வெளியே விடாமல் வீணாக வெளியேற்றுபவர்கள் இந்த உலகில் வெறுமனே உயிர் வாழ்ந்து எந்தப் பயனையும் அடையமாட்டார்கள். அந்த ஐந்து வாயுக்களையும் வீணாக்காமல் பிராணாயாம முறையில் கூறிய அளவுகளின்படி அடக்கி வெளியே விடுபவர்களுக்கு மனமாகிய குரங்கை ஒருமுகப்படுத்தி உடம்பின் உள்ளேயே நிலைத்திருக்கும்படி வைக்க முடியும். உடலிலுள்ள பத்துவித வாயுக்கள்: பிராணன் – உயிர்க்காற்று அபாணன் – மலக் காற்று வியானன் – தொழிற்காற்று உதானன் – ஒலிக்காற்று சமானன் – நிரவுக்காற்று நாகன் – விழிக்காற்று கூர்மன் – இமைக்காற்று கிருகரன் – தும்மற் காற்று தேவதத்தன் – கொட்டாவிக் காற்று தனஞ்செயன் – வீங்கல் காற்று முறைப்படி கட்டுப்படுத்தி வெளியே விடவேண்டிய ஐந்து வாயுக்கள்: பிராணன் – உயிர்க்காற்று நுரையீரலில் இருந்து மேல் நோக்கிச் செல்வது. பசியையும், தாகத்தையும் ஏற்படுத்துவது. உணவை செரிமானம் செய்வது. அபாணன் – மலக் காற்று உடற்கழிவுகளான மலம், ஜலம், சுக்கிலம் (விந்து), சுரோணிதம் (கரு முட்டை) ஆகியவற்றை வெளியேற்ற உதவுவது. வியானன் – தொழிற்காற்று உடல் முழுவதும் பரவி தொடு உணர்ச்சியை உணர வைப்பது ஜீரணமான உணவை சத்து வேறாகவும் சக்கை வேறாகவும் பிரிக்கும் பணியைச் செய்வது. உதானன் – ஒலிக்காற்று தொண்டையில் இருந்து கொண்டு உணவை விழுங்கச்செய்வது, ஏப்பம் வரச்செய்வது, குறட்டை வரச்செய்வது, உறங்கும் போது ஐம்புலன்களுக்கும் ஓய்வு கொடுப்பதும் விழித்த பின்பு ஐம்புலன்களின் இயல்பிற்கேற்ப மறுபடியும் இயங்கச் செய்வது. சமானன் – நிரவுக்காற்று தொப்புள் பகுதியில் இருந்து கொண்டு உணவின் சத்தையெல்லாம் எல்லா உறுப்புகளுக்கும் அதனதன் தேவைக்கேற்ப பகிர்ந்து அளிப்பது.`,
  },
  {
    id: 597, tantraId: 3, verseNumber: 596,
    tamil: `முன்னம் வந்தனர் எல்லாம் முடிந்தனர்
பின்னை வந்தவர்க் கென்ன பிரமாணம்
முன்னுறு கோடி உறுகதி பேசிடில்
என்ன மாயம் இடிகரை நிற்குமே`,
    transliteration: `muṉṉam vantaṉar ellām muṭintaṉar
piṉṉai vantavark keṉṉa piramāṇam
muṉṉuṟu kōṭi uṟukati pēciṭil
eṉṉa māyam iṭikarai niṟkumē`,
    english: `596: Make the Body Immortal
All those who came afore
Have met their final end;
What guarantee is there of any other fate,
For those who come after?
What then there to speak of the millions
And their life to be?
What delusion this!
Will the sandy bank ever hold firm?`,
    elaborationEnglish: `Here, the core of yoga theory of life and death is explained.`,
    elaborationTamil: `நமக்கு முன்பு வந்தவர்களெல்லாம் மனதை ஒருமுகப்படுத்தி நிலைத்து வைக்காமல் இறந்து போய்விட்டார்கள். பின்பு பிறந்த நாமும் அவ்வாறே மனதை ஒருமுகப்படுத்தாமல் அழிந்து விடுவோம் என்பது நிச்சயம் இல்லை. முன்பு வந்த முன்னூறு கோடி மனிதர்களும் அடைந்த கதியைப் பற்றிப் பேசி ஒரு பயனும் இல்லை. மனதை ஒருமுகப்படுத்தி நிலைத்து வைத்தால் அழியக்கூடியதாக இருக்கும் இந்த உடல் அழியாததாக மாற்ற முடியும்.`,
  },
  {
    id: 598, tantraId: 3, verseNumber: 597,
    tamil: `அரித்த வுடலைஐம் பூதத்தில் வைத்துப்
பொருத்தஐம் பூதஞ்சத் தாதியிற் போந்து
தெரித்த மனாதிசத் தாதியிற் செல்லத்
தரித்தது தாரணை தற்பரத் தோடே`,
    transliteration: `aritta vuṭalaiaim pūtattil vaittup
poruttaaim pūtañcat tātiyiṟ pōntu
teritta maṉāticat tātiyiṟ cellat
tarittatu tāraṇai taṟparat tōṭē`,
    english: `597: Dharana is Involution
To contain body's harassing senses five
In elements five,
To contain elements five
In organs cognitive internal,
To contain cognitive organs internal
Into its Primal Reals,
To contain Primal Reals
In the Being Uncreated
That, verily, is Dharana
In stages practised.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-597-Third-Tantra-7.-Yoga-of-Concentration.mp3',
    elaborationTamil: `ஆற்று வெள்ளம் கரையினை அரித்துப் பாழாக்குவது போல ஐம்பூதங்களான மெய் (உணர்வது) கண் (பார்ப்பது) காது (கேட்பது) மூக்கு (நுகர்வது) வாய் (சுவைப்பது) ஆகிய ஐம்புலன்கள் உடம்பினை அரித்துப் பாழாக்குகின்றது. ஐம்புலன்களும் உடலுக்குள் அடங்கும் முறையை உணர்ந்தால் உலகம் அழியக்கூடியது சிவமே அழியாதது என்ற உண்மையை உணரலாம். அவ்வாறு உணர்ந்து விட்டால் உலகப்பற்று அறுந்துவிடும். உடலைக் கட்டுப்படுத்தும் ஐம்பூதங்களையும் மனதால் கட்டுப்படுத்த வேண்டும். வெளியே உள்ள ஐம்பூதங்களின் (உணர்ச்சி, காட்சி, சத்தம், வாசனை, சுவை) உணர்வுகளை உள்ளுக்குள் உணர வேண்டும். மனதை மூலாதாரத்தில் ஒருநிலைப்படுத்த வேண்டும். உடலில் இருக்கும் ஆத்மாவை இறைவனோடு சேர்த்தல் வேண்டும். இவை அனைத்தும் செய்வதே தாரணை எனப்படும்.`,
  },
  {
    id: 599, tantraId: 3, verseNumber: 598,
    tamil: `வருமாதி யீரெட்டுள் வந்த தியானம்
பொருவாத புந்தி புலன்போக மேவல்
உருவாய சத்தி பரத்தியான முன்னுங்
குருவார் சிவத்தியானம் யோகத்தின் கூறே`,
    transliteration: `varumāti yīreṭṭuḷ vanta tiyāṉam
poruvāta punti pulaṉpōka mēval
uruvāya catti parattiyāṉa muṉṉuṅ
kuruvār civattiyāṉam yōkattiṉ kūṟē`,
    english: `598: Dhyana is of Two Kinds
The ten--
The five elements and the five senses
Being contained, one by the other,
The internal organ Buddhi
In turn contains the senses;
Thus is Dhyana born;
The Para Dhyana first
That is on Sakti centered,
And Siva Dhyana next
That is by Guru blessed,
These two the Ways of Dhyana Yoga.`,
    elaborationEnglish: `Dhyana is born out of perfection of dharana; that is, when the five elements, the five senses, and the internal organs are contained, dhyana is born. Dhyana is of two kinds: Parai dhyana and Siva dhyana. Parai dhyana is centered on Sakti, Siva dhyana on Siva. Both the ways of dhyana yoga should be initiated by the Guru.

1) Dhyana has been defined to be the state of the antakharana (mind) of those whose chaitanya holds to and is occupied by the thought, on one object, having first cast away the

thought of all other objects. Through dhyana is acquired the quality of mental realization (pratyaksha). It is of two kinds: Saguna or meditation on a form (murti) and nirguna, in which the Self is its own object Vide ‘‘The Serpent Power’’ by Sir John Woodroffe, pp.193-194.`,
    elaborationTamil: `ஆதியிலிருந்து வரும் பூதங்கள் ஐந்தும் (நிலம், நீர், நெருப்பு, காற்று, ஆகாயம்) புலன்கள் ஐந்தும் (பார்த்தல், கேட்டல், நுகர்தல், சுவைத்தல், தொடுதல்) அந்தக் கரணங்கள் நான்கும் (மனம், புத்தி, சித்தம், அகங்காரம்) மாயை ஒன்றும் ஆத்மா ஒன்றும் ஆகிய 16 உண்மைகளையும் நினைப்பது ஆருயிர்த் தியானம் ஆகும். சாதாரண நிலையில் அறிவு புலன்களின் மேல் பற்றுகொண்டு இருக்கும். அந்த அறிவை புலன்களை விட்டு விலக்கி வைத்தால் வருவது முதல் பிரிவான அம்மை அப்பனாகிய இரண்டு சக்திகளும் பரத்தியானம் ஆகும். அறிவில் குருவாக சிவனை வைத்துவிட்டால் வருவது இரண்டாம் பிரிவான சிவத்தியானம் ஆகும். பரத்தியானம், சிவத்தியானம் ஆகிய இவையே யோகத்தின் இரண்டு பிரிவுகளாகும்.`,
  },
  {
    id: 600, tantraId: 3, verseNumber: 599,
    tamil: `கண்ணாக்கு மூக்குச் செவஞானக் கூட்டத்துட்
பண்ணாக்கி நின்ற பழம்பொருள் ஒன்றுண்(டு)
அண்ணாக்கின் உள்ளே அகண்ட ஔிகாட்டிப்
புண்ணாக்கி நம்மைப் பிழைப்பித்த வாறே`,
    transliteration: `kaṇṇākku mūkkuc cevañāṉak kūṭṭattuṭ
paṇṇākki niṉṟa paḻamporuḷ oṉṟuṇ(ṭu)
aṇṇākkiṉ uḷḷē akaṇṭa auikāṭṭip
puṇṇākki nammaip piḻaippitta vāṟē`,
    english: `599: In Dhyana the Divine Light Appears
Through eye, tongue, nose and ear
And the organ Intellect
There is an Ancient One that pervades as Nada,
Inside the palatal cavity
He shows the Cosmic Light;
He gave the fleshly body,
That we redeemed be.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-599-Third-Tantra-8.-Yoga-of-Meditation.mp3',
    elaborationEnglish: `In dhyana, the cosmic light flashes. Gaze on it. to heart’s

content, mingle with it, get into the heavenly stream of the vast Space, and envision the Uncreated Being.`,
    elaborationTamil: `கண், நாக்கு, மூக்கு, காது ஆகிய நான்கின் உணர்வுகளை உணர்த்தும் ஞானமாகிய கூட்டத்தில் ஓம் என்னும் ஒலியை உருவாக்கி நிற்கின்ற பரம்பொருள் ஒன்று உண்டு. அந்தப் பரம்பொருளை நினைத்து உடலை வருத்தி தியானம் செய்பவர்களின் உள் நாக்கின் உள்ளே அகண்ட பேரொளியைக் காட்டுவது மட்டுமன்றி அவ்வாறு உடலை வருத்தி தியானத்தை செய்தவர்களுக்கு இறப்பில்லாத நிலையையும் கொடுக்கும்.`,
  },
  {
    id: 601, tantraId: 3, verseNumber: 600,
    tamil: `ஒண்ணா நயனத்தில் உற்ற ஔிதன்னைக்
கண்ணாரப் பார்த்துக் கலந்தங் கிருந்திடில்
விண்ணாறு வந்து வௌிகண் டிடவோடிப்
பண்ணாமல் நின்றது பார்க்கலு மாமே`,
    transliteration: `oṇṇā nayaṉattil uṟṟa auitaṉṉaik
kaṇṇārap pārttuk kalantaṅ kiruntiṭil
viṇṇāṟu vantu vauikaṇ ṭiṭavōṭip
paṇṇāmal niṉṟatu pārkkalu māmē`,
    english: `600: In Dhyana Can Be Seen the Jnana Form of Siva
In the undistracted gaze
Appears the Light
Gaze and gaze to heart's content
And mingle one with it;
The Heavenly Stream will then surge
To the spaces infinite of Void Vast;
Then may the Uncreated Being witnessed be.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-600-Third-Tantra-8.-Yoga-of-Meditation.mp3',
    elaborationTamil: `இரண்டு கண்களையும் மூடி மனதை ஒரு நிலைப்படுத்தி தியானம் செய்து ஞானக் கண்ணில் (புருவ மத்தியில்) உள்ள ஜோதியைப் பார்த்து அதிலேயே மனதை வைத்தால் தலைக்கு மேல் ஆகாய கங்கை பாய்வது போன்ற உணர்வுடன் தானே தோன்றிய சுயம்புவாகிய சிவனையும் பார்க்கலாம்.`,
  },
  {
    id: 602, tantraId: 3, verseNumber: 601,
    tamil: `ஒருபொழு துன்னார் உடலோ டுயிரை
ஒருபொழு துன்னார் உயிருட் சிவனை
ஒருபொழு துன்னார் சிவனுறை சிந்தையை
ஒருபொழு துன்னார் சந்திரப் பூவே`,
    transliteration: `orupoḻu tuṉṉār uṭalō ṭuyirai
orupoḻu tuṉṉār uyiruṭ civaṉai
orupoḻu tuṉṉār civaṉuṟai cintaiyai
orupoḻu tuṉṉār cantirap pūvē`,
    english: `601: Alas! They Perform not Dhyana
Even for once they meditate not
On the mystery of Jiva within body;
Even for once they meditate not
On Siva within Jiva;
Even for once they meditate not
On Divine Jnana within Siva;
Even once they meditate not
On the Lotus within the Lunar Sphere.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-601-Third-Tantra-8.-Yoga-of-Meditation.mp3',
    elaborationTamil: `உடலோடு கலந்துள்ள உயிரை ஒரு பொழுதும் நினைக்காதவர்கள் உயிருக்கு உயிராய் இருக்கும் சிவனை ஒரு பொழுதும் நினைக்காதவர்கள் சிவனின் மேல் சிந்தனையை ஒரு பொழுதும் வைக்காதவர்கள் நெற்றிக்கு நடுவில் உள்ள சக்தியை ஒரு பொழுதும் உணர மாட்டார்கள்.`,
  },
  {
    id: 603, tantraId: 3, verseNumber: 602,
    tamil: `மனத்து விளக்கினை மாண்பட ஏற்றிச்
சினத்து விளக்கினைச் செல்ல நெருக்கி
அனைத்து விளக்குந் திரியொக்கத் தூண்ட
மனத்து விளக்கது மாயா விளக்கே`,
    transliteration: `maṉattu viḷakkiṉai māṇpaṭa ēṟṟic
ciṉattu viḷakkiṉaic cella nerukki
aṉaittu viḷakkun tiriyokkat tūṇṭa
maṉattu viḷakkatu māyā viḷakkē`,
    english: `602: Dhyana Brightens All Lamps Within
Light the Lamp of Mind
And dispel the Darkness of Egoity;
Extinguish the Fire of Wrath
And brighten all lamps within
Thenceforth alike,
The Mind's Lamp is an undying Lamp indeed.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-602-Third-Tantra-8.-Yoga-of-Meditation.mp3',
    elaborationEnglish: `The Mind’s Lamp is an undying Lamp indeed. ° Dhyana is a lamp that lights all the lamps within. It lights the lamp of mind, dispels the darkness of egoity, extinguishes the fire of darkness. Then the main lamp (the mind’s lamp) burns undying.`,
    elaborationTamil: `தியானத்தின் மூலம் மனதில் இருக்கும் ஒளியை பிரகாசமாக மேல் நோக்கி செலுத்தி கோபமாகிய அக்கினியை வெளியே போகும்படி செய்து அனைத்தையும் அறிந்து இருக்கும் சிவ ஒளியை பற்றியிருக்கும் சுழுமுனை (முதுகுத்தண்டு) என்னும் திரியை தியானத்தின் மூலம் தூண்டிவிட மனதில் இருக்கும் சிவம் என்னும் ஓளி அணையாமல் இருக்கும்.`,
  },
  {
    id: 604, tantraId: 3, verseNumber: 603,
    tamil: `எண்ணா யிரத்தாண்டு யோகம் இருக்கினும்
கண்ணார் அமுதினைக் கண்டறி வாரில்லை
உண்ணாடிக் குள்ளே ஔியுற நோக்கினால்
கண்ணாடி போலக் கலந்துநின் றானே`,
    transliteration: `eṇṇā yirattāṇṭu yōkam irukkiṉum
kaṇṇār amutiṉaik kaṇṭaṟi vārillai
uṇṇāṭik kuḷḷē auiyuṟa nōkkiṉāl
kaṇṇāṭi pōlak kalantuniṉ ṟāṉē`,
    english: `603: Look Within in Dhyana
Well may they practise Yoga eight-thousand year
Still they see not Lord,
Sweet as ambrosia
And dear unto apple of eye;
But if within you seek Him enlightened
He within you is,
Even unto reflection in the mirror.`,
    elaborationEnglish: `Dhyana is seeking God within. It is seeing Siva’s reflection in the jiva mirror. All practice of yoga is vain without the secking within.`,
    elaborationTamil: `எண்ணிலடங்காத ஆண்டுகள் யோக நிலையில் இருந்தாலும் இறைவனை வெளியே கண்டு அறிந்தவர்கள் யாரும் இல்லை. உள்ளுக்குள் இருக்கும் சகஸ்ரதளத்திலுள்ள ஒளியின் மேல் எண்ணத்தை வைத்து தியானித்தால் கண்ணாடியில் உருவம் கலந்து இருப்பது போல உள்ளுக்குள் கலந்து இருக்கும் இறைவனை உணரலாம்.`,
  },
  {
    id: 605, tantraId: 3, verseNumber: 604,
    tamil: `நாட்டமும் இரண்டும் நடுமூக்கில் வைத்திடில்
வாட்டமும் இல்லை மனைக்கும் அழிவில்லை
ஓட்டமும் இல்லை உணர்வில்லை தானில்லை
தேட்டமும் இல்லை சிவனவ நாமே`,
    transliteration: `nāṭṭamum iraṇṭum naṭumūkkil vaittiṭil
vāṭṭamum illai maṉaikkum aḻivillai
ōṭṭamum illai uṇarvillai tāṉillai
tēṭṭamum illai civaṉava nāmē`,
    english: `604: Fruits of Dhyana
If your eyes twain are
On nasal point fixed,
No sorrows befall you;
Perishes not your body;
Agitation none shall you have;
Feelings none;
Seekings none;
None that is "I";
You and Siva one become.`,
    elaborationEnglish: `Therefore let the eyes be fixed on the tip of the nose. Let the roaming breath be retained within; so let the nadis be stilled. Then no more seeking; no fear of`,
    elaborationTamil: `இரண்டு கண்களையும் புருவ மத்தியிலுள்ள மூக்கின் நுனியில் வைத்து தியானம் செய்தால் உடலில் இருக்கும் சோர்வு நீங்கிவிடும். உடலுக்கு அழிவும் வராது. மனது ஒரு நிலையாக இருக்கும். உலக உணர்வு இருக்காது. தன்னை மறந்த நிலையில் உடல் இருக்கும். எதன் மீதும் நாட்டம் வராது. இந்த நிலையிலிருப்பவர்கள் சிவ நிலையில் இருப்பவர்களாவர்.`,
  },
  {
    id: 606, tantraId: 3, verseNumber: 605,
    tamil: `நயனம் இரண்டும் நாசிமேல் வைத்திட்
டுயர்வெழா வாயுவை உள்ளே அடக்கித்
துயரற நாடியே தூங்கவல் லார்க்குப்
பயனிது காயம் பயமில்லை தானே`,
    transliteration: `nayaṉam iraṇṭum nācimēl vaittiṭ
ṭuyarveḻā vāyuvai uḷḷē aṭakkit
tuyaraṟa nāṭiyē tūṅkaval lārkkup
payaṉitu kāyam payamillai tāṉē`,
    english: `605: Dhyana Leads to Cessation of Birth
Fixing the gaze on nasal point
Retaining the roaming breath within
They who can thus still the nadis,
Will sure reach the Goal
No fear of birth to be for them.`,
    elaborationTamil: `இரண்டு கண்களையும் புருவ மத்தியிலுள்ள மூக்கின் மேல் வைத்து உள்ளிழுத்த மூச்சுக்காற்றை வெளியே விடாமல் அடக்கி வைத்து கர்மாவினால் வரும் உடல் மற்றும் மன துன்பங்கள் நீங்க வேண்டி தியானம் செய்தால் அதன் பயனாக உடலுக்குத் துன்பம் எதுவும் வராது. மனதில் எந்த பயமும் இருக்காது.`,
  },
  {
    id: 607, tantraId: 3, verseNumber: 606,
    tamil: `மணிகடல் யானை வார்குழல் மேகம்
அணிவண்டு தும்பி வளைபேரி கையாழ்
தணிந்தெழு நாதங்கள் தாமிவை பத்தும்
பணிந்தவர்க் கல்லது பார்க்கஒண் ணாதே`,
    transliteration: `maṇikaṭal yāṉai vārkuḻal mēkam
aṇivaṇṭu tumpi vaḷaipēri kaiyāḻ
taṇinteḻu nātaṅkaḷ tāmivai pattum
paṇintavark kallatu pārkkaoṇ ṇātē`,
    english: `606: Varied Sound Experiences in Dhyana
Bell, sea, elephant, flute, cloud
Bee, dragon-fly, conch, drum, and lute
The subtle sounds of these ten are heard
For them alone
Who have stilled their mind in God.`,
    elaborationTamil: `தியானம் செய்வதால் உள்ளுக்குள் கேட்கக்கூடிய பத்துவித ஓசைகளாகிய 1. மணியோசை 2. கடல் அலையோசை 3. யானை பிளிறும் ஓசை 4. புல்லாங்குழலோசை 5. இடியோசை 6. வண்டின் ரீங்கார ஓசை 7. தும்பியின் முரலோசை 8. சங்கொலி 9. பேரிகை ஓசை 10. யாழிசை ஆகிய ஓசைகள் அனைத்தும் சிவனை பணிந்து தியானம் செய்பவர்களுக்கு மட்டுமே உருவாகும்.`,
  },
  {
    id: 608, tantraId: 3, verseNumber: 607,
    tamil: `கடலொடு மேகங் களிறொடும் ஓசை
அடவெழும் வீணை அண்டரண் டத்துச்
சுடர்மன்னு வேணுச் சுரிசங்கின் ஓசை
திடமறி யோகிக்கல் லாற்றெறி யாதே`,
    transliteration: `kaṭaloṭu mēkaṅ kaḷiṟoṭum ōcai
aṭaveḻum vīṇai aṇṭaraṇ ṭattuc
cuṭarmaṉṉu vēṇuc curicaṅkiṉ ōcai
tiṭamaṟi yōkikkal lāṟṟeṟi yātē`,
    english: `607: Other Sound Experiences in Dhyana
The roar of sea, the thundering of cloud,
The trumpeting of elephant, the euphony of lute,
The music of the orbs
That glow in firmament vast,
The melody of the flute; the resonance of conch,
All these
The yogi true alone hears.`,
    elaborationTamil: `கடலின் அலையோசை மேகத்தின் இடியோசை யானை பிளிறும் ஓசை ஆகிய வன்மையான ஓசைகளில் ஆரம்பித்து வீணையின் ஓசை அண்டமெல்லாம் கலந்து இருக்கும் ஓம் எனும் ஓசை புல்லாங்குழலின் மெல்லிய ஓசை சிறிய துளையுடைய சங்கொலி ஆகிய மென்மையான ஓசைகளில் முடியும் இந்த ஓசைகளை மன உறுதியோடு தியானம் செய்யும் யோகியர்களால் மட்டுமே அறிந்துகொள்ள முடியும்.`,
  },
  {
    id: 609, tantraId: 3, verseNumber: 608,
    tamil: `ஈசன் இயல்பும் இமையவர் ஈட்டமும்
பாசம் இயங்கும் பரிந்துய ராய்நிற்கும்
ஓசை யதன்மணம் போல விடுவதோர்
ஓசையாம் ஈசன் உணரவல் லார்க்கே`,
    transliteration: `īcaṉ iyalpum imaiyavar īṭṭamum
pācam iyaṅkum parintuya rāyniṟkum
ōcai yataṉmaṇam pōla viṭuvatōr
ōcaiyām īcaṉ uṇaraval lārkkē`,
    english: `608: Fruits of God-Realization
Those who realize God,
They alone get qualities godly;
They join company of immortals;
Pasa vanishes;
They become immanent in all life
They hear sounds subtlest,
That emanate
Unto fragrance out of flower.`,
    elaborationTamil: `மனதை ஒருநிலைப்படுத்தி தியானம் செய்து சிவபெருமானை உணரக் கூடியவர்களின் உள்ளிருந்து வெளிவரும் ஓசையானது பூவிலிருந்து வெளிவரும் நறுமணம் போலவும் சிவபெருமானின் ஓசை என்னும் சொரூபமாகவும் தேவர்கள் முதலிய அனைத்து உயிர்களுக்குள்ளும் பாசம் என்னும் உணர்வாகவும் அந்தப் பாசத்தின் கருணையால் உயிருக்கு உயிராகவும் கலந்து நிற்கும்.`,
  },
  {
    id: 610, tantraId: 3, verseNumber: 609,
    tamil: `நாத முடிவிலே நல்லாள் இருப்பது
நாத முடிவிலே நல்யோகம் இருப்பது
நாத முடிவிலே நாட்டம் இருப்பது
நாத முடிவிலே நஞ்சுண்ட கண்டனே`,
    transliteration: `nāta muṭivilē nallāḷ iruppatu
nāta muṭivilē nalyōkam iruppatu
nāta muṭivilē nāṭṭam iruppatu
nāta muṭivilē nañcuṇṭa kaṇṭaṉē`,
    english: `609: Yoga Leads to Nadanta
Nada's End is Sakti divine
Nada's End is Yoga goodly
Nada's End is goal Finale
Nada's End is Lord Seated.`,
    elaborationTamil: `தியானத்தினால் உள்ளிருந்து வெளிவரும் ஓசையின் இறுதியில் உண்மை என்னும் இறை சக்தியை உணரலாம். நல்ல யோகத்தினால் இறைவனுடன் கலந்து இருப்பதை உணரலாம். இறைவனைத் தவிர வேறு சிந்தனை இருக்காது. கர்மங்கள் நீங்கித் தூய்மையான சிவனை உணரலாம்.`,
  },
  {
    id: 611, tantraId: 3, verseNumber: 610,
    tamil: `உதிக்கின்ற ஆறினும் உள்ளங்கி ஐந்துந்
துதிக்கின்ற தேசுடைத் தூங்கிருள் நீங்கி
அதிக்கின்ற ஐவருள் நாதம் ஒடுங்கக்
கதிக்கொன்றை ஈசன் கழல்சேர லாமே`,
    transliteration: `utikkiṉṟa āṟiṉum uḷḷaṅki aintun
tutikkiṉṟa tēcuṭait tūṅkiruḷ nīṅki
atikkiṉṟa aivaruḷ nātam oṭuṅkak
katikkoṉṟai īcaṉ kaḻalcēra lāmē`,
    english: `610: Involution Into Nada is Final Stage
As Kundalini Fire glows in Adharas six,
The Primordial Anava Darkness flees,
In tameness followed by Indriyas Five;
Who involute in Tanmatras, their substrate;
And they in turn in Nada;
Then shall you reach Feet of Lord
That is Refuge of All.`,
    elaborationTamil: `தியானத்தினால் ஆறு சக்கரத்திலும் அடங்கியிருக்கும் குண்டலினி சக்தியிலிருந்து வெளிவரும் ஐந்து வகை அக்கினிகளான மூலாக்கினி, வடவாக்கினி, மின்னல் அக்கினி, கதிராவன் அக்கினி, திங்கள் அக்கினி ஆகியவை பிரகாசிக்கும் போது மும்மலங்களான ஆணவம், கன்மம், மாயை ஆகிய இருள்கள் நீங்கும். அதன்பின் ஐந்து புலன்களாகிய சுவைத்தல், பார்த்தல், கேட்டல், முகர்தல், தொடுதல் ஆகிய உணர்வுகள் நீங்கப் பெற்று சிவபெருமானை அடையலாம்.`,
  },
  {
    id: 612, tantraId: 3, verseNumber: 611,
    tamil: `பள்ளி அறையிற் பகலே இருளில்லை
கொள்ளி அறையிற் கொளுந்தாமற் காக்கலாம்
ஒள்ளி தறியிலோ ரோசனை நீளிது
வெள்ளி அறையில் விடிவில்லை தானே`,
    transliteration: `paḷḷi aṟaiyiṟ pakalē iruḷillai
koḷḷi aṟaiyiṟ koḷuntāmaṟ kākkalām
oḷḷi taṟiyilō rōcaṉai nīḷitu
veḷḷi aṟaiyil viṭivillai tāṉē`,
    english: `611: The Way to Ascension to Void lies through Meditation
The mystic bed-chamber is day-light eternal
No darkness invades;
There is a way
This body to fire-chamber consigned not be;
The light of this knowledge
Is by meditation prolonged;
The Chamber of Void
Knows not end of Light ever.`,
    elaborationTamil: `தியானம் செய்பவர்களுக்கு உள்ளம் ஒளிமயமாக இருக்கும். அங்கே இருள் கிடையாது. அவர்களுக்கு மரணம் பற்றிய பயம் இருக்காது. இந்த நுண்ணறிவைப் பெற்ற யோகியர்கள் தங்களுக்குள் காணும் உள்ளொளி ஒரு யோசனை தூரம் பரவியிருக்கும். அந்த ஒளிமயமான வெள்ளி அறையாகிய மனதில் பயத்திற்கு இடமிருக்காது.`,
  },
  {
    id: 613, tantraId: 3, verseNumber: 612,
    tamil: `கொண்ட விரதங் குறையாமற் றானொன்றித்
தண்டுடன் ஓடித் தலைப்பட்ட யோகிக்கு
மண்டல மூன்றினும் ஒக்க வளர்ந்தபின்
பிண்டமும் ஊழி பிரியா திருக்குமே`,
    transliteration: `koṇṭa virataṅ kuṟaiyāmaṟ ṟāṉoṉṟit
taṇṭuṭaṉ ōṭit talaippaṭṭa yōkikku
maṇṭala mūṉṟiṉum okka vaḷarntapiṉ
piṇṭamum ūḻi piriyā tirukkumē`,
    english: `612: Perfect Meditation Leads to Immortality
Having abated not in the rules of vows,
The Yogi that has to meditate learned,
Coursing Kundalini through spinal column,
And passing Mandalas Three with felicity equal
He in fleshly body forever lives.`,
    elaborationTamil: `யோகியர்கள் தாங்கள் எடுத்துக் கொண்ட வைராக்கியம் குறையாமல் தியானத்தில் ஒன்றியபடி இருந்தால் மூலாதார அக்கினியும், ஆக்ஞா சந்திரனும், சகஸ்ரதள சூரியனும் ஆகிய மூன்றும் ஒரு சேர வளர்ந்து முதுகுத்தண்டு வழியாக குண்டலினியை மேலே ஏற்றினால் அவர்களின் உடல் உயிரை விட்டு பிரியாது நிலைத்து இருக்கும்.`,
  },
  {
    id: 614, tantraId: 3, verseNumber: 613,
    tamil: `அவ்வவர் மண்டல மாம்பரி சொன்றுண்டு
அவ்வவர் மண்டலத் தவ்வவர் தேவராம்
அவ்வவர் மண்டலம் அவ்வவர்க் கேவரில்
அவ்வவர் மண்டல மாயமற் றோர்க்கே`,
    transliteration: `avvavar maṇṭala māmpari coṉṟuṇṭu
avvavar maṇṭalat tavvavar tēvarām
avvavar maṇṭalam avvavark kēvaril
avvavar maṇṭala māyamaṟ ṟōrkkē`,
    english: `613: Meditation Leads Across the Three Spheres
There is a way of reaching the Mandalas Three.
In each is its respective God;
Be you blessed
By the God appropriate
Then each Mandala leads to the other.`,
    elaborationTamil: `தலை உச்சியிலுள்ள சகஸ்ரதள சூரியனுக்கு பிரம்மாவும் நெற்றிக்கு நடுவிலுள்ள ஆக்ஞா சந்திரனுக்கு விஷ்ணுவும் மூலாதார அக்கினிக்கு உருத்திரனும் தலைவர்களாக இருக்கின்றார்கள். அவர்களை அவர்கள் இருக்கும் இடத்திலேயே வைத்து தியானிப்பவர்களுக்கு தியானம் கைகூட அவர்கள் உதவுவார்கள்.`,
  },
  {
    id: 615, tantraId: 3, verseNumber: 614,
    tamil: `இளைக்கின்ற நெஞ்சத் திருட்டறை உள்ளே
முளைக்கின்ற மண்டலம் மூன்றினும் ஒன்றித்
துளைப்பெரும் பாசந் துருவிடு மாகில்
இளைப்பின்றி மார்க்கழி ஏற்றம தாமே`,
    transliteration: `iḷaikkiṉṟa neñcat tiruṭṭaṟai uḷḷē
muḷaikkiṉṟa maṇṭalam mūṉṟiṉum oṉṟit
tuḷaipperum pācan turuviṭu mākil
iḷaippiṉṟi mārkkaḻi ēṟṟama tāmē`,
    english: `614: To Transcend Mandalas is to be Exalted
In the dark chamber of the drooping heart
Are the Mandalas Three,
He who becomes one with them
And peirces Pasas
Shall know weariness none;
To transcend the three stages of heart
Is exaltation exceeding indeed.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-614-Third-Tantra-8.-Yoga-of-Meditation.mp3',
    elaborationTamil: `அறியாமை என்னும் மாயையால் மனம் தளர்ந்து இருளாக இருக்கின்றது. அந்த இருள் நீங்க மூன்று சக்கரங்களிலும் (மூலாதாரம், ஆக்ஞா, சகஸ்ரதளம்) தியானம் செய்து முதுகுத்தண்டு வழியாக குண்டலினியை மேலே ஏற்றி அறியாமை நீங்கப் பெறலாம். அப்படிச் செய்தால் மும்மலங்களான ஆணவம், கன்மம், மாயை ஆகிய இருள்கள் நீங்கி ஏற்றம் பெறலாம்.`,
  },
  {
    id: 616, tantraId: 3, verseNumber: 615,
    tamil: `முக்குண மூடற வாயுவை மூலத்தே
சிக்கென மூடித் திரித்துப் பிடித்திட்டுத்
தக்க வலமிடம் நாழிகை சாதிக்க
வைக்கும் உயிர்நிலை வானவர் கோனே`,
    transliteration: `mukkuṇa mūṭaṟa vāyuvai mūlattē
cikkeṉa mūṭit tirittup piṭittiṭṭut
takka valamiṭam nāḻikai cātikka
vaikkum uyirnilai vāṉavar kōṉē`,
    english: `615: Immortality Through Dhyana Yoga
Uprooting the gunas three
He who controlls breath in Muladhara
And courses it alternate
Through nadi left and right,
In time measure prescribed
Will be immortal made
By Him that is King of Beings Heavenly.`,
    elaborationEnglish: `By Him that is King of Beings Heavenly.`,
    elaborationTamil: `மூன்று குணங்களான இராஜசம் (கோபம்) தாமசம் (சமரசம்) சாத்வீகம் (சாந்தம்) ஆகியவற்றால் ஏற்படும் மாயை என்னும் இருள் நீங்க தினமும் அதிகாலையில் ஒரு நாழிகை (24 நிமிஷம்) நேரம் மூலாதாரத்திலுள்ள காற்றை இடகலை பிங்கலை நாடிகள் (பாடல் #567 இல் உள்ளபடி) வழியாக மூச்சுப்பயிற்சி செய்தால் உடம்பில் உயிரை அழியாது சிவபெருமான் வைப்பார்.`,
  },
  {
    id: 617, tantraId: 3, verseNumber: 616,
    tamil: `நடலித்த நாபிக்கு நால்விரன் மேலே
மடலித்த வாணிக் கிருவிரல் உள்ளே
கடலித் திருந்து கருதவல் லார்கள்
சடலத் தலைவனைத் தாமறிந் தாரே`,
    transliteration: `naṭalitta nāpikku nālviraṉ mēlē
maṭalitta vāṇik kiruviral uḷḷē
kaṭalit tiruntu karutaval lārkaḷ
caṭalat talaivaṉait tāmaṟin tārē`,
    english: `616: Deep Meditation on Centers Leads to God
Four finger-length above the tremulous Navel-Center
Is the petalled Heart-Center;
Two finger length still above is the Throat-Center;
Those who can meditate on it in sea-like depth
Sure knew Him;
Him the Lord of Body Corporal.`,
    elaborationEnglish: `When the yogi shifts his centre of thought from the muladhara to the anahata (heart centre), and from anahata to the vishuddhi (throat centre), then he transcends the 36 tattvas, and becomes united with God.`,
    elaborationTamil: `தொப்புள் குழியிலிருந்து நாலு அங்குலத்திற்கு மேலும் நெஞ்சுக்குழிக்கு இரண்டு அங்குலத்திற்கு உள்ளேயும் உள்ள இடத்தில் மனதை வைத்துத் தியானம் செய்யக் கூடியவர்களுக்கு அங்கே இருக்கும் உடலின் தலைவனான இறைவனை அறிய முடியும்.`,
  },
  {
    id: 618, tantraId: 3, verseNumber: 617,
    tamil: `அறிவாய சத்தென்னு மாறா றகன்று
செறிவான மாயை சிதைத்தரு ளாலே
பிறியாத பேரரு ளாயிடும் பெற்றி
நெறியான அன்பர் நிலையறிந் தாரே`,
    transliteration: `aṟivāya catteṉṉu māṟā ṟakaṉṟu
ceṟivāṉa māyai citaittaru ḷālē
piṟiyāta pēraru ḷāyiṭum peṟṟi
neṟiyāṉa aṉpar nilaiyaṟin tārē`,
    english: `617: Grace Comes From Dhyana
Transcending Tattvas six and thirty unreal,
Destroying Maya's layers thick,
Transformed into Jnana Pure by Grace
Themselves that Grace inseparable Becoming
They who achieved thus
Were the goodly souls
The Way of Dhyana knew.`,
    elaborationTamil: `மனம் தியானத்தில் நிலைக்கப் பெற்றால் நிலையில்லாத முப்பத்தாறு தத்துவங்கள் நீங்குவதை உணரலாம். வலிமையான மாயை சிவனருளாலே அழியும். அந்த சிவபெருமானை விட்டு என்றும் பிரியாதிருக்கும் பேரருளைப் பெற்றிடலாம். தியானத்தின் வழியை விட்டு விலகாமல் செல்பவர்கள் இந்த நிலையை உணர்ந்திடலாம். குறிப்பு: திருமந்திரம் – பாடல் #467 ல் முப்பத்தாறு தத்துவங்கள் பற்றி அறிந்து கொள்ளலாம். https://www.kvnthirumoolar.com/பாடல்-467/`,
  },
  {
    id: 619, tantraId: 3, verseNumber: 618,
    tamil: `சமாதி யமாதியிற் றான்செல்லக் கூடும்
சமாதி யமாதியிற் றானெட்டுச் சித்தி
சமாதி யமாதியில் தங்கினோர்க் கன்றே
சமாதி யமாதி தலைப்படுந் தானே`,
    transliteration: `camāti yamātiyiṟ ṟāṉcellak kūṭum
camāti yamātiyiṟ ṟāṉeṭṭuc citti
camāti yamātiyil taṅkiṉōrk kaṉṟē
camāti yamāti talaippaṭun tāṉē`,
    english: `618: Samadhi is the Final Goal of Ashtanga Yoga
Samadhi is end of Iyama and the rest
Samadhi is consummation of Siddhis eight
Who persevere in the path from Iyama to the end
Will alone the end Samadhi attain.`,
    elaborationEnglish: `Samadhi is the final stage in the eight-limbed “yoga commencing from yama through niyama, asana, pranayama, pratyahara, dharana, and dhyana. When it is attained, the miraculous powers (siddhis) come to the yogi of themselves.`,
    elaborationTamil: `; அட்டாங்க யோகத்தில் கூறியுள்ள இயமம் முதலான ஏழு யோகங்களையும் (பாடல் #549 இல் உள்ளபடி) முறையாக செய்வது மட்டுமன்றி அந்த யோகங்களையும் தவறாமல் கடைபிடித்தால் எட்டாவது யோகமான சமாதியும் கைகூடும். அவ்வாறு கைகூடிவிட்டால் எட்டுவித சித்திகளும் கைவரப் பெறும்.`,
  },
  {
    id: 620, tantraId: 3, verseNumber: 619,
    tamil: `விந்துவும் நாதமும் மேருவில் ஓங்கிடிற்
சந்தியி லான சமாதியிற் கூடிடும்
அந்த மிலாத அறிவின் அரும்பொருள்
சுந்தரச் சோதியுந் தோன்றிடுந் தானே`,
    transliteration: `vintuvum nātamum mēruvil ōṅkiṭiṟ
cantiyi lāṉa camātiyiṟ kūṭiṭum
anta milāta aṟiviṉ arumporuḷ
cuntarac cōtiyun tōṉṟiṭun tāṉē`,
    english: `619: Vision of Light Resplendent in Samadhi
When in the Meru Peak of Sahasrara
Bindu and Nada flourish
In their union will Samadhi be;
And the Light Resplendent of Endless Jnana
Will then visioned be!`,
    elaborationEnglish: `Samadhi is to reach the Meru peak of sahasrara, where bindu and nada flourish, and to unite in them. It is to vision the light resplendent of endless jnana.`,
    elaborationTamil: `; சக்தியாகிய ஒளியையும் சிவமாகிய ஒலியையும் புருவமத்தியில் ஒருமுகப்படுத்தி ஆழ்ந்து இருந்தால் அட்டாங்க யோகத்தின் இறுதியான சமாதி கைகூடும். அவ்வாறு சமாதி நிலையை அடைந்துவிட்டால் அழிவில்லாத அறிவின் உண்மைப் பொருளான சிவம் அழகிய ஜோதியாய் தமக்குள்ளேயே தோன்றிடும்.`,
  },
  {
    id: 621, tantraId: 3, verseNumber: 620,
    tamil: `மன்மனம் எங்குண்டு வாயுவும் அங்குண்டு
மன்மனம் எங்கில்லை வாயுவும் அங்கில்லை
மன்மனத் துள்ளே மகிழ்ந்திருப் பார்க்கு
மன்மனத் துள்ளே மனோலய மாமே`,
    transliteration: `maṉmaṉam eṅkuṇṭu vāyuvum aṅkuṇṭu
maṉmaṉam eṅkillai vāyuvum aṅkillai
maṉmaṉat tuḷḷē makiḻntirup pārkku
maṉmaṉat tuḷḷē maṉōlaya māmē`,
    english: `620: In Samadhi Mano-Laya is Reached
Where there is mind absorption,
There life's breath is;
Where there is mind absorption none,
There life none is;
They who, in rapture, sit in mind absorption
Are verily fixed in Yoga of absorption.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-620-Third-Tantra-9.-Yoga-of-Liberation.mp3',
    elaborationEnglish: `Through samadhi, manolaya is attained; all things are absorbed in unitive consciousness.`,
    elaborationTamil: `; இறைவனையே சிந்தித்திருக்கும் மனம் எங்கிருக்கின்றதோ அங்கு பிராணவாயு நிலைத்து இருக்கும். இறைவனை சிந்திக்காத மனம் எங்கிருக்கின்றதோ அங்கு பிராணவாயு நிலைத்து இருக்காது. இறைவனையே நினைத்து பேரானந்தத்தில் இருப்பவர்களின் மனதோடு இறைவனும் கலந்து இருப்பான்.`,
  },
  {
    id: 622, tantraId: 3, verseNumber: 621,
    tamil: `விண்டலர் கூபமும் விஞ்சத் தடவியுங்-
கண்டுணர் வாகக் கருதி யிருப்பர்கள்
செண்டு வௌியிற் செழுங்கிரி யத்திடை
கொண்டு குதிரை குசைசெறுத் தாரே`,
    transliteration: `viṇṭalar kūpamum viñcat taṭaviyuṅ-
kaṇṭuṇar vākak karuti yirupparkaḷ
ceṇṭu vauிyiṟ ceḻuṅkiri yattiṭai
koṇṭu kutirai kucaiceṟut tārē`,
    english: `621: Mystic Vision in Samadhi
They who sit in Samadhi of Pure Consciousness
Vision the Mystic Woods and the Blooming Pond;
They roam in the royal expanse of space
And there at the foot of Fertile Mountain Meru,
They bridled their Horse of Breath to a stop.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-621-Third-Tantra-9.-Yoga-of-Liberation.mp3',
    elaborationTamil: `குதிரையில் ஏறி பல இடங்களைச் சுற்றிப் பார்த்து புல்வெளியில் ஓடவிட்டு பின்பு குதிரையை பசுமையான மலையடிவாரத்தில் கட்டி வைப்பது போல மனமாகிய குதிரையை பிராணவாயுவாகிய கடிவாளத்தின் மூலம் மேல் நோக்கி செலுத்தி சுழுமுனை சேரும் இடத்தையும் அதைச் சுற்றியுள்ள தலை உச்சியையும் சுற்றிப் பார்த்துவிட்டு தலை உச்சிக்கு மேலுள்ள வெற்று வெளியில் செலுத்தி அங்கே வியாபித்திருக்கின்ற சிவபெருமானிடம் கட்டி வைத்து அதன் மூலம் இறைவனை கண்டு உணர்ந்து இறை நினைப்பிலேயே லயித்து இருப்பது சமாதி நிலை ஆகும்.`,
  },
  {
    id: 623, tantraId: 3, verseNumber: 622,
    tamil: `மூல நாடி முகட்டல குச்சியுள்
நாலு வாசல் நடுவுள் இருப்பிர்காள்
மேலை வாசல் வௌியுறக் கண்டபின்
காலன் வார்த்தை கனாவிலும் இல்லையே`,
    transliteration: `mūla nāṭi mukaṭṭala kucciyuḷ
nālu vācal naṭuvuḷ iruppirkāḷ
mēlai vācal vauiyuṟak kaṇṭapiṉ
kālaṉ vārttai kaṉāvilum illaiyē`,
    english: `622: In Samadhi They Vision the Void
On top of Spinal Column in the Center
Is built a habitation unique;
Three the compartments it has
Four the doors;
Within these they sit (in Samadhi);
When through the door on top
They vision the Void
No more the word Death, aye, not even in dream.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-622-Third-Tantra-9.-Yoga-of-Liberation.mp3',
    elaborationEnglish: `On the top of the central spinal column is a habitat. It has three compartments (spheres of sun, moon and fire) and four doors (the cavities where the three nadis, ida, pingala and sushumaa, end and the fourth cavity of brahmarandra, or the final entrance to sahasrara). In samadhi the yogi visions the vast Space through the fourth door.`,
    elaborationTamil: `மூலாதாரத்திருந்து தலை உச்சிக்குச் செல்லும் பாதையின் நடுவில் இருக்கும் கண், காது, மூக்கு, நாக்கு ஆகிய நான்கு உணர்வுகளும் ஒன்று கூடி இருக்கும் புருவ மத்தியில் மனதை வைத்து தலைக்கு உச்சியிலுள்ள சகஸ்ரதளத்திற்கு மேலே அண்ட வெளியில் வியாபித்திருக்கும் சிவபெருமானைத் தரிசித்தப் பிறகு இறப்பு எனும் எண்ணம் கனவிலும் இல்லை.`,
  },
  {
    id: 624, tantraId: 3, verseNumber: 623,
    tamil: `மண்டலம் ஐந்து வரைகளும் ஈராறு
கொண்டிட நிற்குங் குடிகளும் ஆறெண்மர்
கண்டிட நிற்குங் கருத்து நடுவாக
உண்டு நிலாவிடும் ஓடும் பதத்தையே`,
    transliteration: `maṇṭalam aintu varaikaḷum īrāṟu
koṇṭiṭa niṟkuṅ kuṭikaḷum āṟeṇmar
kaṇṭiṭa niṟkuṅ karuttu naṭuvāka
uṇṭu nilāviṭum ōṭum patattaiyē`,
    english: `623: Vision Lord's Dance in Samadhi
Five the Mystic Regions,
Eight the Mountain Ranges,
Six the Adhara tribes that hold them;
With thought centered on Him
They well see Him there stand;
Partaking of the Grace of His Dancing Feet
They shall immortal be.`,
    elaborationTamil: `தியான நிலையில் பஞ்ச பூதங்களான ஐந்து மண்டலங்கள், அவைகள் இருக்கும் பன்னிரண்டு இடங்கள் ஆறு ஆதாரச் சக்கரங்களில் உள்ள அட்சரங்களை இடமாகக் கொண்ட நாற்பத்தெட்டு தேவதைகள் அனைத்தும் காணலாம். அவைகள் அனைத்திற்கும் நடுவில் ஓடும் இறைவன் மேல் மனதை ஒருமுகப்படுத்தினால் சமாதி அடையலாம். ஐந்து மண்டலங்கள்: 1. பிருத்வி மண்டலம் – நிலம் 2. அப்பு மண்டலம் – நீர் 3. ஆகாய மண்டலம் – வானம் 4. வாயு மண்டலம் – காற்று 5. தேயு மண்டலம் – நெருப்பு பன்னிரண்டு இடங்கள்: 1. மூலாதாரம் 2. சுவாதிஷ்டானம் 3. மணிப்பூரகம் 4. அநாகதம் 5. விசுத்தி 6. அண்ணம் (வாயின் உட்புற மேல்பகுதி) 7. ஆக்ஞா 8. சகஸ்ரதளம் 9. சிரசுக்கு மேலிடம் 10. துவாதசாந்தம் ஆகிய சித்தாந்த சரவெளிகளும் (அறிவிற்கு உட்பட்ட இடம்), அதற்கு மேலுள்ள பரவெளியிலுள்ள இரண்டு ஆதாரங்களான தியானபிந்துவும் ஆகும்.`,
  },
  {
    id: 625, tantraId: 3, verseNumber: 624,
    tamil: `பூட்டொத்து மெய்யிற் பொறிபட்ட வாயுவைத்
தேட்டற்ற வந்நிலஞ் சேரும் படிவைத்து
நாட்டத்தை மீட்டு நயனத் திருப்பார்க்குத்
தோட்டத்து மாம்பழந் தூங்கலு மாமே`,
    transliteration: `pūṭṭottu meyyiṟ poṟipaṭṭa vāyuvait
tēṭṭaṟṟa vannilañ cērum paṭivaittu
nāṭṭattai mīṭṭu nayaṉat tiruppārkkut
tōṭṭattu māmpaḻan tūṅkalu māmē`,
    english: `624: Samadhi Leads to Siva
Within the locked body
Is trapped the life-breath;
Course it to the Land
That no desire knows;
They who fix their gaze on Goal True
Will reach the Mango Fruit
That in the garden there hangs.`,
    elaborationTamil: `கட்டுப்பாடின்றி உடம்பின் மேலும் கீழும் செல்லும் பிராணவாயுவை வீட்டைப் பூட்டி வீட்டை தன் கட்டுப்பாட்டில் வைப்பது போல உடம்பினுள் பிராணவாயுவைக் கட்டுப்படுத்தி வைத்து ஆசைப்பட்டு வெளியே அலையும் மனதை ஒருமுகப்படுத்தி வெளியில் பார்க்கும் பார்வையை உள் நோக்கி செலுத்தி தியானத்தில் அமர்ந்திருந்தால் மாம்பழமும் இனிப்பும் போன்று இறைவனுடன் ஒன்றி சமாதியில் இருக்கலாம்.`,
  },
  {
    id: 626, tantraId: 3, verseNumber: 625,
    tamil: `உருவறி யும்பரி சொன்றுண்டு வானோர்
கருவரை பற்றிக் கடைந்தமு துண்டார்
அருவரை யேறி அமுதுண்ண மாட்டார்
திருவரை யாமனந் தீர்ந்தற்ற வாறே`,
    transliteration: `uruvaṟi yumpari coṉṟuṇṭu vāṉōr
karuvarai paṟṟik kaṭaintamu tuṇṭār
aruvarai yēṟi amutuṇṇa māṭṭār
tiruvarai yāmaṉan tīrntaṟṟa vāṟē`,
    english: `625: Ambrosia in Samadhi Leads to God
There is a way to vision the Lord,
The Celestial Beings churned
But with the mountain dark,
And partook of ambrosia;
But they climbed not
The heights of the Mystic Mountain
And partook not of ambrosia there flows,
For, they possess not
The unwavering mind
That soars in Samadhi high.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-625-Third-Tantra-9.-Yoga-of-Liberation.mp3',
    elaborationEnglish: `ach of ambrosia. But they did not think of the ambrosia » within. Only the yogi in samadhi finds it. In thi, with breath halted, the yogi becomes one with God.`,
    elaborationTamil: `உயிர்களுக்கு தியானத்தின் மூலம் உண்மை நிலையை அறிந்து கொள்ளும் வாய்ப்பு திருவருளால் பரிசாக உள்ளது. இது தேவர்களுக்கும் கிடைக்காதது. குண்டலினியினை சிரசில் ஏற்றி தியானித்திருந்தால் உச்சியில் அமுதம் ஊறும். அவ்வமுதினை உண்போர்க்கு முடிவில்லாத ஆசை கொண்ட மனம் அடங்கப்பெற்று சமாதி நிலை வாய்க்கும். இந்த முறை அறியாத தேவர்கள் திருப்பாற்கடலைக் கடைந்து அமுது உண்டார்கள். தேவர்கள் பாற்கடல் கடைந்து எடுத்த அமுதை விட நாம் தியானம் செய்து உச்சியில் ஊறச்செய்யும் அமுதம் உயர்வானது.`,
  },
  {
    id: 627, tantraId: 3, verseNumber: 626,
    tamil: `நம்பனை யாதியை நான்மறை ஓதியைச்
செம்பொனின் உள்ளே திகழ்கின்ற சோதியை
அன்பினை யாக்கி யருத்தி ஒடுக்கிப்போய்க்
கொம்பேறிக் கும்பிட்டுக் கூட்டமிட் டாரே`,
    transliteration: `nampaṉai yātiyai nāṉmaṟai ōtiyaic
cempoṉiṉ uḷḷē tikaḻkiṉṟa cōtiyai
aṉpiṉai yākki yarutti oṭukkippōyk
kompēṟik kumpiṭṭuk kūṭṭamiṭ ṭārē`,
    english: `626: In Samadhi Oneness in God is Attained
He is our Own
He is the Primal One
He taught the Vedas Four
He is the light that glows within the purest gold
They adored Him in love
They approached Him all desires devoid
And climbed the Mystic Tree High;
Their breath halted in Samadhi
They with Him became One.`,
    elaborationTamil: `நம்பிக்கைக்கு உரியவனும் முதற்பொருளாக விளங்குபவனும் நான்கு வேதங்களாலும் ஒதப்படுபவனும் தங்கத்தின் ஜொலிப்பு போல உள்ளே விளங்கும் சோதியும் ஆன சிவபெருமான் மீது அன்பு செலுத்தி ஆசைகளை அடக்கி மனதை சுழுமுனை வழியாக உச்சியில் ஏறுமாறு செய்து தலை உச்சியுள்ள சகஸ்ரதளத்தில் தியானித்திருந்தால் அங்கு இருக்கும் சிவபெருமானைக் வணங்கி அவனுடன் கலந்து இருக்கலாம்.`,
  },
  {
    id: 628, tantraId: 3, verseNumber: 627,
    tamil: `மூலத்து மேலது முச்சது ரத்தது
காலத் திசையிற் கலக்கின்ற சந்தினில்
மேலைப் பிறையினில் நெற்றிநேர் நின்ற
கோலத்தின் கோலங்கள் வெவ்வேறு கொண்டதே`,
    transliteration: `mūlattu mēlatu muccatu rattatu
kālat ticaiyiṟ kalakkiṉṟa cantiṉil
mēlaip piṟaiyiṉil neṟṟinēr niṉṟa
kōlattiṉ kōlaṅkaḷ vevvēṟu koṇṭatē`,
    english: `627: Vision of Mystic Moon in Samadhi
Beyond the Muladhara
Of triple angle shaped
Where Time and Space mingle,
Aloft that Center,
Opposite the forehead
Hangs the Crescent Moon,
Of myriad shape and peerless beauty.`,
    elaborationTamil: `மூலாதாரத்திற்கு மேலுள்ள சுவாதிஷ்டானத்தில் கும்பக முறைப்படி அடக்கி வைத்த மூச்சுக்காற்றை அதற்கு மேலுள்ள மணிப்பூரகத்தில் கலந்து பின்பு சுழுமுனை வழியே மேலே ஏற்றிச் சென்று புருவ மத்தியிலிருக்கும் ஆக்ஞா சக்கரத்துடன் சேர்த்தால் அங்கே நெற்றிக்கு நேரில் அண்டவெளி அழகிய வடிவங்களாக காட்சியளிக்கும். அந்தக் காட்சியுடன் மனதை ஒன்றி இருப்பது சமாதி நிலை ஆகும்.`,
  },
  {
    id: 629, tantraId: 3, verseNumber: 628,
    tamil: `கற்பனை யற்றுக் கனல்வழி யேசென்று
சிற்பனை எல்லாஞ் சிருட்டித்த பேரொளிப்
பொற்பினை நாடிப் புணர்மதி யோடுற்றுத்
தற்பர மாகத் தகுந்தண் சமாதியே`,
    transliteration: `kaṟpaṉai yaṟṟuk kaṉalvaḻi yēceṉṟu
ciṟpaṉai ellāñ ciruṭṭitta pēroḷip
poṟpiṉai nāṭip puṇarmati yōṭuṟṟut
taṟpara mākat takuntaṇ camātiyē`,
    english: `628: Union With Siva in Samadhi
Bereft of distracting thoughts
Ascending the way of Kundalini
Seeking the Creator that created all,
Him that is Light Beauteous,
Reaching the Mystic Moon in union
He becomes one with the Being Uncreated
--That, in sooth, is Samadhi's tranquility.`,
    elaborationEnglish: `Tranquillity in Samadhi

Samadhi attained, Siva is attained; Sakti too will be caught in its fold; Distracting passions will be dispelled; In equanimity perfect,

Will be the mind All this, for those who in ‘Samadhi sleep.

in the tranquillity that is attained in samadhi all distracting passions are dispelled. The mind attains perfect equanimity, and the Grace of Sakti flows unhindered.`,
    elaborationTamil: `எண்ணங்களைச் சிதறவிடாமல் மனதை ஒருமுகப்படுத்தி குண்டலினி சக்தியின் மேல் வைத்து அதை சுழுமுனை வழியே மேலேற்றிச் சென்று இந்த உலகையெல்லாம் அழகாக செதுக்கி உருவாக்கிய பேரொளியாகிய இறைவனின் பொன் போன்ற அழகிய பாதத்தை நாடி அறிவால் இறைவனை உணர்ந்து சிவமும் தாமும் இரண்டாக இல்லாமல் ஒன்றாகக் கலந்து இருத்தல் சமாதி நிலையாகும்.`,
  },
  {
    id: 630, tantraId: 3, verseNumber: 629,
    tamil: `தலைப்பட் டிருந்திடத் தத்துவங் கூடும்
வலைப்பட் டிருந்திடும் மாதுநல் லாளுங்
குலைப்பட் டிருந்திடுங் கோபம் அகலுந்
துலைப்பட் டிருந்திடுந் தூங்கவல் லார்க்கே`,
    transliteration: `talaippaṭ ṭiruntiṭat tattuvaṅ kūṭum
valaippaṭ ṭiruntiṭum mātunal lāḷuṅ
kulaippaṭ ṭiruntiṭuṅ kōpam akalun
tulaippaṭ ṭiruntiṭun tūṅkaval lārkkē`,
    english: `629: Tranquility in Samadhi
Samadhi attained, Siva is attained;
Sakti too will be caught in its fold;
Distracting passions will be dispelled;
In equanimity perfect,
Like unto a balance
Will be the mind
All this, for those who in Samadhi sleep.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-629-Third-Tantra-9.-Yoga-of-Liberation.mp3',
    elaborationTamil: `மனதை ஒருமுகப்படுத்தி இறை நினைப்பிலேயே ஒன்றி சமாதி நிலையில் இருக்கக் கூடியவர்களுக்கு தான் யார் என்பதை உணர்ந்து தனக்குள் இருக்கும் சிவமும் உலகங்களை இயக்கிக்கொண்டிருக்கும் சக்தியும் ஒன்றாக சேர்ந்து இருக்கும். மாயை நீங்கி அருள்சக்திக்கு எதிரான காமம், கோபம், அகங்காரம் அகன்றுவிடும்.`,
  },
  {
    id: 631, tantraId: 3, verseNumber: 630,
    tamil: `சோதித் தனிச்சுட ராய்நின்ற தேவனும்
ஆதியும் உள்நின்ற சீவனு மாகுமால்
ஆதிப் பிரமன் பெருங்கடல் வண்ணனும்
ஆதி அடிபணிந் தன்புறு வாரே`,
    transliteration: `cōtit taṉiccuṭa rāyniṉṟa tēvaṉum
ātiyum uḷniṉṟa cīvaṉu mākumāl
ātip piramaṉ peruṅkaṭal vaṇṇaṉum
āti aṭipaṇin taṉpuṟu vārē`,
    english: `630: Samadhi Leads to Worship by Gods
He stood as the Peerless Pillar of Light;
When Jiva in Samadhi merges in Him,
Brahma that creates
And Vishnu of the ocean-hue,
Both stand adoring him.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-630-Third-Tantra-9.-Yoga-of-Liberation.mp3',
    elaborationEnglish: `He who attains samadhi, merging in Siva, becomes the peerless Pillar of Light. Even Brahma and Vishnu worship him.`,
    elaborationTamil: `சமாதி நிலையில் நம்முடைய ஆன்மா ஈடு இணையில்லாத பேரொளியாய் விளங்கும் சிவபெருமானோடும் ஆதி சக்தியோடும் ஒன்றாகக் கலந்து விடும். அந்நிலையில் படைப்புக்கு முதல்வனான பிரமனும் கடல் போன்ற நீல நிற மேனியுடைய திருமாலும் ஆதிக்கடவுளான சிவபெருமானிடம் அடிபணிந்து அன்பு செலுத்துவதை நாம் உணரலாம்.`,
  },
  {
    id: 632, tantraId: 3, verseNumber: 631,
    tamil: `சமாதிசெய் வார்க்குத் தகும்பல யோகஞ்
சமாதிகள் வேண்டாம் இறையுட னேகிற்
சமாதிதா னில்லை தானவ னாகிற்
சமாதியில் எட்டெட்டுச் சித்தியும் எய்துமே`,
    transliteration: `camāticey vārkkut takumpala yōkañ
camātikaḷ vēṇṭām iṟaiyuṭa ṉēkiṟ
camātitā ṉillai tāṉava ṉākiṟ
camātiyil eṭṭeṭṭuc cittiyum eytumē`,
    english: `631: Samadhi Transcends Siddhis
To those who are in Samadhi
Many the Yogas that come of themselves
And the Siddhis eight that come unsought;
But, Samadhi none is for those who walk with God
Samadhi none is for those who become one in God.`,
    elaborationEnglish: `The yogi, who attains samadhi, does not seek the eight siddhis. He transcends them. He walks with God. He becomes one in God.

10. Gum FRUITS OF EIGHT-LIMBED YOGA`,
    elaborationTamil: `சமாதி நிலையை அடைபவர்களுக்கு பலவிதமான யோகங்களோடு அறுபத்து நான்கு விதமான சித்திகளும் கிடைக்கும். இறைவனுடன் ஒன்றாகக் கலந்து தாமே சிவமாகிய பின் சமாதி நிலையே தேவையில்லை.`,
  },
  {
    id: 633, tantraId: 3, verseNumber: 632,
    tamil: `போதுகந் தேறும் புரிசடை யானடி
யாதுகந் தாரம ராபதிக் கேசெல்வர்
ஏதுகந் தானிவன் என்றருள் செய்திடு
மாதுகந் தாடிடு மால்விடை யோனே`,
    transliteration: `pōtukan tēṟum puricaṭai yāṉaṭi
yātukan tārama rāpatik kēcelvar
ētukan tāṉivaṉ eṉṟaruḷ ceytiṭu
mātukan tāṭiṭu mālviṭai yōṉē`,
    english: `632: Lord's Devotees Reach Abode of Gods
They who seek Lord
Of the matted locks bedecked with flowers
Will sure reach Abode of Gods;
"What this devotee of mine seeks,
That I grant"
Thus blesses the Lord
That mounts the Bull
And dances to His Lady's delight.`,
    elaborationTamil: `காளையை வாகனமாகக் கொண்டவனும் உமையவள் காண ஆனந்த நடனம் புரிபவனும் அழகிய மலரின் நறுமனம் கமழும் படர்ந்த சடையுடையவனுமாகிய சிவபெருமானின் திருவடிகள் எப்படி இருக்கும் என்று காண விருப்பம் கொண்டு தேடுபவர்கள் அமரர்களின் தலைவனாகிய இறைவன் இருக்கும் இடத்திற்கே செல்வார்கள். அவ்வாறு வருபவர்களுக்கு என்ன வேண்டும் என்று அறிந்து அதை அருள்புரிவான் சிவபெருமான்.`,
  },
  {
    id: 634, tantraId: 3, verseNumber: 633,
    tamil: `பற்றிப் பதத்தன்பு வைத்துப் பரன்புகழ்
கற்றிருந் தாங்கே கருது மவர்கட்கு
முற்றெழுந் தாங்கே முனிவர் எதிர்வரத்
தெற்றுஞ் சிவபதஞ் சேரலு மாமே`,
    transliteration: `paṟṟip patattaṉpu vaittup paraṉpukaḻ
kaṟṟirun tāṅkē karutu mavarkaṭku
muṟṟeḻun tāṅkē muṉivar etirvarat
teṟṟuñ civapatañ cēralu māmē`,
    english: `633: Devotees Reach World of Siva (Siva Loka)
Hold fast unto His Feet,
Adore them with love,
Sing His praise
Study His Sacred lore
Constant think of Him
You shall reach the World of Siva,
Received in full regalia
By the sacred Rishi concourse.`,
    elaborationTamil: `சிவத்தின் திருவடியை அன்போடு பற்றிக்கொண்டு அவரின் புகழை கற்று அறிந்துகொண்டு அவரின் சிறப்புகளிலேயே எண்ணத்தை வைத்து இருப்பவர்களை இறைவனிடம் இருக்கும் முனிவரெல்லாம் எதிர்கொண்டு அழைப்பார்கள். அவர்கள் மனத் தெளிவு பெற்று சிவபதம் அடைவார்கள்.`,
  },
  {
    id: 635, tantraId: 3, verseNumber: 634,
    tamil: `வந்தித் தவஞ்செய்து வானவர் கோவாய்த்
திருந்தம ராபதிச் செல்வன் இவனெனத்
தருந்தண் முழவங் குழலும் இயம்ப
இருந்தின்பம் எய்துவர் ஈசன் அருளே`,
    transliteration: `vantit tavañceytu vāṉavar kōvāyt
tiruntama rāpatic celvaṉ ivaṉeṉat
taruntaṇ muḻavaṅ kuḻalum iyampa
iruntiṉpam eytuvar īcaṉ aruḷē`,
    english: `634: Devotees Will Be Elevated
Infinite is Lord's Grace
He elevates His devotee unto Indra,
The Lord of Celestials;
And he shall be received,
In pomp and honour
Drums beating and pipes playing,
All glory and bliss upon him raining.`,
    elaborationTamil: `சிவபெருமானை நோக்கித் தன்னை வருத்தி ஆசனங்கள் வழியாகத் தவம் செய்பவர்களை தேவர்களுக்கு அரசனாக இருந்து பிறவியில்லா உலகத்திற்கு செல்வார் இவர் என குளிர்ந்த சந்தனத்தால் ஆன முரசும் புல்லாங்குழலும் இசைத்துக் கூற சிவபெருமானின் அருளால் இன்பம் பெறுவார்கள். கருத்து: சிவனை நோக்கி ஆசனங்கள் வழியாகத் தவம் செய்தவர் பிறவியில்லா நிலையை அடைவர்.`,
  },
  {
    id: 636, tantraId: 3, verseNumber: 635,
    tamil: `செம்பொற் சிவகதி சென்றெய்துங் காலத்துக்
கும்பத் தமரர் குழாம்வந் தெதிர்கொள்ள
எம்பொற் றலைவன் இவனா மெனச்சொல்ல
இன்பக் கலவி இருக்கலு மாமே`,
    transliteration: `cempoṟ civakati ceṉṟeytuṅ kālattuk
kumpat tamarar kuḻāmvan tetirkoḷḷa
empoṟ ṟalaivaṉ ivaṉā meṉaccolla
iṉpak kalavi irukkalu māmē`,
    english: `635: Devotee Welcomed by Celestials
When devotee reaches the World of Siva
He shall be received by Celestial throngs,
"Hail! Here comes our Golden Lord"
Thus shall they welcome;
And he in raptuous pleasures shall revel.`,
    elaborationEnglish: `He who practises pranayama will be honoured by the celestials in the world of Siva.`,
    elaborationTamil: `பிராணாயாம முறைப்படி தியானம் செய்தவர்கள் சிவகதி சென்று அடையும் காலத்தில் பூரண கும்பத்தோடு தேவர்கள் கூட்டமாக எதிரே வந்து பொன் போல போற்றத்தக்க எங்கள் தலைவர் இவர் என்று சொல்லி வரவேற்பார்கள். அவர்களுடன் இன்பத்தில் கலந்து இருப்பார்கள்.`,
  },
  {
    id: 637, tantraId: 3, verseNumber: 636,
    tamil: `சேருறு காலந் திசைநின்ற தேவர்கள்
ஆரிவன் என்ன அரனாம் இவனென்ன
ஏருறு தேவர்கள் எல்லாம் எதிர்கொள்ளக்
காருறு கண்டனை மெய்கண்ட வாறே`,
    transliteration: `cēruṟu kālan ticainiṉṟa tēvarkaḷ
ārivaṉ eṉṉa araṉām ivaṉeṉṉa
ēruṟu tēvarkaḷ ellām etirkoḷḷak
kāruṟu kaṇṭaṉai meykaṇṭa vāṟē`,
    english: `636: The Devotee Hailed as Siva Himself
When he reaches the World of Siva
The Celestials,
Who in directions eight stood
Ask, "Who is he;"
And Hara says: "He is Me;"
And the noble Devas forgather and hail him
As well as they met Siva Himself.`,
    elaborationEnglish: `‘The end of Pratyahara is to reach the world of Siva, and to be recognised by the Lord Himself.`,
    elaborationTamil: `பிரத்தியாகாரம் மூலம் வெளியே செல்லும் மனதை உள்ளே நிறுத்தித் தியானம் செய்தவர்கள் இறைவனின் திருவடி சேரும் காலத்தில் சிவரூபம் பெற்று விளங்குவதால் எட்டுத் திசைகளுக்கும் அதிபதியாக நிற்கும் தேவர்கள் யாரிவர் என்று ஆச்சரியத்துடன் எதிர்கொண்டு வரவேற்று அவரின் உடலில் நீலகண்டனாகிய சிவபெருமானை தேவர்கள் தரிசிப்பார்கள்.`,
  },
  {
    id: 638, tantraId: 3, verseNumber: 637,
    tamil: `நல்வழி நாடி நமன்வழி மாற்றிடுஞ்
சொல்வழி யாளர் சுருங்காப் பெருங்கொடை
இல்வழி யாளர் இமையவர் எண்டிசைப்
பல்வழி எய்தினும் பார்வழி யாகுமே`,
    transliteration: `nalvaḻi nāṭi namaṉvaḻi māṟṟiṭuñ
colvaḻi yāḷar curuṅkāp peruṅkoṭai
ilvaḻi yāḷar imaiyavar eṇṭicaip
palvaḻi eytiṉum pārvaḻi yākumē`,
    english: `637: Even Celestials Have to Follow the Path of Devotees
Seeking the goodly path
They turn away Death's path;
They walk the path of Truth
They seek the path of Liberation ;
Of limitless bounty they are;
Well may the Celestials
In directions eight roam
They perforce have to come
To this earth's way of devotees,
And they Him seek.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-637-Third-Tantra-10.-Benefits-of-Eight-Part-Yoga.mp3',
    elaborationTamil: `நல் வழியாகிய தாரணை மூலம் அடங்கிய மனதை உள்ளே இருக்கும் இறைவன் மீது ஒருநிலைபெறச் செய்தவர்களுக்கு மரணத்திற்குச் செல்லும் வழியை மாற்றிவிடும். இறைவனால் கொடுக்கப்படும் ஞானமாகிய குறைவில்லாத பெரும் கொடையை அடைந்தவர்கள் இறைவனை அடையக்கூடிய அனைத்து வழிகளிலும் இந்த உலகத்திலிருந்தே செல்லக்கூடியவர்கள் ஆவார்கள்.`,
  },
  {
    id: 639, tantraId: 3, verseNumber: 638,
    tamil: `தூங்க வல் லார்க்கும் துணையேழ் புவனமும்
வாங்கவல் லார்க்கும் வலிசெய்து நின்றிடுந்
தேங்க வல் லார்க்கும் திளைக்கும் அமுதமுந்
தாங்கவல் லார்க்குந் தன்னிட மாமே`,
    transliteration: `tūṅka val lārkkum tuṇaiyēḻ puvaṉamum
vāṅkaval lārkkum valiceytu niṉṟiṭun
tēṅka val lārkkum tiḷaikkum amutamun
tāṅkaval lārkkun taṉṉiṭa māmē`,
    english: `638: Devotee's Way is the Seeking of Gods
His (devotee's) is the World of Seeking--
Of Vishnu who sleeps on ocean
Of Brahma who creates worlds twice seven
Of Rudra who brings dissolution of life all,
Of Devas who revel in bubbling nectar.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-638-Third-Tantra-10.-Benefits-of-Eight-Part-Yoga.mp3',
    elaborationEnglish: `In dhyana the yogi reaches all the worlds of Brahma, Vishnu, Rudra and Devas.`,
    elaborationTamil: `ஏழு உலகங்களையும் தாங்கக்கூடிய வலிமையைக் கொண்டு நிற்பவனும், இறைவனை மனதில் வைத்து தியானம் செய்பவர்களுக்குள்ளே அமுதமாய் லயித்திருப்பவனுமாகிய இறைவன் சமாதி நிலையை அடைந்தவர்களைத் தனது இருப்பிடமாகக் கொண்டு அவர்களுக்குத் துணையாக இருக்கின்றான்.`,
  },
  {
    id: 640, tantraId: 3, verseNumber: 639,
    tamil: `காரிய மான உபாதியைத் தாங்கடந்
தாரிய காரணம் ஏழுந்தன் பாலுற
ஆரிய காரண மாய தவத்திடைத்
தாரியல் தற்பரஞ் சேர்தல் சமாதியே`,
    transliteration: `kāriya māṉa upātiyait tāṅkaṭan
tāriya kāraṇam ēḻuntaṉ pāluṟa
āriya kāraṇa māya tavattiṭait
tāriyal taṟparañ cērtal camātiyē`,
    english: `639: In Samadhi Jiva Unites in Uncaused Being
Transcending Jiva's caused experience limitations
Himself the Causal Tattvas Becoming,
Extinguishing the Causal sources themselves,
Thus do tapasvins unite in the Being Uncaused
That, in truth is Samadhi supreme.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-639-Third-Tantra-10.-Benefits-of-Eight-Part-Yoga.mp3',
    elaborationTamil: `இந்த உலகத்தில் துன்பம் தரக்கூடிய காரணங்களாகிய தனு, கரணம், புவனம், போகம் ஆகிய பந்தங்களைக் கடந்து சென்று ஏழுவகையான சிவ தத்துவங்களையும் தன் அறிவாலேயே உணர்ந்து பெற்று ஜென்ம ஜென்மமாய்த் தொடர்ந்து வரும் மாயையைத் தவத்தால் வெற்றி பெற்று இறைவனின் திருவடியைச் சேருதல் சமாதியால் பெறும் பயனாகும். நான்கு வகை பந்தங்கள்: தனு – தன் உடலின் மேல் இருக்கும் பற்று கரணம் – ஆசைப்படும் மனது புவனம் – உலகப் பற்று போகம் – உலகப் பொருள்களை அனுபவித்தல் ஏழுவகை சிவ தத்துவங்கள்: இறைமை – இறைவனாக தன்னை உணர்தல் முற்றறிவு உடைமை – அனைத்தையும் அறிந்தவனாக இருத்தல் எங்கும் தானாதல் – எங்கும் வியாபித்து இருத்தல் இயல்பாகவே மாயையின்மை – மாயையே இல்லாது இருத்தல் வரம்பில்லாத ஆற்றல் – எல்லையில்லா சக்தியைக் கொண்டிருத்தல் தன்வயத்தன் ஆதல் – எதனாலும் கட்டுப்படாமல் தன் கட்டுப்பாட்டிலேயே இருத்தல் ஒன்றியுணர்தல் – அனைத்திலும் ஒன்றி இருப்பதாக உணர்தல் கருத்து: சமாதி நிலையை அடைந்தால் அனைத்துவித துன்பங்கள் மற்றும் மாயையிலிருந்து விடுதலை பெற்று சிவ தத்துவங்களை உணரலாம்.`,
  },
  {
    id: 641, tantraId: 3, verseNumber: 640,
    tamil: `பணிந்தெண் திசையும் பரமனை நாடித்
துணிந்தெண் திசையுந் தொழுதெம் பிரானை
அணிந்தெண் திசையினும் அட்டமா சித்தி
தணிந்தெண் திசைசென்று தாபித்த வாறே`,
    transliteration: `paṇinteṇ ticaiyum paramaṉai nāṭit
tuṇinteṇ ticaiyun toḻutem pirāṉai
aṇinteṇ ticaiyiṉum aṭṭamā citti
taṇinteṇ ticaiceṉṟu tāpitta vāṟē`,
    english: `640: Perform Siddhis in Meekness
Pray and seek Lord in directions eight
Adore Lord with constancy in directions eight
Attain Eight Siddhis Great in directions eight
And in meekness perform in directions eight.`,
    elaborationEnglish: `They walk the path of Truth They seek the path of Liberation; Of limitless bounty they are; Well may the Celestials

In directions eight roam

They perforce have to come

To this earth’s way of devotees, And there Him seek.`,
    elaborationTamil: `சிவபெருமானைத் தேடி எட்டுத் திசைகளிலும் பணிந்து அவனே பரம் பொருள் என்று அறிந்ததால் தைரியமுடன் எட்டுத் திசையிலும் சிவத்தை வணங்க அதனால் உள்ளம் குளிர்ந்த சிவபெருமான் தன் அருளால் எட்டு சித்திகளும் அவருக்குள் நிலைபெறச் செய்வார். கருத்து: எதையும் சிவமாய்ப் பணிந்து வணங்குபவர்களுக்கு சிவபெருமான் எட்டுவித சித்திகளும் கொடுத்து அருள்வான்.`,
  },
  {
    id: 642, tantraId: 3, verseNumber: 641,
    tamil: `பரிசறி வானவர் பண்பன் அடியென்னத்
துரிசற நாடியே தூவெளி கண்டேன்
அரிய தெனக்கில்லை அட்டமா சித்தி
பெரிதருள் செய்து பிறப்பறுத் தானே`,
    transliteration: `paricaṟi vāṉavar paṇpaṉ aṭiyeṉat
turicaṟa nāṭiyē tūveḷi kaṇṭēṉ
ariya teṉakkillai aṭṭamā citti
peritaruḷ ceytu piṟappaṟut tāṉē`,
    english: `641: Nothing Impossible Then
Lord is the Prized Being of Celestials,
I sought His Feet in devotion
All my blemish vanished
And I visioned the Mystic Void
Nothing impossible for me now;
He blessed me with Eight Great Siddhis
And ended my birth to be.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-641-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationTamil: `தேவர்கள் முதலான அனைத்து உயிர்களின் தன்மையையும் அறிந்து கொள்கின்ற பண்பாளனாகிய இறைவனின் திருவடியை தூய எண்ணத்துடன் சரண் அடைந்து தூய்மையான பரவெளியைக் (அண்ட சராசரங்கள்) கண்டேன். ஆதலால் இறைவன் தனது பேரருளால் அரிதான எட்டுவித சித்திகளையும் எனக்கு வழங்கி எனது பிறப்பை அறுத்து அருளினான். கருத்து: சிவபெருமானின் திருவடியை சரணடைந்தால் எட்டுவித சித்திகளும் பெற்று பிறவி இல்லாத நிலையை அடையலாம்.`,
  },
  {
    id: 643, tantraId: 3, verseNumber: 642,
    tamil: `குரவன் அருளிற் குறிவழி மூலன்
பரையின் மணமிகு சங்கட்டம் பார்த்துத்
தெரிதரு சாம்பவி கேசரி சேரப்
பெரிய சிவகதி பேறெட்டாஞ் சித்தியே`,
    transliteration: `kuravaṉ aruḷiṟ kuṟivaḻi mūlaṉ
paraiyiṉ maṇamiku caṅkaṭṭam pārttut
teritaru cāmpavi kēcari cērap
periya civakati pēṟeṭṭāñ cittiyē`,
    english: `642: Sambhavi and Kechari Mudras for Siddhis
By Muladhara Way,
With Grace of Guru
Vision Sakti,
Seated fragrant and lovely;
Practise Sambhavi and Kechari mudras
You shall attain Siddhis Eight,
That to mighty Siva's goal leads.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-642-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationTamil: `குருவின் அருளினால் அவர் காட்டிய வழியிலேயே மூலாதார அக்கினியை ஏழாவது சக்கரமான சகஸ்ரதளத்திற்கு கொண்டு சேர்ப்பதற்கு தனக்குள்ளேயே அலையும் எண்ணங்களையும் (கேசரி யோகம்) வெளியே அலையும் எண்ணங்களையும் (சாம்பவி யோகம்) கடினத்துடன் ஒன்றாகச் சேர்த்து ஒருமுகப்படுத்தி வைத்தால் சிவகதிப் பேறான எட்டுவித சித்திகளில் எட்டாவது சித்தியான வசித்துவம் (அனைத்தையும் வசியப்படுத்துதல்) கைவரப் பெறும். கருத்து: குரு அருளிய வழியில் மனதை ஒருமுகப்படுத்தி தியானித்தால் எட்டாவது சித்தியான அனைத்தையும் வசியப்படுத்தும் நிலையை அடையலாம்.`,
  },
  {
    id: 644, tantraId: 3, verseNumber: 643,
    tamil: `காயாதி பூதங் கலைகால மாயையில்
ஆயா தகல அறிவொன் றனாதியே
ஓயாப் பதியதன் உண்மையைக் கூடினால்
வீயாப் பரகாயம் மேவலு மாமே`,
    transliteration: `kāyāti pūtaṅ kalaikāla māyaiyil
āyā takala aṟivoṉ ṟaṉātiyē
ōyāp patiyataṉ uṇmaiyaik kūṭiṉāl
vīyāp parakāyam mēvalu māmē`,
    english: `643: Power of Transmigration
The Elements, Kalas, Time and Maya
Escape unentangled in them,
That is but Wisdom;
And embrace fast the Truth of Lord
That Uncreated and Unending One;
Then can you transmigrate
Into mortal coils of beings other.`,
    elaborationEnglish: `This is another one of Siddhi powers (Tantric) through which one can leave one’s own body and enter into that of another. Traditionally Mular is said to have done this (See The great Sankaracarya is also said to have adopted this, during the course of a debate with Vacaspati Misra.`,
    elaborationTamil: `ஆகாயம், நிலம், நீர், காற்று, நெருப்பு ஆகிய பஞ்ச பூதங்களிலும் அறுபத்து நான்கு கலைகள், மூன்று காலங்கள் (இறந்த காலம், நிகழ் காலம், எதிர் காலம்) மாயை ஆகிய தத்துவங்களிலும் சேராமல் விலகி ஒன்றுபட்டு இருக்கும் அறிவை ஆத்மாவிற்கும் பரமாத்மாவிற்கும் இருக்கும் தொடர்பை உண்மையென அறிந்து அதிலேயே கலந்திருந்தால் என்றும் அழியாத உடலை அடையலாம். கருத்து: நிலையில்லாத உலகை விட்டு நிலையான இறைவனோடு கலந்திருந்தால் என்றும் அழியாத உடலை அடையலாம்.`,
  },
  {
    id: 645, tantraId: 3, verseNumber: 644,
    tamil: `இருபதி நாயிரத் தெண்ணூறு பேதம்
மருவிய கன்ம மாமந்த யோகந்
தருமிவை காய உழைப்பாகுந் தானே
அருமிகு நான்காய் அடங்குமா சித்திக்கே`,
    transliteration: `irupati nāyirat teṇṇūṟu pētam
maruviya kaṉma māmanta yōkan
tarumivai kāya uḻaippākun tāṉē
arumiku nāṉkāy aṭaṅkumā cittikkē`,
    english: `644: Karma Yoga Practices are Inferior to Eight Siddhis
Karma yoga is several, several in number;
Twenty thousand eight hundred kinds they count;
And all they can give is but physical work,
Inferior are they to the Eight Siddhis Great.`,
    elaborationEnglish: `in the course of the practice of the eight-limbed yoga, eight siddhis or miraculous powers appear.`,
    elaborationTamil: `விருப்பத்தோடு மனதை ஒருமுகப்படுத்தி செய்யும் செயல்கள் கர்ம யோகமாகும். அது இருபதாயிரத்து எண்ணூறு பிரிவுகளைக் கொண்டது. கர்ம யோகம் உடம்பினால் செய்யப்படும் அருமையான உழைப்பினால் நிறைவு பெறும். அவ்வாறு நிறைவு பெறுவதால் பெறக்கூடிய சித்திகள் எட்டுவித சித்திகளாகும். கருத்து: கர்ம யோகத்தை மனதை ஒருமுகப்படுத்தி உடல் உழைப்பால் செய்து முடித்தவர்களுக்கு எட்டுவித சித்திகளும் கிடைக்கும்.`,
  },
  {
    id: 646, tantraId: 3, verseNumber: 645,
    tamil: `மதிதனில் ஈராறாய் மன்னுங் கலையின்
உதய மதுநா லொழியவோ ரெட்டுப்
பதியுமஈ ராறாண்டு பற்றறப் பார்க்கில்
திதமான ஈராறு சித்திக ளாமே`,
    transliteration: `matitaṉil īrāṟāy maṉṉuṅ kalaiyiṉ
utaya matunā loḻiyavō reṭṭup
patiyumaī rāṟāṇṭu paṟṟaṟap pārkkil
titamāṉa īrāṟu cittika ḷāmē`,
    english: `645: Twelve Years for Eight Siddhis
On the Moon's nadi to the left (Idakala)
The breath of Prana measures units twelve;
Of this, exhale four;
If the eight saved is within retained,
And that for twelve years continuous practised,
Then shall Siddhis Eight ever abide.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-645-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationTamil: `சந்திர நாடியாகிய இடைகலையில் (இடது நாசி) பன்னிரண்டு அங்குல அளவாய் இழுக்கப் பெறும் மூச்சுக்காற்றில் சூரிய நாடியாகிய பிங்கலை (வலது நாசி) வழியாக நாலங்குல அளவு மூச்சுக்காற்று வெளியே போக மீதியுள்ள எட்டங்குல அளவு மூச்சுக்காற்று உள்ளே தங்கும். இதனைப் பன்னிரண்டு ஆண்டுகள் உலகப்பற்றை விட்டுக் கவனித்து வந்தால் உறுதியாக அட்டமா சித்திகளை அடையலாம். கருத்து: பன்னிரண்டு ஆண்டுகள் முறைப்படி பிராணாயாமம் செய்து வந்தால் எட்டுவித சித்திகளையும் உறுதியாக அடையலாம்.`,
  },
  {
    id: 647, tantraId: 3, verseNumber: 646,
    tamil: `நாடும் பிணியாகு நஞ்சனஞ் சூழ்ந்தக்கால்
நீடுங் கலைகல்வி நீள்மேதை கூர்ஞானம்
பீடொன்றி னால்வாயாச் சித்திபே தத்தின்
நீடுங் துரங்கேட்டல் நீண்முடி வீராறே`,
    transliteration: `nāṭum piṇiyāku nañcaṉañ cūḻntakkāl
nīṭuṅ kalaikalvi nīḷmētai kūrñāṉam
pīṭoṉṟi ṉālvāyāc cittipē tattiṉ
nīṭuṅ turaṅkēṭṭal nīṇmuṭi vīrāṟē`,
    english: `646: Subtle Sounds Signifying Siddhis
Abounding in wealth of men around,
You but pave the way for birth again;
Nor can Siddhi be attained
By art, learning, genius and wisdom subtle;
At the end of diverse melodies heard in Yoga
For twelve years long
Does it take Siddhi for fullness to attain.`,
    elaborationTamil: `எண்ணிலடங்காத நோய்கள் போன்ற பிறப்புகளில் நம்மைச் சூழ்ந்து பற்றிக் கொண்டிருக்கும் உறவுகளும், நிலைத்திருக்கும் கலை உணர்வுகளும், அந்த உணர்வுகளைத் தரும் கல்விகளும், அந்தக் கல்விகளால் வரும் தெளிவும், அந்தத் தெளிவால் பெறப்படும் நுட்பமான உணர்வுகளும், அந்த உணர்வினால் அடையும் பெருமைகளாலும் எட்டுவித சித்திகளும் கிடைப்பதில்லை. பன்னிரண்டு ஆண்டுகள் ஆத்ம குரு கூறிய வழியைக் கேட்டு அதன்படி பொறுமையுடன் நடந்துவந்தால் எட்டுவித சித்திகளும் கிடைக்கும். கருத்து: உலகத்தில் கிடைக்கும் எதனாலும் சித்திகள் கிடைப்பதில்லை. பன்னிரண்டு ஆண்டுகள் குரு கூறிய வழியைக் கடைபிடித்தால் எட்டுவித சித்திகளும் கிடைக்கும்.`,
  },
  {
    id: 648, tantraId: 3, verseNumber: 647,
    tamil: `ஏழா னதிற்சண்ட வாயுவின் வேகியாந்
தாழா நடைபல யோசனை சார்ந்திடுஞ்
சூழான ஓரெட்டில் தோன்றா நரைதிரை
தாழான ஒன்பதிற் றான்பர காயமே`,
    transliteration: `ēḻā ṉatiṟcaṇṭa vāyuviṉ vēkiyān
tāḻā naṭaipala yōcaṉai cārntiṭuñ
cūḻāṉa ōreṭṭil tōṉṟā naraitirai
tāḻāṉa oṉpatiṟ ṟāṉpara kāyamē`,
    english: `647: Siddhis in the Seventh, Eighth and Ninth Years
In the seventh year of his practice
The Yogi becomes fleet of foot like wind;
His footfall touches not the ground
He divines the thoughts of other beings;
In the eighth year he becomes eternal young,
For ever bereft of graying hair and wrinkled muscles
In the ninth, he transmigrates into other coils mortal.`,
    elaborationEnglish: `For ever berefi of graying hait and wrinkled muscles In the ninth. he transmigrates into other bodies mortal.`,
    elaborationTamil: `பாடல் #644 #645 #646 இல் உள்ள முறைகளில் ஏதேனும் ஒன்றை கடைபிடித்தால் ஏழாவது ஆண்டில் சூறாவளிக் காற்றைவிட வேகமாக செல்லக்கூடிய தன்மையும் உடல் தளராது நெடுந்தூரம் நடந்து செல்லக்கூடிய வலிமையும் கிடைக்கும். எட்டாவது ஆண்டில் வயோதிகத்தால் வரும் நரைமுடியும் உடல் சுருக்கங்களும் மறைந்து இளமை கிடைக்கும். ஒன்பதாவது ஆண்டில் என்றும் அழியாத உடல் கிடைக்கும். கருத்து: குரு அருளிய யோக முறையைக் கடைபிடித்தால் 7,8,9 ஆம் ஆண்டுகளில் வேகமும் வலிமையும் இளமையும் அழியாத உடலும் கிடைக்கும்.`,
  },
  {
    id: 649, tantraId: 3, verseNumber: 648,
    tamil: `ஈரைந்திற் பூரித்துத் தியான உருத்திரன்
ஏர்வொன்று பன்னொன்றில் ஈராறாம் எண்சித்தி
சீரொன்று மேலேழ் கீழேழ் புவிச்சென்று
ஏரொன்று வியாபியாய் நிற்றல்ஈ ராறே`,
    transliteration: `īraintiṟ pūrittut tiyāṉa uruttiraṉ
ērvoṉṟu paṉṉoṉṟil īrāṟām eṇcitti
cīroṉṟu mēlēḻ kīḻēḻ puvicceṉṟu
ēroṉṟu viyāpiyāy niṟṟalī rāṟē`,
    english: `648: Siddhis in the Tenth, Eleventh and Twelfth Years
In the tenth year the yogi can expand and contract into space
In the eleventh he can assume form he meditates on;
In the twelfth all eight siddhis complete he masters;
He then gains the powers to roam the worlds
Seven above and seven below
And take one cosmic form spanning space all.`,
    elaborationEnglish: `Himself the atom, himself the cosmos

Himself migrating into tiortal bodies other, possessing prowess of the Truthful One Himself immanent in all

—These eight arc the Siddhis Great.`,
    elaborationTamil: `பாடல் #644 #645 #646 ல் உள்ள முறைகளில் ஏதேனும் ஒன்றை கடைபிடித்து வந்தால் பத்தாவது ஆண்டில் தியானத்திலிருக்கும் சிவ நிலையை அடையலாம். பதினோராவது ஆண்டில் எட்டுவித சித்திகளும் கிடைக்கும். பன்னிரண்டாவது ஆண்டில் மேலிருக்கும் ஏழு உலகங்களுக்கும் கீழிருக்கும் ஏழு உலகங்களுக்கும் சென்று அங்கிங்கெனாதபடி எங்கும் பரந்து இருக்கும் நிலையை அடையலாம். கருத்து: குரு அருளிய யோக முறையைக் கடைபிடித்தால் 10,11,12 ஆம் ஆண்டுகளில் சிவ நிலையும் எட்டுவித சித்திகளையும் எங்கும் பரந்து இருக்கும் நிலையையும் அடையலாம்.`,
  },
  {
    id: 650, tantraId: 3, verseNumber: 649,
    tamil: `தானே அணுவுஞ் சகத்துத்தன் நோன்மையும்
மானாக் கனமும் பரகாயத் தேகமுந்
தானாவ தும்பர காயஞ்சேர் தன்மையும்
ஆனாத வுண்மையும் வியாபியு மாம்எட்டே`,
    transliteration: `tāṉē aṇuvuñ cakattuttaṉ nōṉmaiyum
māṉāk kaṉamum parakāyat tēkamun
tāṉāva tumpara kāyañcēr taṉmaiyum
āṉāta vuṇmaiyum viyāpiyu māmeṭṭē`,
    english: `649: The Eight Siddhis Enumerated
Himself the atom, himself the cosmos
Himself light, himself heavy
Himself invisible air,
Himself migrating into mortal bodies other,
Himself possessing prowess of the Truthful One
Himself immanent in all
--These eight are the Siddhis Great.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-649-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationTamil: `தானே அணிமாவும் உலகமாகிய மகிமாவும் கனமுடையதாகிய கரிமாவும் எல்லவற்றிலும் அடங்கிய ஆகாயமாகிய லகிமாவும் அழியா உடலையடைதலாகிய பிரப்தியும் தானே ஆதலாகிய பரகாயத்தை அடையும் பிராகாமியமும் அமையாத உண்மையாகிய ஈசத்துவமும் வியாப்பியமாகிய வசித்துவமும் ஆகியவை அட்டமா சித்திகள் ஆகும். எட்டுவித சித்திகள்: அணிமா – அணுவைப் போல் உடலை சிறிதாக்கும் ஆற்றல். மகிமா – மலையைப் போல் உடலை பெரிதாக்கும் ஆற்றல். கரிமா – மலை போல எதனாலும் அசைக்க முடியாத அளவு உடலை கனமாக்கும் ஆற்றல். இலகிமா – காற்றைப் போல் இலேசாய் உடலை மாற்றி எங்கும் செல்லும் ஆற்றல். பிராப்தி – தூரத்திலிருப்பதையும் இருக்கும் இடத்திலேயே பார்க்கவும், மனதினால் நினைத்தவை யாவையும் அடையவும் பெறும் ஆற்றல். பிராகாமியம் – எதையும் நினைத்தவுடன் அதாகவே தன்னை மாற்றிக் கொள்ளும் ஆற்றல். ஈசத்துவம் – ஆக்கல், காத்தல், அழித்தல், மறைத்தல், அருளல் ஆகிய ஐந்தொழில்களைத் தன் ஆளுகைக்குட்பட்டுச் செய்தல். வசித்துவம் – ஈரேழு பதினான்கு உலகங்களிலும் கலந்து, அங்கிங்கெனாதபடி எங்கும் வியாபித்து இருக்கும் ஆற்றல். கருத்து: எட்டுவித சித்திகளாவன அணிமா, மகிமா, கரிமா, இலகிமா, பிராப்தி, பிராகாமியம், ஈசத்துவம், வசித்துவம்.`,
  },
  {
    id: 651, tantraId: 3, verseNumber: 650,
    tamil: `தாங்கிய தன்மையுந் தானணுப் பல்லுயிர்
வாங்கிய காலத்து மற்றோர் குறையில்லை
யாங்கே எழுந்தோம் அவற்றுள் எழுந்துமிக்
கோங்கி வரமுத்தி முந்திய வாறே`,
    transliteration: `tāṅkiya taṉmaiyun tāṉaṇup palluyir
vāṅkiya kālattu maṟṟōr kuṟaiyillai
yāṅkē eḻuntōm avaṟṟuḷ eḻuntumik
kōṅki varamutti muntiya vāṟē`,
    english: `650: Anima Siddhi to Mukti
The Yogi assumes atom-size,
Into lives of several beings enters,
And then returns to his form original;
Either way is he least affected;
From that stage reached in Anima Siddhi,
He rises further
Into Nada chanting Aum,
And thus toward Mukti hastens.`,
    elaborationEnglish: `As in 647 and 648, here also the time taken, and the process through which some of the Siddhis are attained, is explained.`,
    elaborationTamil: `சிவயோகியாகி அணு அளவு மாறினாலும் பல உயிர்களைத் தாங்கும் தன்மையைப் பெறுவார். அவ்வுயிர்களைத் தமக்குள் கலந்து இருந்த போதும் தமக்குள் எந்தவித மாற்றமும் இல்லை. தமக்குள் இருக்கும் அவ்வுயிர்கள் ஓம் எனும் நாதமாக எழுந்து உச்சிக்கு சென்று முக்தி பெறுகின்றன. கருத்து: அட்டமா சித்தியடைந்தவர் எவ்வுயிரையும் தமக்குள் எடுத்து முக்தி பெறச் செய்வார்.`,
  },
  {
    id: 652, tantraId: 3, verseNumber: 651,
    tamil: `முந்திய முந்நூற் றறுபது தேர்ந்தறிவார்வலர்
வந்தது நாழிகை வான்முத லாயிடச்
சிந்தை செயச்செய மண்முதல் தேர்ந்தறிந்
உந்தியுள் நின்று உதித்தெழு மாறே`,
    transliteration: `muntiya munnūṟ ṟaṟupatu tērnttaṟivārvar
vantatu nāḻikai vāṉmuta lāyiṭac
cintai ceyacceya maṇmutal tērntaṟin
untiyuḷ niṉṟu utitteḻu māṟē`,
    english: `651: A Year for Anima
Days are counted by astral Nazhigai sixty
And year by days three hundred and sixty;
Do meditate incessant through time thus reckoned,
And pierce the Chakras upward from Muladhara;
At the Navel-Center arises the power of Anima.`,
    elaborationTamil: `வானம் முதல் பூமி வரையுள்ள அனைத்திலும் சிவனையே கண்டு சிந்தித்து ஆராய்ந்து அறிந்து கொள்பவர்களுக்கு 360 நாள்களில் தொப்புள் குழிக்கு அருகில் இருக்கும் மணிப்பூரக சக்கரத்தில் ஒளி எழும்பி மேலெழுந்து செல்லும். கருத்து: பார்ப்பவைகள் அனைத்திலும் சிவனையே கண்டு சிந்திப்பவர்களுக்கு 360 நாட்களில் மணிப்பூரகச் சக்கரத்திலிருந்து ஒளி எழும்பும்.`,
  },
  {
    id: 653, tantraId: 3, verseNumber: 652,
    tamil: `சித்தந் திரிந்து சிவமய மாகியே
முத்தந் தெரிந்துற்ற மோனர் சிவமுத்தர்
சுத்தம் பெறலாம் ஐந்தில் தொடக்கற்றோர்
சித்தம் பரத்தில் திருநடத் தோரே`,
    transliteration: `cittan tirintu civamaya mākiyē
muttan terintuṟṟa mōṉar civamuttar
cuttam peṟalām aintil toṭakkaṟṟōr
cittam parattil tirunaṭat tōrē`,
    english: `652: On the Way to Siva Mukti
They are Siva Muktas
Who turned their thoughts to Siva
Who became Siva-suffused,
Who attained Mukti
By silentness that leads to it;
They abandoned the senses five
In search of Divine Purity
Their thoughts centered on Dance Cosmic.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-652-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationTamil: `ஐம்புலன்களாகிய பார்த்தல், கேட்டல், சுவைத்தல், நுகர்தல், உணர்தல் ஆகியவற்றில் செல்லும் எண்ணங்கள் எல்லாம் சிவமாய் உணர்ந்து முக்தி நிலையை அறிந்து அதிலேயே லயித்து இருப்பவர்கள் சிவ முக்தர்கள் ஆவார்கள். இவர்கள் ஐந்து புலன்களின் உணர்விலும் தொடர்பில்லாதவர்கள் ஆகையால் தூய நிலையை அடைந்து அவர்களின் எண்ணம் சிவனோடு ஒன்றுபட்டு ஆனந்த நிலையில் நடனம் ஆடுவார்கள். கருத்து: சிவயோகியர் உடம்பை மறந்து மேல் நிலையில் இன்புற்று இருப்பார்கள்.`,
  },
  {
    id: 654, tantraId: 3, verseNumber: 653,
    tamil: `ஒத்தஇவ் வொன்பது வாயுவும் ஒத்தன
ஒத்தஇவ் வொன்பதின் மிக்க தனஞ்செயன்
ஒத்தஇவ் வொன்பதில் ஒக்க இருந்திட
ஒத்த வுடலும் உயிரும் இருந்ததே`,
    transliteration: `ottaiv voṉpatu vāyuvum ottaṉa
ottaiv voṉpatiṉ mikka taṉañceyaṉ
ottaiv voṉpatil okka iruntiṭa
otta vuṭalum uyirum iruntatē`,
    english: `653: How the Vayus Stand for Yogis
Nine the Vayus in body equal are,
Dananjaya, the tenth superior is,
When the nine in their channels accord
Life and body well accord, too.`,
    elaborationEnglish: `The vayus are ten: I) prana; 2) apana; 3) samana, 4) udana; 5} 6) naga; 7) kurma; 8) krikara; 9) devadatta; and 10) dhanamjaya.

“The prana moves always in the heart; the apana in the sphere of the anus; the samana in the navel region; the udana in the throat; and the pervades the whole body. These are the five principal vayus. known as ‘pranadi.’ They belong to the inner body. The ‘nagadi’ five vayus belong to the outer body.

i now tell the seats of these five external vayus. The naga vayu performs the function of belching: the kurma opens the eVelids: the krikara causes sneezing; the devadatta does yawning; the dhunamiaya pervades the whole gross body, and does not teave it, even after death.

The naga vayu gives rise to conscipusness, the kurma causes vision, the krikara, hunger and thirst, the devadatta produces yawning, and by dhanamjaya, sound is produced. This does not leave the body even for a minute.’’ Vide Gheranda Samhita, v., 58-68.

Compare Siva 1-9: ‘‘From the different modifications of the prana, it receives various names, all of which cannot be stated here. Prana, apana, samana, udana, naga, kurma, krikara, devadatta, and dhanamjaya. These are the ten principal names, described by me in this sastra; they perform all the functions, incited thereto by their own actions. Again, out of these ten, the first five are the highest agents in my opinion. The seat of the prana is the heart; of the apana, the anus; of the samana, the region around the navel; of the udana, the throat; while the moves all over the body. The five remaining. vayus, the naga, eric, perform the following functions in the body:’ eructation, opening the eyes, hunger and thirst, gaping or yawning, and lastly hiccuping. He who in this way knows the microcosm of the body, being absolved from all sins, reaches the highest state’’ — quoted in ‘“‘Hatha Yoga’’ by Theos Bernard,

Vayus are nerve currents—‘‘Shakti and Shakta’’ by Sir John Woodroffe, p.686. "

These three verses which deal with Vayu (Body-Wind) and physical health are medicinal in nature.

Importance of Dhanamjaya

Danamjaya pervades the other nine Vayus Within the body it permeates

Nadis two hundred and twenty four

If Dhanamjaya functions not thus,

This body will swell and burst.

The Importance of two Vayus is mentioned. This is a part of Ayur or Siddha Veda which was the specialty in the medicine of the Siddhars.`,
    elaborationTamil: `பிராணன், அபானன், வியானன், சமானன், நாகன், கூர்மன், கிருகரன், தேவதத்தன், உதானன் ஆகிய ஒன்பது வாயுக்களும், இடகலை, பிங்கலை, சிகுவை, புருடன், காந்தாரி, அத்தி, அலம்புடை, சங்கினி, குகு ஆகிய ஒன்பது நாடிகளில் (நரம்புகளில்) அதிகமாகாமலும் குறையாமலும் சரிசமமாக இருந்தால் பத்தாவது நாடியான சுழுமுனை வழியே செல்லும் பத்தாவது வாயுவான தனஞ்செயன் என்னும் வாயு உடலோடும் உயிரோடும் ஒன்றுபட்டு பிரியாமல் இருக்கும். கருத்து: உடலிலுள்ள ஒன்பது வாயுக்களும் சமமாக இருந்தால் உடலை விட்டு உயிர் பிரியாது இருக்கும்.`,
  },
  {
    id: 655, tantraId: 3, verseNumber: 654,
    tamil: `இருக்குந் தனஞ்செயன் ஒன்பது காலில்
இருக்கும் இருநூற் றிருபத்து மூன்றாய்
இருக்கு முடலி லிருந்தில வாகில்
இருக்கும் உடலது வீங்கி வெடித்ததே`,
    transliteration: `irukkun taṉañceyaṉ oṉpatu kālil
irukkum irunūṟ ṟirupattu mūṉṟāy
irukku muṭali liruntila vākil
irukkum uṭalatu vīṅki veṭittatē`,
    english: `654: Importance of Dhananjaya
Dananjaya pervades other the nine Vayus
Within the body it permeates
Nadis two hundred and twenty four
If Dhananjaya does function not thus,
This body will swell and burst.`,
    elaborationEnglish: `Infinite is the Lord’s Grace

He ‘elevates His devotees unto Indra, The Lord of Celestials;

And he shall be received,

In pomp and honour

Drums beating and pipes playing, All glory and bliss upon him raining.

The fruit of asana is the attainment of the status oi Indra, the king of devas.`,
    elaborationTamil: `தனஞ்செயன் என்னும் வாயு உடம்பில் இருக்கும் ஒன்பது வாயுக்களோடு கலந்து உடலில் உள்ள இருநூற்று இருபத்து நான்கு நரம்புகள் வழியே சென்று கொண்டு இருக்கும். அவ்வாறு செல்லாமல் இருந்தால் உடம்பு வீங்கி வெடித்துவிடும். கருத்து: தனஞ்செயன் என்னும் வாயு உடலில் உள்ளவரை உடல் அழியாது.`,
  },
  {
    id: 656, tantraId: 3, verseNumber: 655,
    tamil: `வீங்குங் கழலை சிரங்கொடு குட்டமும்
வீங்கும் வியாதிகள் சோகை பலவதாய்
வீங்கிய வாதமுங் கூனு முடமதாய்
வீங்கு வியாதிகள் கண்ணில் மருவியே`,
    transliteration: `vīṅkuṅ kaḻalai ciraṅkoṭu kuṭṭamum
vīṅkum viyātikaḷ cōkai palavatāy
vīṅkiya vātamuṅ kūṉu muṭamatāy
vīṅku viyātikaḷ kaṇṇil maruviyē`,
    english: `655: Diseases Appear When Dhananjaya Does not Function
Boils, itches and leprosy
Anaemia, and like diseases
That swellings show
Paralysis, hunchback, arthritis
And diseases of eye that bulging show
All appear
When Dananjaya in disorder functions.`,
    elaborationTamil: `வயிற்றுக் கட்டி அல்லது வீக்கம், சிரங்கு, குஷ்டம், உறுப்புகள் வீக்கம், பலவகை சோகைகள், வாதம் (நரம்பு தளர்ச்சி) கூன், முடம் (ஊனம்) கண் நோய்கள் ஆகிய வியாதிகள் உடலிலுள்ள தனஞ்செயன் என்னும் வாயு குறைவதால் உருவாகும். கருத்து: உடலுக்கு வரும் வியாதிகளில் பல தனஞ்செயன் என்னும் வாயு குறைவதால் வருகின்றன.`,
  },
  {
    id: 657, tantraId: 3, verseNumber: 656,
    tamil: `கண்ணில் வியாதி யுரோகந் தனஞ்செயன்
கண்ணிலிவ் வாணிகள் காச மவனல்லன்
கண்ணினிற் கூர்மன் கலந்தில நாதலாற்
கண்ணினிற் சோதி கலந்ததும் இல்லையே`,
    transliteration: `kaṇṇil viyāti yurōkan taṉañceyaṉ
kaṇṇiliv vāṇikaḷ kāca mavaṉallaṉ
kaṇṇiṉiṟ kūrmaṉ kalantila nātalāṟ
kaṇṇiṉiṟ cōti kalantatum illaiyē`,
    english: `656: Importance of Kurma Vayu for Eye
When Dananjaya malfunctions
The eye gets diseases like cataract and glaucoma
But Kurma is goodly to the eye;
If Kurma permeates not the eye,
It receives light none.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-656-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationTamil: `கண்ணில் வியாதிகளைக் கொடுக்கும் தனஞ்செயன் கண்ணில் பூ விழுதல் (கருவிழியில் வெள்ளை நிறம் தோன்றி கண் பார்வை போதல்) காசம் (கண்ணில் சீழ் வழிதல்) ஆகியவற்றிற்கு காரணம் இல்லை. கண்ணிலிருந்து ஒளியை மூளைக்குக் கொண்டு செல்லும் கூர்மன் என்னும் வாயு குறைபாட்டால் இவ்விரு வியாதிகள் வருகின்றன. இந்த வாயுவின் குறைபாட்டால் பார்வையில் ஒளி இல்லாமலும் ஆகும். கருத்து: கூர்மன் என்னும் வாயு குறைபாட்டால் கண்ணில் பூ விழுதல் காசம் ஆகிய இரு நோய்கள் உண்டாகும்.`,
  },
  {
    id: 658, tantraId: 3, verseNumber: 657,
    tamil: `நாடியின் ஓசை நயனம் இருதயந்
தூடி யளவுஞ் சுடர்விடு சோதியைத்
தேவருள் ஈசன் திருமால் பிரமனும்
ஓவற நின்றங் குணர்ந்திருந் தாரே`,
    transliteration: `nāṭiyiṉ ōcai nayaṉam irutayan
tūṭi yaḷavuñ cuṭarviṭu cōtiyait
tēvaruḷ īcaṉ tirumāl piramaṉum
ōvaṟa niṉṟaṅ kuṇarntirun tārē`,
    english: `657: The Three Gods Animate Three Nadis
Through the Nadis that pulsate
In the ear, eye and heart
Animates the one spark of Light Divine
That is God;
The Gods, Rudra, Vishnu, and Brahma
Respective there seated art.`,
    elaborationTamil: `மூலாதாரத்திலிருந்து தலை உச்சிக்கு செல்லும் குண்டலினி சக்தியின் ஜோதியை அகக் கண்ணால் கண்டு அந்த ஜோதியின் ஒளிர்விடும் ஓசையை இதயத்துடிப்பால் உணர்ந்து இருப்பவர்களை தேவர்களுள் முதல்வர்களான உருத்ரன், திருமால், பிரம்மன் ஆகிய மூவரும் இடைவிடாது உள்ளுக்குள் உணர்ந்திருப்பார்கள். கருத்து: குண்டலியின் ஜோதியையும் அதன் ஓசையும் தமக்குள் உணர்ந்தவர்களை முப்பெரும் தேவர்களும் உணர்ந்து இருப்பார்கள்.`,
  },
  {
    id: 659, tantraId: 3, verseNumber: 658,
    tamil: `ஒன்பது வாசல் உடையதோர் பிண்டத்துள்
ஒன்பது நாடி யுடையதோ ரோரிடம்
ஒன்பது நாடி ஒடுங்கவல் லார்கட்கு
ஒன்பது காட்சி உலைநல மாமே`,
    transliteration: `oṉpatu vācal uṭaiyatōr piṇṭattuḷ
oṉpatu nāṭi yuṭaiyatō rōriṭam
oṉpatu nāṭi oṭuṅkaval lārkaṭa(ku)
oṉpatu kāṭci yilaipala vāmē`,
    english: `658: Mukti Vision in Center of Nine Nadis
Within the fleshly body
That has gates nine,
There is a Center
Where the Nadis nine meet;
For them who can contain the Nadis nine
Not nine their vision, but several, several.`,
    elaborationEnglish: `For them who can contain the Nadis nine Not nine their vision, but several. several.`,
    elaborationTamil: `ஒன்பது துவாரங்களைக் (இரண்டு கண், இரண்டு காது, வாய், மூக்கு, மலத் துவாரம், சிறுநீர்த் துவாரம்) கொண்ட மனித உடலில் இருக்கும் ஒன்பது வித நாடிகளை (இடகலை, பிங்கலை, சிகுவை, புருடன், காந்தாரி, அத்தி, அலம்புடை, சங்கினி, குகு) புருவ மத்தியில் ஒருமுகப்படுத்தி தவம் செய்யக்கூடியவர்களின் உடலுக்கு என்றும் அழிவில்லை. கருத்து: ஒன்பது நாடிகளையும் ஒருமுகப்படுத்தி தவம் செய்பவர்களுக்கு உடல் என்றும் அழியாமல் இருக்கும்.`,
  },
  {
    id: 660, tantraId: 3, verseNumber: 659,
    tamil: `ஓங்-கிய அங்கிக்கீழ் ஒண்சுழு னைச்செல்ல
வாங்கி இரவி மதிவழி ஓடிடத்
தாங்கி உலகங்கள் ஏழுந் தரித்திட
ஆங்கது சொன்னோம் அருவழி யோர்க்கே`,
    transliteration: `ōṅ-kiya aṅkikkīḻ oṇcuḻu ṉaiccella
vāṅki iravi mativaḻi ōṭiṭat
tāṅki ulakaṅkaḷ ēḻun tarittiṭa
āṅkatu coṉṉōm aruvaḻi yōrkkē`,
    english: `659: Practice of Kundalini Yoga
Kindle Kundalini Fire
That burns lamnent in Muladhara
Send it up through Sushumna
The spinal column Central,
Course into it Prana breath
That runs through Nadis Sun and Moon,
That the way to reach
The seven mystic worlds in Cranium
To them we bade this
That are wise to learn.`,
    elaborationTamil: `மூலாதாரத்தில் உள்ள குண்டலினி அக்கினியை எழுப்பிச் சுழுமுனை நாடி வழியே தலை உச்சிக்கு இழுத்து பிராணாயம முறைப்படி சூரியகலை (வலது நாசி), சந்திரகலை (இடது நாசி) வழியாக உள்ளிழுக்கும் மூச்சுக்காற்றால் தாங்கி ஏழு உலகங்களிலும் வியாபித்து இருக்கும் ஆற்றலை அடையலாம். இம்முறையை சிவனது அருள்வழியில் செல்பவர்களுக்கு யாம் கூறினோம். கருத்து: ஏழு உலகங்களிலும் வியாபித்து இருக்கும் ஆற்றலை அடையும் வழியை சிவ வழியில் செல்வோர்க்கு கூறுகிறார்.`,
  },
  {
    id: 661, tantraId: 3, verseNumber: 660,
    tamil: `தலைப்பட்ட வாறண்ணல் தையலை நாடி
வலைப்பட்ட பாசத்து வன்பிணை மான்போல்
துலைப்பட்ட நாடியைத் தூவழி செய்தால்
விலைக்குண்ண வைத்ததோர் வித்தது வாமே`,
    transliteration: `talaippaṭṭa vāṟaṇṇal taiyalai nāṭi
valaippaṭṭa pācattu vaṉpiṇai māṉpōl
tulaippaṭṭa nāṭiyait tūvaḻi ceytāl
vilaikkuṇṇa vaittatōr vittatu vāmē`,
    english: `660: Conquest of Bindu Through Nadi
O! Jiva! you seek woman in lust
And Lo! like a fawn are you caught in net;
And you know how to make
Central Nadi the Way Great,
The seed (Bindu) you kept for sale,
May your own be to consume.`,
    elaborationTamil: `இடகலை பிங்கலை நாடிகளுக்கு நடுவிலுள்ள சுழுமுனை நாடியை பிராணாயாமத்தின் மூலம் திறக்க வைத்தால் வலையில் சிக்கிய மானைத் தேடி ஓடிவரும் அதன் துணை மானைப் போல குண்டலினி சக்தியானது சகஸ்ரதளத்திலுள்ள சிவத்தை தேடி அடையும். அடைந்தபின் சேமித்து வைத்த உணவு பண்டம் எப்போதும் உண்ண உதவுவதுபோல அந்நாக்கில் ஊறும் அமுதமானது உடலோடு உயிர் நீடித்திருக்க வைத்திருக்கும். கருத்து: குண்டலினி சக்தியை தலை உச்சியில் சேர்த்தால் அமுதம் ஊறி உடலோடு உயிர் நீண்டகாலம் நீடித்திருக்கும்.`,
  },
  {
    id: 662, tantraId: 3, verseNumber: 661,
    tamil: `ஓடிச்சென் றங்கே ஒருபொருள் கண்டவர்
நாடியி னுள்ளாக நாதம் எழுப்புவர்
தேடிச்சென் றங்கே தேனை முகந்துண்டு
பாடியுள் நின்ற பகைவரைக் கட்டுமே`,
    transliteration: `ōṭicceṉ ṟaṅkē oruporuḷ kaṇṭavar
nāṭiyi ṉuḷḷāka nātam eḻuppuvar
tēṭicceṉ ṟaṅkē tēṉai mukantuṇṭu
pāṭiyuḷ niṉṟa pakaivaraik kaṭṭumē`,
    english: `661: Raise Nada and Vision Lord Through Nadi
They who raise Nada within the Nadi
In a flash behold the Being One;
There they bibed the mystica nectar
Vanquishing besieging foes all.`,
    elaborationTamil: `மூலாதாரத்திலிருந்து குண்டலினியை எழுப்பி சகஸ்ரதளத்திற்கு விரைவாக அடைந்து அங்கு சிவத்தை தரிசித்தவர்கள் அங்குள்ள நாடியினுள்ளே ஓங்கார ஒலியை எழுப்புவார்கள். அதன்பிறகு அமுதம் ஊறுகின்ற அன்னாக்கைத் தேடிச் சென்று அங்கே ஊறும் அமுதத்தை பருகியவர்களுக்கு இறைவனை அடையத் தடையாயிருக்கின்ற மாயை, அகங்காரம், ஆணவம், காமம், குரோதம் ஆகிய ஐந்துவித பகைவர்களும் அடங்கி இருப்பார்கள். கருத்து: குண்டலினி சக்தியின் மூலம் இறைவனை தரிசித்தவர்களுக்கு இறைவனை அடையத் தடையாயிருக்கும் அனைத்தும் அடங்கியிருக்கும்.`,
  },
  {
    id: 663, tantraId: 3, verseNumber: 662,
    tamil: `கட்டிட்ட தாமரை ஞாளத்தில் ஒன்பது
மட்டிட்ட கன்னியர் மாதுடன் சேர்ந்தனர்
கட்டிட்டு நின்று களங்கனி யூடுபோய்ப்
பொட்டிட்டு நின்று பூரண மானதே`,
    transliteration: `kaṭṭiṭṭa tāmarai ñāḷattil oṉpatu
maṭṭiṭṭa kaṉṉiyar mātuṭaṉ cērntaṉar
kaṭṭiṭṭu niṉṟu kaḷaṅkaṉi yūṭupōyp
poṭṭiṭṭu niṉṟu pūraṇa māṉatē`,
    english: `662: Reaching Purna Sakti
Up on the stalk of the Mystic Lotus bud
The Nine Virgins sweet as nectar
Joined the Lady (Kundalini)
One by one they climbed the floors
They reached the victorious top
And there into Perfection transformed.`,
    elaborationTamil: `உடலிலுள்ள ஒன்பதுவித சக்திகளும் சகஸ்ரதளத் தாமரையின் தண்டாகிய சுழுமுனை வழியே குண்டலினி சக்தியோடு இணைந்து சென்று சகஸ்ரதளத்தை அடைந்து அங்கு இருக்கும் பராசக்தியோடு சேர்ந்து பூரண சக்தியாகி (முழுமையான சக்தியாகி) நிரந்தரமாக இருக்கும். ஒன்பது சக்திகள்: வாமை = ஊன்றல் ஜேஷ்டை = சுழித்தல் ரெளத்திரி = விசிரிம்பித்தல் காளி = மடித்து மேலேறல் கலவிகரணி = அங்கிருந்து கீழ்வரல் பலவிகரணை = மேல் புடை பெயர்த்தல் பலப்பிரமதனி = கீழ்த் தாழல் சர்வபூததமனி = கீழ் ஊன்றி நிற்றல் மனோன்மணி = வரி வடிவாதல் கருத்து: குண்டலினியை சகஸ்ரதளத்தோடு சேர்ப்பவர்களுக்கு உடலிலுள்ள ஒன்பது சக்திகளும் பராசக்தியோடு இணைந்து நிரந்தரமாக இருக்கும்.`,
  },
  {
    id: 664, tantraId: 3, verseNumber: 663,
    tamil: `பூரண சத்தி ஏழுமூன் றறையாக
ஏரணி கன்னியர் எழுநூற்றஞ் சாக்கினார்
நாரணன் நான்முக னாதிய ஐவர்க்குங்
காரண மாகிக் கலந்து விரிந்ததே`,
    transliteration: `pūraṇa catti ēḻumūṉ ṟaṟaiyāka
ēraṇi kaṉṉiyar eḻunūṟṟañ cākkiṉār
nāraṇaṉ nāṉmuka ṉātiya aivarkkuṅ
kāraṇa mākik kalantu virintatē`,
    english: `663: Poorna Sakti as the Supreme Cause Expands
Sakti that is Poorna (Perfection)
Filled Herself into Chambers Three times Seven;
The Nine lovely Virgins became a hundred and five
And as the Cause of Vishnu, Brahma
And the rest of the Gods Five
She expanded pervasive.`,
    elaborationEnglish: `Line 1—poorna sakti is Adi or Primal Sakti.

Line 2—She evolves as ichcha, jnana and kriya and fills the seven adharas, including sahasrara.

Poorna Sakti evolves in Nada

The Damsel thus blossomed the expanded; But if’ She chooses to hide Herself within, The elements five and ali.that expanded out of Her Will evolves in the reverberant. primal sound, Nada.`,
    elaborationTamil: `ஒன்பது சக்திளும் இணைந்த பராசக்தியானது (பாடல் #663 இல் உள்ளபடி) உடலில் படைத்தல், காத்தல், அழித்தல், மறைத்தல், அருளல் ஆகிய தொழில்களைச் செய்யும் ஐந்து மூர்த்திகளையும் உணர்கின்ற ஐந்து இடங்களுக்கும் இருபத்து ஒருவராக பிரிந்து மொத்தம் நூற்று ஐவராக கலந்து இருக்கின்றார்கள். கருத்து: உடலில் ஐந்தொழில்களையும் செய்கின்ற ஐந்து இடங்களிலும் சக்தியாக பூரணசக்தி கலந்து இருக்கின்றது.`,
  },
  {
    id: 665, tantraId: 3, verseNumber: 664,
    tamil: `விரிந்து குவிந்து விளைந்தஇம் மங்கை
கரந்துள் எழுந்து கரந்தங் கிருக்கிற்
பரந்து குவிந்தது பார்முதற் பூதம்
இரைந்தெழு வாயு விடத்தினில் ஒடுங்கே`,
    transliteration: `virintu kuvintu viḷaintaim maṅkai
karantuḷ eḻuntu karantaṅ kirukkiṟ
parantu kuvintatu pārmutaṟ pūtam
irainteḻu vāyu viṭattiṉil oṭuṅkē`,
    english: `664: Poorna Sakti Involutes in Nada
The Damsel thus blossomed and expanded;
But if She chooses to hide Herself within,
The elements five and all that expanded out of Her
Will involute in the reverberant primal sound, Nada.`,
    elaborationTamil: `உடலில் நூற்று ஐந்தாக பிரிந்து இருக்கின்ற சக்தி (பாடல் #664 இல் உள்ளபடி) பரிபூரணமாய் ஒருநிலைப்பட்டு மறைந்தவாறு உடலுக்குள் எழுந்து அங்கே மறைந்து உடலெங்கும் பரவி உடலிலுள்ள பஞ்ச பூதங்களுடன் ஒருமுகப்பட்டு உடலிலுள்ள பத்துவித வாயுக்களோடு ஒடுங்கி இருக்கும். கருத்து: உடலிலுள்ள பஞ்ச பூதங்களோடும் பத்துவித வாயுக்களோடும் பூரணசக்தி கலந்து இருக்கும்.`,
  },
  {
    id: 666, tantraId: 3, verseNumber: 665,
    tamil: `இடையொடு பிங்கலை என்னும் இரண்டு
மடைபடு வாயுவு மாறியே நிற்குந்
தடையவை யாறேழுந் தண்சுட ருள்ளே
மிடைவளர் மின்கொடி தன்னில் ஒடுங்கே`,
    transliteration: `iṭaiyoṭu piṅkalai eṉṉum iraṇṭu
maṭaipaṭu vāyuvu māṟiyē niṟkun
taṭaiyavai yāṟēḻun taṇcuṭa ruḷḷē
miṭaivaḷar miṉkoṭi taṉṉil oṭuṅkē`,
    english: `665: Merge in Poorna Sakti
The breath in nadisto Left and Right
When in alternation made to course,
And passes beyond the Adhara barrier Six,
There amidst the Cool Flame
Is seated Sakti of the Lightning Form,
In Her merged you be.`,
    elaborationTamil: `உடம்பில் அடங்கியிருக்கும் மூச்சுக்காற்றை இடகலை, பிங்கலை மூச்சுப்பயிற்சி முறைப்படி பிராணாயாமம் செய்து மாற்றி சுழுமுனை வழியே மேலெழும்புமாறு செய்தால் குளிர்ந்த கடலில் மழை பெய்யும் பொழுது ஏற்படும் கொடி போன்ற மின்னலும் கடலும் சேர்ந்து ஒன்றாகத் தெரிவது போல குண்டலினி சக்தி ஆறு சக்கரங்களைக் கடந்து ஏழாவது சக்கரமான சகஸ்ரதளத்தோடு மனம் ஒடுங்கும். கருத்து: பிராணாயாமப் பயிற்சியை முறைப்படி செய்தால் குண்டலினி சக்தி சகஸ்ரதளத்தோடு மனமும் ஒன்றிவிடும்.`,
  },
  {
    id: 667, tantraId: 3, verseNumber: 666,
    tamil: `ஒடுங்கி ஒருங்கி யுணர்ந்தங் கிருக்கில்
மடங்கி அடங்கிடும் வாயு வதனுள்
மடங்கி மடங்கிடு மன்னுயி ருள்ளே
நடங்கொண்ட கூத்தனும் நாடுகின் றானே`,
    transliteration: `oṭuṅki oruṅki yuṇarntaṅ kirukkil
maṭaṅki aṭaṅkiṭum vāyu vataṉuḷ
maṭaṅki maṭaṅkiṭu maṉṉuyi ruḷḷē
naṭaṅkoṇṭa kūttaṉum nāṭukiṉ ṟāṉē`,
    english: `666: Lord Dances in Jiva
Senses controlled,
Thought in oneness centered
If you sit in realization thus,
Prana breath that comes
Circling again and again
Will in Jiva gently merge;
Within that Jiva the Dancer dances
And I stand seeking Him there.`,
    elaborationTamil: `பாடல் #665 ல் உள்ளபடி ஒடுங்கிய மனதில் இருக்கும் இறைவனை உணர்ந்து லயித்திருந்தால் மூச்சுக்காற்றும் அதனோடு அடங்கியிருக்கும். அவ்வாறு அனைத்தும் அடங்கியிருக்கும் உடம்போடு உயிர் நிலைபெற்று இருக்கும். அவ்வாறு நிலைபெற்ற உயிரில் நடனத்திற்குத் தலைவனான இறைவனே நாடி வந்து இருப்பான். கருத்து: குண்டலினி சக்தியும் மூச்சுக்காற்றும் மனமும் ஒருமுகப்பட்டு இருக்கும் உயிரில் இறைவன் நாடி வந்து இருப்பான்.`,
  },
  {
    id: 668, tantraId: 3, verseNumber: 667,
    tamil: `நாடியின் உள்ளே நாதத் தொனியுடன்
தேடி யுடன்சென்றத் திருவினைக் கைக்கொண்டு
பாடியுள் நின்ற பகைவரைக் கட்டிட்டு
மாடி ஒருகை மணிவிளக் கானதே`,
    transliteration: `nāṭiyiṉ uḷḷē nātat toṉiyuṭaṉ
tēṭi yuṭaṉceṉṟat tiruviṉaik kaikkoṇṭu
pāṭiyuḷ niṉṟa pakaivaraik kaṭṭiṭṭu
māṭi orukai maṇiviḷak kāṉatē`,
    english: `667: Through Nada Yoga I Reached to Sakti
I coursed the breath upward through Sushumna
And to the accompaniment of Nada's sound (Aum)
I sought;
And lo! there the Damsel was
And I had Her
And seized and bound the enemies shielding Her;
And thus I possessed the Jewelled Lamp of Undying Flame
The Lamp that is of salvation's Treasure House.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-667-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationTamil: `பாடல் #666 ல் உள்ளபடி உயிரைத் தேடி வந்த இறைவன் சுழுமுனை நாடியின் உள்ளே ஓம் எனும் நாதமாய் நின்று இறைவனை அடையத் தடையாயிருக்கின்ற மாயை, அகங்காரம், ஆணவம், காமம், குரோதம் ஆகிய ஐந்துவித பகைவர்களையும் அவன் அருளால் அடக்கிவிட்டு என்றும் அணையாமல் வெளிச்சம் கொடுக்கும் விளக்குபோல என்றும் ஜோதியாய் விளங்குவான். கருத்து: உயிரோடு கலந்த இறைவன் அவனை அடையத் தடையாயிருக்கின்ற ஐந்துவித பகைவர்களை அடக்கி என்றும் அணையாத ஜோதியாய் இருப்பான்.`,
  },
  {
    id: 669, tantraId: 3, verseNumber: 668,
    tamil: `அணுமாதி சித்திக ளானவை கூறில்
அணுவில் அணுவின் பெருமையில் நேர்மை
இணுகாத வேகார் பரகாய மேவல்
அணுவத் தனையெங்குந் தானாத லென்றெட்டே`,
    transliteration: `aṇumāti cittika ḷāṉavai kūṟil
aṇuvil aṇuviṉ perumaiyil nērmai
iṇukāta vēkār parakāya mēval
aṇuvat taṉaiyeṅkun tāṉāta leṉṟeṭṭē`,
    english: `668: The Eight Siddhis Enumerated
To become tiny as the atom within atom (Anima)
To become big in unshakeable proportions (Mahima)
To become light as vapour in levitation (Lahima)
To enter into other bodies in transmigration (Prapt)
To be in all things, omni-pervasive (Prakamya)
To be lord of all creation in omnipotence (Isavatam)
To be everywhere in omnipresence (Vasitvam)
--These eight are the Siddhis Great.`,
    elaborationEnglish: `These eight siddhis are: 1) aniraa; -2) laghima; 3) mahima; 4) prapti; 5) garima; 6) prakamyam; 7) isatvam; and 8) vasitvam

Some authorities on the subject mention another siddhi known as kamavasayitham in place of garima.Tirumular calls this kamaru tattva. Although the subtitle, Garima, finds a place in the Tamil text — strictly as a subtitle .— there is no description of it. Actually the mantra under it relates to prapti. The subtitle. Garima, therefore, seems to be a: later extrapolation by some scholars. Garima can be. included. in mahima.`,
    elaborationTamil: `பாடல் #667 ல் உள்ளபடி உயிருக்குள் இறைவன் ஜோதியாய் விளங்கினால் அவ்வுயிருக்குக் கிடைக்கக் கூடிய எட்டுவித சித்திகளான, 1. அணிமா – அணுவைப் போல் உடலை சிறிதாக்கும் ஆற்றல். 2. மகிமா – மலையைப் போல் உடலை பெரிதாக்கும் ஆற்றல். 3. கரிமா – மலை போல எதனாலும் அசைக்க முடியாத அளவு உடலை கனமாக்கும் ஆற்றல். 4. இலகிமா – காற்றைப் போல் இலேசாய் உடலை மாற்றி எங்கும் செல்லும் ஆற்றல். 5. பிராப்தி – தூரத்திலிருப்பதையும் இருக்கும் இடத்திலேயே பார்க்கவும், மனதினால் நினைத்தவை யாவையும் அடையவும் பெறும் ஆற்றல். 6. பிராகாமியம் – எதையும் நினைத்தவுடன் அதாகவே தன்னை மாற்றிக் கொள்ளும் ஆற்றல். 7. ஈசத்துவம் – ஆக்கல், காத்தல், அழித்தல், மறைத்தல், அருளல் ஆகிய ஐந்தொழில்களைத் தன் ஆளுகைக்குட்பட்டுச் செய்தல். 8. வசித்துவம் – ஈரேழு பதினான்கு உலகங்களிலும் கலந்து அங்கிங்கெனாதபடி எங்கும் வியாபித்து இருக்கும் ஆற்றல் ஆகியவனவாகும். கருத்து: உயிருக்குள் இறைவன் ஜோதியாய் விளங்கினால் எட்டுவித சித்திகளும் கிடைக்கும்.`,
  },
  {
    id: 670, tantraId: 3, verseNumber: 669,
    tamil: `எட்டா கியசித்தி யோரெட்டி யோகத்தாற்
கிட்டாப் பிராணனே செய்தாற் கிடைத்திடும்
ஒட்டா நடுநாடி மூலத்த னல்பானு
விட்டான் மதியுண்ண வும்வரு மேலதே`,
    transliteration: `eṭṭā kiyacitti yōreṭṭi yōkattāṟ
kiṭṭāp pirāṇaṉē ceytāṟ kiṭaittiṭum
oṭṭā naṭunāṭi mūlatta ṉalpāṉu
viṭṭāṉ matiyuṇṇa vumvaru mēlatē`,
    english: `669: Beyond the Eight Siddhis in the Moon's Nectar
By eight-limbed yoga are Siddhis eight attained
When breath is in accord controlled;
But when Kundalini fire is through the Central Nadi coursed up,
And the Sun's mandala passed
Beyond that is the Moon's
Whence flow the ambrosia that may swilled be.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-669-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationTamil: `இயல்பாக எளிதில் அடங்காத மூச்சுக் காற்று அட்டாங்க யோகத்திலுள்ள பிராணாயாமத்தை முறைப்படி செய்வதன் மூலம் அடங்குவதோடு மட்டுமல்லாது எட்டுவிதமான சித்திகளும் கிடைப்பதற்கு வழிவகுக்கும். அதன் பின்னர் மூலாதாரத்திலிருக்கும் குண்டலினி சக்தி அக்கினிப் பிழம்பாய் கிளம்பி நடு நாடியாகிய சுழுமுனை வழியே மேலே சென்று சகஸ்ரதளத்தை அடைந்து பேரறிவாகிய இறைவனை உணரலாம். கருத்து: பேரறிவான இறைவனை உணர்வதற்கும் எட்டுவித சித்திகளை அடைவதற்கும் பிராணாயமம் உதவும்.`,
  },
  {
    id: 671, tantraId: 3, verseNumber: 670,
    tamil: `சித்திக ளெட்டன்றிச் சேரெட்டி யோகத்தாற்
புத்திக ளானவை எல்லாம் புலப்படுஞ்
சித்திகள் எண்சித்தி தானாந் திரிபுரை
சத்தி அருள்தரத் தானுள வாகுமே`,
    transliteration: `cittika ḷeṭṭaṉṟic cēreṭṭi yōkattāṟ
puttika ḷāṉavai ellām pulappaṭuñ
cittikaḷ eṇcitti tāṉān tiripurai
catti aruḷtarat tāṉuḷa vākumē`,
    english: `670: Siddhis Lead to Mukti Only by Sakti's Grace
By eight-limbed yoga way
Not only will Siddhis eight be
And the Goal behind the Siddhis too;
With effortless ease will they all be
If but Tripura Sakti Her Grace grants.`,
    elaborationTamil: `அட்டாங்க யோகத்தை முறைப்படி செய்பவர்களுக்கு எட்டு சித்திகள் கிடைப்பது மட்டுமன்றி ஆத்ம அறிவு முதல் அண்டசராசரங்கள் வரை அறிந்துகொள்ள முடியும். நமக்குள் இருக்கும் இறைவனது அருளால் அந்த இறைவனின் சக்தியானது நமக்குள்ளே எட்டுவித சித்திகளையும் உணர்த்திவிடும். கருத்து: அட்டாங்க யோகத்தை முறைப்படி செய்தால் இறைவனின் அருளால் எட்டுவித சித்திகளையும் பெற்று பேரறிவையும் அறியலாம்.`,
  },
  {
    id: 672, tantraId: 3, verseNumber: 671,
    tamil: `எட்டிவை தன்னோ டெழிற்பரங் கைகூடப்
பட்டவர் சித்தர் பரலோகஞ் சேர்தலால்
இட்டம துள்ளே இறுக்கல் பரகாட்சி
எட்டு வரப்பு மிடந்தானின் றெட்டுமே`,
    transliteration: `eṭṭivai taṉṉō ṭeḻiṟparaṅ kaikūṭap
paṭṭavar cittar paralōkañ cērtalāl
iṭṭama tuḷḷē iṟukkal parakāṭci
eṭṭu varappu miṭantāṉiṉ ṟeṭṭumē`,
    english: `671: Beyond Siddhis is True Goal
They are Siddhas
Who together with Siddhis eight
Attain the Divine;
They reach Para Loka
And within them vision the Dear Lord
Then they reach Him true,
Going beyond the boundaries eight.`,
    elaborationTamil: `அட்டமா சித்திகளோடு அழகுமிகுந்த பரம்பொருளான இறைவனும் தனக்குள் வரப் பெற்றவரே சித்தர் ஆவார். இவர்கள் தாம் இருக்கும் இடத்திலிருந்தே பரலோகத்தோடு ஒன்றி தம் உள்ளத்துள் பரம்பொருளான இறைவனை தரிசிக்கக்கூடியவர்கள். இவ்வருள் பெற்றவர்கள் இருக்கும் இடம் தேடி அட்டமா சித்திகளைச் சார்ந்த பல சித்திகளும் தானே வந்து சேரும். கருத்து: அட்டமா சித்திகளோடு இறைவனையும் தமக்குள் பெற்றவரே சித்தர் ஆவார்.`,
  },
  {
    id: 673, tantraId: 3, verseNumber: 672,
    tamil: `மந்தர மேறு மதிபானு வைமாற்றிக்
கந்தாய்க் குழியிற் கசடற வல்லார்க்குத்
தந்தின்றி நற் கா மியலோகஞ் சார்வாகும்
அந்த வுலகம் அணிமாதி யாமே`,
    transliteration: `mantara mēṟu matipāṉu vaimāṟṟik
kantāyk kuḻiyiṟ kacaṭaṟa vallārkkut
tantiṉṟi naṟ kā miyalōkañ cārvākum
anta vulakam aṇimāti yāmē`,
    english: `672: Siddhis Lead to Kamiya Loka
They who can alternate the course of breath Left and Right,
And send it upward through Spinal Cavity unerring to Mount Meru at top
To them, Kamiya Loka will of itself come;
The world that is reached by Anima and the rest of Siddhis Eight.`,
    elaborationTamil: `மூலாதாரத்திலிருந்து குண்டலினி சக்தியை சுழுமுனை நாடி வழியே மேலே ஏற்றிச் செல்வதால் கிடைக்கும் சக்தியானது நமது சிற்றறிவை மாற்றி பேரறிவைக் கொடுக்கும். அதன்பின் அந்நாக்கில் அமுதம் ஊறியவுடன் தீமைகளை அகற்றி யோகத்திலிருக்க வல்லவர்களுக்கு அவர்கள் எந்த உலகத்திற்குச் சென்றாலும் அதைச் சார்ந்திருக்கக்கூடிய நல்ல உடம்பு கிடைக்கும். அவ்வாறு வெவ்வேறு உலகங்களுக்கு ஏற்ப உடலை மாற்ற முடிவதே அணிமா என்னும் சித்தியாகும். கருத்து: குண்டலினி சக்தியை சகஸ்ரதளத்திற்கு ஏற்றுபவர்களுக்கு எல்லா உலகத்தையும் சார்ந்திருக்கக்கூடிய உடல் என்னும் அணிமா சித்தி கிடைக்கும்.`,
  },
  {
    id: 674, tantraId: 3, verseNumber: 673,
    tamil: `முடிந்திட்டு வைத்து முயங்கிலோ ராண்டில்
அணிந்த அணிமாகை தானாம் இவனுந்
தணிந்தவப் பஞ்சினுந் தானொய்ய தாகி
மெலிந்தங் கிருந்திடும் வெல்லவொண் ணாதே`,
    transliteration: `muṭintiṭṭu vaittu muyaṅkilō rāṇṭil
aṇinta aṇimākai tāṉām ivaṉun
taṇintavap pañciṉun tāṉoyya tāki
melintaṅ kiruntiṭum vellavoṇ ṇātē`,
    english: `673: Anima
Having succeeded in shooting Kundalini to Meru through
The Spinal Cavity
If he perseveres for a year,
He will attain Anima Siddhi;
Lighter than flimsiest cotton wool will he be
Yet invincible will he be.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-673-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationTamil: `அணிமா சக்தி கைவரப் பெற்றபின் ஓராண்டு யோகப் பயிற்சிகளை விடாமல் செய்து வந்தால் அணிமா சித்தியானது நிரந்தரமாகக் கைவரப் பெறும். அவ்வாறு பெற்றபின் யோகப் பயிற்சி செய்தவரின் உடல் பஞ்சைவிட மெலியதாகி இருந்தாலும் வலிமையானதாகவும் எவராலும் வெல்ல முடியாததாகவும் இருக்கும். கருத்து: அணிமா சித்தி கைவரப் பெற்றபின் ஓராண்டு விடாமல் பயிற்சி செய்துவர நிரந்தரமாகி உடல் பஞ்சைவிட மெலியதாகி எவராலும் வெல்லமுடியாமல் இருக்கும்.`,
  },
  {
    id: 675, tantraId: 3, verseNumber: 674,
    tamil: `ஆகின்ற வத்தனி நாயகி தன்னுடன்
போகின்ற தத்துவம் எங்கும் புகல தாய்ச்
சாகின்ற காலங்கள் தன்வழி நின்றிடின்
மாய்கின்ற தையாண்டின் மாலகு வாகுமே`,
    transliteration: `ākiṉṟa vattaṉi nāyaki taṉṉuṭaṉ
pōkiṉṟa tattuvam eṅkum pukala tāyc
cākiṉṟa kālaṅkaḷ taṉvaḻi niṉṟiṭiṉ
māykiṉṟa taiyāṇṭiṉ mālaku vākumē`,
    english: `674: Laghima
If after visioning Thani Nayaki (Adi Sakti)
And the Tattvas that go with Her,
For five years the yogi perseveres steadfast
He attains the Siddhi that is Laghima;
The power to penetrate anywhere at will.`,
    elaborationEnglish: `Laghima— The traditional interpretations are: 1) ‘‘The power of levitation;’’-2} ““The power to render the body light at will.’ This achievement is the mastery over the element ‘air’, the plane of ‘buddhi’ or spiritual discrimination. The soul, by rising up into the air, obtains “‘birds-eye-view’’ of the lower planes. — “‘The Book Of Signs’’ by G.H. Mees, Vol/T., p-200

After attaining anima siddhi, the yogi should persevere for five years to attain the laghima siddhi. This is the power to render the body light at will. it is the power of levitation. It is the mastery over element ‘air’ The yogi will glow with divine light suffusing a radiance that is milk-white. In laghima the yogi visions the Melliyal Sakti (Sakti of Tender Form)`,
    elaborationTamil: `அணிமா என்கின்ற சக்தியானது கைவரப் பெற்ற பின்னும் விட்டுவிடாமல் யோகப் பயிற்சி செய்து முடிந்த ஐந்தாண்டு காலமும் தான் பயிற்சி செய்யும் யோகத்தின் வழியிலிருந்து மாறாது இருக்க இலகிமா என்கின்ற சித்தியும் கிடைக்கும். கருத்து: அணிமா என்னும் சித்தி கிடைத்தபின் ஐந்தாண்டுகள் இடைவிடாமல் யோகப் பயிற்சி செய்தால் இலகிமா என்னும் சித்தி கிடைக்கும்.`,
  },
  {
    id: 676, tantraId: 3, verseNumber: 675,
    tamil: `மாலகு வாகிய மாயனைக் கண்டபின்
தானொளி யாகித் தழைத்தங் கிருந்திடும்
பாலொளி யாகிப் பரந்தெங்கு நின்றது
மேலொளி யாகிய மெய்ப்பொருள் காணுமே`,
    transliteration: `mālaku vākiya māyaṉaik kaṇṭapiṉ
tāṉoḷi yākit taḻaittaṅ kiruntiṭum
pāloḷi yākip paranteṅku niṉṟatu
mēloḷi yākiya meypporuḷ kāṇumē`,
    english: `675: Vision in Laghima
When the yogi attains Laghima Siddhi,
He will glow with divine light;
With that glow suffusing milk white radiance
He will vision the heavenly glow
That is Truth.`,
    elaborationTamil: `இலகிமா என்னும் சித்தி கிடைத்து இறைவனை தரிசித்தபின் தாமே ஒளி உடம்பாய் மாறி ஒளி உடம்போடு இருக்கப் பால் போன்ற வெண்மையான ஒளியாகி எங்கும் பரந்து இருக்கும் பேரொளியாய் உண்மைப் பொருளாகவும் உள்ள இறைவனை தரிசிக்கலாம். கருத்து: இலகிமா சித்தியடைந்தபின் வெண்மையான ஒளி உடம்பாய் மாறி உண்மைப் பொருளான இறைவனை தரிசிக்கலாம்.`,
  },
  {
    id: 677, tantraId: 3, verseNumber: 676,
    tamil: `மெய்ப்பொருள் சொல்லிய மெல்லிய லாளுடன்
தற்பொரு ளாகிய தத்துவங் கூடிடக்
கைப்பொரு ளாகக் கலந்திடு மோராண்டின்
மைப்பொரு ளாகு மகிமாவ தாகுமே`,
    transliteration: `meypporuḷ colliya melliya lāḷuṭaṉ
taṟporu ḷākiya tattuvaṅ kūṭiṭak
kaipporu ḷākak kalantiṭu mōrāṇṭiṉ
maipporu ḷāku makimāva tākumē`,
    english: `676: Mahima
A year after attaining Laghima
When Tattvas take their refuge in Sakti of Form Tender,
Will Mahima Siddhi be;
As plain as his palm
It shall be for the yogi to see.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-676-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationEnglish: `Mahima —- The traditi<..a] interpretations are: 1} ““The power to expand one’s cuusciousness to the largest atom or form;” 2) “Power, might, glory."’ It is the power of ‘greatness,”’ referring to the element, ‘fire’, the mental plane. It is the mastery over thought, over the lower mind, over the ‘creative urges of that mind. The attainment of this mastery truly implies Height is the dimension which this plane. it also requires greatness to overcome the adversaries on this plane, which in and fairy tales take the form of giants. — Vide G.H. Mees op. cit.

A year after attaining laghima, the yogi attains mahima siddhi. it is the power of becoming great. It is the mastery over the element ‘fire’. It is the power to expand one’s consciousness to the largest atom or form. The yogi conquers time. It stops for him. The past merges into space. Of the future he becomes the Lord. His breath is transformed into light. From him emanaies jeana, and he visions Tattvanayaki (Sakti of Taitvas).`,
    elaborationTamil: `அணிமாவும் இலகிமாவும் கிடைத்தபின் உண்டான உண்மை ஞானமாகிய பேரறிவை உணர்த்தும் அருள் சக்தியுடன் தமக்குள் தத்துவமாய் இருக்கும் இறைவனுடன் கலந்து ஒரு வருடம் இருந்தால் மாயை விலகி மறைந்திருந்த மகிமா எனும் சித்தி நமக்குக் கிடைக்கும். கருத்து: உண்மை ஞானமாகிய பேரறிவும் தமக்குள் தத்துவமாய் இருக்கும் இறைவனுடன் கலந்து ஒரு வருடம் இருந்தால் மகிமா எனும் சித்தி கிடைக்கும்.`,
  },
  {
    id: 678, tantraId: 3, verseNumber: 677,
    tamil: `ஆகின்ற காலொளி யாவது கண்டபின்
போகின்ற காலங்கள் போவது மில்லையாம்
மேனின்ற காலம் வௌியுற நின்றன
தானின்ற காலங்கள் தன்வழி யாகுமே`,
    transliteration: `ākiṉṟa kāloḷi yāvatu kaṇṭapiṉ
pōkiṉṟa kālaṅkaḷ pōvatu millaiyām
mēṉiṉṟa kālam vauiyuṟa niṉṟaṉa
tāṉiṉṟa kālaṅkaḷ taṉvaḻi yākumē`,
    english: `677: Time Transcended in Mahima
Having seen the light of time arise,
The passing times no longer pass;
The time that stands above is manifest in space,
The time that stands within becomes its own way.`,
    elaborationTamil: `பிராணாயாம முறைப்படி மூச்சுக்காற்றை சுழுமுனை நாடி வழியே மேலேற்றிச் சென்று அது சகஸ்ரதளத்தோடு கலந்து ஜோதியானதை அகக் கண்ணால் கண்டபின் மகிமா எனும் சித்தி கிடைக்கும். அதன்பின் வரும் காலங்கள் நமது ஆயுள் காலத்தை அழிப்பது இல்லை. உலகத்திலுள்ள அனைத்தையும் விட பெரியதாகிய காலத்தை மகிமா எனும் சித்தியால் வென்று காலத்தால் நாம் பாதிக்கப்படாமல் இருக்கலாம். அவ்வாறு இருக்கும் காலங்களை நமது எண்ணப்படி அமைக்கலாம். கருத்து: சகஸ்ரதளத்தில் ஜோதி தரிசனம் கண்டபின் மகிமா எனும் சித்தி கைவரப்பெற்று காலத்தை வெல்லலாம்.`,
  },
  {
    id: 679, tantraId: 3, verseNumber: 678,
    tamil: `தன்வழி யாகத் தழைத்திடு ஞானமுந்
தன்வழி யாகத் தழைத்திடும் வையகந்
தன்வழி யாகத் தழைத்த பொருளெல்லாந்
தன்வழி தன்னரு ளாகிநின் றானே`,
    transliteration: `taṉvaḻi yākat taḻaittiṭu ñṉamun
taṉvaḻi yākat taḻaittiṭum vaiyakan
taṉvaḻi yākat taḻaitta poruḷellān
taṉvaḻi taṉṉaru ḷākiniṉ ṟāṉē`,
    english: `678: Finite Attainments Through Mahima Siddhi
Through him all Jnana grows
Through him all world flourishes
Through him all things prosper
Himself in the Grace of Lord stands.`,
    elaborationTamil: `தான் என்னும் அகங்காரத்தை விட்டு தானே சிவம் என்பதை உணர்ந்தவன் மூலம் உலகத்தார் ஞானம் செழித்து ஓங்கும். உலகமும் செழிப்புற்று விளங்கும். அவன் வழியால் செழித்த பொருட்களெல்லாம் அவன் வசப்பட்டு நிற்கும். உலகத்தைவிட பெரியவனாக அவன் இருப்பதால் மகிமா எனும் சித்தியைக் குறிக்கின்றது. கருத்து: மகிமா சித்தி கைவரப் பெற்றவரின் அருளால் உலகத்தில் ஞானமும் வளங்களும் செழித்து இருக்கும்.`,
  },
  {
    id: 680, tantraId: 3, verseNumber: 679,
    tamil: `நின்றன தத்துவ நாயகி தன்னுடன்
கண்டன பூதப் படையவை யெல்லாங்
கொண்டவை யோராண்டு கூட இருந்திடில்
விண்டது வேநல்ல பிராத்தி யதாகுமே`,
    transliteration: `niṉṟaṉa tattuva nāyaki taṉṉuṭaṉ
kaṇṭaṉa pūtap paṭaiyavai yellāṅ
koṇṭavai yōrāṇṭu kūṭa iruntiṭil
viṇṭatu vēnalla pirātti yatākumē`,
    english: `679: Prapti in a Year After Visioning Sakti
He who thus stood in Mahima
Visions the Lady of Tattvas (Tattva Nayaki)
And the Celestial Bhutas,
If the yogi thus perseveres continuous for a year
Then he attains Prapti divine.`,
    elaborationEnglish: `Prapti —- The iraditional interpretations are: 1) “‘The power

to give indefinite extension to the subtle body or its members;"’ 2) “‘The power to obtain any desired objective anywhere; 3) “‘The connection of a being with his organs as their presiding deity known as attainment;’’ 4) ‘‘Arrival at the goal, deliverance, discovery, good fortune, joyful meaning..."" This particular achievement refers to mastery or tulership of the earth-sphere. — Vide G.H. Mees, op.cit..`,
    elaborationTamil: `நம்மைக் கட்டுப்படுத்தும் பஞ்ச பூதங்கள் முதலான பல்வேறு தத்துவங்களை உணர்ந்து அனைத்திற்கும் தலைவியான அருள் சக்தியுடன் மனதை ஒருமுகப்படுத்தி வைத்து அதிலேயே லயித்து யோகப் பயிற்சியில் ஒரு வருடம் இருந்தால் அந்தத் தத்துவங்களை வெல்லலாம். அவ்வாறு அனைத்து தத்துவங்களையும் வென்றவருக்கு பிராத்தி எனும் சித்தி கிடைக்கும். கருத்து: உலகத் தத்துவங்களிலிருந்து விலகி ஒரு வருடம் யோகப் பயிற்சி செய்தால் பிராத்தி எனும் சித்தி கிடைக்கும். பிராப்தி என்பது தூரத்திலிருப்பதை இருக்கும் இடத்திலேயே பார்க்கவும் மனதினால் நினைத்தவை யாவையும் அடையவும் பெறும் ஆற்றல்.`,
  },
  {
    id: 681, tantraId: 3, verseNumber: 680,
    tamil: `ஆகின்ற மின்னொளி யாவது கண்டபின்
பாகின்ற பூவிற் பரப்பவை காணலா
மேகின்ற காலம் வௌியுற நின்றது
போகின்ற காலங்கள் போவது மில்லையே`,
    transliteration: `ākiṉṟa miṉṉoḷi yāvatu kaṇṭapiṉ
pākiṉṟa pūviṟ parappavai kāṇalā
mēkiṉṟa kālam vauiyuṟa niṉṟatu
pōkiṉṟa kālaṅkaḷ pōvatu millaiyē`,
    english: `680: Time Stops in Prapti
Having visioned the dazzling Light of Sakti,
The Siddha perceives the Cosmos vast
That unto a flower unfolds,
The past merged into Space
And the future Time for ever stops.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-680-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationEnglish: `Experiences in Prapti

No going; No coming;

No death; No aging

No delay in secing Light of Breath (Nada) ‘Nothing desired in particular,

Thus it is with Siddhas

Who attained this Siddhi.`,
    elaborationTamil: `பிராணாயாம முறைப்படி மூச்சுக்காற்றை சுழுமுனை நாடி வழியே மேலேற்றிச் சென்று அது சகஸ்ரதளத்தோடு கலந்து ஜோதியானதை அகக் கண்ணால் கண்டபின் கரிமா எனும் சித்தி கிடைக்கும். அதன்பின் வரும் காலங்கள் நமது ஆயுள் காலத்தை அழிப்பது இல்லை. அவ்வாறு கரிமா எனும் சித்தியால் காலத்தை வெல்பவர்கள் மலைபோல அசைக்கமுடியாமல் இருப்பார்கள். கருத்து: சகஸ்ரதளத்தில் ஜோதி தரிசனம் கண்டபின் கரிமா எனும் சித்தி கைவரப்பெற்று காலத்தால் அசைக்கமுடியாமல் இருக்கலாம்.`,
  },
  {
    id: 682, tantraId: 3, verseNumber: 681,
    tamil: `போவதொன் றில்லை வருவது தானில்லை
சாவதொன் றில்லை தழைப்பது தானில்லை
தாமத மில்லை தமரகத் தின்னொளி
யாவது மில்லை யறிந்துகொள் வார்க்கே`,
    transliteration: `pōvatoṉ ṟillai varuvatu tāṉillai
cāvatoṉ ṟillai taḻaippatu tāṉillai
tāmata millai tamarakat tiṉṉoḷi
yāvatu millai yaṟintukoḷ vārkkē`,
    english: `681: Experiences in Prapti
No going; No coming;
No death; No aging
No delay in seeing Light of Breath (Nada)
Nothing desired in particular,
Thus it is with Siddhas
Who attained this Siddhi.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-681-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationTamil: `கரிமா சித்தி பெற்றவர்களுக்கு காலங்கள் அழிவது இல்லை. காலங்கள் புதிதாக வருவதும் இல்லை. இறப்பு இல்லை. ஆகவே பிறப்பும் இல்லை. அவர்கள் நிகழ்காலத்திலேயே எப்போதும் தனக்குள் இருக்கும் ஒளியுடனே லயித்து எவற்றாலும் பாதிக்கப்படாமல் இருப்பார்கள். கருத்து: கரிமா சித்தி பெற்றவர்களுக்கு காலத்தினால் பாதிப்புகள் வருவது இல்லை.`,
  },
  {
    id: 683, tantraId: 3, verseNumber: 682,
    tamil: `அறிந்த பராசத்தி யுள்ளே அமரில்
பறிந்தது பூதப் படையவை யெல்லாங்
குவிந்தவை யோராண்டு கூட இருக்கில்
விரிந்தது பரகாய மேவலு மாமே`,
    transliteration: `aṟinta parācatti yuḷḷē amaril
paṟintatu pūtap paṭaiyavai yellāṅ
kuvintavai yōrāṇṭu kūṭa irukkil
virintatu parakāya mēvalu māmē`,
    english: `682: Prakamya a Year After Prapti
When Prapti is attained
Parasakti resides palpably within;
And all Tattvas flee
When he is for a year thus,
He attains the power to transmigrate into alien bodies.`,
    elaborationEnglish: `He attains the power to transmigrate into alien bodies.`,
    elaborationTamil: `இறை சக்தியை நமக்குள்ளே உணர்ந்து அதனோடு ஒரு ஆண்டு மனதை ஒருமுகப்படுத்தி ஒன்றியிருந்தால் நம்மைக் கட்டுப்படுத்தும் பஞ்ச பூதங்கள் முதலான பல்வேறு தத்துவங்கள் அனைத்தும் விலகிவிடும். அவ்வாறு விலகியபின் எதையும் நினைத்தவுடன் அதாகவே தன்னை மாற்றிக் கொள்ளும் பிராகாமியம் என்னும் சித்தி கிடைக்கும். கருத்து: இறை சக்தியோடு ஒரு ஆண்டு ஒன்றியிருந்தால் உலகத் தத்துவங்களிலிருந்து விலகி பிராகாமியம் எனும் சித்தியை அடையலாம்.`,
  },
  {
    id: 684, tantraId: 3, verseNumber: 683,
    tamil: `ஆன விளக்கொளி யாவ தறிகிலர்
மூல விளக்கொளி முன்னே யுடையவர்
கான விளக்கொளி கண்டுகொள் வார்கட்கு
மேலை விளக்கொளி வீடௌி தாநின்றே`,
    transliteration: `āṉa viḷakkoḷi yāva taṟikilar
mūla viḷakkoḷi muṉṉē yuṭaiyavar
kāṉa viḷakkoḷi kaṇṭukoḷ vārkaṭku
mēlai viḷakkoḷi vīṭaui tāniṉṟē`,
    english: `683: Salvation Easy After Prakamya
They know not how the Being within
Becomes the Light Radiant;
That Light is already within in Muladhara;
With it they can see the Light of Nada above;
Them who thus seek
The Light Above leads to Liberation effortless.`,
    elaborationEnglish: `1) Prakamya — The traditional interpretations are: 1) ‘‘The capacity to derive enjoyment from everything heard or seen;"’ 2) “The power to exercise an irresistible will upon the minds

of others;’’ 3) ““The power to obtain more than one expects;”” 4) ‘‘The power to enter into the body of another;’’ 5) ““The power to maintain a youthful appearance for an unusual length of time.’’ It is the mastery over the element water,’’ the emotional or astral plane —- G.H. Mees, op.cit.`,
    elaborationTamil: `எதையும் நமக்கு உணரவைக்கும் சிவத்தின் ஒளி நமது புருவ மத்தியில் ஆக்ஞா ஒளியாக இருப்பதை யாரும் அறியவில்லை. மூலாதாரத்திலிருக்கும் அக்கினியை மேலேற்றிச் சென்று சகஸ்ரதளத்தில் ஒளிமயமாக பார்க்க முடிந்தவர்களுக்கு ஜோதியாய் இருக்கும் சதாசிவத்தை தரிசிப்பதும் அதன் மூலம் முக்தியை அடைவதும் எளிதாகும். கருத்து: மூலாதாரத்திலிருக்கும் அக்கினியை சகஸ்ரதளத்திற்கு கொண்டு செல்ல முடிந்தவர்களுக்கு ஜோதி தரிசனமும் முக்தியும் எளிதாகும்.`,
  },
  {
    id: 685, tantraId: 3, verseNumber: 684,
    tamil: `நின்ற சதாசிவ நாயகி தன்னுடன்
கண்டன பூதப் படையவை எல்லாங்
கொண்டவை யோராண்டு கூடி யிருந்திடிற்
பண்டையவ் வீசன் தத்துவ மாகுமே`,
    transliteration: `niṉṟa catāciva nāyaki taṉṉuṭaṉ
kaṇṭaṉa pūtap paṭaiyavai ellāṅ
koṇṭavai yōrāṇṭu kūṭi yiruntiṭiṟ
paṇṭaiyav vīcaṉ tattuva mākumē`,
    english: `684: Isatva a Year After Prakamya
A year rolls by after the Siddha attains Prakamya
And he perseveres in his adoration
Then he visions Sada Siva Sakti and Her hosts of Bhutas
And attains Isatva.`,
    elaborationEnglish: `A, year after attaining prakamyam siddhi, ‘isatva siddhi is attained. Isatva consists in the power to control and create. It is the power of mind over maya. He becomes the moon’s Tays, its cooling softness, acquire moon’s kalas, and himself the moon becomes.`,
    elaborationTamil: `நமக்குள் அனைத்தையும் செயல்படுத்தும் சதாசிவ சக்தியின் மேல் மனதை ஒருமுகப்படுத்தி வைத்து அதிலேயே லயித்து அனைத்து தத்துவங்களாலும் பாதிக்கப்படாமல் யோகப் பயிற்சியில் ஒரு வருடம் இருந்தால் அந்தத் தத்துவங்களை வெல்லலாம். அவ்வாறு அனைத்து தத்துவங்களையும் வென்றவருக்கு ஈசத்துவம் (ஆக்கல், காத்தல், அழித்தல், மறைத்தல், அருளல் ஆகிய ஐந்தொழில்களைத் தன் ஆளுகைக்குட்பட்டுச் செய்தல்) எனும் சித்தி கிடைக்கும். கருத்து: சதாசிவ சக்தியின் மேல் ஒரு வருடம் மனதை ஒருமுகப்படுத்தி இருந்தால் ஈசத்துவம் எனும் சித்தி கிடைக்கும்.`,
  },
  {
    id: 686, tantraId: 3, verseNumber: 685,
    tamil: `ஆகின்ற சந்திரன் தன்னொளி யாயவன்
ஆகின்ற சந்திரன் தட்பமு மாயிடும்
ஆகின்ற சந்திரன் தன்கலை கூடிடில்
ஆகின்ற சந்திரன் தானவ நாமே`,
    transliteration: `ākiṉṟa cantiraṉ taṉṉoḷi yāyavaṉ
ākiṉṟa cantiraṉ taṭpamu māyiṭum
ākiṉṟa cantiraṉ taṉkalai kūṭiṭil
ākiṉṟa cantiraṉ tāṉava nāmē`,
    english: `685: In Isatva Yogi Becomes Moon
At that stage,
The Siddha becomes the rays of the moon
He becomes the moon's kalas in his merge
He himself the moon becomes.`,
    elaborationEnglish: `Then merging in them he himself the moon becomes.`,
    elaborationTamil: `புருவ மத்தியிலுள்ள ஆக்ஞா சக்கரத்தில் பேரொளியைக் கண்ட யோகி அங்கே காணப் பெறுகின்ற சந்திரனது குளிர்ந்த ஒளியாவான். அதன்பின் அந்த சந்திர மண்டலத்தின் பகுதிகளான நெற்றி தலையின் முற்பக்கம், பிற்பக்கம், வலப்பக்கம், இடப் பக்கம், பிரமரந்திரம் ஆகிய அனைத்தையும் ஒவ்வொன்றாக உணர்ந்தால் இறுதியில் அந்த ஆக்ஞா சக்கரத்திலுள்ள சந்திரனாகவே மாறிவிடுவான். கருத்து: சந்திர மண்டலத்தை உணர்ந்து பேரொளியைக் கண்டவன் சந்திரனாகவே மாறிவிடுவான்.`,
  },
  {
    id: 687, tantraId: 3, verseNumber: 686,
    tamil: `தானே படைத்திட வல்லவ னாயிடுந்
தானே யளித்திட வல்லவ னாயிடுந்
தானே சங்காரத் தலைவனு மாயிடுந்
தானே யிவனெனுந் தன்மைய னாமே`,
    transliteration: `tāṉē paṭaittiṭa vallava ṉāyiṭun
tāṉē yaḷittiṭa vallava ṉāyiṭun
tāṉē caṅkārat talaivaṉu māyiṭun
tāṉē yivaṉeṉun taṉmaiya ṉāmē`,
    english: `686: Powers Isatva Confers
He acquires the power to create
He acquires the power to preserve
He shall himself be Lord of destruction
He and Isa inextricably one become.`,
    elaborationTamil: `ஈசத்துவம் பெற்றவர் படைத்தல், காத்தல், அழித்தல் ஆகிய தொழில்கள் அனைத்தையும் தன் ஆளுகைக்கு உட்பட்டுச் செய்யக்கூடியவர் ஆவார். அவ்வாறு முத்தொழில்களைச் செய்வதால் சதாசிவத்தின் தன்மையைப் பெறுவார். கருத்து: ஈசத்துவம் சித்தியைப் பெற்றவர் சதாசிவத்தின் தன்மையைப் பெற்று முத்தொழில்களை செய்யக்கூடியவர் ஆவார்.`,
  },
  {
    id: 688, tantraId: 3, verseNumber: 687,
    tamil: `தன்மைய தாகத் தழைத்த கலையினுள்
பன்மைய தாகப் பரந்தஐம் பூதத்தை
வன்மைய தாக மறித்திடில் ஓராண்டின்
மென்மைய தாகிய மெய்பொருள் காணுமே`,
    transliteration: `taṉmaiya tākat taḻaitta kalaiyiṉuḷ
paṉmaiya tākap parantaaim pūtattai
vaṉmaiya tāka maṟittiṭil ōrāṇṭiṉ
meṉmaiya tākiya meyporuḷ kāṇumē`,
    english: `687: After One Year of Isatva Yogi Attains Power to Perceive
God in Vasitva
If within the cool kala of the moon
The Siddha contains the elements five
In a year shall he attain
The power rare to perceive the True One.`,
    elaborationEnglish: `A year after attaining isatva comes vasitva or the power to perceive the True One. He can become immanent like God in all that comes within his reach. He becomes radiant like the sun. His body gleams golden. His sense organs die; he visions the Narkodi Sakti (Sakti of Glorious Vine).`,
    elaborationTamil: `புருவ மத்தியிலுள்ள குளிர்ச்சியான ஆக்ஞா சக்கரத்தின் பேரறிவின் மூலம் உடலெங்கும் பலவாறாக வியாபித்திருக்கின்ற ஐம்பூதங்களையும் கடினப்பட்டு கட்டுப்படுத்தி ஓராண்டு வைத்திருந்தால் அனைத்திற்கும் மேலான உண்மைப் பொருளாகிய சதாசிவத்தை உணரலாம். கருத்து: பேரறிவின் மூலம் உடலிலுள்ள ஐம்பூதங்களையும் கட்டுப்படுத்தி ஓராண்டு வைத்திருந்தால் உண்மைப் பொருளை உணரலாம்.`,
  },
  {
    id: 689, tantraId: 3, verseNumber: 688,
    tamil: `மெய்ப்பொரு ளாக விளைந்தது வேதெனின்
நற்பொரு ளாகிய நல்ல வசித்துவங்
கைப்பொரு ளாகக் கலந்த உயிர்க்கெல்லாந்
தற்பொரு ளாகிய தன்மைய னாகுமே`,
    transliteration: `meypporu ḷāka viḷaintatu vēteṉiṉ
naṟporu ḷākiya nalla vacittuvaṅ
kaipporu ḷākak kalanta uyirkkellān
taṟporu ḷākiya taṉmaiya ṉākumē`,
    english: `688: Vasitva Confers Immenence
That power rare to perceive the True One
Is the divine Siddhi that is Vasitva
In beings all that come within his reach
He immanent becomes like God Himself.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-688-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationEnglish: `Vasitva — The traditional interpretations are: 1) power of command and control, resulting from non-attachment to objects: 2) 3) and power over the elements.”’ Indeed, it is the power which controls maya, and the achievement of that power, controls and restrains the All contained in the ‘self, and the Self contained in the All —°G.H. Mees, op. cit.`,
    elaborationTamil: `பாடல் #687 இல் உள்ளபடி உணர்ந்த உண்மைப் பொருளான சதாசிவம் எது என்று பார்த்தால் நல்ல வசித்துவம் எனும் சித்தியாகும். அவ்வாறு வசித்துவம் எனும் சித்தியை அடைந்தவர்கள் தன்னுடைய உயிர் எது என்று உணர்ந்தது போல எல்லா உயிர்களையும் உணர்ந்து தாமே சிவமாகி அந்த உயிர்களோடு கலந்து இருப்பார்கள். கருத்து: வசித்துவம் எனும் சித்தி பெற்றவர்கள் சிவ தன்மையை அடைந்து அனைத்து உயிர்களோடும் கலந்து இருப்பார்கள்.`,
  },
  {
    id: 690, tantraId: 3, verseNumber: 689,
    tamil: `தன்மைய தாகத் தழைத்த பகலவன்
மென்மைய தாகிய மெய்ப்பொருள் கண்டிடின்
பொன்மைய தாகப் புலன்களும் போயிட
நன்மைய தாகிய நற்கொடி காணுமே`,
    transliteration: `taṉmaiya tākat taḻaitta pakalavaṉ
meṉmaiya tākiya meypporuḷ kaṇṭiṭiṉ
poṉmaiya tākap pulaṉkaḷum pōyiṭa
naṉmaiya tākiya naṟkoṭi kāṇumē`,
    english: `689: In Vasitva the Yogi Visions Chit-Sakti
In the days the Siddha stands thus in Vasitva
Radiant as the Sun,
If he attains the rare vision of te True Being,
Golden becomes his body
Dead his sense organs,
And he visions the goodly Sakti
That lke a Tender Vine appears.`,
    elaborationTamil: `வசித்துவம் எனும் சித்தியைப் பெற்று சிவமாக மாறியபின் சூரியனைப் போன்ற பிராகாசத்துடன் விளங்கும் யோகி அனைத்திற்கும் மேலான உண்மைப் பொருளான சதாசிவத்தை தரிசித்தபின் உலகப் பற்றை விட்டது போலவே உடலின் ஐம்புலன்களின் பற்றையும் விட்டுவிட நன்மை தரும் சதாசிவத்தின் சக்தியை தரிசிக்கலாம். கருத்து: வசித்துவம் எனும் சித்திபெற்ற யோகி ஐம்புலன்களின் மேலிருக்கும் பற்றை விட்டுவிட்டால் சதாசிவத்தின் சக்தியை தரிசிக்கலாம்.`,
  },
  {
    id: 691, tantraId: 3, verseNumber: 690,
    tamil: `நற்கொடி யாகிய நாயகி தன்னுடன்
அக்கொடி யாகம் அறிந்திடில் ஓராண்டு
பொற்கொடி யாகிய புவனங்கள் போய்வருங்
கற்கொடி யாகிய காமுக னாமே`,
    transliteration: `naṟkoṭi yākiya nāyaki taṉṉuṭaṉ
akkoṭi yākam aṟintiṭil ōrāṇṭu
poṟkoṭi yākiya puvaṉaṅkaḷ pōyvaruṅ
kaṟkoṭi yākiya kāmuka ṉāmē`,
    english: `690: Kamarutatva (Kamavasayitha)
After attaining Vasitva Siddhi
The Siddha perserveres in the knowledge of Sakti,
And of Siva who Her body shares;
And then a year thereafter
He attains the powers to visit worlds all,
That hang from the golden stalk of the Cosmic Flower;
Sitting inert like a flag of stone
Attains Siddhi Kamarutattva (Kamavasayitva).`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-690-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationEnglish: `Kamaru tattva — The- traditional interpretaions are: 1) “Consummation of any and every desire;’’ 2) power of suppressing desire;’’ 3) ‘“‘It is the achievement of the fulfilment of the heart’s supreme desire, which is liberation from. bondage and the salvation from suffering by the annihilation of all desire.’’ It is God-realization. It is the power which subdues the primordial kama or desire, the primal cause of existence... It is nirvana — G.H. Mees, op.cit.

On the other hand, kamavasayitva is defined as attainment of whatever I desire’ (Srimad Bhagavata, quoted in “Principles of Tantra,”’ edited by Arthur Avalon) — Vide “Lights On Tantra’’ by M.P. Pandit, p.96. In this account there is no reference to garima as a siddhi.

Also referred to as ‘sarva kama siddhi’ — in Bhavanopanisad of as quoted in ‘Sri Chakra’ by S. Shankaranarayanan, p.82.

A year after attaining vasitva, the siddha attains kamaru tattva or kamavasayitva siddhi. This is the power to visit all the worlds that hang from the golden stalk of the cosmic flower He receives the power to pervade, like the flower’s fragrance; in space. He is transformed into mayasakti, and he visions the light of the Divine Mother. He visits the worlds and then sees the light of Supreme Siva.`,
    elaborationTamil: `பாடல் #689 இல் உள்ளபடி சதாசிவத்தின் சக்தியைத் தரிசித்தபின் அச்சக்த்தியைத் தனக்குள்ளேயே உணர்ந்து அதிலேயே மனதை வைத்து ஒரு வருடம் யோகப் பயிற்சி செய்தால் ஏற்கனவே பெற்ற வசித்துவ சித்தியின் மூலம் எல்லா உலகங்களுக்கும் தன் விருப்பம் போல சென்று வருவது மட்டுமின்றி அவ்வுலகங்களில் இருக்கும் எல்லா உயிர்களோடும் கலந்து அந்த உயிர்களை தன்வசம் ஈர்க்கவும் முடியும். கருத்து: சதாசிவ சக்தியை ஒரு வருடம் தியானம் செய்தால் எல்லா உலகங்களிலுள்ள உயிர்களையும் தன்வசப்படுத்த முடியும்.`,
  },
  {
    id: 692, tantraId: 3, verseNumber: 691,
    tamil: `காமரு தத்துவ மானது வந்தபின்
பூமரு கந்தம் புவனம தாயிடும்
மாமரு வுன்னிடை மெய்த்திடு மானனாய்
நாமரு வுமஔி நாயக மானதே`,
    transliteration: `kāmaru tattuva māṉatu vantapiṉ
pūmaru kantam puvaṉama tāyiṭum
māmaru vuṉṉiṭai meyttiṭu māṉaṉāy
nāmaru vumaaui nāyaka māṉatē`,
    english: `691: What Kamarutatva Leads to
Having attained Kamaru Siddhi
You will receive the power to pervade
As unto the flower's fragrance in Space all
Divine Fragrance yours shall be;
Transformed unto Maya Sakti,
You shall be the Lord of Light we adore.`,
    elaborationTamil: `பாடல் #690 இல் உள்ளபடி எல்லா உயிர்களையும் தன்வசப்படுத்தும் சக்தியைப் பெற்றபின் உயிர்களைத் தன் விருப்பத்திற்கேற்ப செயல்படுத்தி உலகத்தை மாற்றலாம். ஆனாலும் அனைத்தையும் தன்வசப்படுத்தும் பெருஞ்சக்தியான சதாசிவத்தை ஒளியாக தன் உள்ளத்தில் வைத்திருந்தால் அந்த ஒளியே நம்மை வசப்படுத்தும் சதாசிவமாகிவிடும். கருத்து: வசித்துவம் சித்தி பெற்றவர் உலகத்தை தன் எண்ணத்திற்கேற்ப மாற்றும் ஆற்றலைப் பெறுவார்.`,
  },
  {
    id: 693, tantraId: 3, verseNumber: 692,
    tamil: `நாயக மாகிய நல்லொளி கண்டபின்
தாயக மாகத் தழைத்தங் கிருந்திடும்
போயக மான புவனங்கள் கண்டபின்
பேயக மாகிய பேரொளி காணுமே`,
    transliteration: `nāyaka mākiya nalloḷi kaṇṭapiṉ
tāyaka mākat taḻaittaṅ kiruntiṭum
pōyaka māṉa puvaṉaṅkaḷ kaṇṭapiṉ
pēyaka mākiya pēroḷi kāṇumē`,
    english: `692: Visions in Kamarutatva
Having visioned the Divine Light
He abides in it as in mother's home;
The myriad worlds having visited,
He sees the Supreme light of Siva
Who has His home amidst ghosts and ghouls.`,
    elaborationTamil: `பாடல் #691 இல் உள்ளபடி சதாசிவமாகிய ஒளியை உணர்ந்தபின் ஆன்மாவின் பிறப்பிடமாகிய சதாசிவம் தமக்குள்ளேயே தழைத்து இருக்கும். உலகப் பற்றுகள் அனைத்தும் தம்மை விட்டு விலகுவதைக் உணர்ந்தபின் தமக்குள் இருக்கும் இருள் அனைத்தையும் விலக்கும் பேரொளியைக் காணலாம். கருத்து: உலகப் பற்றுகள் தம்மை விட்டு விலகுவதை உணர்ந்தபின் அனைத்து இருளையும் அகற்றும் பேரொளியைத் தரிசிக்கலாம்.`,
  },
  {
    id: 694, tantraId: 3, verseNumber: 693,
    tamil: `பேரொளி யாகிய பெரியஅவ் வேட்டையும்
பாரொளி யாகப் பதைப்புறக் கண்டவன்
தாரொளி யாகத் தரணி முழுதுமாம்
ஓரொளி யாகிய காலொளி காணுமே`,
    transliteration: `pēroḷi yākiya periyaav vēṭṭaiyum
pāroḷi yākap pataippuṟak kaṇṭavaṉ
tāroḷi yākat taraṇi muḻutumām
ōroḷi yākiya kāloḷi kāṇumē`,
    english: `693: When the Eight Siddhis are Attained
He who has mastered the Siddhis eight high.
Will be the Lord of globe entire,
Gleaming shall be his garland of victory
And His breath shall turn to peerless light.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-693-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationEnglish: `When the yogi attains the eight siddhis, he will verily be the lord of the world. He will be its beacon-light. He will sport the gleaming garland of victory.`,
    elaborationTamil: `சகஸ்ரதளத்தின் மேலே இருக்கும் பெரிய தாமரை மலர் போன்ற பேரொளியைத் தரிசிக்கக் கூடிய சக்தியைப் பெற்றவன் தனது மூச்சுக்காற்று ஒரு ஒளியாக மாறி அது பிரபஞ்சம் முழுவதும் பரவியிருப்பதைக் காண முடியும். கருத்து: பேரொளியைத் தரிசிக்கும் சக்தியுடையவன் தனது மூச்சுக்காற்றை பிரபஞ்சம் முழுவதும் பரவும் ஒளியாகக் காண முடியும்.`,
  },
  {
    id: 695, tantraId: 3, verseNumber: 694,
    tamil: `காலோ டுயிருங் கலக்கும் வகைசொல்லிற்
காலது அக்கொடி நாயகி தன்னுடன்
காலது ஐஞ்நூற் றொருபத்து மூன்றையங்
காலது வேண்டிக் கொண்டஇவ் வாறே`,
    transliteration: `kālō ṭuyiruṅ kalakkum vakaicolliṟ
kālatu akkoṭi nāyaki taṉṉuṭaṉ
kālatu aiñnūṟ ṟorupattu mūṉṟaiyaṅ
kālatu vēṇṭik koṇṭaiv vāṟē`,
    english: `694: Sakti Pervades Prana After Siddhis are Attained
The Way Prana mingles in Jiva
Is through Sakti of the Tender Vine
Prana pervades the five hundred then the ten.
And then the three nadis
And Sakti pervades Prana entire.`,
    elaborationTamil: `மூச்சுக்காற்றோடு உயிர் கலக்கும் முறை என்னவென்றால் உடம்பில் மொத்தம் உள்ளதாக யோக நூல்கள் கூறும் எழுபதாயிரம் நாடிகளில் ஐநூறு நாடிகள் சிறப்பானவை. இவற்றில் பத்து நாடிகள் மிகவும் சிறப்பானவை (பாடல் #595 இல் உள்ளபடி). அதிலும் சிறப்பானவை இடைகலை, பிங்கலை, சுழுமுனை ஆகிய மூன்று நாடிகளாகும். இந்த ஐநூற்று பதிமூன்று நாடிகளும் சுழுமுனை நாடியிலிருக்கும் சிவசக்தியோடு கலந்து இருந்தால் மூச்சுக்காற்றோடு உயிர் கலந்து இருக்கும். கருத்து: சிறப்பான ஐநூற்றி பதிமூன்று நாடிகளும் சிவசக்தியோடு கலந்திருந்தால் மூச்சுக்காற்றோடு உயிர் கலந்து இருக்கும்.`,
  },
  {
    id: 696, tantraId: 3, verseNumber: 695,
    tamil: `ஆறது வாகும் அமிர்தத் தலையினுள்
ஆறது ஆயிர முந்நூற் றொடைஞ்சுள
ஆறது வாயிர மாகு மருவழி
ஆறது வாக வளர்ப்ப திரண்டே`,
    transliteration: `āṟatu vākum amirtat talaiyiṉuḷ
āṟatu āyira munnūṟ ṟoṭaiñcuḷa
āṟatu vāyira māku maruvaḻi
āṟatu vāka vaḷarppa tiraṇṭē`,
    english: `695: Nectar Flows When Breath Pervades Body
Inside the head ambrosia flows like a river
In nadi channels a thousand three hundred and five in number
The adharas are the Way to the thousand petalled Sahasrara;
The twin breaths Idakala and Pingala shows the Way.`,
    elaborationEnglish: `Prana breath draws the nectar within the sahasrara. When it pervades the nadis, the nectar flows.`,
    elaborationTamil: `: தலைக்கு உள்ளே ஆறு போல உண்டாகின்ற அமுதம் ஆயிரத்து முந்நூற்று ஐந்து நரம்புத் தொகுதிகள் வழியாக செல்கின்றன. அவ்வாறு செல்லும் அமுதம் அந்த நரம்புத் தொகுதிகளின் மறுபகுதியில் உள்ள சகஸ்ரதளத்தை அடைந்து உயிரை பக்குவப்படுத்தி மேல்நிலைக்கு கொண்டு செல்வது சிவசத்திகளே ஆகும். கருத்து : சிவசக்திகளே அமுதத்தை நரம்புத்தொகுதிகளின் வழியாக சகஸ்ரதளத்திற்கு கொண்டு சென்று உயிரை பக்குவப்படுத்துகிறார்கள்.`,
  },
  {
    id: 697, tantraId: 3, verseNumber: 696,
    tamil: `இரண்டினின் மேலே சதாசிவ நாயகி
இரண்டது கால்கொண் டெழுவகை சொல்லில்
இரண்டது ஆயிரம் ஐம்பதோ டொன்றாய்த்
திரண்டது காலம் எடுத்ததும் அஞ்சே`,
    transliteration: `iraṇṭiṉiṉ mēlē catāciva nāyaki
iraṇṭatu kālkoṇ ṭeḻuvakai collil
iraṇṭatu āyiram aimpatō ṭoṉṟāyt
tiraṇṭatu kālam eṭuttatum añcē`,
    english: `696: From Ajna Where Sadasiva Nayaki is, Prana Ascends to
Sahasrara of Thousand Petalled Lotus
Above the twin-petalled Center
Is the Seat of Sadasiva Sakti;
As breath in double ascends further
There is the Sahasrara of thousand petalled lotus;
And on it are the Letters Fifty and One
That in time became the Letters Five.`,
    elaborationTamil: `: இடைகலை பிங்கலை நாடிகளின் மேல் சுழுமுனைத் தலையில் இருக்கும் சிவசத்தி இடைகலை பிங்கலை இரண்டு நாடிகள் வழியாக மூச்சுக்காற்று செயல் புரிகின்ற முறையைக் கூறினால் உடலில் உள்ள மண்டலங்களையும் நரம்புத் தொகுதிகளையும் தாண்டி ஆறு சக்கரங்களில் உள்ள ஐம்பத்தொன்று கைகள் வழியாக கலந்து ஆயிரம் தாமரை இதழ்களைக் கொண்ட சகஸ்ரதளத்தை அடைகின்றன. காலத்தைக் கடப்பதற்குத் துணை செய்வது ஐம்முகச் சக்தி ஆகும். இந்நிலையில் உயிரின் காலத்தைக் கடக்கச் செய்வதும் ஐம்முகங்களோடு கூடிய சதாசிவனின் நாயகியாகும்.`,
  },
  {
    id: 698, tantraId: 3, verseNumber: 697,
    tamil: `அஞ்சுடன் அஞ்சு முகமுள நாயகி
அஞ்சுடன் அஞ்சது வாயுத மாவது
அஞ்சது வன்றி இரண்டது வாயிரம்
அஞ்சது காலம் எடுத்துளும் ஒன்றே`,
    transliteration: `añcuṭaṉ añcu mukamuḷa nāyaki
añcuṭaṉ añcatu vāyuta māvatu
añcatu vaṉṟi iraṇṭatu vāyiram
añcatu kālam eṭuttuḷum oṉṟē`,
    english: `697: Description of Sadasiva Nayaki
Five are Her awe-inspiring faces;
Ten Her weapons deadly;
Without the five-lettered mantra
No ascension is,
From the twin petalled Center to the thousand petalled;
The Five Letters in time the One Letter become (Aum).`,
    elaborationEnglish: `The Five Letters in time the One Letter become (Aum).`,
    elaborationTamil: `பத்துத் திசைகளையும் பத்து முகங்களாகக் கொண்டிருக்கும் சதாசிவசக்திக்கு உயிரின் மூச்சிக்காற்றுடன் உடலில் இருக்கும் பத்து வாயுக்களும் பத்து ஆயுதங்களாகும். இந்த பத்து ஆயுதங்களும் கீழே பார்த்த சகஸ்ரதளம் மேலே பார்த்த சகஸ்ரதளம் என்று இரண்டு ஆயுதங்களான அச்சக்தியுடன் உருவமற்ற நிலையில் ஆயிரம் இதழ்கள் கொண்ட தாமரை மலராக இருக்கும் சகஸ்ரார தளத்தில் என்றும் ஒடுங்கியே இருந்து பலகாலங்கள் பேரின்பத்தில் திளைத்திருக்க வைத்து அருளுவது சதாசிவமூர்த்தியாகிய ஒரு சக்தியே ஆகும். கருத்து: ஆயிரம் இதழ்கள் கொண்ட மலர்ந்த தாமரை மலராத தாமரை ஆகிய இரண்டுவித சக்திகளையும் பத்து திசைகளாகிய முகங்களையும் பத்து வாயுக்களாகிய ஆயுதங்களையும் கொண்டிருக்கும் சதாசிவமூர்த்தியாகிய இறை சக்தி ஒன்றுதான் எட்டுவிதமான சித்திகள் அடைந்தவர்களுக்கு அனைத்தையும் அருளுகின்றது. பத்துவித காற்றுக்கள்: பிராணன் – உயிர்க்காற்று அபாணன் – மலக் காற்று வியானன் – தொழிற்காற்று உதானன் – ஒலிக்காற்று சமானன் – நிரவுக்காற்று நாகன் – விழிக்காற்று கூர்மன் – இமைக்காற்று கிருகரன் – தும்மற் காற்று தேவதத்தன் – கொட்டாவிக் காற்று தனஞ்செயன் – வீங்கல் காற்று`,
  },
  {
    id: 699, tantraId: 3, verseNumber: 698,
    tamil: `ஒன்றது வாகிய தத்துவ நாயகி
ஒன்றது கால்கொண் டூர்வகை சொல்லிடில்
ஒன்றது வென்றிகொள் ஆயிரம் ஆயிரம்
ஒன்றது காலம் எடுத்துளும் முன்னே`,
    transliteration: `oṉṟatu vākiya tattuva nāyaki
oṉṟatu kālkoṇ ṭūrvakai colliṭil
oṉṟatu veṉṟikoḷ āyiram āyiram
oṉṟatu kālam eṭuttuḷum muṉṉē`,
    english: `698: How to Reach Tattva Nayaki
She is the One Being;
She is the Tattva Nayaki (Lady of the Tattvas)
When breath ascends united through Spinal Cavity
Then will that one breath reach the thousand petalled Sahasrara;
Think of Her,
A thousand year shalt thou live.`,
    elaborationEnglish: `Sakta-Tantra -is closely linked with Nada or varna concepts, varna referring to letters of. the alphabets. (Varna-mala is a garland of letters, said to be worn by Sakti). Sir John Woodroff has explained this concept in his Varna-mala’’ In this philosophy, the concept of pancakshara or five’ letters (principal) plays an important, part. This ‘five-letter mantra’ is not the same as ‘‘Om Namasivaya’’ which is the 5-lettered mantra of pure Saivism`,
    elaborationTamil: `தனக்கு நிகராக ஒன்றும் இல்லாமல் தானே தனிப்பொருளாய் இருக்கும் இறை சக்தியானது ஒன்றே ஆகும். அந்த சக்தி மூச்சுக்காற்றை இயக்கி யோக நிலையில் நடுநாடியாகிய ஒன்றன் வழியே செலுத்தி மேல் ஏறுகின்ற முறையைக் கூறினால் உள்ளிழுக்கும் மூச்சுக்காற்று ஆயிரமாயிரம் நாடி நரம்புகளைக் கடந்து உடல் முழுவதற்கும் சக்தியூட்டி அதில் ஒவ்வொரு சக்கரங்களாக வெற்றி கொண்டு மேலெழுந்து அங்கே சுழுமுனை நாடியில் கவிழ்ந்த சகஸ்ரதளத்தை நிமிர்ந்த சகஸ்ரதளமாய் மாற்றி அமைத்து காலத்தையும் கடக்கச் செய்யும்.`,
  },
  {
    id: 700, tantraId: 3, verseNumber: 699,
    tamil: `முன்னெழும் அக்கலை நாயகி தன்னுடன்
முன்னுறு வாயு முடிவகை சொல்லிடின்
முன்னுறும் ஐம்பத் தொன்றுடன் அஞ்சுமாய்
முன்னுறு வாயு முடிவகை யாமே`,
    transliteration: `muṉṉeḻum akkalai nāyaki taṉṉuṭaṉ
muṉṉuṟu vāyu muṭivakai colliṭiṉ
muṉṉuṟum aimpat toṉṟuṭaṉ añcumāy
muṉṉuṟu vāyu muṭivakai yāmē`,
    english: `699: Prana Merges in Kalaicoursed upwards through
Sushumna
Reaches the Kalai Nayaki in Sahasrara;
And there it merges with the letters Fifty and One
And then with the Letters Five
That the final end of Prana art.`,
    elaborationEnglish: `The prana that reaches sahasrara meets the kalainayaki, and merges with the Fifty-One Letters; then with the Five Letters. Prana that merges in that sakti remains exalted.`,
    elaborationTamil: `தலையுச்சியின் முன்னே வீற்றிருக்கும் இறைசக்தியுடன் கீழிருந்து மேலெழுந்து சென்ற மூச்சுக்காற்று ஒன்றாகச் சேர்ந்து கலக்கும் விதத்தை சொன்னால் அடியிலிருந்து சுழுமுனை நாடி வழியே மேலே எழும்பும் வாயுவானது உயிர் சக்தியாகிய குண்டலினியை எழுப்பி மூலாதாரத்திலிருந்து ஒவ்வொரு சக்கரங்களாக அவற்றின் ஐம்ப்தத்தோரு இதழ்களின் வழியே சக்தியூட்டி (பாடல் #696 இல் கொடுத்துள்ளபடி) ஐந்து புலன்களுக்கும் செயல் திறனை அளித்து மொத்தமாய் மேலே சென்று அங்கிருக்கும் சகஸ்ரார தளத்தில் முடிவடைகின்றது. உயிர்சக்தி அங்கிருக்கும் இறை சக்தியோடு கலக்கும் முறை இதுவே ஆகும்.`,
  },
  {
    id: 701, tantraId: 3, verseNumber: 700,
    tamil: `ஆய்வரும் அத்தனி நாயகி தன்னுடன்
ஆய்வரு வாயு அளப்பது சொல்லிடில்
ஆய்வரும் ஐஞ்நூற்று முப்பதொ டொன்பது
மாய்வரு வாயு வளப்புள் ளிருந்ததே`,
    transliteration: `āyvarum attaṉi nāyaki taṉṉuṭaṉ
āyvaru vāyu aḷappatu colliṭil
āyvarum aiñnūṟṟu muppato ṭoṉpatu
māyvaru vāyu vaḷappuḷ ḷiruntatē`,
    english: `700: Prana Reaches Tani Nayaki and Remains Exalted
The life breath that rose with the Tani Nayaki
Filled the nadis five hundred and thirty nine
(Before it upward coursed)
And remained in Sakti, total absorbed.`,
    elaborationTamil: `ஆராய்ந்து அறிந்து கொள்ளுவதற்கு முடியாத தலைவியாகிய ஆதிசக்தியுடனும் ஆராய்ந்து அறிந்து கொள்ள முடியாத குண்டலினி சக்தியுடனும் வாயு ஒன்றாகக் கலக்கும் அளவு எவ்வளவு என்று சொன்னால் உயிர்கள் தமக்குள் இழுக்கப்படும் மூச்சுக்காற்றில் 540 அளவுகளில் 539 அளவு உடலின் சக்தியூட்டத்திற்கு பயனாகி மீதியிருப்பது ஒரு அளவே ஆகும். அந்த ஒரு அளவு வாயு மட்டும் உடலின் உள்ளிருந்து மேலே சென்று அங்கிருக்கும் இறை சக்தியோடு கலக்கின்றது. 540 வாயு அளவு விளக்கம்: ஆரோக்யமான ஒரு மனிதன் ஒரு நிமிடத்திற்கு 15 முறை சுவாசிக்கிறான். இந்தக் கணக்குப் படி ஒரு மணிக்கு 900 முறை. ஒரு நாளைக்கு 21,600 முறை சுவாசிக்கிறான். இதை 40 கூறுகளாகப் பிரித்தால் மொத்தம் 21,600/40 = 540 பங்குகள் வரும். இந்த 540 பங்கு மூச்சுக்காற்றில் 539 பங்கு மூச்சுக்காற்று உடலின் சக்தியூட்டத்திற்கு பயனாகிறது. ஒரு பங்கு மூச்சுக்காற்று சகஸ்ரதளத்தில் இருக்கும் இறைசக்தியுடன் கலக்கிறது.`,
  },
  {
    id: 702, tantraId: 3, verseNumber: 701,
    tamil: `இருநிதி யாகிய எந்தை யிடத்து
இருநிதி வாயு இயங்கு நெறியில்
இருநூற்று முப்பத்து மூன்றுடன் அஞ்சாய்
இருநிதி வாயு இயங்கும் எழுத்தே`,
    transliteration: `iruniti yākiya entai yiṭattu
iruniti vāyu iyaṅku neṟiyil
irunūṟṟu muppattu mūṉṟuṭaṉ añcāy
iruniti vāyu iyaṅkum eḻuttē`,
    english: `701: Prana Merges in the Five-Letters
When the precious prana reached Siva
It pervaded the nadis two hundred and thirty three
And in the Letters Five
Where Prana finally merges.`,
    elaborationTamil: `பாடல் 700 ல் உள்ளபடி சகஸ்ர தளத்தில் வீற்றிருக்கும் எம் தந்தையாகிய இறைவனிடத்தில் சென்று சேரும் ஒரு பங்கு காற்றின் அளவு உயிர்களின் உடலில் இருக்கும் இருநூற்று முப்பத்து மூன்று நாடிகளில் பரவிச்சென்று சகஸ்ர தளத்திலுள்ள ஆயிரம் இதழ்கள் கொண்ட தாமரை மலரை மலரச் செய்து சங்கமமாகி விடுகின்றது. சங்கமமானதும் நமசிவாய என்னும் ஐந்து எழுத்து மந்திரமாய் சகஸ்ர தளத்தை இயங்குகிறது. கருத்து: சிவசக்தியாய் இருக்கும் சகஸ்ரதளத்தில் கலக்கும் ஒரு பங்கு காற்று நமசிவாய என்னும் மந்திரமாய் செயல்பட்டு தவத்தால் அடையக்கூடிய அட்டமா சித்திகளை இயக்குகிறது.`,
  },
  {
    id: 703, tantraId: 3, verseNumber: 702,
    tamil: `எழுகின்ற சோதியுள் நாயகி தன்பால்
எழுகின்ற வாயு இடமது சொல்லில்
எழுநூற் றிருபத் தொன்பா னதுநாலாய்
எழுந்துடன் அங்கி இருந்ததிவ் வாறே`,
    transliteration: `eḻukiṉṟa cōtiyuḷ nāyaki taṉpāl
eḻukiṉṟa vāyu iṭamatu collil
eḻunūṟ ṟirupat toṉpā ṉatunālāy
eḻuntuṭaṉ aṅki iruntativ vāṟē`,
    english: `702: How Prana Pervaded the Nadis
The Prana that reaches Sakti
Emanating from the four petalled Muladhara
Where Kundalini fire is,
How Prana Pervaded the Nadis
The Prana that reaches Sakti
Emanating fro`,
    elaborationEnglish: `Pervaded the seven hundred and twenty nine Nadis within.

In ali, by the time the prana travels from the four-petalled muladhara to the thousand-petalied sahasrara, it will have pervaded 729 nadis within.

This verse introduces the concept of the general topic knqwn as “Varna Mala’’ by describing how (the vital principle), merges in the Letters Five (to be described in subsequent verses)`,
    elaborationTamil: `பாடல் 700 ல் உள்ளபடி மூலாதாரத்தில் ஜோதி வடிவமாக இருக்கும் சக்தியுடன் ஓர் பங்கு மூச்சுக்காற்று கலக்கும். அந்த மூச்சுக்காற்று எழும் இடத்தை சொன்னால் எழுநூற்று இருபத்து ஒன்பது நாடிகள் வழியாக நான்கு இதழ்களைக் கொண்ட மூலாதாரச் சக்கரத்தின் அக்கினியோடு இருந்தவாறே ஆரம்பிக்கின்றது. கருத்து: நான்கு இதழ்களாக இருக்கின்ற மூலாதார சக்கரத்தில் இருந்து எழுநூற்று இருபத்து ஒன்பது நாடிகளின் வழியாக ஓர் பங்கு காற்று மூலாதாரத்தில் ஜோதி வடிவமாக இருக்கும் சக்தியுடன் கலக்கிறது. குறிப்பு: பாடல் #700ல் உள்ளபடி ஓர் பங்கு மூச்சுக்காற்று பாடல் #701ல் தலை உச்சியில் இருக்கும் சகஸ்ரதளத்தோடு மூச்சுக்காற்று கலக்கும் விதத்தை சொன்ன திருமூலர் இப்பாடலில் கீழே இருக்கும் மூலாதார சக்கரத்தில் மூச்சுக்காற்று கலக்கும் விதத்தை கூறுகிறார்.`,
  },
  {
    id: 704, tantraId: 3, verseNumber: 703,
    tamil: `ஆறது கால்கொண் டிரதம் விளைத்திடும்
ஏழது கால்கொண் டிரட்டி இறக்கிட
எட்டது கால்கொண் டிடவகை யொத்தபின்
ஒன்பது மாநிலம் ஒத்தது வாயுவே`,
    transliteration: `āṟatu kālkoṇ ṭiratam viḷaittiṭum
ēḻatu kālkoṇ ṭiraṭṭi iṟakkiṭa
eṭṭatu kālkoṇ ṭiṭavakai yottapiṉ
oṉpatu mānilam ottatu vāyuvē`,
    english: `703: Samadhi When Prana Reaches the Ninth Center
When Prana course through adharas six
Then will nectar be;
Then Prana reaches the Seventh Center of the Sun
And further onward proceeds to the Eighth Center of the Moon
In the Ninth Center Prana attains Samadhi.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-703-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationTamil: `உயிரின் உடலாகிய தேருக்கு ஆறு ஆதாரச் சக்கரங்கள் இருக்கின்றன. இந்த ஆறு ஆதாரச் சக்கரங்களின் வழியே சக்தியூட்டப்பட்ட வாயு ஏழாவது ஆதாரமான சகஸ்ரதளத்திற்கு சென்று அங்கிருக்கும் இறைசக்தியோடு கலந்தபின் உருவாகின்ற அமிர்தம் அங்கிருந்து கீழிறங்கி எட்டாவது இடமாகிய உள் நாக்கிற்கு மேலே வந்து விழுகின்றது. இவ்வாறு விழுகின்ற அமிர்தத்தைப் பருகிக்கொண்டே பேரின்பத்தில் திளைத்திருக்கும் போது மாபெரும் நிலம் போன்ற உடலின் ஒன்பது துவாரங்களும் மூச்சுக்காற்றோடு இணைந்து இருக்கின்றது. கருத்து: அமிர்தத்தைப் பருகி வாழ்பவர்களுக்கு உணவோ தண்ணீரோ தேவைப்படுவதில்லை. அவர்கள் அமிர்தத்தை மட்டுமே பருகிக்கொண்டு ஒன்பது துவாரங்களின் வழியாக வெளிக்காற்றோடு இணைந்திருக்கின்றார்கள்.`,
  },
  {
    id: 705, tantraId: 3, verseNumber: 704,
    tamil: `சந்திரன் சூரியன் தற்பரன் தாணுவிற்
சந்திரன் தானுந் தலைப்படுந் தன்மையைச்
சந்தியி லேகண்டு தானாஞ் சகமுகத்
துந்திச் சமாதி யுடையொளி யோகியே`,
    transliteration: `cantiraṉ cūriyaṉ taṟparaṉ tāṇuviṟ
cantiraṉ tāṉun talaippaṭun taṉmaiyaic
cantiyi lēkaṇṭu tāṉāñ cakamukat
tuntic camāti yuṭaiyoḷi yōkiyē`,
    english: `704: In Samadhi Yogi Visions Light Divine
The Moon and the Sun are in the Uncreated Being
The Yogi that visions the Moon at the mystic junction of Nadis three
Is in Light merged;
He, attains Samadhi,
That had its beginning at the Navel Center.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-704-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationTamil: `சந்திரகலையாகிய இடகலை நாடியின் வழியே செல்லும் மூச்சுக்காற்றும் சூரியகலையாகிய பிங்கலை நாடியின் வழியே செல்லும் மூச்சுக்காற்றும் சுழுமுனை நாடி வழியே மேலே சென்று சிவபெருமான் இருக்கும் சகஸ்ரதளத்தில் இணைவதை புருவமத்தியில் இருக்கும் ஆக்ஞா சக்கரத்தில் பார்த்து அதிலேயே லயித்து தன்னுடல் மேலும் இந்த உலகத்தின் மேலும் உள்ள பற்றுக்களை அறுத்து பேரொளியாகிய இறைவனையே நினைத்து சமாதி நிலையில் இருப்பவர்கள் சிவ யோகியர்கள் ஆவார்கள். கருத்து: தனக்குள்ளே இறைவனை தரிசித்து இறை நினைப்போடு பற்றுக்களை அறுத்து சமாதி நிலையில் இருப்பவர்கள் சிவ யோகியர்கள்.`,
  },
  {
    id: 706, tantraId: 3, verseNumber: 705,
    tamil: `அணங்கற்ற மாதல் அருஞ்சன நீவல்
வணங்குற்ற கல்விமா ஞான மிகுத்தல்
சிணங்குற்ற வாயர் சித்திதூரங் கேட்டல்
நுணங்கற் றிரோதல்கால் வேகத்து நுந்தலே`,
    transliteration: `aṇaṅkaṟṟa mātal aruñcaṉa nīval
vaṇaṅkuṟṟa kalvimā ñāṉa mikuttal
ciṇaṅkuṟṟa vāyar cittitūraṅ kēṭṭal
nuṇaṅkaṟ ṟirōtalkāl vēkattu nuntalē`,
    english: `705: Conduct of Aspirant For Yoga Samadhi
To give up thoughts of women
To think no more of kith and kin
To be meek in learning
To abound in jnana
To be sparing of speech
To listen to deeds of Siddhi
To sit unruffled
--These the ways of the aspirant of yoga samadhi.`,
    elaborationTamil: `உற்றார் உறவினர் சுற்றத்தார் ஆகியோரை விட்டு நீங்கி இருப்பதும் பணிவை தருகின்ற உண்மையான கல்வியால் வருகின்ற ஞானத்தை அதிகமாகக் கொண்டிருப்பதும் எதையும் முணுமுணுக்காமல் உண்மையான மெளனத்தோடு அடங்கிக் கிடக்கும் சித்தர்கள் எண்ணத்தால் போதித்தவற்றை தமக்குள்ளேயே கேட்டுக்கொண்டிருப்பதும், உலக விஷயங்களில் அலைபாயாமல் ஒருமுகப்பட்ட மனதைக் கொண்டு எப்போதும் மூச்சுக்காற்றை தமக்குள்ளேயே வேகமாக ஏற்றி இறக்கி தியானத்தில் இருப்பதும் சித்தர்களின் செயல்களாகும். கருத்து: உலக விஷயங்களில் எதிலும் தலையிடாமல் எதனாலும் பாதிக்காத மனதுடன் குரு போதித்ததை தமக்குள்ளேயே உணர்ந்து மெளனமாய் இருப்பதும் தியானம் செய்து மூச்சுக்காற்றை கவனித்துக்கொண்டு இருப்பவர்களே சித்தர்கள்.`,
  },
  {
    id: 707, tantraId: 3, verseNumber: 706,
    tamil: `மரணஞ் சரைவிடல் வண்பர காயம்
இரணஞ் சேர்பூமி இறந்தோர்க் களித்தல்
அரணன் திருவுற வாதன்மூ வேழாங்
கரனுறு கேள்வி கணக்கறிந் தோனே`,
    transliteration: `maraṇañ caraiviṭal vaṇpara kāyam
iraṇañ cērpūmi iṟantōrk kaḷittal
araṇaṉ tiruvuṟa vātaṉmū vēḻāṅ
karaṉuṟu kēḷvi kaṇakkaṟin tōṉē`,
    english: `706: Prowess of Those Who Attain Samadhi
He vanquishes death and age,
He enters into other bodies at will,
He confers paradise to the dead
He assumes form divine of Gods
He becomes learned in the twenty-one branches of Sivagamic lore
He who has mastered the Science of Breath.`,
    elaborationTamil: `பாடல் #705 ல் கூறியுள்ள ஆறு தகுதிகளுடன் முதுமை அடையாமல் மரணம் இல்லாத தன்மையைப் பெறுதலும் எங்கிருந்தாலும் எப்போதும் அருள் வெளியோடு கலந்திருத்தலும் இந்த உலகத்தில் இருப்பவர்களுக்கு பலவித நற்செயல்கள் செய்து பெற்ற பலன்களை பித்ருக்களுக்கு சமர்ப்பணமாக அளித்தலும் சிவபெருமானை உணர்ந்து அவனது திருவுருவமாகவே மாறுவதும் ஆகிய மொத்தம் பத்து வித தகுதிகளை பலவித யோகங்கள் மூலமாக கற்று தமது கையில் இருக்கும் பொருள் போலத் தெள்ளத் தெளிவாக உணர்ந்தவர்களே சித்தர்கள் ஆவார்கள். கருத்து: யோகமுறைகளை முறையாகக் கற்று உணர்ந்து பத்துவிதமான தகுதிகளை அடைந்தவர்களே சித்தர்கள் ஆவார்கள்.`,
  },
  {
    id: 708, tantraId: 3, verseNumber: 707,
    tamil: `ஓதம் ஒலிக்கும் உலகை வலம்வந்து
பாதங்கள் நோவ நடந்தும் பயனில்லை
காதலில் அண்ணலைக் காண இனியவர்
நாதன் இருந்த நகரறி வாரே.`,
    transliteration: `ōtam olikkum ulakai valamvantu
pātaṅkaḷ nōva naṭantum payaṉillai
kātalil aṇṇalaik kāṇa iṉiyavar
nātaṉ irunta nakaraṟi vārē.`,
    english: `707: Seek Lord Within
Vain is it seeking Lord
Wearing away sole of their feet
In pilgrimage to corners four
Of the seagirt world;
Only those who seek Him in love intense
Shall know the City of Lord.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-707-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationTamil: `இறைவனைக் காண வேண்டுமென்று ஓயாமல் அலைகள் அடித்துக் கொண்டிருக்கும் கடல்கள் சூழ்ந்த இந்த உலகம் முழுவதையும் தனது பாதங்கள் வலிக்கும் வரை நடந்து தேடினாலும் ஒரு பயனும் இருக்காது. பார்க்கும் அனைத்தையும் இறைவனாக பார்த்து அந்த இறைவன் மீது உண்மையான அன்பை செலுத்துபவர்கள் சித்திகளை அடைந்து தமது உள்ளமாகிய திருக்கோயிலேயே இறைவன் வீற்றிருக்கின்றான் என்பதை அறிந்து கொள்வர்கள். கருத்து: இறைவனை வெளியில் எங்கு தேடினாலும் காண முடியாது. உண்மையான அன்பால் தேடினால் கண்டு கொள்ளலாம்.`,
  },
  {
    id: 709, tantraId: 3, verseNumber: 708,
    tamil: `மூல முதல்வேதா மாலரன் முன்னிற்கக்
கோலிய ஐம்முகன் கூறப் பரவிந்து
சாலப் பரநாதம் விந்துத் தனிநாதம்
பாலித்த சத்தி பரைபரன் பாதமே`,
    transliteration: `mūla mutalvētā mālaraṉ muṉṉiṟkak
kōliya aimmukaṉ kūṟap paravintu
cālap paranātam vintut taṉinātam
pālitta catti paraiparaṉ pātamē`,
    english: `708: Gods in Successive Adharas and Niradharas
Brahma, Vishnu and Rudra
Maheswara, Sadasiva,
Bindu, Nada, Sakti,
Para Bindu and Para Nada
In that ascending order
They all seek
Feet of Para-Para Beyond.`,
    elaborationTamil: `மூலாதாரத்தில் வீற்றிருந்து வேதங்களை ஓதிக்கொண்டே இருக்கின்ற பிரம்மனும் சுவாதிட்டானத்தில் வீற்றிருக்கின்ற திருமாலும் மணிப்பூரகத்தில் வீற்றிருக்கின்ற உருத்திரனும் அநாகதத்தில் வீற்றிருக்கின்ற மகேஸ்வரனும் விசுத்தியில் வீற்றிருக்கின்ற சதாசிவனும் ஆக்ஞையில் வீற்றிருக்கின்ற ஒளியும் சகஸ்ரரத்தில் வீற்றிருக்கின்ற ஒலியும் அதைத்தாண்டி உள் நாக்கிற்கு மேலே அமிர்தம் கொட்டுகின்ற இடத்தில் வீற்றிருக்கும் பரஒளியும் தலை உச்சியிலிருந்து 12 அங்குலம் உயரத்தில் உள்ள துவாதசாந்த வெளியில் வீற்றிருக்கும் பரஒலியும் ஆகிய இந்த ஒன்பதுவிதமான சக்திகளும் அசையா சக்தி (பரன்-சிவம்) அசையும் சக்தி (பரை-சக்தி) என்று இரண்டாக விளங்கும் பராபரையின் திருவடிகளே ஆகும். கருத்து: உயிர்களின் உடலின் ஆறு ஆதாரச் சக்கரங்களில் சக்திமயமாகவும் ஏழாவது சக்கரத்தில் ஒளிமயமாகவும் எட்டாவதாக அமிர்தம் பொழிகின்ற இடத்தில் பரஒளியாகவும், ஒன்பதாவதாக தலையைத் தாண்டிய துவாதசாந்த வெளியில் பரஒலியாகவும் இருக்கின்ற மூர்த்திகள் அனைவரும் பராபரை எனும் ஆதிமூலசக்தியின் திருவடிவங்களே ஆகும்.`,
  },
  {
    id: 710, tantraId: 3, verseNumber: 709,
    tamil: `ஆதார யோகத் ததிதே வொடுஞ்சென்று
மீதான தற்பரை மேவும் பரனொடு
மேதாதி யீரெண் கலைசெல்ல மீதொளி
ஓதா அசிந்தமீ தானந்த யோகமே`,
    transliteration: `ātāra yōkat tatitē voṭuñceṉṟu
mītāṉa taṟparai mēvum paraṉoṭu
mētāti yīreṇ kalaicella mītoḷi
ōtā acintamī tāṉanta yōkamē`,
    english: `709: Unalloyed Bliss Beyond the Adhara Yoga
Worshipping the appropriate God at Centers
Ascend above;
There the cranial region is
Where Sakti and Siva reside
Shedding Sixteen Kalas of Mystic Moon;
Ascend yet beyond
There lies the region of Effulgent-Light;
Yet above it is bliss
Defying speech and thought.`,
    elaborationEnglish: `Adhara yoga consists in worshipping the appropriate God at each of the centres, and ascending them one after another. In the sahasrara region eventually to be reached are Sakti and Siva with the 16 kalas in the moon. Ascending still beyond is jnana, the light divine. Yet beyond this is unalloyed bliss, defying speech and thought, and which is reached through niradhara yoga.

Each of the successive adharas (chakras) has its presiding deity — in muladhara, Brahma, in svadhishtana, Vishnu; in

manipura, Rudra; in anahata, Mahesvara; in vishuddhi, Sadasiva; in ajna, the apara bindu; in sahasrara, the paranada, Sakti and Siva. Still beyond are the parabindu, the paranada, Parasakti and Parasiva, and finally there is the Space. Thus, in effect, the centres are eleven in number. Only the first six are known as adharas or centres, and piercing them by kundalini yoga and reaching the seventh is known as adhara yoga. When the prana ascends further beyond to the next four centres above the seventh — they are known as ‘sthanas’. When prana reaches the Paraparam in the Space this is known as or the ‘twelfth end.” Prana’s ascension beyond sahasrara to the space; known as niradhara yoga.

By ‘Niradhara’’, Mular apparently means beyond the “‘adharas”’ of the body.

Each of the adharas or centers within has a presiding deity: In muladhara is Brahma seated; In svadhishtana is Vishnu;

In manipuraka is Rudra; ~

anahata is Mahesvara;

In visuddhi is Sadasiva;

In ajna is Bindu (apara);

Coursing the kundalini through these six centres and reaching the apara nada sakti and Siva in sahasrara is adhara yoga.

Beyond are the categories para bindu, para nada, Parasakti, and Parasiva, These categories are the presiding deities of the eighth. ninth, tenth and eleventh sthanas. They are not centres as are met with in the lower adhara yoga.`,
    elaborationTamil: `யோகத்தின் மூலம் குண்டலினி சக்தியை மேலெழுப்பி மூலாதாரம் முதலிய ஆறு ஆதார சக்கரங்களிலும் வீற்றிருக்கும் மூர்த்திகளோடும் கலந்து சென்று அதற்கு மேலே இருக்கும் சகஸ்ரதளத்தில் வீற்றிருக்கும் சதாசிவமூர்த்தியோடு இணைந்து அமிர்தமாகி தலை உச்சியிலிருந்து நான்கு அங்குலத்திற்குக் கீழே இருக்கும் உள் நாக்கில் பரஒளியாகிய அசையும் சக்தியுடன் கலந்து அதன்பிறகு தலை உச்சியிலிருந்து பன்னிரண்டு அங்குலத்திற்கு மேலே இருக்கும் துவாதசாந்த வெளியில் இருக்கும் பரநாதமாகிய அசையா சக்தியோடு இரண்டறக் கலந்து இருப்பதே பேரின்பம் கொடுக்கும் ஆனந்த யோகமாகும். கருத்து: குண்டலினி சக்தியை ஏழு சக்கரங்களுக்கும் ஏற்றிச் சென்று எட்டாவது நிலையில் அமிர்தமாகி ஒன்பதாவது நிலையில் இறைவனோடு கலந்து இருப்பதே பேரின்பம் கொடுக்கும் ஆனந்த யோகமாகும்.`,
  },
  {
    id: 711, tantraId: 3, verseNumber: 710,
    tamil: `மதியமும் ஞாயிறும் வந்துடன் கூடித்
துதிசெய் பவரவர் தொல்வா னவர்கள்
விதியது செய்கின்ற மெய்யடி யார்க்குப்
பதியது காட்டும் பரமன்நின் றானே`,
    transliteration: `matiyamum ñāyiṟum vantuṭaṉ kūṭit
tuticey pavaravar tolvā ṉavarkaḷ
vitiyatu ceykiṉṟa meyyaṭi yārkkup
patiyatu kāṭṭum paramaṉniṉ ṟāṉē`,
    english: `710: Lord Himself Appears Before Yogis
They who practise yoga
Through Nadis breath in one flowing Moon and Sun
Become Beings Celestial;
To them who perform it unceasing true
The Lord Himself reveals.`,
    elaborationTamil: `குளிர்ச்சியான சந்திரனின் குணம் கொண்ட இடகலை மற்றும் வெப்பமான சூரியனின் குணம் கொண்ட பிங்கலை ஆகிய நாடிகளின் வழியே உள்ளிழுத்த மூச்சுக்காற்றுகளை சுழுமுனை நாடிவழியே ஒன்றாகச் சேர்த்து மேலெழுப்பிச் சென்று சகஸ்ரதளத்தில் வீற்றிருக்கும் இறைவனிடம் ஒன்றாகக் கலக்கும் படி செய்யும் அகயோகத்தை செய்த யோகியர்களே வானத்தில் வீற்றிருக்கும் பழம்பெரும் தேவர்களாகிறார்கள். இந்த அகயோகத்தை உண்மையாக கடைபிடித்து இருக்கும் சித்தர்களுக்கு அதையும் தாண்டிய ஆனந்த யோகத்தில் தன்னை அடையும் வழியைக் காட்டி அங்கே அவர்களுடன் கலந்து இறைவனும் நிற்கின்றான். கருத்து: சுழுமுனை நாடி வழியே மூச்சுக்காற்றை மேலே சேர்க்கும் அகயோகத்தை செய்த யோகிகள் தேவர்களாகிறார்கள். அதையும் தாண்டி துவாதசாந்த வெளியில் இருக்கும் இறைவனோடு இணைகின்ற ஆனந்த யோகத்தை செய்த யோகிகள் இறைவனோடு இரண்டறக் கலந்துவிடுகிறார்கள்.`,
  },
  {
    id: 712, tantraId: 3, verseNumber: 711,
    tamil: `கட்ட வல்லார்கள் எங்கும்தான் ஆவர்
மட்டு அவிழ் தாமரையுள்ளே மணம் செய்து
பொட்டு எழக்குத்தி பொறிஎழ தண்டுஇட்டு
நட்டு அறிவார்க்கு நமன் இல்லைத்தானே`,
    transliteration: `kaṭṭa vallārkaḷ eṅkumtāṉ āvar
maṭṭu aviḻ tāmaraiyuḷḷē maṇam ceytu
poṭṭu eḻakkutti poṟieḻa taṇṭuiṭṭu
naṭṭu aṟivārkku namaṉ illaitāṉē`,
    english: `711: Immortality for Yogis Who Have Reached the Ultima Thule
They who control breath
Will pervade all everywhere, unseen;
They who pierce the Mystic Lotus
Sending breath up through spinal column
And taste of its fragrant nectar
Will never death know.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-711-Third-Tantra-11.-Eight-Great-Attainments.mp3',
    elaborationTamil: `கீழ்நோக்கிச் செல்லும் மூச்சுக்காற்றை மேல்நோக்கி செல்ல வைத்து அதை சுழுமுனை நாடியோடு கட்டி வைக்கும் திறனைப் பெற்ற யோகியர்கள் அனைத்தும் தாமே என்பதை உணர்ந்து நிற்பார்கள். அதன்பின் சகஸ்ரதளத்தில் மலர்ந்த ஆயிரம் தாமரை இதழ்களின் மேலே வீற்றிருக்கும் இறைவனோடு மூச்சுக்காற்றை கலக்கவிட்டு அதை மீண்டும் கீழிறக்கி உள் நாக்கின் மேலே மூடியுள்ள துளையைக் குத்தி அதில் அமிர்தத்தை சுரக்க வைத்து அந்த அமிர்தத்தைப் பருகி தனது நடு நாடியாகிய சுழுமுனையிலேயே மூச்சுக்காற்றை நிறுத்தி வைக்க முடிந்த யோகியர்கள் இனி எப்போதும் இறந்து பிறவாத நிலையை அடைவார்கள். கருத்து: அகயோகம் ஆனந்தயோகம் செய்த யோகியர்களுக்கு இறப்பும் பிறப்பும் இல்லை.`,
  },
  {
    id: 713, tantraId: 3, verseNumber: 712,
    tamil: `காதல் வழிசெய்த கண்ணுதல் அண்ணலைக்
காதல் வழிசெய்து கண்ணுற நோக்கிடிற்
காதல் வழிசெய்து கங்கை வழிதருங்
காதல் வழிசெய்து காக்கலு மாமே`,
    transliteration: `kātal vaḻiceyta kaṇṇutal aṇṇalaik
kātal vaḻiceytu kaṇṇuṟa nōkkiṭiṟ
kātal vaḻiceytu kaṅkai vaḻitaruṅ
kātal vaḻiceytu kākkalu māmē`,
    english: `712: Yoga Leads to Divine Nectar
The Lord of the Fore-head-eye
That showed the path of Love Divine;
Seek Him in love intense;
The Ganga in cranium will in grace flow;
And in love exceeding, He your saviour will be.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-712-Third-Tantra-12.-State-of-Breath-Tubes.mp3',
    elaborationTamil: `தன்னை அடைவதற்கு உண்மையான அன்பை வழியாக வைத்த நெற்றிக்கண்ணையுடைய இறைவனை உண்மையான அன்போடு இருகண்களுக்கு நடுவே இருக்கும் சுழுமுணை நாடியின் உச்சியை நோக்கி தியானத்தில் இருந்தால் தலை உச்சியிலுள்ள சகஸ்ரதளத்தில் ஒளிப்பிரவாகமாக வீற்றிருக்கும் இறைவனைச் சென்றடையும் வழி கிடைக்கும். அந்த வழியை அன்போடு பின்பற்றி அடைந்து விட்டால் எப்போதும் பேரின்பத்தில் திளைத்து என்றும் அழியாமல் இறையருள் காத்து நிற்கும். கருத்து: நாடிகளின் வழியே இறைவனை அடைவதற்கு உண்மையான அன்பு ஒன்றே வழியாகும்.`,
  },
  {
    id: 714, tantraId: 3, verseNumber: 713,
    tamil: `காக்கலு மாகுங் கரணங்கள் நான்கையுங்
காக்கலு மாகுங் கலைபதி னாறையுங்
காக்கலு மாகுங் கலந்தநல் வாயுவுங்
காக்கலு மாகுங் கருத்துற நில்லே`,
    transliteration: `kākkalu mākuṅ karaṇaṅkaḷ nāṉkaiyuṅ
kākkalu mākuṅ kalaipati ṉāṟaiyuṅ
kākkalu mākuṅ kalantanal vāyuvuṅ
kākkalu mākuṅ karuttuṟa nillē`,
    english: `713: Anchor Thoughts Firm on Lord
Anchor your thoughts firm on the Lord
Impregnable then you shall be;
Impregnable shall be your cognition organs four;
Impregnable shall be Kalas six and ten of the Moon within;
Impregnable shall be the Prana that is of life breath.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-713-Third-Tantra-12.-State-of-Breath-Tubes-2.mp3',
    elaborationTamil: `உலக விஷயங்களை எண்ணாமல் ஒளி உருவமான இறைவனின் மேல் எப்போதும் எண்ணத்தை வைத்திருந்தால் இறைவனின் திருவருள் நமது நான்கு அந்தக்கரணங்களையும், பதினாறு கலைகளையும், மூச்சுக்காற்றோடு என்றும் கலந்து நின்று காத்தருளும். கருத்து: இறைவனின் மேல் எண்ணம் வைத்து தியானிப்பவர்களை இறையருள் அனைத்திலிருந்தும் காத்து அருளும். நான்கு அந்தக்கரணங்கள்: மனம் புத்தி சித்தம் அகங்காரம் பதினாறு கலைகள் (நாடிகள்): மேதைக்கலை அருக்கீசக்கலை விடக்கலை விந்துக்கலை அர்த்தசந்திரன் கலை நிரோதினிக்கலை நாதக்கலை நாதாந்தக்கலை சக்திக்கலை வியாபினிக்கலை சமனைக்கலை உன்மனைக்கலை வியோமரூபினிக்கலை அனந்தைக்கலை அனாதைக்கலை அனாசிருதைக்கலை 1. மேதைக்கலை தொப்புள் முதல் மார்பு நடு இதயம் வரை இருக்கும் 2. அருக்கீசக்கலை இதயம் முதல் தொண்டைக்குழிவரை இருக்கும். 3. விடக்கலை தொண்டை முதல் நாக்கின் அடிவரை இருக்கும். 4. விந்துக்கலை நாக்கினடி முதல் புருவ நடுவரை இருக்கும். 5. அர்த்தசந்திரக்கலை புருவநடு முதல் உச்சித்துளைவரை இருக்கும். 6. நிரோதினிக்கலை, 7. நாதக்கலை, 8. நாதாந்தகலை ஆகிய மூன்றும் சம அளவில் பரவியிருக்கும். 9. சக்திக்கலை, 10. வியாபினிக்கலை, 11. சமனைக்கலை, 12. உன்மனைக்கலை, ஆகிய நான்கும் 12 விரல் அளவில் பரவியிருக்கும். 13. வியோமரூபிணிக் கலை 14. அனந்தைக் கலை 15. அனாதைக் கலை, 16. அனாசிருதைக் கலை சமனைக்கும் வியாபினிக்கும் நடுவே இருக்கும்.`,
  },
  {
    id: 715, tantraId: 3, verseNumber: 714,
    tamil: `நிலைபெற நின்றது நேர்தரு வாயு
சிலைபெற நின்றது தீபமும் ஒத்துக்
கலைவழி நின்ற கலப்பை அறியில்
அலைவற வாகும் வழியிது வாமே`,
    transliteration: `nilaipeṟa niṉṟatu nērtaru vāyu
cilaipeṟa niṉṟatu tīpamum ottuk
kalaivaḻi niṉṟa kalappai aṟiyil
alaivaṟa vākum vaḻiyitu vāmē`,
    english: `714: Way to Steady Kalas
Straight through Sushumna
The Prana stood unwavering
As a steady flame
And unto a still stone;
They who know
How the Lord stood commingled with Kalas
Know the Way True;
Even those in despair
Will espouse that Way.`,
    elaborationEnglish: `it is important in yoga practice that the prana is kept up, in a steady unwavering as a still stone. This comes only by anchoring the thought on the Lord. By steadying of the prana, the vision of the Lord who wears the moon that has 16 kalas is obtained.`,
    elaborationTamil: `இடகலை பிங்கலை நாடிகளின் வழியே உள்ளிழுத்த மூச்சுக்காற்றை நடுவில் உள்ள சுழுமுனை நாடி வழியே நேராக மேலேற்றிச் சென்று சகஸ்ரதளத்தில் ஒளி வடிவமாக இருக்கின்ற இறைவனோடு கலந்து அசைவில்லாமல் சிலை போல ஒன்றாக நின்றால் வெளிப்படும் அமிர்தத்தின் மூலம் ஒளி வடிவமாக இருக்கின்ற இறைவனின் அருள் வடிவம் பதினாறு கலைகளிலும் (பாடல் #713 இல் கொடுக்கப்பட்டுள்ளபடி 16 நாடிகள்) கலந்து நிற்பதை அறிந்து கொள்ளலாம். யோகியர்கள் மாயையினால் உருவாகும் மயக்கத்திலிருந்து விலகி உண்மை ஞானத்தில் எப்போதும் இருப்பதற்கான வழி இதை அறிந்து கொள்வதே ஆகும். கருத்து: சுழுமுனை நாடி வழியே மூச்சுக்காற்றை கொண்டு சென்று சக்ஸ்ரதளத்தில் சேர்க்கும் யோகியர்கள் தங்களின் 16 நாடிகளிலும் இறைவனது திருவருள் கலந்து இருப்பதை அறிந்து எப்போதும் மாயை இல்லாத உண்மை ஞானத்தில் இருப்பார்கள்.`,
  },
  {
    id: 716, tantraId: 3, verseNumber: 715,
    tamil: `புடையொன்றி நின்றிடும் பூதப் பிரானை
மடையொன்றி நின்றிட வாய்த்த வழியுஞ்
சடையொன்றி நின்றஅச் சங்கர நாதன்
விடையொன்றி லேறியே வீற்றிருந் தானே`,
    transliteration: `puṭaiyoṉṟi niṉṟiṭum pūtap pirāṉai
maṭaiyoṉṟi niṉṟiṭa vāytta vaḻiyuñ
caṭaiyoṉṟi niṉṟaac caṅkara nātaṉ
viṭaiyoṉṟi lēṟiyē vīṟṟirun tāṉē`,
    english: `715: Steady Prana Breath, Sankara Appears
When life breath is coursed up
Through the single channel Sushumna,
The Lord of Bhuta hordes,
Sankara of matted locks
Appears before you
Mounted on the Sacred Bull.`,
    elaborationEnglish: `Kala is a Sakti Tantric term; the nature and evolution of Kalas is explained by Sir John Woodroffe in his (pp.185 at seq.):`,
    elaborationTamil: `மூச்சுக்காற்றோடு கலந்து உயிர்களின் உயிர்த்துடிப்பின் நாதமாக நிற்கின்ற பஞ்ச பூதங்களின் தலைவனாகிய இறைவனை அந்த மூச்சுக்காற்று மற்ற நாடிகளின் வழியே சென்று வீணாகிவிடாமல் சுழுமுனை நாடியின் வழியே மேலேற்றிச் சென்று தலை உச்சியில் சடையணிந்த கோலத்தில் நின்ற சங்கரனின் தலைவனாகிய இறைவனோடு கலந்து விட்டால் அந்த இறைவன் உயிர்களின் உடலையே தனக்கு ஏற்ற காளை வாகனமாக்கி அதிலேயே அழியாமல் என்றும் வீற்றிருந்து அருளுவான். கருத்து: மூச்சுக்காற்றை மற்ற நாடிகளின் வழியே செலுத்தி வீணாக்காமல் சுழுமுனை நாடி வழியே எடுத்துச் சென்று இறைவனோடு கலந்துவிடும் யோகியர்களின் உடல் என்றும் அழியாமல் இறைவனின் திருவருளோடு நிலைத்து நிற்கின்றது.`,
  },
  {
    id: 717, tantraId: 3, verseNumber: 716,
    tamil: `இருக்கின்ற காலங்கள் ஏதும் அறியார்
பெருக்கின்ற காலப் பெருமையை நோக்கி
ஒருக்கின்ற வாயு வொளிப்பெற நிற்கத்
தருக்கொன்றி நின்றிடுஞ் சாதக னாமே`,
    transliteration: `irukkiṉṟa kālaṅkaḷ ētum aṟiyār
perukkiṉṟa kālap perumaiyai nōkki
orukkiṉṟa vāyu voḷippeṟa niṟkat
tarukkoṉṟi niṉṟiṭuñ cātaka ṉāmē`,
    english: `716: Sadhaka's State in Samadhi
They know not the time that passes in Samadhi
They look forward to the Big Time ahead,
Thus they direct the breath
Through the single channel Sushumna
To the void in cranium
There he stands, all conflicts resolved,
He truly is the Sadhaka.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-716-Third-Tantra-12.-State-of-Breath-Tubes.mp3',
    elaborationTamil: `உயிர்களுக்கு தாம் வாழுகின்ற காலம் எவ்வளவு என்பது தெரியாது. தமது வாழ்நாளை அதிகப்படுத்திக் கொடுக்கும் அகயோகத்தின் பெருமையை உணர்ந்து அதனை நோக்கிச்சென்று தங்களின் மூச்சுக்காற்றை சுழுமுனை நாடி வழியே மேலேற்றிச் சென்று சகஸ்ரதளத்தில் ஒளியாக வீற்றிருக்கும் இறைவனோடு கலந்து அதனால் கிடைக்கும் பேரின்பத்தில் திளைத்து எப்போதும் நிலையாக நிற்பவர்கள் சாதகர்கள் ஆகின்றார்கள். கருத்து: அழிகின்ற வாழ்நாளை நீட்டிக்க அகயோகம் செய்து இறைவனோடு கலந்து பேரின்பத்தில் திளைத்து நிற்பவர்கள் சாதகர்கள் ஆவார்கள்.`,
  },
  {
    id: 718, tantraId: 3, verseNumber: 717,
    tamil: `சாதக மானஅத் தன்மையை நோக்கியே
மாதவ மான வழிபாடு செய்திடும்
போதக மாகப் புகலுறப் பாய்ச்சினால்
வேதக மாக விளைந்து கிடக்குமே`,
    transliteration: `cātaka māṉaat taṉmaiyai nōkkiyē
mātava māṉa vaḻipāṭu ceytiṭum
pōtaka mākap pukaluṟap pāycciṉāl
vētaka māka viḷaintu kiṭakkumē`,
    english: `717: Perform Yoga Penance and Reach Lord
Thus toward that goodly state
Practise yogic penance;
If you succeed in coursing breath
Into the lotus in cranium,
You shall gain the Lord
That remains hidden in Vedas.`,
    elaborationTamil: `பாடல் #716 ல் உள்ளபடி அகயோகம் செய்வதன் பெருமையை உணர்ந்து மாபெரும் தவமாகிய அந்த யோகத்தை செய்து மூச்சுக்காற்றை சுழுமுனை நாடி வழியே தலை உச்சியிலுள்ள சகஸ்ரதளத்தில் போய்ச் சேரும்படி மேல் நோக்கிப் பாய்ச்சினால் இரும்பை தங்கமாக்கிவிடும் இரசவாத குளிகையைப் போலவே யோகம் செய்பவரின் உடல் பொன்னொளி வீசும் தங்கத்தாலான உடலாக மாறிவிடும். கருத்து: அகயோகம் செய்யும் யோகியரின் உடல் பொன்னொளி வீசும் தங்கமாக மாறிவிடும்.`,
  },
  {
    id: 719, tantraId: 3, verseNumber: 718,
    tamil: `கிடந்தது தானே கிளர்பயன் மூன்று
நடந்தது தானேஉள் நாடியுள் நோக்கிப்
படர்ந்தது தானே பங்கய மாகத்
தொடர்ந்தது தானேஅச் சோதியுள் நின்றே`,
    transliteration: `kiṭantatu tāṉē kiḷarpayaṉ mūṉṟu
naṭantatu tāṉēuḷ nāṭiyuḷ nōkkip
paṭarntatu tāṉē paṅkaya mākat
toṭarntatu tāṉēac cōtiyuḷ niṉṟē`,
    english: `718: Stages of Prana's Ascending Course
The breath has stages three
As Prana it courses upward
In single stream through spinal nadi;
And then spreads into cranial space
For the lotus there to blossom
And finally merges into the Divine Flame there.`,
    elaborationTamil: `பாடல் #717 ல் உள்ளபடி அகயோகத்தால் தம் உடலைத் தங்கமாக மாற்றிக்கொண்ட யோகியர்களுக்குள் உருவாகும் பயன்கள் மூன்றுவிதமாகும். முதலாவதாக மூலாதாரத்தில் இருந்து வெளிவரும் காற்று சுழுமுனை நாடி வழியாக உள்ளுக்குள் சென்று சகஸ்ரதளத்திற்கும் மூலாதாரத்திற்கும் இடையே உள்ளுக்குள் நோக்கி சுழன்று கொண்டு இருப்பதால் வெளிக்காற்றை சுவாசிக்க வேண்டியது இல்லை. இரண்டாவதாக அவர்களின் உள்ளுக்குள்ளே சுழன்று கொண்டு இருக்கும் காற்று சகஸ்ரதளத்தில் உள்ள ஆயிரம் தாமரை இதழ்களிலும் பரவி அதை மலரச் செய்து எப்போதும் இயக்கத்திலேயே வைத்திருக்கும். மூன்றாவதாக அவர்களின் உடல் இறைவனின் ஜோதிமயத்திலேயே மூழ்கி பேரின்பத்தில் எப்போதும் அழியாமல் நிற்கும். கருத்து: அகயோகம் செய்கின்ற யோகியர்கள் உடலுக்கு தேவையான மூச்சுக்காற்றை தனக்குள்ளேயே பெற்றுக்கொண்டு தனக்குள் ஜோதியாய் இருக்கும் இறைவனுடன் பேரின்பத்தில் மூழ்கி இருப்பார்கள்.`,
  },
  {
    id: 720, tantraId: 3, verseNumber: 719,
    tamil: `தனே எழுந்தஅத் தத்துவ நாயகி
ஊனே வழிசெய்தெம் உள்ளே யிருந்திடும்
வானோர் உலகீன்ற அம்மை மதித்திடத்
தேனே பருகிச் சிவாலய மாகுமே`,
    transliteration: `taṉē eḻuntaat tattuva nāyaki
ūṉē vaḻiceytem uḷḷē yiruntiṭum
vāṉōr ulakīṉṟa ammai matittiṭat
tēṉē parukic civālaya mākumē`,
    english: `719: Kundalini Yoga Turns the Body into Temple of Siva
The Kundalini Sakti that thus arose
Made her way aloft through the fleshly coil
And yet within me remained;
And She who created the worlds of Devas
Churned the mystic ambrosia within;
Drinking deep of it
This body became Siva's temple.`,
    elaborationEnglish: `Kundalini yoga turns the body into a temple of Siva. The guru’s guidance is essential for knowing how to course the prana through the successive adharas. The guru alone can guide this upward journey.`,
    elaborationTamil: `இறைவனை அடைவதற்கு வழியாக பிறக்கும் போதே அனைத்து உயிர்களுக்கும் உள்ளே இருக்கும் குண்டலினி சக்தியானது பாடல் #717 ல் உள்ளபடி அகயோகத்தால் தம் உடலைத் தங்கமாக மாற்றிக்கொண்ட யோகியர்களுக்குள் தானாக எழுந்துவிடும். தேவர்களையும் உலகத்தையும் படைத்த அசையும் சக்தியாகவும் அசையா சக்தியாகவும் இருக்கின்ற இறைவனை சுழுமுனை நாடி வழியாக சகஸ்ரதளத்தை சென்று அடைந்து அங்கிருக்கும் அமிர்தத்தை பருகிவிட்டால் அந்த யோகியரின் உடல் இறைவனை வீற்றிருக்கும் ஆலயமாகும். கருத்து: அகயோகம் செய்து குண்டலினி சக்தியை மேலெழுப்பி அமிர்தத்தை பருகும் யோகியர்களின் உடல் இறைவனை வீற்றிருக்கும் ஆலயமாகும்.`,
  },
  {
    id: 721, tantraId: 3, verseNumber: 720,
    tamil: `திகழும் படியே செறிதரு வாயு
அழியும் படியை அறிகில ராரும்
அழியும் படியை அறிந்தபின் நந்தி
திகழ்கின்ற வாயுவைச் சேர்தலு மாமே`,
    transliteration: `tikaḻum paṭiyē ceṟitaru vāyu
aḻiyum paṭiyai aṟikila rārum
aḻiyum paṭiyai aṟintapiṉ nanti
tikaḻkiṉṟa vāyuvaic cērtalu māmē`,
    english: `720: Know the Mystery of Prana Merging in Nada
The breath that glows within
None knows how it merges
When you know how it merges
Then can you reach the region
Where Nandi holds His sway.`,
    elaborationEnglish: `In Kundalini yoga, the body becomes the of Siva,” that is Siva comes to there. Mular’s message that Kundalini Yoga turns the Body into Temple of Siva is a very vital one and has had very in Temple art, whose basic design resembles the pathway to the which corresponds to the position of the heart of the human body.`,
    elaborationTamil: `உயிர்கள் வாழ்வதற்கு மட்டுமன்றி தம்மை வந்தடைந்து மேன்மையடையவும் மூச்சுக்காற்றை படைத்து அருளியிருக்கின்றான் இறைவன். ஆனால் உயிர்கள் சுவாசிக்கும் 540 பங்குகளில் (பாடல் #700 இல் காண்க) ஒரு பங்கைத் தவிர மீதி அனைத்தும் இறைவனை அடையாமலேயே வீணாகிவிடுவதை யாரும் அறிந்திருக்கவில்லை. வீணாகும் மூச்சுக்காற்றின் உண்மைப் பயனை அறிந்து கொண்டு அகயோகம் செய்யும் யோகியர்களுக்கு இறைவனே குருவாக இருந்து அவர்களின் வெளிப்புற மூச்சுக்காற்றை நிறுத்தி உட்புறமாக மூலாதாரத்தில் இருந்து சுழுமுனை நாடிவழியே சுவாசிக்க வைத்து அந்த சுவாசத்தோடு கலந்து நின்று அருளுகின்றான் கருத்து: உடலின் செயல்களில் வீணாகிவிடும் மூச்சுக்காற்றை அகயோகம் செய்து மாற்றி முழுமையாக பயன்படுத்தும் யோகியர்களின் சுவாசத்தோடு கலந்து குருவாக நின்று இறைவன் அருளுகின்றான்.`,
  },
  
  {
    id: 722, tantraId: 3, verseNumber: 721,
    tamil: `சோதனை தன்னில் துரிசறிக் காணலாம்
நாதனும் நாயகி தன்னிற் பிரியுநாள்
சாதன மாகுங் குருவை வழிபட்டு
மாதன மாக மதித்துக்கொள் ளீரே`,
    transliteration: `cōtaṉai taṉṉil turicaṟik kāṇalām
nātaṉum nāyaki taṉṉiṟ piriyunāḷ
cātaṉa mākuṅ kuruvai vaḻipaṭṭu
mātaṉa māka matittukkoḷ ḷīrē`,
    english: `721: Treasure Guru's Guidance for Yoga
As through breath you pierce the adharas
You shall vision clear;
Prana leaving the Kundalini Sakti
On its upward journey through Sushumna;
That you gain through the Guru guiding;
Take that as treasure precious gained.`,
    elaborationTamil: `யோகியர் தாம் விடும் மூச்சுக்காற்றின் அளவைக் கொண்டே தமக்குள் இறைவன் வீற்றிருக்கும் உடலும் இறைவி வீற்றிருக்கும் உயிரும் எப்போது பிரியும் என்பதை ஒரு சில சோதனைகளால் சிறிதும் பிழையின்றி மிகச் சரியாக அறிந்து கொள்ளலாம். அந்த சோதனைகள் என்ன என்பதை யோக குருவை வழிபட்டு அவர் அருளுகின்ற சாதனைகளை அரிய மாபெரும் செல்வமாக மதித்து சிரத்தையாக செய்வதன் மூலம் அறிந்து கொள்ளலாம். கருத்து: உடலை விட்டு உயிர் பிரிந்து விடும் ஆயுளை மிகச் சரியாகக் கணக்கிடும் சாதனைகளை யோக குருவின் அருள் கொண்டு அறிந்து கொண்டு சிரத்தையுடன் செய்யும் சாதகர்களுக்கு இறப்பிலிருந்து தப்பிக்கும் வழி கிடைக்கும். யோக குருவை வழிபட்டு அவர் அருளுகின்ற சாதனைகளைச் சிரத்தையாக செய்வதன் மூலம் கிடைக்கும் பலனை அடுத்த பாடல் #722ல் காணலாம்.`,
  },
{
    id: 723, tantraId: 3, verseNumber: 722,
    tamil: `ஈராறு கால்கொண் டெழுந்த புரவியைப்
பேராமற் கட்டிப் பெரிதுண்ண வல்லீரேல்
நீரா யிரமும் நிலமாயி ரத்தாண்டும்
பேராது காயம் பிரான்நந்தி ஆணையே`,
    transliteration: `īrāṟu kālkoṇ ṭeḻunta puraviyaip
pērāmaṟ kaṭṭip perituṇṇa vallīrēl
nīrā yiramum nilamāyi rattāṇṭum
pērātu kāyam pirāṉnanti āṇaiyē`,
    english: `722: immortality Through Samadhi Yoga
The breath that arose twelve matras long,
If you control and absorb within,
Well may you live a thousand years on land and sea;
The body perishes not;
True this is,
Upon Lord Nandi I declare.`,
    elaborationTamil: `பாடல் #721 இல் கூறியுள்ளபடி யோக குருவை வழிபட்டு அவரது அருளால் கிடைத்த சாதனைகளின் மூலம் ஆறுகளைப் போன்ற இடகலை பிங்கலை நாடிகளின் வழியே குதிரையைப் போல குதித்துவரும் மூச்சுக்காற்றை வீணாக்காமல் கட்டி வைத்து சுழுமுனை நாடி வழியே மேலேற்றிச் சென்று சகஸ்ரதளத்தில் சேர்த்து அங்கே சுரக்கும் அமிர்தத்தைப் பருக முடிந்த யோகியர்களின் உடல் கடலுக்கு அடியில் ஆயிரம் ஆண்டுகள் இருந்தாலும் நிலத்திற்கு அடியில் ஆயிரம் ஆண்டுகள் இருந்தாலும் அழியவே அழியாமல் என்றும் உயிர்ப்புடன் இருக்கும் என்பது குருவிற்கெல்லாம் மேலான மஹா குருவான இறைவனின் மேல் ஆணையே. கருத்து: யோக குருவின் அருளால் கிடைத்த சாதனைகளின் மூலம் தங்களின் உடலும் உயிரும் பிரியும் ஆயுட் காலத்தை துல்லியமாக அறிந்து கொள்ளும் யோகியர்கள் அதை மாற்றுவதற்கு அகயோகம் செய்தால் அவர்களின் உடலும் உயிரும் எவ்வளவு ஆயிரம் வருடங்களானாலும் பிரியாமல் இருக்கும் இது குருவிற்கெல்லாம் மேலான மஹா குருவான இறைவனின் மேல் ஆணை.`,
  },
  {
    id: 724, tantraId: 3, verseNumber: 723,
    tamil: `ஓசையில் ஏழும் ஔியிங்கண் ஐந்தும்
நாசியில் மூன்றும் நாவில் இரண்டுந்
தேசியுந் தேசனுந் தன்னிற் பிரியுநாள்
மாசறு சோதி வகுத்துவைத் தானே`,
    transliteration: `ōcaiyil ēḻum auiyiṅkaṇ aintum
nāciyil mūṉṟum nāvil iraṇṭun
tēciyun tēcaṉun taṉṉiṟ piriyunāḷ
mācaṟu cōti vakuttuvait tāṉē`,
    english: `723: Experiences of Yogi When Prana Ascends
When Prana and Sakti their departure take
One from the other,
The yogi knows it this way;
Seven sounds he hears
Five colors he sees
Three odors he smells,
Two tastes he knows
Thus has the Lord of Light
The symptoms indicated.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-723-Third-Tantra-12.-State-of-Breath-Tubes.mp3',
    elaborationTamil: `ஏழு விதமான ஒலிகளை உணரும் காதுகளும் ஐந்து விதமான ஒளிகளைக் காணும் கண்களும் மூன்று விதமான சுவாசங்களை முகரும் நாசிகளும் இரண்டு விதமானதைச் செய்யும் நாக்கும் தொடுவதை உணரும் உடலும் உயிரான ஆன்மாவை விட்டுப் பிரியும் நாள் எதுவென்பதை மிகவும் துல்லியமாக மூச்சுக்காற்றை வைத்தே அளந்து வைத்திருக்கின்றான் அனைத்துவித மலங்களையும் அறுத்து அருளும் சோதிமயமான இறைவன். கருத்து: உயிர்கள் தம்மிடம் அடையும் வழியை வைத்தருளிய இறைவன் அதன்படி செய்யாத உயிர்கள் அழிந்து மறுபடியும் பிறவி எடுப்பதற்கான ஆயுளையும் துல்லியமாக அளந்து வைத்திருக்கின்றான். காதுகள் உணரும் ஏழு விதமான ஒலிகள்: சத்தம் – இயற்கையான ஓசைகள் பரிசம் – கருவிகளினால் எழுப்பப்படும் இசை உருவம் – பிம்பங்களின் அசைவைக் காட்டும் சலசலப்பு இரசம் – நீர் எழுப்பும் ஓசை கந்தம் – காற்று எழுப்பும் ஓசை சரித்தல் – உலகத்தோடு இயங்கும் நுண்ணிய ஓசைகள் சேர்த்தல் – உடலுக்குள் இயங்கும் நுண்ணிய ஓசைகள் கண்கள் காணும் ஐந்து விதமான ஒளிகள்: உருவம் – நிலம் (பிம்பங்கள்) இரசம் – நீர் (திரவங்கள்) கந்தம் – காற்று (புகைகள்) தகித்தல் – நெருப்பு (தீக்கள்) வெம்மை – ஆகாயம் (வெற்றிடம்) நாசிகள் முகரும் மூன்று விதமான சுவாசங்கள்: வாசனை இடகலை மூச்சு குளிர்ச்சியான காற்று பிங்கலை மூச்சு வெப்பமான காற்று நாக்கு செய்யும் இரண்டு விதமான செயல்கள்: சுவைத்தல் பேசுதல்`,
  },
  {
    id: 725, tantraId: 3, verseNumber: 724,
    tamil: `உடம்பார் அழியில் உயிரார் அழிவர்
திடம்பட மெய்ஞ்ஞானஞ் சேரவு மாட்டார்
உடம்பை வளர்க்கும் உபாயம் அறிந்தே
உடம்பை வளர்த்தேன் உயிர்வளர்த் தேனே`,
    transliteration: `uṭampār aḻiyil uyirār aḻivar
tiṭampaṭa meyññāṉañ cēravu māṭṭār
uṭampai vaḷarkkum upāyam aṟintē
uṭampai vaḷarttēṉ uyirvaḷart tēṉē`,
    english: `724: Importance of Preserving Body
If the body pershes, so does Prana
Nor will the Light of Truth be reached;
I learned the way of preserving my body
And so doing, my Prana too.`,
    elaborationTamil: `உயிர்களின் உடல் அழிந்துவிட்டால் அதனுள்ளிருக்கும் உயிர் நீங்கிவிடும். உறுதியான உடல் வலிமை சீர்குலைந்தால் ஞானத்தை அடைய உடலை ஒரு கருவியாகப் பயன்படுத்த முடியாது. உடலை உறுதியாக வைத்து வளர்க்கும் வழியை இறையருளால் அறிந்து கொண்டு அதன் மூலம் உடலை வளர்த்து அதனுள்ளிருக்கும் உயிரையும் வளர்த்தேன். கருத்து: இறைவனை அடைவதற்கு கருவியாக பயன்படும் உடலையும் உயிரையும் உறுதியாக நீண்ட காலம் அழியாமல் வளர்த்து இறைவனை அடையலாம்.`,
  },
  {
    id: 726, tantraId: 3, verseNumber: 725,
    tamil: `உடம்பினை முன்னம் இழுக்கென் றிருந்தேன்
உடம்பினுக் குள்ளே யுறுபொருள் கண்டேன்
உடம்புளே உத்தமன் கோயில்கொண் டான் என்று
உடம்பினை யானிருந் தோம்புகின் றேனே`,
    transliteration: `uṭampiṉai muṉṉam iḻukkeṉ ṟiruntēṉ
uṭampiṉuk kuḷḷē yuṟuporuḷ kaṇṭēṉ
uṭampuḷē uttamaṉ kōyilkoṇ ṭāṉ eṉṟu
uṭampiṉai yāṉirun tōmpukiṉ ṟēṉē`,
    english: `725: Why I Preserve Body
Time was when I despised the body;
But then I saw the God within
And the body, I realised, is the Lord's temple
And so I began preserving it
With care infinite.`,
    elaborationTamil: `உடம்பை முன்பு குறையுடையது என்று எண்ணியிருந்தேன். உடம்புக்குள்ளே உரிமையாளர் இல்லாமல் தானே வந்தடையும் பொருள் ஒன்று இருப்பதை கண்டேன். அந்த பொருள் பரம்பொருளாகிய இறைவன் என்பதையும் அவன் இந்த உடம்புக்குள்ளே கோவில் கொண்டுள்ளான் என்பதை தெரிந்து கொண்டு இந்த உடம்பை யாம் பேணி பாதுகாத்து வருகின்றோம். கருத்து: உடம்புக்குள் பரம்மொருளாகிய இறைவன் இருப்பதினால் பிராணாயமம் யோகப்பயிற்சிகள் செய்து உடம்பை பாதுகாத்து வரவேண்டும்.`,
  },
  {
    id: 727, tantraId: 3, verseNumber: 726,
    tamil: `சுழற்றிக் கொடுக்கவே சுத்திக் கழியுங்
கழற்றி மலத்தைக் கமலத்துப் பூரித்து
உழற்றிக் கொடுக்கும் உபாயம் அறிவார்க்கு
அழற்றித் தவிர்ந்துடல் அஞ்சன மாமே`,
    transliteration: `cuḻaṟṟik koṭukkavē cuttik kaḻiyuṅ
kaḻaṟṟi malattaik kamalattup pūrittu
uḻaṟṟik koṭukkum upāyam aṟivārkku
aḻaṟṟit tavirntuṭal añcaṉa māmē`,
    english: `726: Purification of Internal Organs of Body
Churn the intestines in Suddhi practice
Your bowels become clean;
Then control the breath in the heart's region
And make it pervade the nadis entire;
They who can do this
Will gain a body
That no fire can burn.`,
    elaborationEnglish: `If the breath is used to flush the Ida and Pingala

By Pranayama, the heart gets purified

And the body becomes impervious

Even to fire. :

The body must be kept pure. This is achieved by churning the intestines through the practice known as ‘suddhi.” Then the bowels become clean. Control the breath in the heart's region and make it pervade the entire nadi`,
    elaborationTamil: `சுவாசிக்கும் மூச்சுக்காற்றை மூலாதாரத்திற்கு அனுப்பி மூலாதாரத்திலுள்ள அக்கினியால் மூச்சுக்காற்றை சுத்தம் செய்து சுழுமுனை நாடியின் கீழ்புறத்திலிருந்து மேலாகச் செலுத்தினால் சுழுமுனையை நாடி சுத்தம் அடையும். பின்பு அந்த காற்றை சகஸ்ரதளத்தில் இருக்கும் ஆயிரம் இதழ்கள் கொண்ட தாமரை மலரோடு சேர்த்து அந்த மலரை விரியச் செய்த பிறகு அந்த வாயுவை உடம்பிலுள்ள அனைத்து நாடிகளுக்குள்ளும் செலுத்தும் அகயோகப் பயிற்சியை அறிந்து கொண்டு அதைச் செய்பவர்களின் உடல் நெருப்பில் கருகி வெந்துபோகாமல் என்றும் அழியாமல் நிலைத்து நிற்கும். கருத்து: சுவாசிக்கும் மூச்சுக்காற்றை மூலாதாரத்திற்கு அனுப்பி சுழுமுனை நாடியை சுத்தப்படுத்தி சகஸ்ரதளத்தில் சேர்த்து பின்பு உடலில் உள்ள அனைத்து நாடிகளுக்கும் அனுப்பும் பயிற்சியை செய்பவர்களின் உடல் நெருப்பினால் சுட்டாலும் அழியாமல் இருக்கும்.`,
  },
  {
    id: 728, tantraId: 3, verseNumber: 727,
    tamil: `அஞ்சனம் போன்றுட லையறு மந்தியில்
வஞ்சக வாத மறுமத்தி யானத்திற்
செஞ்சிறு காலையிற் செய்திடிற் பித்தறும்
நஞ்சறச் சொன்னோம் நரைதிரை நாசமே`,
    transliteration: `añcaṉam pōṉṟuṭa laiyaṟu mantiyil
vañcaka vāta maṟumatti yāṉattiṟ
ceñciṟu kālaiyiṟ ceytiṭiṟ pittaṟum
nañcaṟac coṉṉōm naraitirai nācamē`,
    english: `727: Effect of Practising Yoga at Dawn, Noon and Dusk
As body wax-like suppleness attains,
Practicing yoga in dusk
The phlegm leaves;
At noon leaves the wind that is treacherous;
At dawn practised, the bile leaves;
Thus all poison from body expelled
And you shall know no greying, nor wrinkling.`,
    elaborationEnglish: `And you shall know no greying, nor wrinkling. Practise yoga at dusk; phlegm disappears. Practise yoga at mooi, the treacherous wind within leaves. Practise at dawn, tute is expelled. Thus the body, purified from the poison of the three “humours,” knows no greying or wrinkiing.`,
    elaborationTamil: `பாடல் #726 ல் உள்ளபடி மூச்சுசுழற்சிப் பயிற்சியை சூரியன் மறையும் சாயந்திர நேரத்தில் செய்தால் கபம் சம்பந்தமான அனைத்து வியாதிகளும் நீங்கும். இந்தப் பயிற்சியை சூரியன் உச்சியிலிருக்கும் மத்தியான நேரத்தில் செய்தால் வாதம் சம்பந்தமான அனைத்து வியாதிகளும் நீங்கும். இந்தப் பயிற்சியை சூரியன் தோன்றும் காலை நேரத்தில் செய்தால் பித்தம் சம்பந்தமான அனைத்து வியாதிகளும் நீங்கும். உடலில் விஷமாக இருக்கும் மூன்றுவிதமான வியாதிகளையும் நீக்கும் வழியாகவே இந்த பயிற்சியை அருளினோம். இந்தப் பயிற்சியை நாள் முழுவதும் செய்துகொண்டே இருந்தால் முடிகள் நரைக்காமல் உடலும் முதுமையடையாமல் இளமையாகவே எப்போதும் நிலைத்து நிற்கும். கருத்து: கபம் பித்தம் வாதம் ஆகிய மூன்றும் உடலுக்கு வரும் அனைத்து வியாதிகளுக்கும் காரணம். சரியான நேரத்தில் பாடல் #726 ல் உள்ளபடி அகயோகம் செய்வதன் மூலம் கபம் பித்தம் வாதம் மூன்றையும் நீக்கலாம். அதே யோகத்தை நாள் முழுவதும் செய்தால் உடலில் நோய் இல்லாமல் எப்போதும் இளமையாகவே இருக்கும்.`,
  },
  {
    id: 729, tantraId: 3, verseNumber: 728,
    tamil: `மூன்று மடக்குடைப் பாம்பிரண் டெட்டுள
வேன்ற வியந்திரம் பன்னிரண் டங்குலம்
நான்றவிம் முட்டை யிரண்டையுங் கட்டியிட்டு
ஊன்றி யிருக்க உடம்பழி யாதே`,
    transliteration: `mūṉṟu maṭakkuṭaip pāmpiraṇ ṭeṭṭuḷa
vēṉṟa viyantiram paṉṉiraṇ ṭaṅkulam
nāṉṟavim muṭṭai yiraṇṭaiyuṅ kaṭṭiyiṭṭu
ūṉṟi yirukka uṭampaḻi yātē`,
    english: `728: Yoga Leads to Imperishable Body
Three the coils of serpent Kundalini
Ten the Vayus that agitate the body;
Twelve finger-length the Prana breath;
When the two bags of spiration
Are tight controlled,
And you sit in meditation unwavering
The body perishes not ever.`,
    elaborationTamil: `மூன்று வளைவுகளை உடைய இடகலை பிங்கலை எனும் நாடிகளாக இரண்டு பாம்புகள் எட்டு அங்குல நீளத்திற்கு இருக்கின்றன. இயல்பான சுவாசமானது நாசியிலிருந்து இந்த இரண்டு நாடிகளின் வழியே கீழ் நோக்கி எட்டு அங்குல அளவு செல்லும். இந்த இரண்டு நாடிகளின் அடியிலிருந்து தலை உச்சி வரை செல்லும் பன்னிரண்டு அங்குல அளவிற்கு சுழுமுனை நாடி இருக்கிறது. முதுகெலும்பு ஆரம்பிக்கும் கழுத்து அது முடியும் இடுப்பு ஆகிய இரண்டு மூட்டுக்களையும் நேராக வைத்து இரண்டு கால்களையும் மடக்கி உடம்பை நேராக வைத்து அசையாமல் அமர்ந்து மூச்சுக்காற்றாகிய இயந்திரத்தை இடகலை பிங்கலை வழியாக எட்டு அங்குலம் கீழ் நோக்கி பயணிக்க வைத்து அதன் முடிவில் தொடங்கும் சுழுமுனை நாடி வழியே திசை மாற்றி பன்னிரண்டு அங்குலம் மேல் நோக்கி பயணிக்க வைத்து அதன் முடிவில் இருக்கும் சகஸ்ரதள ஆயிரம் தாமரை இதழ்களோடு கலக்க வைக்கும் சுழற்சியான அகயோகத்தை எப்போதும் செய்து கொண்டு இருந்தால் உடல் எவ்வளவு காலம் ஆனாலும் அழியாமல் இருக்கும். கருத்து: கழுத்தையும் இடுப்பையும் வளைக்காமல் நேராக வைத்துக் கொண்டு அமர்ந்திருந்து மூச்சுக்காற்றை சுழுமுனை நாடி வழியே மேலேற்றி சகஸ்ரதளத்தோடு கலந்து மறுபடியும் உடல் முழுவதும் பரவும் சுழற்சியை செய்து கொண்டிருந்தால் உடல் எவ்வளவு காலம் ஆனாலும் அழியாமல் இருக்கும்.`,
  },
  {
    id: 730, tantraId: 3, verseNumber: 729,
    tamil: `நூறும் அறுபதும் ஆறும் வலம்வர
நூறும் அறுபதும் ஆறும் இடம்வர
நூறும் அறுபதும் ஆறும் எதிரிட
நூறும் அறுபது மாறும் புகுவரே`,
    transliteration: `nūṟum aṟupatum āṟum valamvara
nūṟum aṟupatum āṟum iṭamvara
nūṟum aṟupatum āṟum etiriṭa
nūṟum aṟupatu māṟum pukuvarē`,
    english: `729: How to Live for 166 Years
Breathe by the Right Nadi a hundred and sixty six matra
Breathe by the Left a hundred and sixty six matra
And then reverse the rhythm
If you do it in alternation thus
You shall live long
A hundred and sixty six years.`,
    elaborationTamil: `பிங்கலை இடகலை நாடிகளின் வழியே மூச்சுக்காற்றை அறுபது மாத்திரை அளவிற்கு (30 வினாடிகள்) வலதும் இடதுமாக உள்ளிழுத்து நூறு மாத்திரை அளவிற்கு (50 வினாடிகள்) அடக்கி வைத்து ஆறு மாத்திரை அளவிற்கு (3 வினாடிகள்) சுழுமுனை நாடி வழியே மேல் நோக்கி எடுத்துச் சென்று சகஸ்ரதளத்தில் இருக்கும் ஆயிரம் இதழ்கள் கொண்ட தாமரை மலரோடு அறுபது மாத்திரை அளவிற்கு (30 வினாடிகள்) வைத்திருந்து பிறகு நூறு மாத்திரை அளவிற்கு (50 வினாடிகள்) உடலிலுள்ள அனைத்து நாடிகளுக்கும் கொண்டு செல்லும் சுழற்சியைத் தொடர்ச்சியாக செய்தால் ஆயுளை எப்போதும் கூட்டிக்கொண்டே இருக்கலாம். கருத்து: அகயோகப் பயிற்சியை முறைப்படி தொடர்ச்சியாக செய்ய ஆயுட்காலத்தை நீட்டிக்கலாம்.`,
  },
  {
    id: 731, tantraId: 3, verseNumber: 730,
    tamil: `சத்தியார் கோயி லிடம்வலஞ் சாதித்தான்
மத்தியா னத்திலே வாத்தியங் கேட்கலாந்
தித்தித்த கூத்துஞ் சிவனும் வௌிப்படுஞ்
சத்தியஞ் சொன்னோஞ் சதாநந்தி ஆணையே`,
    transliteration: `cattiyār kōyi liṭamvalañ cātittāṉ
mattiyā ṉattilē vāttiyaṅ kēṭkalān
tittitta kūttuñ civaṉum vauippaṭuñ
cattiyañ coṉṉōñ catānanti āṇaiyē`,
    english: `730: Divine Music in Yoga Practice
In the body-temple where Sakti is seated
If you practise transference of breath from right to left and vice versa,
You can hear the mystic sounds from Forehead Center
And Lord Siva will Himself reveal
Dancing to rhythmic music;
This we declare true
In the name of Sadasiva.`,
    elaborationTamil: `இறைவன் குடியிருக்கும் உடலாகிய கோயிலில் இடதும் வலதுமாக இருக்கும் இடகலை பிங்கலை நாடிகளின் வழியே உள்ளிழுத்த மூச்சுக்காற்றை அடக்கியாண்டு சுழுமுனை நாடி வழியே மேலேற்றிச் செல்லும் பயிற்சியை சாதித்த சாதகனுக்கு மூச்சுக்காற்றின் சுழுமுனை பயணம் புல்லாங்குழலில் புகுந்த காற்றின் இசை போல கேட்கவும் சுழுமுனையின் உச்சியிலிருந்து வெளிப்படும் அமிர்தத்தின் தித்திப்பில் இறைவனின் பேரின்பக் பெருங்கூத்தும் சகஸ்ரதள ஜோதியில் சிவமாகிய ஒளியும் வெளிப்படும் என்பதை குருவிற்கெல்லாம் மஹாகுருவான சதாசிவமூர்த்தியின் மேல் ஆணை. கருத்து: அகயோகப் பயிற்சியை சாதித்த சாதகர்களுக்கு இசையோடு நடனமும் ஆடும் இறைவனின் பேரின்பப் பெருங்கூத்துத் தரிசனம் கிடைத்து அவர்களுக்குள்ளிருந்தே ஒளியுருவமாக இறைவனும் வெளிப்படுவார்.`,
  },
  {
    id: 732, tantraId: 3, verseNumber: 731,
    tamil: `திறத்திறம் விந்து திகழு மகார
முறப்பெற வேநினைந் தோதுஞ் சகார
மறிப்பது மந்திர மன்னிய நாத
மறப்பெற யோகிக் கறநெறி யாமே`,
    transliteration: `tiṟattiṟam vintu tikaḻu makāra
muṟappeṟa vēniṉain tōtuñ cakāra
maṟippatu mantira maṉṉiya nāta
maṟappeṟa yōkik kaṟaneṟi yāmē`,
    english: `731: In Yoga Practice Soham is Chanted
In the Bindu that is pure by far
Shines the sound "Ha"
In the Nada that abides
Lives the sound "Sa"
Together they become the mantra "Soham"
The yogi who silent chants it while breathing
Sure attains the Holy Way.`,
    elaborationEnglish: `From bindu emanates the sound ‘ha’; from nada, the sound ‘sa’. Repeated continuously they become the mantra ‘soham.’ The yogi chants it silently.`,
    elaborationTamil: `ஒரு மாசுமில்லாத தூய்மையான ஒளியுருவான சிவத்தின் அம்சமாக விளங்கும் அ எனும் எழுத்தையும் மாமாயையின் ஒலியுருவான சக்தியின் அம்சமாக விளங்கும் ச எனும் எழுத்தையும் மனதுக்குள் உச்சரிக்கும்பொழுது தோன்றும் அசபை மந்திரத்தை சத்தமாகச் சொல்லாமல் மனதுக்குள்ளேயே ஓதி மனனம் செய்வது அகயோகத்தைக் கடைபிடிக்கும் யோகியர்களுக்கான தர்ம வழியாகும். கருத்து: அகயோகம் செய்யும் யோகியர்கள் அம்ச எனும் அசபை மந்திரத்தை மனதிற்குள்ளேயே ஓதுவது அவர்களுக்கான தர்மவழியாகும். இதை முறைப்படி குருவிடம் பெற்று பயன்படுத்துதல் வேண்டும்.`,
  },
  {
    id: 733, tantraId: 3, verseNumber: 732,
    tamil: `உந்திச் சுழியி னுடனேர் பிராணனைச்
சிந்தித் தெழுப்பிச் சிவமந்திரத்தினால்
முந்தி முகட்டின் நிறுத்தி அபானனைச்
சிந்தித் தெழுப்பச் சிவனவ நாமே`,
    transliteration: `untic cuḻiyi ṉuṭaṉēr pirāṇaṉaic
cintit teḻuppic civamana tirattiṉāl
munti mukaṭṭiṉ niṟutti apāṉaṉaic
cintit teḻuppac civaṉava nāmē`,
    english: `732: Course Prana and Apana Through Meditation
Rouse the Prana that resides in the Navel Center
By meditating and chanting Siva mantra;
Retain that breath in the Ajna frontal
Then rouse the apana breath by meditation;
That way you Siva become.`,
    elaborationTamil: `நாசியின் மூலம் தொப்புள் இருக்கும் வயிறு வரை உள்ளிழுத்த மூச்சுக்காற்றை பாடல் #731 இல் கூறிய மந்திரத்தை இறைவனை நினைத்து தியானித்துக் கொண்டே மேலே எடுத்துச் சென்று இரண்டு புருவங்களுக்கு மத்தியில் நிறுத்தி வைத்துவிட்டு மூலாதாரத்திலுள்ள மூலாக்கினியை இறைவனை சிந்தித்துக் கொண்டே சுழுமுனை நாடியின் வழியாக மேலே எடுத்துச் சென்று இரண்டு புருவங்களுக்கு மத்தியில் நிறுத்தி வைத்த காற்றோடு சேர்த்து சகஸ்ரதளத்திலுள்ள ஆயிரம் இதழ்கொண்ட தாமரை மலரோடு கலக்கும் சாதகன் சிவனாவான். கருத்து: மூச்சுக்காற்றையும் மூலாக்கினியையும் சகஸ்ரதளத்தில் இருக்கும் இறைவனோடு கலந்து அகயோகம் செய்யும் சாதகன் சிவனாவான்.`,
  },
  {
    id: 734, tantraId: 3, verseNumber: 733,
    tamil: `மாறா மலக்குதந் தன்மே லிருவிரற்
கூறா இலங்கத்தின் கீழே குறிக்கொண்மின்
ஆறா உடம்பிடை அண்ணலும் அங்குளன்
கூறா உபதேசங் கொண்டது காணுமே`,
    transliteration: `māṟā malakkutan taṉmē liruviraṟ
kūṟā ilaṅkattiṉ kīḻē kuṟikkoṇmiṉ
āṟā uṭampiṭai aṇṇalum aṅkuḷaṉ
kūṟā upatēcaṅ koṇṭatu kāṇumē`,
    english: `733: Center Thy Thoughts on Muladhara
Two finger length above the anus
Where faecal matter leaves not;
And below the male organ
Is the Linga in Muladhara;
Meditate on that Center;
There resides the Lord of the six adharas;
This my upadesa, rare revealed;
Do take it and vision the Lord.`,
    elaborationTamil: `எப்போதும் மாறாத மலத்தைக் கொண்டிருக்கும் மலத்துவாரத்திற்கு இரண்டு விரற்கடை மேலேயும் சொல்லாமல் உணரும் பாலுணர்ச்சியின் குறிக்கு இரண்டு விரற்கடை கீழேயும் உள்ள இடமே மூலாதாரம் இருக்கும் இடமாகும். அந்த இடத்தின் மேல் எண்ணத்தை வைத்து பாடல் #731 இல் கொடுத்துள்ள மந்திரத்தை மனதிற்குள் தியானித்தால் உடலிலுள்ள ஆறு ஆதாரங்களிலும் உள்ள இறை சக்தியே அங்கேயும் அக்கினியாக இருக்கிறது என்பதை கண்டு உணரலாம். கருத்து: உடலிலுள்ள அனைத்து சக்திமயங்களிலும் இறை சக்தியே இருக்கின்றது. மூலாதாரத்தை எண்ணி மந்திரத்தால் மனதிற்குள் தியானிக்க ஆறு ஆதாரங்களிலும் உள்ள இறை சக்தியே உணரலாம்.`,
  },
  {
    id: 735, tantraId: 3, verseNumber: 734,
    tamil: `நீல நிறனுடை நேரிழை யாளொடுஞ்
சாலவும் புல்லிச் சதமென் றிருப்பார்க்கு
ஞாலம் அறிய நரைதிரை மாறிடும்
பாலனு மாவர் பராநந்தி ஆணையே`,
    transliteration: `nīla niṟaṉuṭai nēriḻai yāḷoṭuñ
cālavum pullic catameṉ ṟiruppārkku
ñālam aṟiya naraitirai māṟiṭum
pālaṉu māvar parānanti āṇaiyē`,
    english: `734: Eternal Youth Through Yoga
They who effect the mystic union
With the azure-hued Sakti within
Will shed greying and wrinkling
And regain youth for all to see;
This I say is true, by Nandi the Great.`,
    elaborationTamil: `பாடல் #732 இல் உள்ளபடி மூச்சுக்காற்றை புருவ மத்தியில் நிறுத்திய பிறகு நடு நெற்றியில் தோன்றும் நீல நிறத்தில் ஜோதிமயமாக இருக்கும் சக்தியிலேயே சிந்தனையை நிரந்தரமாக வைத்து சரணாகதியில் இருப்பவர்களுக்கு உலகத்தவர்கள் அனைவரும் பார்க்கும்படி நரை முடியும் தோல் சுருக்கங்களும் நீங்கி வயது குறைந்து இளைஞனைப் போல இருப்பார்கள் என்பது பரம்பொருளாகிய குருநாதரின் ஆணையாகும். கருத்து: தியானத்தில் எப்போதும் நீல நிற சக்தியோடு இணைந்திருப்பவர்களின் உடல் முதுமை மாறி எப்போதும் இளமையோடு இருக்கும்.`,
  },
  {
    id: 736, tantraId: 3, verseNumber: 735,
    tamil: `அண்டஞ் சுருங்கில் அதற்கோ ரழிவில்லை
பிண்டஞ் சுருங்கிற் பிராணன் நிலைபெறும்
உண்டி சுருங்கில் உபாயம் பலவுள
கண்டங் கறுத்த கபாலியு மாமே`,
    transliteration: `aṇṭañ curuṅkil ataṟkō raḻivillai
piṇṭañ curuṅkiṟ pirāṇaṉ nilaipeṟum
uṇṭi curuṅkil upāyam palavuḷa
kaṇṭaṅ kaṟutta kapāliyu māmē`,
    english: `735: Continence Leads to God-hood
If the seminal seed thickens by sexual absention
It shall never be destroyed;
If the body is lightened by austere discipline
Long shall the life be;
If food is eaten sparingly
Many the good that flow;
You may verily become
The Lord of Dark-Hued throat.`,
    elaborationEnglish: `Abstain from sexual union. Abstention thickens thé seminal seed. It will never be dried up. Lighten your body by ausiere discipline. Long shall you live. If food is eaten sparingly, many are the good things that flow.`,
    elaborationTamil: `உயிர்கள் உணவை குறைப்பதினால் உடல் எடை குறைந்து சுருங்கினாலும் பாடல் #734 ல் உள்ளபடி நெற்றியின் நடுவில் இருக்கும் நீல நிற ஜோதி அழியாது. உணவை குறைத்து உடலை சுருக்கி நெற்றியின் நடுவில் இருக்கும் நீல நிற ஜோதியில் சிந்தனையை நிரந்தரமாக வைத்து சரணாகதியில் இருப்பவர்களுக்கு மூச்சுக்காற்று அங்கேயே நிரந்தரமாக நிலைபெறும். உணவை குறைத்து உடலை சுருக்கி பாதுகாத்தால் இறைவனை அடையும் வழிகள் பல உள்ளன. இதனை செய்யும் சாதகன் கருமை நிறமுடைய கழுத்தைக் கொண்ட நண்மையே உருவான இறைவனைப் போல் ஆகிவிடுவார்கள். கருத்து: உணவை குறைத்து உடலை சுருக்கி நெற்றியின் நடுவில் இருக்கும் நீல நிற ஜோதியில் சிந்தனையை நிரந்தரமக வைத்து சரணாகதியில் இருக்கும் சாதகனுக்கு மூச்சுக்காற்று நெற்றியில் நிலைபெற்று கருமை நிறமுடைய கழுத்தைக் கொண்ட நன்மையே உருவான இறைவனைப் போல் ஆகிவிடுவார்கள்.`,
  },
  {
    id: 737, tantraId: 3, verseNumber: 736,
    tamil: `பிண்டத்துள் உற்ற பிழக்கடை வாசலை
அண்டத்துள் உற்று அடுத்தடுத் தேகிடில்
வண்டிச் சிக்கு மலர்க்குழல் மாதரார்
கண்டிச் சிக்குநற் காயமு மாமே`,
    transliteration: `piṇṭattuḷ uṟṟa piḻakkaṭai vācalai
aṇṭattuḷ uṟṟu aṭuttaṭut tēkiṭil
vaṇṭic cikku malarkkuḻal mātarār
kaṇṭic cikkunaṟ kāyamu māmē`,
    english: `736: Yoga Gives Comeliness of Body
If Kundalini that is in Muladhara
Is sent upward often to reach the space in cranium,
Comely your body becomes;
A desire-object for damsels bedecked with flowers
Around which bees swarm humming.`,
    elaborationTamil: `உயிர்களின் உடலுக்குள் மலத்துவாரத்திற்கும் பிறவிக்குறிக்கும் நடுவிலுள்ள மூலாதாரத்திலிருக்கும் குண்டலினி சக்தியை எழுப்பி பாடல் #734 இல் உள்ளபடி நெற்றியின் நடுவில் இருக்கும் நீல நிற ஜோதியின் மேல் சிந்தனையை வைத்துக்கொண்டே சுழுமுனை நாடியின் வழியாக ஒவ்வொரு ஆதாரச் சக்கரங்களாக மேல் நோக்கி எடுத்து வந்து தலை உச்சியிலிருக்கும் சகஸ்ரதளத்தில் சேர்த்துவிட்டால் வண்டுகள் தேனை விரும்பி சுற்றும் அழகிய மலர்களை தலையில் அணிந்திருக்கும் பெண்கள் கூட இப்படிப்பட்ட உடல் நமக்கு கிடைக்காதா என்று ஏங்கித் தவிக்கும் அளவிற்கு சாதகரின் உடல் அழகாகிவிடும். கருத்து: மூலாதாரத்திலுள்ள குண்டலினியை எழுப்பி ஆறு சக்கரங்களுக்கும் சக்தியூட்டி ஏழாவதான சகஸ்ரதளத்தில் சேர்ப்பவர்களின் உடல் அழகாகிவிடும்.`,
  },
  {
    id: 738, tantraId: 3, verseNumber: 737,
    tamil: `சுழலும் பெருங்கூற்றுத் தொல்லைமுன் சீறி
அழலும் இரத்ததுள் அங்கியுள் ஈசன்
கழல்கொள் திருவடி காண்குறில் ஆங்கே
நிழலுளுந் தெற்றுளும் நிற்றலு மாமே`,
    transliteration: `cuḻalum peruṅkūṟṟut tollaimuṉ cīṟi
aḻalum irattatuḷ aṅkiyuḷ īcaṉ
kaḻalkoḷ tiruvaṭi kāṇkuṟil āṅkē
niḻaluḷun teṟṟuḷum niṟṟalu māmē`,
    english: `737: Imperishable Life in Yogic Vision
The Lord, of yore, spurned the mighty God of Death
Who ever harasses life;
The Lord rides the Chariot of Fire within;
If you vision His Holy Feet,
Decked with triumphal anklet
You shall for ever live
In the canopied terrace above.`,
    elaborationTamil: `சுழன்று அடிக்கின்ற சூறாவளிக் காற்றின் நடுவில் சிக்கி தேர் அலைந்து திரிவது போல இறப்பு பிறப்பு எனும் சுழற்சியில் சிக்கிக்கொண்ட உயிர்கள் பிறவித் துன்பத்தில் கிடந்து அலைகின்றன. இந்தப் பிறவிச் சுழற்சியிலிருந்து உயிர்களை விடுவிக்கும் இறைவன் உயிர்களின் உடலுக்குள்ளேயே பாடல் #734 இல் உள்ளபடி நெற்றியின் நடுவில் தோன்றும் நீல நிற ஜோதியில் ஒளியுருவமாக வீற்றிருக்கின்றான். அகயோகம் செய்து நீல நிற ஜோதியின் நடுவில் இறைவனின் ஒளியுருவத்தைத் தரிசித்து அவனது திருவடிகளில் அணிந்திருக்கும் சிலம்பின் ஓசையும் கேட்டு அதிலேயே சிந்தனையை வைத்திருக்கும் சாதகர்கள் இறப்பு பிறப்பு என்கிற பிறவிச் சுழற்சி நீங்கி எப்போதும் பேரின்பத்தில் இறைவனின் திருவடி நிழலிலேயே வீற்றிருப்பார்கள். கருத்து: அகயோகம் செய்து இறைவனின் திருவடியை நெற்றிக்குள் தரிசிக்க பிறவி எனும் பெருந்துன்பம் தீர்ந்து இறப்பும் பிறப்பும் இன்றி எப்போதும் இறைவனது திருவடியிலேயே இருக்கலாம்.`,
  },
  {
    id: 739, tantraId: 3, verseNumber: 738,
    tamil: `நான்கண்ட வன்னியும் நாலு கலையேழுந்
தான்கண்ட வாயுச் சரீர முழுதொடும்
ஊன்கண்டு கொண்ட வுணர்வு மருந்தாக
மாங்கன்று நின்று வளர்க்கின்ற வாறே`,
    transliteration: `nāṉkaṇṭa vaṉṉiyum nālu kalaiyēḻun
tāṉkaṇṭa vāyuc carīra muḻutoṭum
ūṉkaṇṭu koṇṭa vuṇarvu maruntāka
māṅkaṉṟu niṉṟu vaḷarkkiṉṟa vāṟē`,
    english: `738: Yogi Vibrates With Youthfulness
The Fire I saw in Kundalini radiates Kala four
The Prana I kindled and coursed through Centers seven
Pervades the body entire;
With divine life that suffuses the fleshly body as ambrosia;
I grow unto a tender fawn.`,
    elaborationTamil: `பாடல் #734 இல் உள்ளபடி நெற்றி நடுவில் கண்ட நீல நிற ஜோதியும் நான்கு கலைகளைக் கொண்டு ஏழு ஆதாரச் சக்கரங்களுக்கும் எடுத்துச் சென்ற மூச்சுக்காற்றும் உடலை முழுவதும் மூடியிருக்கும் தோலும் தமக்குள் உணர்ந்த உண்மை ஞானமாகிய மெய்யுணர்வானது உடலுக்கு சிறந்த மருந்தாகி மான் குட்டி கீரையைத் தின்று வளர்வது முதிர்ச்சி அடைவது போல மெய்யுணர்வைத் தின்று ஆன்மா பிறவியில்லா நிலைக்கு முதிர்ச்சி அடைகிறது. கருத்து: அகயோகத்தை முறையாக செய்தால் மெய்யுணர்வை பெற்று ஆன்மா பிறவியில்லா நிலைக்கு முதிர்ச்சி அடையும்.`,
  },
  {
    id: 740, tantraId: 3, verseNumber: 739,
    tamil: `ஆகுஞ் சனவேத சத்தியை அன்புற
நீகொள்ளின் நெல்லின் வளர்கின்ற நேர்மையைப்
பாகு படுத்திப் பல்கோடி களத்தினால்
ஊழ்கொண்ட மந்திரத் தன்னால் ஒடுங்கே`,
    transliteration: `ākuñ caṉavēta cattiyai aṉpuṟa
nīkoḷḷiṉ nelliṉ vaḷarkiṉṟa nērmaiyaip
pāku paṭuttip palkōṭi kaḷattiṉāl
ūḻkoṇṭa mantirat taṉṉāl oṭuṅkē`,
    english: `739: Meditate on Appropriate Mantra to Attain Kaya Siddhi
If you in ardor pursue
The search for power to acquire Kaya Siddhi,
You shall flourish far and wide
Like a seed of paddy planted
In a million, million fields;
Do you therefore meditate single-minded
On the mantra that conquers Fate.`,
    elaborationEnglish: ``,
    elaborationTamil: `ஒரு நெல்லை பயிர் செய்தால் அதிலிருந்து பல நெல் வரும் அந்த பல நெல்லை மீண்டும் பயிர் செய்தால் பல ஆயிரம் வரும் அதனையும் பயிர் செய்தால் பல கோடி வரும். அது போல பாடல் #737 ல் உள்ளபடி சரீர நெற்றியில் இருக்கும் நீலநிற ஜோதியில் இருக்கும் வெப்பத்தில் இருந்து வரும் மந்திரமான ஒலியை மீண்டும் மீண்டும் சரீரத்திற்குள்ளேயே எந்தவித எதிர்பார்ப்பின்றி மனனம் செய்யும் சாதகனின் உடல் அழியாமல் இருந்து ஒரு மந்திரம் பல மந்திரமாக பெருகி வேதமந்திரமாக இருக்கும் இறைவனுடனேயே ஒடுங்கிவிடுவார். கருத்து: சரீரத்திற்குள்ளேயே எந்தவித எதிர்பார்ப்பின்றி மனனம் செய்யும் சாதகனின் உடல் அழியாமல் இருந்து வேதமந்திரமாக இருக்கும் இறைவனுடனேயே ஒடுங்கிவிடுவார்.`,
  },
  {
    id: 741, tantraId: 3, verseNumber: 740,
    tamil: `மதிவட்ட மாக வரையைந்து நாடி
இதுவிட்டிங் கீரா றமர்ந்த அதனாற்
பதிவட்டத் துள்நின்று பாலிக்கு மாறு
மதுவிட்டுப் போமாறு மாயலுற் றேனே`,
    transliteration: `mativaṭṭa māka varaiyaintu nāṭi
ituviṭṭiṅ kīrā ṟamarnta ataṉāṟ
pativaṭṭat tuḷniṉṟu pālikku māṟu
matuviṭṭup pōmāṟu māyaluṟ ṟēṉē`,
    english: `740: Ascension of Jiva from Moon's Sphere
Seeking the Mountain Ranges Five (Siva Tattvas)
Here am I in the Moon's Sphere;
Leaving this I reach the Region of the Great Void of Twelve
That lies in the Sphere of Pati Supreme;
And from thence I pass on to the Farthest Beyond
--These I seek to search here.`,
    elaborationTamil: `பூமியை நிலா சுற்றி வருகின்ற ஒரு நாளிலிருந்து பதினைந்து நாட்களுக்கு ஐந்து ஐந்து நாளாக சூரியனின் வட்டத்திலிருந்து விலகி கொஞ்சம் கொஞ்சமாக வெளிச்சம் பெற்று பெளர்ணமியாகும் விதமும் பின்பு ஐந்து ஐந்து நாளாக சூரியனின் வட்டத்தை நோக்கி கொஞ்சம் கொஞ்சமாக வெளிச்சம் இழந்து பின்பு அமாவாசையாகும் விதமும் சந்திரன் சூரியனின் வட்டத்தில் இருக்கும் பன்னிரண்டு இராசிகளில் ஒவ்வொரு ராசியிலும் இரண்டரை நாட்கள் அமர்ந்து பின் அடுத்த ராசிக்கு மாறுகின்ற விதமும் இவை அனைத்தும் இறைவனின் திருவருளாலே உயிர்களின் கர்ம வினைகளுக்கேற்ப காத்து அருளுகின்ற விதமும் உடலை விட்டு உயிர் பிரியும்போது அதனை விட்டுப் பிரிந்து செல்லுகின்ற விதமும் ஆராய்ந்து அருளுகின்றேன். கருத்து: சந்திரன் பூமியைச் சுற்றும்போது சூரியவட்டத்தில் வரும் பன்னிரண்டு இராசிகளிலும் 30 நாட்களில் அமர்ந்து மாறும்போது இறையருளால் உயிர்களைக் காக்கின்ற தன்மையையும் பின்பு உயிர் உடலை விட்டுப் பிரியும் விதமும் ஆராய்ந்து இந்தத் தலைப்பிலுள்ள பாடல்கள் அருளப்பட்டுள்ளன.`,
  },
  {
    id: 742, tantraId: 3, verseNumber: 741,
    tamil: `உற்றறி வைந்தும் உணர்ந்தறி வாறேழுங்
கற்றறி வெட்டுங் கலந்தறி வொன்பதும்
பற்றிய பத்தும் பலவகை நாழிகை
அற்ற தறியா தழிகின்ற வாறே`,
    transliteration: `uṟṟaṟi vaintum uṇarntaṟi vāṟēḻuṅ
kaṟṟaṟi veṭṭuṅ kalantaṟi voṉpatum
paṟṟiya pattum palavakai nāḻikai
aṟṟa taṟiyā taḻikiṉṟa vāṟē`,
    english: `741: Life Wasted Away in Pursuit of Worldly Knowledge
Knowledge that comes of senses five,
Knowledge that comes of discrimination that is sixth
Knowledge that comes of judgement that is seventh
Knowledge that comes by learning that is eighth,
Knowledge that comes from experience that is ninth
Knowledge that comes from attachment that is tenth
--Thus does knowledge that comes in diverse ways,
But erode life span in succession;
Knowing this not, they perish away.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-741-Third-Tantra-14.-Cycle-of-Time.mp3',
    elaborationEnglish: `Knowledge comes in diverse ways. Through the senses, through discrimination, through judgement, through experience, through attachments — coming through all these in succession, knowledge erodes the life span.`,
    elaborationTamil: `முதல் நிலையில் ஐந்து புலன்களைச் சார்ந்து இருக்கும் உணர்வுகளில் பெற்ற ஐந்து அறிவுகளும் இரண்டாவது நிலையில் ஐந்தறிவோடு நன்மை தீமையை உணரும் பகுத்தறிவு சேர்ந்து பெற்ற ஆறு அறிவுகளும் மூன்றாவது நிலையில் பகுத்தறிவோடு மனம் சேர்ந்து பெற்ற ஏழு அறிவுகளும் நான்காவது நிலையில் மனதோடு கல்வி சேர்ந்து பெற்ற எட்டு அறிவுகளும் ஐந்தாவது நிலையில் கல்வியோடு அனுபவம் சேர்ந்து பெற்ற ஒன்பது அறிவுகளும் ஆறாவது நிலையில் அனைத்தும் இறையருளாலே என்பதை உணர்ந்து அவனது திருவடிகளை விடாமல் பற்றிக்கொண்டு பெற்ற பத்து அறிவுகளைக் கொண்டு அழிந்து போகும் உடலை விட்டு அழியாத ஞானத்தைப் பெறுவது எப்படி என்பதை அறியாமலேயே பல உயிர்கள் வீணாக அழிந்து போகின்றன. கருத்து: உயிர்களின் வளர்ச்சியில் ஆறு வகை அறிவு நிலைகளையும் அறிந்து அதன்மூலம் இறைவனின் திருவடிகளைப் பற்றிக்கொண்டு காலச் சுழற்சியாகிய பிறவியிலிருந்து நீங்கும் வழியை அறியாமலேயே பல உயிர்கள் வீணாகிவிடுகின்றன.`,
  },
  {
    id: 743, tantraId: 3, verseNumber: 742,
    tamil: `அழிகின்ற ஆண்டவை ஐயைஞ்சு மூன்று
மொழிகின்ற முப்பத்து மூன்றென்ப தாகுங்
கழிகின்ற காலறு பத்திரண் டென்ப
தெழுகின்ற ஈரைம்ப தெண்ணற் றிருந்தே`,
    transliteration: `aḻikiṉṟa āṇṭavai aiyaiñcu mūṉṟu
moḻikiṉṟa muppattu mūṉṟeṉpa tākuṅ
kaḻikiṉṟa kālaṟu pattiraṇ ṭeṉpa
teḻukiṉṟa īraimpa teṇṇaṟ ṟiruntē`,
    english: `742: Critical Years of Life
Many are the stages when death assails man;
From twenty five to twenty eight;
From thirty to thirty three
From sixty to sixty two
From hundred and beyond
These are the critical ages in man's life span;
When death may visit him.`,
    elaborationEnglish: `Many are the critical years in the life of man when -death may assail him. 13, 33, 62 and beyond that, any time upto 100 and over, are considered as critical years in a man's life. iB : AGLI Douws`,
    elaborationTamil: `உயிர்களின் வாழ்நாளில் அழியக்கூடிய நான்கு பகுதிகள் இருக்கின்றன. முதலாவது எதற்கும் பயனின்றி அழிகின்ற பகுதி பதிமூன்று வயது வரையான குழந்தை பருவம். இரண்டாவது பலராலும் சொல்லப்படுகின்ற அளவிற்கு வாழ்ந்து முடியும் பகுதி முப்பத்து மூன்று வயது வரையான வாலிப பருவம். மூன்றாவது பலருக்கும் பயனுள்ளதாக வாழ்ந்து முடியும் பகுதி அறுபத்தி இரண்டு வயது வரையான முதிர்வு பருவம். நான்காவது முழுவதும் வாழ்ந்து பரிபூரணம் என்று சொல்லப்படுகின்ற நிலையில் முடியும் பகுதி நூறு வயது வரையான வயோதிக பருவம். பதிமூன்று வயதிலிருந்து எப்போது வேண்டுமானாலும் இறைவனை அடையக்கூடிய வழிகளில் முயன்று இறைவனை உணர்ந்து விட்டால் எல்லைகள் இல்லாமல் எண்ணிலடங்காத ஆண்டுகள் ஆனாலும் அழியாமல் இருக்கலாம் கருத்து: உயிர்களின் வாழ்நாளில் நான்கு விதமான பகுதிகள் இருகின்றன. இந்தக் பகுதிகளுக்குள் வாழ்க்கையை முடித்துக் கொள்வதும் அதைத் தாண்டி இறையருளால் யோகப் பயிற்சிகள் செய்து நீண்ட காலம் வாழ்வதும் ஒவ்வொரு உயிரின் நோக்கத்தைப் பொறுத்தது.`,
  },
  {
    id: 744, tantraId: 3, verseNumber: 743,
    tamil: `திருந்து தினமத் தினத்தி னொடுநின்
றிருந்தறி நாளொன் றிரண்டெட்டு மூன்று
பொருந்திய நாளொடு புக்கறிந் தோங்கி
வருந்துத லின்றி மனைபுக லாமே`,
    transliteration: `tiruntu tiṉamat tiṉatti ṉoṭuniṉ
ṟiruntaṟi nāḷoṉ ṟiraṇṭeṭṭu mūṉṟu
poruntiya nāḷoṭu pukkaṟin tōṅki
varuntuta liṉṟi maṉaipuka lāmē`,
    english: `743: Days Appropriate for Commencing Yoga
The birth day, The first, second, third and the eight day following it
Any one of these is day appropriate for commencing yoga;
Find the day suitable most,
And easy shall be your entry
Into the Mystic House within.`,
    elaborationEnglish: ``,
    elaborationTamil: `உயிர்கள் பிறந்த தினத்தின் நட்சத்திரத்தை அறிந்து கொண்டு அதிலிருந்து ஒரு நாள், இரண்டு நாள், மூன்று நாள், எட்டு நாள் ஆகிய நாட்களைக் கூட்டி வருகின்ற நாட்களில் அமையும் நட்சத்திரங்களை அறிந்து அந்த நட்சத்திரங்கள் அமையும் நாட்களில் இறைவனை அறிந்துகொள்ளும் அகயோகப் பயிற்சிகளை எதைப்பற்றியும் கவலைப் படாமல் ஆரம்பிக்கலாம். கருத்து: அகயோகப் பயிற்சியை ஆரம்பிப்பதற்கு ஏதுவான நாட்களை பிறந்த நாள் நட்சத்திரத்திலிருந்து எடுத்துக்கொண்டு எந்தத் தயக்கமும் இன்றி ஆரம்பிக்கலாம்.`,
  },
  {
    id: 745, tantraId: 3, verseNumber: 744,
    tamil: `மனைபுகு வீரும் மகத்திடை நாடி
எனவிரு பத்தஞ்சும் ஈரா றதனால்
தனையறிந் தேறட்டுத் தற்குறி யாறு
வினையறி யாறு விளங்கிய நாலே`,
    transliteration: `maṉaipuku vīrum makattiṭai nāṭi
eṉaviru pattañcum īrā ṟataṉāl
taṉaiyaṟin tēṟaṭṭut taṟkuṟi yāṟu
viṉaiyaṟi yāṟu viḷaṅkiya nālē`,
    english: `744: Yoga Explained
You who enter the land of yoga practice!
Know that it consists in this
The measure of breath inhaled is twelve angula
Having measured accordingly
Exhale eight matra consciously
The four matras retained
Are in the six adharas to suffuse
And thus breathing examine the Tattvas twenty and five.`,
    elaborationEnglish: `Yoga consists in the following: inhalation of 12 matras; exhalation of eight matras; retention of four matras. Breathirig

in this measure continuously, yoga suffuses the six adharas with prana which ascends beyond the 25 tattvas.`,
    elaborationTamil: `அகயோகம் செய்ய வேண்டும் என்கிற எண்ணத்தில் பாடல் #748 இல் உள்ளபடி நட்சத்திரம் பார்த்து சாதனைகளை ஆரம்பிக்கும் சாதகர்கள் பாடல் #451 இல் உள்ளபடி தமக்குள் இருபத்தைந்து தத்துவங்களாக இருக்கும் இறைவனை அறிய வேண்டி மூச்சுக்காற்றை பாடல் #728 இல் உள்ளபடி சுழுமுனை நாடியின் 12 அங்குல அளவிற்கும் இறைவனின் மேல் சிந்தனையை வைத்து ஏற்றி இறக்கி தமது மூலாதாரத்திலுள்ள குண்டலினி சக்தியை எழுப்பி ஒவ்வொரு சக்கரமாக ஏறி ஏழாவது சக்கரமாகிய சகஸ்ரதளம் சென்றடைந்தவுடன் பாடல் #709 இல் உள்ளபடி அதையும் தாண்டிய துவாதசாந்த வெளியில் இறைவனோடு கலந்து அவன் நான்கு உயர் தத்துவங்களாக இருப்பதை உணர்ந்து கொள்வார்கள். கருத்து: முறைப்படி அகயோகம் செய்யும் சாதகர்கள் இறைவனோடு கலந்து உண்மை ஞானத்தை அடைவார்கள். இருபத்தைந்து தத்துவங்கள்: 5 பூதங்கள்: நிலம், நீர், காற்று, நெருப்பு, ஆகாயம். 5 புலன்கள்: கண்களால் பார்த்தல், காதுகளால் கேட்டல், வாயால் சுவைத்தல், மூக்கால் நுகருதல், தோலால் தொடுதல். 5 ஞானேந்திரியங்கள்: ஓசை – கேட்பது, ஊறு – உணர்தல், ஒளி – பார்ப்பது, சுவை – உண்பது, நாற்றம் – முகர்வது. 5 கன்மேந்திரியங்கள்: வாய் – பேச்சு, கைகள் – செயல், கால்கள் – போக்குவரவு, எருவாய் – கழிவு நீக்கம் பகுதி, கருவாய் – இன்பமும் பிறப்பும். 4 அந்தக்கரணங்கள்: மனம் – எண்ணங்கள், புத்தி – அறிவு, சித்தம் – சிந்தனை, அகங்காரம் – நான் எனும் நினைப்பு. 1 புருடன்: ஆன்மா. நான்கு உயர் தத்துவங்கள்: சிவம் (அசையாசக்தி) 2. சக்தி (அசையும் சக்தி) 3. நாதம் (ஒலி), 4. விந்து (ஒளி)`,
  },
  {
    id: 746, tantraId: 3, verseNumber: 745,
    tamil: `நாலுங் கடந்தது நால்வரும் நாலைந்து
பாலங் கடந்தது பத்துப் பதினைந்து
கோலங் கடந்த குணத்தாண்டு மூவிரண்
டாலங் கடந்ததொன் றாரறி வாரே`,
    transliteration: `nāluṅ kaṭantatu nālvarum nālaintu
pālaṅ kaṭantatu pattup patiṉaintu
kōlaṅ kaṭanta kuṇattāṇṭu mūviraṇ
ṭālaṅ kaṭantatoṉ ṟāraṟi vārē`,
    english: `745: God is Beyond Adharas and Tattvas
Beyond the Muladhara of the four pointed Center is He;
Beyond the barriers of Tattvas twenty and four is He;
Beyond the twenty and five Tattvas is His Guna
Beyond the six adharas that rise like the spreading banyan tree is He,
Who ever does know Him!`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-745-Third-Tantra-14.-Cycle-of-Time.mp3',
    elaborationTamil: `பாடல் #744 இல் உள்ளபடி துவாதசாந்த வெளியில் இறைவன் நான்கு உயர் தத்துவங்களாக இருப்பதை உணர்ந்த யோகியர்கள் அதையும் தாண்டிய நிலையில் பாடல் #467 இல் உள்ளபடி ஒன்பது துவாரங்கள் இருபத்தைந்து தத்துவங்களால் ஆன உருவத்தைத் தாண்டி அதைச் சுற்றியிருக்கும் குணங்களைக் கொண்ட ஐந்துவித கோசங்களையும் தாண்டி அண்டசராசரங்கள் அனைத்தையும் தாண்டிய ஒரே பொருளாக இருப்பதை அறிந்துகொள்வதில்லை. கருத்து: இறைவனை நான்கு உயர் தத்துவங்களாக உணர்ந்த யோகியர்களாலும் இறைவன் அனைத்தையும் கடந்த ஒரே பொருளாக இருப்பதை உணர்ந்துகொள்வதில்லை. ஐந்து கோசங்கள்: அன்னமயம் – உணவினால் உருவாகும் உடல். பிராணமயம் – மூச்சுக்காற்றால் உருவாகும் உயிர். மனோமயம் – மனதினால் உருவாகும் எண்ணங்கள். விஞ்ஞானமயம் – அறிவினால் உருவாகும் ஞானம். ஆனந்தமயம் – உண்மை ஞானமாகிய பேரறிவால் உருவாகும் பேரின்பம்.`,
  },
  {
    id: 747, tantraId: 3, verseNumber: 746,
    tamil: `ஆறும் இருபதுக் கையஞ்சு மூன்றுக்குந்
தேறு மிரண்டு மிருபத்தொ டாறிவை
கூறு மதியொன் றினுக்கிரு பத்தேழு
வேறு பதியங்க ணாள்விதித் தானே`,
    transliteration: `āṟum irupatuk kaiyañcu mūṉṟukkun
tēṟu miraṇṭu mirupatto ṭāṟivai
kūṟu matiyoṉ ṟiṉukkiru pattēḻu
vēṟu patiyaṅka ṇāḷvitit tāṉē`,
    english: `746: The Days it Takes the Yogi to Traverse Adharas and
Mandalas
The days that take to pierce the Centers nine are this:
Twentieth day adharas six;
Twenty-fifth day Seventh Center of Fire Mandala
Twenty-sixth day the Eighth Center of Solar Mandala
Twenty-seventh day the Ninth Center of Lunar Mandala
--These the days for yogi's Prana to reach Centers nine.`,
    elaborationTamil: `பாடல் #743 ல் உள்ள முறைப்படி நட்சத்திரம் பார்த்து அகயோகப் பயிற்சியை குருநாதரின் வழிகாட்டுதலின் வழியில் மேற்கொள்ளும் சாதகர்களுக்கு இருபதாவது நாளில் மூச்சுக்காற்று ஆறு ஆதார சக்கரங்களையும் செல்வதை உணரலாம். இருபத்தி ஐந்தாவது நாளில் சகஸ்ரதளத்தைத் தாண்டிய துவாதசாந்த வெளியில் இருக்கும் மூன்று மண்டலங்களில் முதலாவதான அக்கினி மண்டலத்திலும் இருபத்தி ஆறாவது நாளில் இரண்டாவதான சூரிய மண்டலத்திலும் இருபத்தி ஏழாவது நாளில் மூன்றாவதான சந்திர மண்டலத்திலும் மூச்சுக்காற்றை வைத்து பயிற்சி செய்தால் இருபத்தி எட்டாவது நாளில் அனைத்தையும் தாண்டி இருக்கும் இறைவனை அறியலாம் என்று யோகத்தின் தலைவனாகிய இறைவன் விதித்து வைத்தான். கருத்து: அகயோகப் பயிற்சியை குருநாதரின் வழிகாட்டுதலின் வழியில் முறையாக ஆரம்பிக்கும் சாதகர்கர்கள் தமது இருபத்தி எட்டாவது நாளில் அனைத்தையும் தாண்டி இருக்கும் இறைவனை அறியலாம்.`,
  },
  {
    id: 748, tantraId: 3, verseNumber: 747,
    tamil: `விதித்த இருபத்தெட் டொடுமூன் றறையாகத்
தொகுத்தறி முப்பத்து மூன்று தொகுமின்
பதித்தறி பத்தெட்டும் பாரா திகணால்
உதித்தறி மூன்றிரண் டொன்றின் முறையே`,
    transliteration: `vititta irupatteṭ ṭoṭumūṉ ṟaṟaiyākat
tokuttaṟi muppattu mūṉṟu tokumiṉ
patittaṟi patteṭṭum pārā tikaṇāl
utittaṟi mūṉṟiraṇ ṭoṉṟiṉ muṟaiyē`,
    english: `747: Vision of the Three Mandalas
On the twenty-eighth day
You gain the vision of Mandalas Three, each apart
On the thirty-third day
You gain their collective vision;
Do Center your thoughts further
And vision the tattvas twenty and four
That to Earth and the rest of elements in order belong.`,
    elaborationTamil: `பாடல் #746 இல் உள்ளபடி அகயோகத்தில் இறைவன் விதித்த இருபத்தி எட்டு நாட்கள் முடிந்த பின் அனைத்தையும் தாண்டி இருக்கும் இறைவனை அறிய முயலும் சாதகர்கள் பாடல் # 467 ல் உள்ளபடி தமக்குள் இருக்கும் முப்பத்தாறு தத்துவங்களையும் ஒன்றாகத் தொகுத்து தமது மூச்சுக்காற்றை சுழுமுனை நாடியிலிருந்து 18 அங்குலம் தாண்டியிருக்கும் (புருவ மத்தியிலிருந்து தலை உச்சி 6 அங்குலம், தலை உச்சியிலிருந்து துவாதசாந்த வெளி 12 அங்குலம்) துவாதசாந்த வெளியில் பதித்து பாடல் #744 இல் உள்ளபடி உணர்ந்த நான்கு உயர் தத்துவங்களிலேயே மனதைச் செலுத்தி அகயோகம் பயின்றால் ஐந்து சிவதத்துவங்களாக இருக்கும் இறைவன் ஒருவனே என்பதை அறிந்து கொள்ளலாம். கருத்து: ஐந்து சிவதத்துவங்களாக இருக்கும் இறைவன் ஒருவனே சதாசிவமூர்த்தி என்பதை இருபத்தி எட்டு நாட்களுக்குப் பின் முயலும் அகயோகப் பயிற்சியால் அறிந்து கொள்ளலாம்.`,
  },
  {
    id: 749, tantraId: 3, verseNumber: 748,
    tamil: `முறைமுறை யாய்ந்து முயன்றில ராகில்
இறையிறை யார்க்கும் இருக்க அரிது
மறையது காரண மற்றொன்று மில்லை
பறையறை யாது பணிந்து முடியே`,
    transliteration: `muṟaimuṟai yāyntu muyaṉṟila rākil
iṟaiyiṟai yārkkum irukka aritu
maṟaiyatu kāraṇa maṟṟoṉṟu millai
paṟaiyaṟai yātu paṇintu muṭiyē`,
    english: `748: Practise Yoga in Time and Order Stated
Thus if in succession and stages
The yogi aspires not
Impossible it be for him to become God;
Much less to near Him;
No other secret the Vedas hold
Trumpet this not;
But in meekness accomplish it.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-748-Third-Tantra-14.-Cycle-of-Time.mp3',
    elaborationEnglish: `Let the yogi practise in successive stages; then he approaches God. Kindle the kundalini lamp within. Search for God with that biazing torch. That alone is the way to the goal.`,
    elaborationTamil: `பாடல் #743 ல் இருந்து #747 வரை உள்ள அகயோகப் பயிற்சி முறைகளை முறையாக குருவின் மூலம் கற்று பகுத்து அறிந்துகொண்டு முயற்சிக்க வேண்டும். குருவருள் இல்லாமல் முறையில்லாமல் செய்யும் யோகப் பயிற்சியால் நீண்ட காலம் நிலைத்து நிற்கவும் முடியாமல் இறையருளும் அவர்களுக்கு கிடைக்காது. குருவின் மூலம் முறையாக கற்றுக்கொண்டதும் அதை வேறு எவருக்கும் சொல்லாமல் பணிவோடு முயற்சி செய்து முடியுங்கள். யாருக்கும் சொல்லாமல் பணிவோடு செய்யுங்கள் என்று அருளியதன் காரணம் இறையருள் கிடைக்காது இதுவே காரணம் அன்றி வேறொன்றும் இல்லை. கருத்து: குருவின் மூலம் முறையாகக் கற்று அதன்படி அகயோகப் பயிற்சிகளை மேற்கொள்ள வேண்டும்.`,
  },
  {
    id: 750, tantraId: 3, verseNumber: 749,
    tamil: `முடிந்த தறியார் முயல்கின்ற மூர்க்கர்
இட்ஞ்சில் இருக்க விளக்கெரி கொண்டு
கடிந்தனன் மூளக் கதுவவல் லார்க்கு
நடந்திடும் பாரினில் நண்ணலு மாமே`,
    transliteration: `muṭinta taṟiyār muyalkiṉṟa mūrkkar
iṭñcil irukka viḷakkeri koṇṭu
kaṭintaṉaṉ mūḷak katuvaval lārkku
naṭantiṭum pāriṉil naṇṇalu māmē`,
    english: `749: Kindle Kundalini Lamp Within
They who know not this Way to the goal
And try other Ways
Are but fools;
They search with blazing torch
While within them is the hand-lamp
They who can kindle the Kundlini Fire within
Will abide ever in this fleeting world.`,
    elaborationEnglish: `They who can kindle the Kundalini Fire within Willi abide ever in this fleeting world.`,
    elaborationTamil: `முறையாகச் செய்யும் அகயோகப் பயிற்சினால் சாதிக்கக்கூடிய விஷயங்களை அறியாமல் வேறு பல வழிகளில் அதை சாதிக்க வேண்டி முயற்சி செய்பவர்கள் கையில் அகல் விளக்கு இருந்தாலும் அதை அறியாமல் தீப்பந்தத்தை தேடி அலையும் மூடர்களைப் போன்றவர்களே. உயிர்களின் உடலுக்குள்ளேயே குண்டலினி சக்தி எனும் நெருப்பு மூலாதாரம் எனும் அகலில் தூங்கிக் கொண்டு இருக்கின்றது. அதை எழுப்பி சுழுமுனை நாடியின் வழியே எடுத்துச் சென்று சகஸ்ரதளத்தில் இருக்கும் ஜோதியில் பொருத்தி பெரிய விளக்காகப் பற்ற வைத்து அஞ்ஞானம் எனும் இருளை அகற்றி உண்மை ஞானத்தை உணர முடிந்த சாதகர்களுக்கு காலம் சக்கரம் போல் ஓடிக் கொண்டே இருக்கும் இந்த உலகத்தில் எதனாலும் பாதிக்கப் படாமல் என்றும் நீடித்து வாழும் வல்லமை கிடைக்கும். கருத்து: அகயோகப் பயிற்சிகளை முறையாகக் கடைபிடித்து ஞானத்தை உணர முடிந்த சாதகர்கள் நீடித்தகாலம் வாழலாம்.`,
  },
  {
    id: 751, tantraId: 3, verseNumber: 750,
    tamil: `நண்ணு சிறுவிர னாணாக மூன்றுக்கும்
பின்னிய மார்பிடைப் பேராமல் ஒத்திடுஞ்
சென்னியின் மூன்றுக்குன்ய் சேரவே நின்றிடும்
உன்னி யுணர்ந்திடும் ஓவியந் தானே`,
    transliteration: `naṇṇu ciṟuvira ṉāṇāka mūṉṟukkum
piṉṉiya mārpiṭaip pērāmal ottiṭuñ
ceṉṉiyiṉ mūṉṟukkuṉy cēravē niṉṟiṭum
uṉṉi yuṇarntiṭum ōviyan tāṉē`,
    english: `750: Journey Through Six Adharas in Two Stages
Unto the girth of the little finger
Is the spinal cord, taut like the string of bow;
There the adharas are
Traversing the first three
Do you reach the Heart's Center.
And, be in constancy fixed;
When you journey further onward
To the three Centers that end with Forehead
You shall firm be
As unto a picture painted.`,
    elaborationTamil: `கட்டை விரலால் சுண்டு விரலைப் பிடித்துக் கொண்டு மற்ற மூன்று விரல்களையும் நேராக நீட்டினால் வரும் முத்திரை வில்லில் ஏற்றிய அம்புகள் போல இருக்கும் மூன்று விரல்களைப் போலவே இடகலை, பிங்கலை மற்றும் சுழுமுனை ஆகிய மூன்று நாடிகளும் மார்பில் உள்ள இதயத்தில் பின்னிப் பிணைந்து பிரியாமல் ஒன்றாகச் சேர்ந்து இருக்கின்றன. அதைப் போலவே மூன்று நாடிகளையும் தலையிலுள்ள மூன்று ஆதாரச் சக்கரங்களோடு (விசுக்தி, ஆக்ஞா, சகஸ்ரதளம்) ஒன்றாகப் பொருந்தும் படி செய்து மூச்சுக்காற்றை சகஸ்ரதளத்திற்கு மேலே இருக்கும் மூன்று மண்டலங்களோடும் (அக்கினி, சந்திர, சூரிய மண்டலங்கள் பாடல் #746 இல் உள்ளபடி) கலக்கும் படி செய்து எண்ணங்களை மொத்தமும் அதிலேயே வைத்து காகிதத்தில் வரைந்த ஓவியம் போல எந்த அசைவும் இன்றி இருந்தால் உண்மை ஞானத்தை உணர்ந்து உடல் என்றும் அழியாத அழகான ஓவியம் போல இளமையுடன் நீண்ட காலம் இருக்கும். கருத்து: அகயோகப் பயிற்சியின்படி ஒன்றாக இருக்கும் மூன்று நாடிகளைகளோடு மூச்சுக்காற்றையும் மூன்று மண்டலங்களோடும் கலந்து தியானித்தால் உண்மை ஞானத்தை உணர்ந்து உடல் என்றும் அழியாத ஓவியம் போல இருக்கும்.`,
  },
  {
    id: 752, tantraId: 3, verseNumber: 751,
    tamil: `ஓவிய மான வுணர்வை அறிமின்கள்
பாவிக ளித்தின் பயனறி வாரில்லை
தீவினை யாமுடன் மண்டல மூன்றுக்கும்
பூவில் இருந்திடும் புண்ணியத் தண்டே`,
    transliteration: `ōviya māṉa vuṇarvai aṟimiṉkaḷ
pāvika ḷittiṉ payaṉaṟi vārillai
tīviṉai yāmuṭaṉ maṇṭala mūṉṟukkum
pūvil iruntiṭum puṇṇiyat taṇṭē`,
    english: `751: Importance of Spinal Cord in Yoga
Know thou the Consciousness that is Perfection;
The sinners know not its goodness;
This body no doubt is evil Karma's product;
Yet it holds the stalk (Spinal Cord) of the sacred Lotus
That blossoms in the Mystic Regions Three within.
The Lord, of yore, spurned the mighty God of Death
Who ever harasses life;
The Lord rides the Chariot of Fire within;
If you vision His Holy Feet,
Decked with triumphal anklet
You shall for ever live
In the canopied terrace above.`,
    elaborationTamil: `பாடல் #750 இல் உள்ளபடி அகயோகத்தால் உண்மை ஞானத்தை உணர்ந்து ஓவியம் போல அசையாமல் நிலைபெறும் உணர்வுகளை அறிந்து கொள்ளுங்கள். ஒழுக்கத்திலிருந்து தவறி பாவத்திலேயே வாழுகின்ற உயிர்கள் இந்த யோகத்தின் பயன்களை அறிந்து கொள்வதில்லை. தீவினையால் பிறந்த இந்த உடலுக்கு இருக்கும் அனைத்து வினைகளையும் நீக்கி பிறவிச் சுழற்சியை அகயோகப்பயிற்சியால் அறுத்து அடைய வேண்டிய அக்கினி, சந்திர, சூரிய மண்டலங்களுக்கு (பாடல் #746 ல் உள்ளபடி) செல்லும் வழியாக சகஸ்ரதளத்தின் ஆயிரம் இதழ் கொண்ட தாமரைப் பூவிற்கு காம்பு போல புண்ணிய பாதையான சுழுமுனை நாடி இருக்கின்றது. கருத்து: தீவினையால் பிறந்த உடலுக்கு புண்ணியத்தை பெற்று பிறவி இல்லா நிலையடைய ஆயிரம் இதழ்கள் கொண்ட தாமரை மலரும் அதன் காம்பு போல நீண்ட சுழுமுனை நாடியும் இருக்கின்றது.`,
  },
  {
    id: 753, tantraId: 3, verseNumber: 752,
    tamil: `தண்டுடன் ஓடித் தலைப்பெய்த யோகிக்கு
மண்டல மூன்று மகிழ்ந்துடல் ஒத்திடுங்
கண்டவர் கண்டனர் காணார் வினைப்பயன்
பிண்டம் பிரியப் பிணங்குகின் றாரே`,
    transliteration: `taṇṭuṭaṉ ōṭit talaippeyta yōkikku
maṇṭala mūṉṟu makiḻntuṭal ottiṭuṅ
kaṇṭavar kaṇṭaṉar kāṇār viṉaippayaṉ
piṇṭam piriyap piṇaṅkukiṉ ṟārē`,
    english: `752: Collective Vision of Mandalas End Karma
The Yogi who through the spinal column
Ascends the adharas above
Sees the Mandalas Three together, rapture bound;
Those who say that vision
Saw the end of Karmas;
Those who saw that not;
But die to be born again.`,
    elaborationEnglish: `The collective vision of the six adharas and the iriple mandalas ends the karmas. Missing that vision, however great the man, his body perishes.`,
    elaborationTamil: `சுழுமுனை நாடியின் வழியே மூச்சுக்காற்றை மேலேற்றிச் சென்று தலை உச்சியிலிருக்கும் சகஸ்ரதள ஆயிரம் இதழ்கள் கொண்ட தாமரை மலரோடு கலந்து விடும் அகயோகத்தை செய்த சாதகர்கள் சகஸ்ரதளத்தையும் தாண்டிய துவாதசாந்த வெளியிலிருக்கும் அக்கினி, சந்திர, சூரிய மண்டலங்களோடு (பாடல் #746 ல் உள்ளபடி) உணர்வு ஒடுங்கி இருந்தால் பேரின்பத்தில் திளைத்து அந்த மண்டலங்களோடு கலந்து நீண்ட காலம் அழியாமல் அழகுடன் இருப்பார்கள். இந்த நிலையை அகயோகப் பயிற்சியினால் முயற்சி செய்து அடைந்தவர்கள் மட்டுமே கண்டு உணர்கின்றார்கள். தங்களின் தீவினைப் பயனால் இந்தப் பயிற்சியைப் பற்றித் தெரியாமலோ அல்லது இதைச் செய்யாமல் வேறு வழிகளில் முயன்று தோல்வியடைந்தவர்களோ தங்களின் உடலை விட்டு உயிர் பிரிந்து மீண்டும் மீண்டும் பிறக்கும் பிறவிச் சுழற்சியில் சிக்கிக் கொண்டு வருந்துகின்றார்கள். கருத்து: அகயோகத்தை செய்பவர்கள் அதைப் பெற்று பேரின்பத்தில் திளைத்து பிறவிச் சுழற்சியிலிருந்து விடுபடுவார்கள். மற்றவர்கள் தங்களின் தீவினைப் பயனால் பிறவித் துன்பத்திலேயே கிடந்து வருந்துகின்றார்கள்.`,
  },
  {
    id: 754, tantraId: 3, verseNumber: 753,
    tamil: `பிணங்கி அழிந்திடும் பேறது கேள்நீ
அணங்குட னாதித்த னாறு விரியின்
வணங்குட னேவந்த வாழ்வு குலைந்து
சுணங்கனுக் காகச் சுழல்கின்ற வாறே`,
    transliteration: `piṇaṅki aḻintiṭum pēṟatu kēḷnī
aṇaṅkuṭa ṉātitta ṉāṟu viriyiṉ
vaṇaṅkuṭa ṉēvanta vāḻvu kulaintu
cuṇaṅkaṉuk kākac cuḻalkiṉṟa vāṟē`,
    english: `753: Missing the Vision, the Body Perishes
Do you know how this body perishes?
Hear this:
A pretty damsel the man has for wife;
And like the sun his prosperity spreads;
And all bow to him in respect;
A body that waxed in a life like thus
Became a prey for prowling dogs to consume.`,
    elaborationTamil: `பிறவிச் சுழற்சியில் சிக்கிக்கொண்டு இறைவனை அடைய உதவும் இந்த பிறவி எப்படி அழிந்து போகின்றது என்பதைக் கேட்டுக்கொள்ளுங்கள். வினைகளைத் தீர்த்துக்கொண்டு தம்மை வந்து அடைய வேண்டும் என்பதற்காக இறைவன் கொடுத்த பிறவியை உயிர்கள் தங்களது ஆசைகளின் வழியிலேயே சென்று மேலும் மேலும் அதிகமாக வினைகளைச் சேர்த்துக் கொண்டே இருந்தால் இறைவனை உணர்ந்து அனைவரும் போற்றி வணங்கிடும் நிலை பெற வேண்டிய வாழ்க்கை சீர்குலைந்து எந்தவித இலக்கும் இல்லாமல் திரியும் நாய்களைப்போல் திரிந்து இறந்து மீண்டும் மீண்டும் பிறந்து அழிகின்ற வாழ்க்கையாக மாறிவிடும். கருத்து: உயிர்கள் தங்கள் ஆசைகளின் வழி செல்வதால் வினைகளை சேர்த்துக்கொண்டு மீண்டும் மீண்டும் பிறப்பெடுத்துக்கொண்டே இருக்கின்றன.`,
  },
  {
    id: 755, tantraId: 3, verseNumber: 754,
    tamil: `சுழல்கின்ற வாறின் துணைமலர் காணான்
தழலிடைப் புக்கிடுந் தன்னு ளிலாமற்
கழல்கண்ட போம்வழி காணவல் லார்க்குக்
குழல்வழி நின்றிடுங் கூத்தனு மாமே`,
    transliteration: `cuḻalkiṉṟa vāṟiṉ tuṇaimalar kāṇāṉ
taḻaliṭaip pukkiṭun taṉṉu ḷilāmaṟ
kaḻalkaṇṭa pōmvaḻi kāṇaval lārkkuk
kuḻalvaḻi niṉṟiṭuṅ kūttaṉu māmē`,
    english: `754: Those Who Vision Can Become the Dancing Lord
They who knock about
Reach not the Refuge of Blossom Feet;
Containing not the Kundalini fire within
Their body a pray to fire becomes;
They who know the Way
And seek His Victorious Feet
See the Heavenly Dancer
Through their spinal hollow.`,
    elaborationEnglish: ``,
    elaborationTamil: `பிறவிச் சுழற்சியில் சிக்கிக்கொண்டு பிறந்து கொண்டே இருக்கின்ற உயிர்கள் தம்மோடு எப்போதும் துணையாக இருக்கும் இறைவனின் திருவடியைத் தாங்கிக் கொண்டு இருக்கின்ற மலரைக் காண்பதில்லை. இறந்த பிறகு நெருப்பில் இடப்படும் இந்த உடலை நிரந்தரம் என்று எண்ணாமல் தமக்குள்ளேயே துணையாக இருக்கும் இறைவனே என்றும் நிரந்தரம் என்பதை உணர்ந்து அவனது திருவடிகளைச் சென்று அடையும் வழியான சுழுமுனை நாடியைக் கண்டுகொண்டவர்கள் அதன் வழியே சென்று அடையும் தலை உச்சியைத் தாண்டிய துவாதசாந்த வெளியில் திருநடனம் புரிந்து கொண்டிருக்கும் இறைவனை கண்டு உணர்ந்து அவனோடு கலந்து பேரின்பத்தில் இருக்கலாம். கருத்து: இறந்த பிறகு நெருப்புக்கு இரையாகும் உடலை பற்றிக்கொண்டு பிறவிச் சுழற்சியில் சிக்கிக் கொள்ளாமல் உடலுக்குள் ஏழாவது சக்கரத்தில் இருக்கும் ஆயிரம் இதழ் கொண்ட தாமரை மலரில் இறைவன் ஒளி உருவமாக வீற்றிருப்பதை பார்த்து இறைவனின் திருவடிகளைப் பற்றிக்கொண்டு அவனோடு கலந்து பேரின்பத்தில் எப்போதும் நிலைத்து வாழலாம்.`,
  },
  {
    id: 756, tantraId: 3, verseNumber: 755,
    tamil: `கூத்தன் குறியிற் குணம்பல கண்டவர்
சாத்திரந் தன்னைத் தலைப்பெய்து நிற்பர்கள்
பார்த்திருந் துள்ளே அனுபோக நோக்கிடில்
ஆத்தனு மாகி யலர்ந்திரு மொன்றே`,
    transliteration: `kūttaṉ kuṟiyiṟ kuṇampala kaṇṭavar
cāttiran taṉṉait talaippeytu niṟparkaḷ
pārttirun tuḷḷē aṉupōka nōkkiṭil
āttaṉu māki yalarntiru moṉṟē`,
    english: `755: Seek the Dancing Lord as Goal and Become One With Him
They who sought the Dancer as their goal
Gained many things goodly;
And so stood in the path of the holy scriptures;
Seeking Him within and experiencing His presence
In eagerness they sit
And one with Siva become.`,
    elaborationTamil: `பாடல் #754 ல் உள்ளபடி தலை உச்சியைத் தாண்டிய துவாதசாந்த வெளியில் திருநடனம் புரிந்து கொண்டிருக்கும் இறைவனைத் தரிசித்து தமக்குள் இறைத்தன்மைகள் பலவற்றை கண்டவர்கள் சாஸ்திரங்கள் கூறும் தர்மங்களையே தலையானதாகக் கொண்டு அவற்றை விட்டு சிறிதும் விலகாமல் கடைபிடித்து நிற்பவர்கள். தர்மம் தவறாமல் நின்று தமக்குள்ளேயே இறைவனின் திருவடியையும் திருநடனத்தையும் தரிசித்துக்கொண்டு அவனருளால் பெற்ற பேரின்பத்தை அனுபவித்துக் கொண்டிருப்பவர்கள் தாமே சிவமாகி அவனைப் போலவே எங்கும் வியாபித்து இருப்பார்கள். கருத்து: இறைவனை தமக்குள்ளே தரிசித்து தர்மத்தை கடைபிடித்து அதன் படி நடப்பவர்கள் பேரின்பத்தில் திளைத்து தாமே சிவமாகி எங்கும் வியாபித்து இருப்பார்கள்.`,
  },
  {
    id: 757, tantraId: 3, verseNumber: 756,
    tamil: `ஒன்றில் வளர்ச்சி உலப்பிலி கேளினி
நன்றென்று மூன்றுக்கு நாளது சென்றிடுஞ்
சென்றிடு முப்பதுஞ் சேர இருந்திடிற்
குன்றிடைப் பொன்திகழ் கூத்தனு மாமே`,
    transliteration: `oṉṟil vaḷarcci ulappili kēḷiṉi
naṉṟeṉṟu mūṉṟukku nāḷatu ceṉṟiṭuñ
ceṉṟiṭu muppatuñ cēra iruntiṭiṟ
kuṉṟiṭaip poṉtikaḻ kūttaṉu māmē`,
    english: `756: God Vision at the End of 33 Days of Yoga
Countless are the gains that flow
From single-minded meditation;
Hear yet;
And thus if for Three and thirty days
You well and deep meditate
The Dancer on top of the Mountain of Gold
Will appear,
And You one with Him become.`,
    elaborationEnglish: ``,
    elaborationTamil: `பாடல் #755 ல் உள்ளபடி இறைவனோடு ஒன்றாய் இரண்டறக் கலந்து தாமே சிவமாகி இருப்பவர்கள் அளவில்லாத காலங்கள் ஆயுள் வளர்ந்து அழியாமல் இருக்கின்ற முறையை கேட்டுக் கொள்ளுங்கள். தமக்குள் இருக்கும் இறைவனை அடைய உதவுவதால் மிகவும் நல்லது என்று சாதகர்கள் உணர்ந்து கொண்ட இடகலை, பிங்கலை, சுழுமுனை ஆகிய மூன்று நாடிகள் வழியாகவும் மூச்சுக்காற்றை உள்ளிழுத்து மேலேற்றி கீழிறக்கி என்று சுழற்சி செய்து கொண்டே இருந்தால் பல காலங்கள் உடல் அழியாமல் சென்று கொண்டே இருக்கும். முப்பது நாட்களுக்கு முறையாகச் செய்த பின்பு குன்றின் மேல் ஏற்றிவைத்த தீபம் போல தலை உச்சியிலிருக்கும் சகஸ்ரதளத்தில் பொன் நிற ஜோதி உருவமாக இருக்கும் இறைவனே தாமாகி ஒளிப் பிரகாசமாக எங்கும் பரவிக்கொண்டே இருப்பார்கள். கருத்து: அகயோகம் செய்யும் சாதகர்கள் இறைவனோடு கலந்து அவனைப் போலவே பொன் நிற ஜோதியாகி எங்கும் பரவிக்கொண்டே இருப்பார்கள்.`,
  },
  {
    id: 758, tantraId: 3, verseNumber: 757,
    tamil: `கூத்தவன் ஒன்றிடுங் கூர்மை அறிந்தங்கே
ஏத்துவர் பத்தினில் எண்டிசை தோன்றிடப்
பார்த்து மகிழ்ந்து பதுமரை நோக்கிடிற்
சாத்திடு நூறு தலைப்பெய்ய லாமே`,
    transliteration: `kūttavaṉ oṉṟiṭuṅ kūrmai aṟintaṅkē
ēttuvar pattiṉil eṇṭicai tōṉṟiṭap
pārttu makiḻntu patumarai nōkkiṭiṟ
cāttiṭu nūṟu talaippeyya lāmē`,
    english: `757: Vision of the Hundred Petalled Lotus of Sahasrara
Knowing the secret of reaching the Dancer,
They meditate on the tenth Center
They see the directions eight in rapturous vision
They glimpse the Lord seated on Lotus,
And attain radiance a hundred fold.`,
    elaborationTamil: `பாடல் #756 ல் உள்ளபடி இறைவனோடு இரண்டறக் கலந்து தாமே சிவமாகிவிடும் வழிமுறையை அறிந்து அதன்படியே அகயோகம் செய்து ஆறு ஆதாரச் சக்கரங்களையும் தாண்டி சகஸ்ரதளத்தின் ஆயிரம் இதழ்கள் கொண்ட தாமரை மலரில் ஒளி உருவமாக வீற்றிருக்கும் இறைவனோடு கலந்து அதையும் தாண்டி துவாதசாந்த வெளியில் இருக்கும் மூன்று மண்டலங்களில் (அக்கினி, சூரிய, சந்திர மண்டலங்கள் பாடல் #746 இல் உள்ளபடி) இரண்டு மண்டலங்களைத் தாண்டி மூன்றாவதாக இருக்கும் சந்திர மண்டலத்தில் எட்டுத் திசைகளும் பரவி விரியும்படி இறைவனின் ஒளி உருவத்தை ஏற்றிவைத்து பேரின்பத்தில் திளைத்து அதைத் தரிசித்துக் கொண்டே இருப்பவர்கள் சாஸ்திரங்கள் கூறிய முழுமையான வயதான நூறு ஆண்டுகளையும் கடந்து நிற்பார்கள். கருத்து: அகயோகம் செய்து ஜோதியான இறைவனோடு கலந்தவர்கள் அந்த ஜோதியை துவாதசாந்த வெளியிலுள்ள மூன்றாவது சந்திர மண்டலத்தில் எட்டுத் திசைகளுக்கும் பரவி விரியும்படி ஏற்றி வைத்தால் நூறு ஆண்டுகளைக் கடந்தும் பேரின்பத்தில் வாழ்வார்கள்.`,
  },
  {
    id: 759, tantraId: 3, verseNumber: 758,
    tamil: `சாத்திடு நூறு தலைப்பெய்து நின்றவர்
காத்துடல் ஆயிரங் கட்டுறக் காண்பர்கள்
சேர்த்துடல் ஆயிரஞ் சேர இருந்தவர்
மூத்துடன் கோடி யுகமது வாமே`,
    transliteration: `cāttiṭu nūṟu talaippeytu niṉṟavar
kāttuṭal āyiraṅ kaṭṭuṟak kāṇparkaḷ
cērttuṭal āyirañ cēra iruntavar
mūttuṭaṉ kōṭi yukamatu vāmē`,
    english: `758: Eternal Life Through Yoga
They who thus attained radiance a hundred fold
Will live a thousand years in body robust;
And they who saw a thousand years thus
May well live a million, trillion years.`,
    elaborationTamil: `பாடல் #757 இல் உள்ளபடி அகயோகம் செய்து சாஸ்திரங்கள் கூறிய முழுமையான வயதான நூறு ஆண்டுகளையும் கடந்து நிற்பவர்கள் ஆயிரம் ஆண்டுகளுக்கும் உடல் கட்டுக்குலையாமல் இருப்பதைக் காண்பார்கள். இறைவனோடு கலந்து ஆயிரம் ஆண்டுகளுக்கு மேல் இருந்தவர்கள் பேரறிவால் முதிர்ந்து கோடி ஆண்டுகளுக்கும் உடல் அழியாமல் இருந்து பல யுகங்களையும் காண்பார்கள். கருத்து: அகயோகப் பயிற்சியை முழுமையாகச் செய்து இறைவனோடு இரண்டறக் கலந்து பேரின்பத்தில் இறைவனை தரிசித்துக்கொண்டே இருப்பவர்கள் பலகோடி வருடங்கள் ஆனாலும் அழியாமல் பல யுகங்களைக் கண்டு அறிவால் முதிர்ந்து உடல் அழியாமல் இருப்பார்கள்.`,
  },
  {
    id: 760, tantraId: 3, verseNumber: 759,
    tamil: `உகங்கோடி கண்டும் ஒசிவற நின்று
அகங்கோடி கண்டு ளயலறக் காண்பர்கள்
சிவங்கோடி விட்டுச் செறிய இருந்தங்
குகங்கோடி கண்டல் குயருறு வாரே`,
    transliteration: `ukaṅkōṭi kaṇṭum ocivaṟa niṉṟu
akaṅkōṭi kaṇṭu ḷayalaṟak kāṇparkaḷ
civaṅkōṭi viṭṭuc ceṟiya iruntaṅ
kukaṅkōṭi kaṇṭal kuyaruṟu vārē`,
    english: `759: Thus They Live Through Timeless Aeons
Well may they thus live for aeons and aeons,
And they tire not in their devotion;
And thus see the mind's end
And within see Him as Entity Inseparate;
And as one with Siva they live filled in divinity
And so see countless ages of Life Exalted.`,
    elaborationTamil: `பாடல் #758 இல் உள்ளபடி கோடி யுகங்களைக் கண்ட யோகியர்கள் சிறிதும் தளர்வின்றி தமது அகயோகத்திலேயே நிலைபெற்று நின்று தான் எனும் எண்ணம் இல்லாமல் இறைவனும் தாமும் வேறு இல்லை என்பதையும் காண்பார்கள். தமக்குள் உணர்ந்த சிவத்தின் ஒளியுருவத்தையும் கடந்து உருவமும் குணமும் இல்லாத இறை நிலையை அடைந்து பல கோடி யுகங்களையும் கண்டு அனைத்திற்கும் மேலானதொரு நிலையை அடைவார்கள். கருத்து: கோடி யுகங்கள் கண்டும் தளர்வில்லாமல் நிலைபெற்று நிற்கும் அகயோகிகள் அதன் பிறகு சிவ நிலையையும் கடந்த பரநிலையில் பலகோடி யுகங்கள் கண்டு அனைத்திற்கும் மேலான நிலையை அடைவார்கள்.`,
  },
  {
    id: 761, tantraId: 3, verseNumber: 760,
    tamil: `உயருறு வாருல கத்தொடுங் கூடிப்
பயனுறு வார்பலர் தாமறி யாமற்
செயலுறு வார்சிலர் சிந்தையி லாமற்
கயலுறு கண்ணியைக் காணகி லாரே`,
    transliteration: `uyaruṟu vārula kattōṭuṅ kūṭip
payaṉuṟu vārpalar tāmaṟi yāmaṟ
ceyaluṟu vārcilar cintaiyi lāmaṟ
kayaluṟu kaṇṇiyaik kāṇaki lārē`,
    english: `760: Worldly Thoughts do not Lead to Sakti
Some seek to exalt themselves
Pursuing ways worldly;
Some seek the fruits of enjoyment
Knowing not what they do;
Some strive after action
With no thought of goal whatsoever;
But none of them will see
The Sakti of lovely eyes.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-760-Third-Tantra-14.-Cycle-of-Time.mp3',
    elaborationTamil: `பாடல் #759 இல் உள்ளபடி அனைத்திற்கும் மேலானதொரு நிலையை அடைந்த யோகியர்கள் உலகத்தவர்களின் மேல் கொண்ட கருணையினால் அவர்கள் அறியாமலேயே அவர்களோடு கலந்து நின்று பல நல்வினைகளைப் புரிந்து பயன்பெற வைக்கின்றார்கள். உலகத்தவர்களையும் பயன்பெற வைக்கின்ற உயர்வான நிலையைப் பற்றி தெரியாத அல்லது அதில் விருப்பமில்லாதவர்கள் தங்களின் கர்மவினைகளைச் செய்துகொண்டு வீணாக வாழ்க்கையைக் கழித்து மீன்களைப் போல் எப்போதும் கண்மூடாமல் அன்பர்களுக்கு அருள்கொடுக்கும் இறை சக்தியை காணாமலேயே காலத்தை கழித்து அழிந்து போகின்றார்கள். கருத்து: அகயோகம் செய்து அனைத்திற்கும் மேலான உயர் நிலையை அடைந்த யோகியர்கள் உலகத்தவர் மேல் கருணை கொண்டு அவர்களுக்காக பல நல்வினைகளைப் புரிகின்றார்கள். இதை அறியாத மற்றவர்கள் தங்களின் வினைகளையே புரிந்து வீணாக காலத்தைக் கழிக்கின்றார்கள்.`,
  },
  {
    id: 762, tantraId: 3, verseNumber: 761,
    tamil: `காணகி லாதார் கழிந்தோடிப் போவர்கள்
நாணகி லாதார் நயம்பேசி விடுவர்கள்
காணகி லாதார் கழிந்த பொருளெலாங்
காணகி லாமற் கழிகின்ற வாறே`,
    transliteration: `kāṇaki lātār kaḻintōṭip pōvarkaḷ
nāṇaki lātār nayampēci viṭuvarkaḷ
kāṇaki lātār kaḻinta poruḷelāṅ
kāṇaki lāmaṟ kaḻikiṉṟa vāṟē`,
    english: `761: Worldly Wealth is Perishable
They who see Her not
Wasted away their lives;
They who seek not
Spent away in artful talks;
The riches and possessions of those who see not
Vanished away unseen and untraced.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-761-Third-Tantra-14.-Cycle-of-Time.mp3',
    elaborationEnglish: `The riches and possessions of those who see not Vanished away unseen and untraced.`,
    elaborationTamil: `பாடல் #760 இல் உள்ளபடி இறை சக்தியைத் தமக்குள் கண்டு உணராதவர்கள் தங்களின் வாழ்க்கையை வீணே வாழ்ந்து கழித்து மீண்டும் பிறக்கும்படி இறந்து போகின்றார்கள். இறை சக்தியை அடையும் வழியைக் கற்று அறிந்தவர்கள் கூட தாம் கற்ற கல்வியை உபயோகித்துப் பயன் பெறாமல் அதைப் பற்றி பலவிதமாகப் பேசுவதில் காலத்தை கழித்துக் கொண்டு தாம் கற்றதெல்லாம் பயனில்லாமல் போகின்றதென்ற நாணம் இல்லாமல் காலத்தை வீணடிக்கின்றார்கள். இறை சக்தியைத் தமக்குள் கண்டு உணராததால் தம்மை விட்டுப் போகின்ற அருட்செல்வங்கள் என்ன என்பதையும் காணமலேயே இவர்களின் காலம் வீணாகக் கழிந்துவிடுகின்றது. கருத்து: இறைவனை அடையவே சாஸ்திரங்களும் கலைகளும் இறைவனால் அருளப்பட்டன. இதை அறியாமல் கற்றவர் கல்லாதவர் ஆகிய இரண்டு வகையினருமே காலத்தை வீணடித்து இறைவனை அறியாமலேயே இறந்து போகின்றார்கள்.`,
  },
  {
    id: 763, tantraId: 3, verseNumber: 762,
    tamil: `கழிகின்ற அப்பொருள் காணகி லாதார்
கழிகின்ற அப்பொருள் காணலு மாகுங்
கழிகின்ற வுள்ளே கருத்துற நோக்கிற்
கழியாத அப்பொருள் காணலு மாமே`,
    transliteration: `kaḻikiṉṟa apporuḷ kāṇaki lātār
kaḻikiṉṟa apporuḷ kāṇalu mākuṅ
kaḻikiṉṟa vuḷḷē karuttuṟa nōkkiṟ
kaḻiyāta apporuḷ kāṇalu māmē`,
    english: `762: Treasure Within is Imperishable
They who do not see the Treasure that surpasses all,
But seek the treasures that perish,
If within their melting heart they seek inside
They will see the Treasure that dies not.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-762-Third-Tantra-14.-Cycle-of-Time.mp3',
    elaborationEnglish: `Seek the treasure within. It is imperishable. If you but seek, you can attain the imperishable Siva state.`,
    elaborationTamil: `பாடல் #761 இல் உள்ளபடி இறை சக்தியைத் தமக்குள் கண்டு உணராததால் தம்மை விட்டுப் போகின்ற அருட்செல்வங்கள் என்ன என்பதைக் காண முடியாதவர்கள் தாம் பெரிதாக எண்ணியிருந்த உலகச் செல்வங்கள் அனைத்தும் தம் கண் முன்பே அழிந்து போவதைக் காண்கிறார்கள். அழிகின்ற உடலுக்குள்ளும் செல்வத்துக்குள்ளும் என்ன இருக்கின்றதேன்று ஆராய்ந்து பார்த்தால் அழிகின்ற அனைத்து பொருட்களுக்குள்ளும் என்றும் அழியாத பெரும் செல்வமான இறைவன் இருப்பதை அறிந்து கொள்ள முடியும். கருத்து: தமக்குள் ஆழ்ந்து தேடி இறைவனை உணர்ந்தவர்களால் மட்டுமே அழிகின்ற அனைத்திலும் என்றும் அழியாத இறை சக்தி இருப்பதைக் கண்டுகொள்ள முடியும்.`,
  },
  {
    id: 764, tantraId: 3, verseNumber: 763,
    tamil: `கண்ணன் பிறப்பிலி காணந்தி யாயுள்ளே
எண்ணுந் திசையுடன் ஏகாந்த னாயிடுந்
திண்ணென் றிருக்குஞ் சிவகதி யாநிற்கும்
நண்ணும் பதமிது நாடவல் லார்கட்கே`,
    transliteration: `kaṇṇaṉ piṟappili kāṇanti yāyuḷḷē
eṇṇun ticaiyuṭaṉ ēkānta ṉāyiṭun
tiṇṇeṉ ṟirukkuñ civakati yāniṟkum
naṇṇum patamitu nāṭaval lārkaṭkē`,
    english: `763: Seek Siva-State
He is the One with the Fore-head eye
He is Birthless
He is Nandi within, Know this;
He in solitariness pervades spaces all
He stands as Siva, the goal unwavering
That state you shall attain
If you but seek.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-763-Third-Tantra-14.-Cycle-of-Time.mp3',
    elaborationTamil: `மூன்று கண்களுடைய பிறப்பில்லாத இறைவனை தனது எண்ணங்கள் அனைத்திலும் காணக்கூடிய சாதகனின் உள்ளே குருவாய் அமர்ந்து அனைத்திற்கும் ஒருவனாகவும் எதிலும் உறுதியாக நிலைத்து இருப்பவனுமான இறைவனின் திருவடிகள் தனக்குள்ளே உறுதியுடன் தேடி சரணாகதியாய் இருப்பவர்களுக்கே கிடைக்கும். கருந்து: காலங்கள் அனைத்திலும் இறைவனை தமக்குள் உறுதியாக தேடி சரணாகதியாய் இருப்பவர்களுக்கு இறைவனின் திருவடி கிடைக்கும்.`,
  },
  {
    id: 765, tantraId: 3, verseNumber: 764,
    tamil: `நாடவல் லார்க்கு நமனில்லை கேடில்லை
நாடவல் லார்கள் நரபதி யாய்நிற்பர்
தேடவல் லார்கள் தெரிந்த பொருளிது
கூடவல் லார்கட்குக் கூறலு மாமே`,
    transliteration: `nāṭaval lārkku namaṉillai kēṭillai
nāṭaval lārkaḷ narapati yāyniṟpar
tēṭaval lārkaḷ terinta poruḷitu
kūṭaval lārkaṭkuk kūṟalu māmē`,
    english: `764: Fruits of Seeking
They who seek
Know death none; evil none;
They who seek
Will become lords of earth;
They who seek
But know this true;
And well may it be told
To those that aspire.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-764-Third-Tantra-14.-Cycle-of-Time.mp3',
    elaborationTamil: `பாடல் #763 இல் உள்ளபடி தமக்குள் உறுதியுடன் இறைவனைத் தேடி அடையக்கூடியவர்களுக்கு இறப்பு இல்லை. இவ்வுலகத்தில் எந்தக் குறையும் இன்றி உயிர்களுக்குத் தலைவனாக இருப்பார்கள். இறைவனைத் தமக்குள்ளே தேடி அடைந்தவர்களுக்குத் தெரிந்த பொருள் இதுவாகும். அவர்கள் அறிந்த இறைவனை அடையும் வழியைக் காட்டும்படி கேட்பவர்களில் தகுதியுள்ளவர்களுக்கு தான் அறிந்ததை எடுத்துக் கூறுவார்கள். கருத்து: இறைவனைத் தமக்குள்ளே தேடி அடைந்தவர்கள் என்றும் இறப்பு இல்லாமல் தம்மை நாடி வருபவர்களில் தகுதியுள்ளவர்களுக்கு தாம் அறிந்தவற்றை எடுத்துக் கூறுவார்கள்.`,
  },
  {
    id: 766, tantraId: 3, verseNumber: 765,
    tamil: `கூறும் பொருளி தகார வுகாரங்கள்
தேறும் பொருளிது சிந்தையுள் நின்றிடக்
கூறு மகாரங் குழல்வழி யோடிட
ஆறும் அமர்ந்திடும் அண்ணலு மாமே`,
    transliteration: `kūṟum poruḷi takāra vukāraṅkaḷ
tēṟum poruḷitu cintaiyuḷ niṉṟiṭak
kūṟu makāraṅ kuḻalvaḻi yōṭiṭa
āṟum amarntiṭum aṇṇalu māmē`,
    english: `765: Seek Lord Through Aum
These the things worthy of telling:
Ahara or the sound "A" that is Siva
Uhara or the sound "U" that is Sakti
Let these in your thought abide
And Mahara or the sound"m"
Let them through thy Spinal Cavity rise upward;
The six adharas will then be reached
And you shall gain the Lord.`,
    elaborationEnglish: `When practising chant the mantra ‘Aum’ continuously in silence. When you thus chant, as the prana rises through the spinal cavity and-courses through the’six adharas, the Lord will be reached.`,
    elaborationTamil: `பாடல் #764 ல் உள்ளபடி தம்மை நாடி வருபவர்களில் தகுதியுள்ளவர்களுக்கு கூறும் பொருளானது ஓங்கார மந்திரத்தின் அகார உகார விளக்கமாகும். அகார உகார மகார எழுத்துக்கள் (அ, உ, ம்) சேர்ந்ததே ஓம் எனும் மந்திரம். அதில் அகாரம் சிவத்தையும் உகாரம் சக்தியையும் மகாரம் உயிரையும் குறிக்கும். குருவானவர் கூறிய ஓம் எனும் மந்திரத்தை தமது சிந்தனையுள் எப்போது நினைத்துக் கொண்டே இருக்கும் சாதகர்களுக்கு ஓம் என்னும் மந்திரத்தின் பொருள் உயிர்கள் தமக்குள் ஒளிந்திருக்கும் குண்டலினி சக்தியே என்பதை உணர்ந்து அதை மூலாதாரத்திலிருந்து எழுப்பி சுழுமுனை நாடி வழியே தலை உச்சியிலுள்ள சகஸ்ரதளத்தில் வீற்றிருக்கும் இறைசக்தியோடு சேர்த்துவிட்டால் அவர்களுக்குள் இருக்கும் ஆறு ஆதாரச் சக்கரங்களிலும் சக்திமயமாக அமர்ந்து இருக்கும் இறைசக்தியும் தாமே என்பதை உணர்ந்து கொள்வார்கள். கருத்து: ஓம் என்னும் மந்திரத்தில் இருக்கும் பொருளை குருவானவரிடம் கேட்டுத் தமக்குள் அதை உணர்ந்த சாதகர்கள் மகாரமாகிய தங்களின் உயிர்சக்தியை அகாரமாகிய சிவத்தோடும் உகாரமாகிய சக்தியோடும் கலந்துவிட்டால் அவர்கள் இறைவனாக ஆகிவிடுவார்கள்.`,
  },
  {
    id: 767, tantraId: 3, verseNumber: 766,
    tamil: `அண்ணல் இருப்பிட மாரும் அறிகிலர்
அண்ணல் இருப்பிடம் ஆய்ந்துகொள் வார்களுக்
கண்ணல் அழிவின்றி உள்ளே அமர்ந்திடும்
அண்ணலைக் காணில் அவனிவ வாகுமே`,
    transliteration: `aṇṇal iruppiṭa mārum aṟikilar
aṇṇal iruppiṭam āyntukoḷ vārkaḷuk
kaṇṇal aḻiviṉṟi uḷḷē amarntiṭum
aṇṇalaik kāṇil avaṉiva vākumē`,
    english: `766: Know Lord Within and Become One With Him
None know where the Lord resides;
To them who seek Him
He resides eternal within;
When you see the Lord
He and you one become.`,
    elaborationTamil: `இறைவன் இருக்கின்ற இடத்தை யாரும் அறிவதில்லை. பாடல் #765 இல் உள்ளபடி இறைவனை அறிந்தவர் மூலம் கேட்டு தமக்குள் ஆராய்ந்து உறுதியுடன் தேடினால் இறைவன் தமக்குள்ளேயே வீற்றிருப்பதை அறிந்து கொள்ளலாம். தமக்குள் இறைவன் வீற்றிருப்பதை அறிந்து கொண்டவர்களுக்கு இறைவன் பேரறிவாய் நின்று அவர்களுக்குள்ளேயே அழியாமல் அமர்ந்திருப்பான். பேரறிவாய் அமர்ந்திருக்கும் இறைவனையே எப்போதும் தரிசித்துக் கொண்டு இருப்பவர்கள் தாமும் அந்த இறைவனாகவே ஆகிவிடுவார்கள். கருத்து: தமக்குள்ளேயே வீற்றிருக்கின்ற இறைவனைக் கண்டு உணர்ந்தவர்கள் இறைவனாகவும் ஆகிவிடுவார்கள்.`,
  },
  {
    id: 768, tantraId: 3, verseNumber: 767,
    tamil: `அவனிவ நாகும் பரிசறி வாரில்லை
அவனிவ நாகும் பரிசது கேள்நீ
அவனிவ நோசை ஔியினுள் ஒன்றிடும்
அவனிவன் வட்டம தாகிநின் றானே`,
    transliteration: `avaṉiva nākum paricaṟi vārillai
avaṉiva nākum paricatu kēḷnī
avaṉiva nōcai auiyiṉuḷ oṉṟiṭum
avaṉivaṉ vaṭṭama tākiniṉ ṟāṉē`,
    english: `767: Way to Become One With Siva
They know not how He and you one become;
This the Way how He and you one become:
Hearken!
He stands in your hearing and sight
He stands in the Mystic Circle within you.`,
    elaborationEnglish: `He is in your hearing. He is in your sight. He stands within the circle within you. It is for you to become one with Him.`,
    elaborationTamil: `தாமும் இறைவனாகவே ஆகிவிடும் பெரும் பயனை அறிந்து கொண்டவர்கள் யாரும் இல்லை. தாமும் இறைவனாகவே ஆகிவிடும் பெரும் பயனைப் பற்றிக் கேட்டுக்கொள்ளுங்கள். பாடல் #765 இல் உள்ளபடி ஓங்கார மந்திரத்தில் அகாரம் எனும் ஒலியாக இருப்பவன் சிவம். உகாரம் எனும் ஒளியாக இருப்பவள் சக்தி. மகாரம் எனும் குண்டலினியாக இருப்பது உயிர்கள். உயிர்களின் உடலுக்குள் இருக்கும் ஆறு ஆதார சக்கரங்களில் சக்திமயமாகவும் ஏழாவது சக்கரமான சகஸ்ரதளத்தில் ஒளியாகவும் எட்டாவது இடமான துவாதசாந்த வெளியில் ஒலியாகவும் இருக்கின்ற இறைவனே பிரணவ மந்திரத்திலுள்ள மூன்று எழுத்துக்களின் தத்துவம் என்பதை உணர்ந்து அந்த இடங்களோடு தமது உயிர்சக்தியைக் கலந்து நிற்கின்றவனே இறைவனாக ஆகிவிடுகின்றான். கருத்து: பிரணவ மந்திரத்தின் தத்துவம் ஒலியாகிய சிவமும், ஒளியாகிய சக்தியும், உயிராகிய ஆன்மாக்களும் ஒன்றாகக் கலந்து ஒன்றோடு ஒன்று வேறுபடாமல் இருப்பதே ஆகும். இதை உணர்ந்து அறிந்து கொண்டவர்கள் இறைவனாக ஆகிவிடுகிறார்கள்.`,
  },
  {
    id: 769, tantraId: 3, verseNumber: 768,
    tamil: `வட்டங்க ளேழு மலர்ந்திடும் உம்முளே
சிட்டன் இருப்பிடஞ் சேர அறிகிலீர்
ஒட்டி யிருந்துள் உபாயம் உணர்ந்திடக்
கட்டி இருப்பிடங் காணலு மாகுமே`,
    transliteration: `vaṭṭaṅka ḷēḻu malarntiṭum ummuḷē
ciṭṭaṉ iruppiṭañ cēra aṟikilīr
oṭṭi yiruntuḷ upāyam uṇarntiṭak
kaṭṭi iruppiṭaṅ kāṇalu mākumē`,
    english: `768: Vision the Lord in the Seven Adharas
You know not how to reach His abode;
Transfixing your thoughts within you in the yogic way
The seven circles inside will open
And you shall see the abode of Lord
Sweet as sugar-lump.`,
    elaborationEnglish: `Six adharas plus the sahasrara. In the adharas. He is seated as Brahtma; as Vishnu; as Rudra; as Mahesvara; as Sadasiva and as Sakti. He that is immanent thus can be seen by you.`,
    elaborationTamil: `உயிர்களின் உடலுக்குள்ளேயே தாமரை மலர்கள் போல மலர்ந்து இருக்கின்ற ஏழு சக்கரங்களிலும் தலை உச்சியைத் தாண்டிய துவாதசாந்த வெளியிலும் இருக்கின்ற சக்திமயங்களே இறைவன் என்பதை அறிந்துகொண்டு அந்த இடங்களோடு தம் உயிர்சக்தியை ஒன்றாகச் சேர்த்து வைத்து இருக்கும் வழிமுறையை உயிர்கள் அறிந்து கொள்வதில்லை. அப்படி இருக்கும் வழிமுறையை பாடல் #765 ல் உள்ளபடி குருவானவர் மூலம் அறிந்து தமக்குள் இருக்கும் இறைசக்தியோடு ஒன்றாகக் கூடியிருந்து உணர்ந்துவிட்டால் கருப்பங்கட்டி போல இனிக்கின்ற அமிர்தமான இறைவனை கண்டுகொள்ளலாம். கருத்து: பேரின்பத்தைக் கொடுக்கும் இறைவன் இருக்குமிடத்தை அடையும் வழிமுறையை உயிர்கள் குருவானவர் மூலம் அறிந்து தமக்குள் உணர்ந்துவிட்டால் இறைவனை கண்டுவிடலாம்.`,
  },
  {
    id: 770, tantraId: 3, verseNumber: 769,
    tamil: `காணலு மாகும் பிரமன் அரியென்று
காணலு மாகுங் கறைக்கண்டன் ஈசனைக்
காணலு மாகுஞ் சதாசிவ சத்தியங்
காணலு மாகுங் கலந்துடன் வைத்ததே`,
    transliteration: `kāṇalu mākum piramaṉ ariyeṉṟu
kāṇalu mākuṅ kaṟaikkaṇṭaṉ īcaṉaik
kāṇalu mākuñ catāciva cattiyaṅ
kāṇalu mākuṅ kalantuṭaṉ vaittatē`,
    english: `769: Vision of Gods in Adharas
TYu may see Him as Brahma and Vishnu
You may see Him as Rudra blue-throat and Mahesa,
You may see Him as Sakti and Sadasiva
You may see Him within you immanent (in Adharas).`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-769-Third-Tantra-14.-Cycle-of-Time.mp3',
    elaborationTamil: `பாடல் #768 ல் உள்ளபடி தமக்குள் இறைவனை உணர்ந்து கண்டுகொண்ட யோகியர்கள் அந்த இறைவனே படைக்கின்ற பிரம்மனாகவும், காக்கின்ற திருமாலாகவும், கருநீலக் கறையுடைய தொண்டையைக் கொண்டு மாயையை அழிக்கின்ற உருத்திரனாகவும், மாயையால் மறைக்கின்ற மகேசுவரனாகவும், அருளுகின்ற சதாசிவனாகவும் உயிர்களின் உடலோடு கலந்து நிற்கின்ற சக்திமயங்களாகவும் இருப்பதை கண்டுகொள்வார்கள். கருத்து: யோகியர்கள் தமக்குள் உணர்ந்த இறைவனே அனைத்து சக்தியாகவும் இருப்பதை கண்டுகொள்வார்கள்.`,
  },
  {
    id: 771, tantraId: 3, verseNumber: 770,
    tamil: `வைத்தகை சென்னியில் நேரிதாய்த் தோன்றிடில்
உத்தம மிக்கிடில் ஓராறு திங்களா
மத்த மிகுத்திட் டிரட்டிய தாயிடில்
நித்தல் உயிர்க்கொரு திங்களில் ஓசையே`,
    transliteration: `vaittakai ceṉṉiyil nēritāyt tōṉṟiṭil
uttama mikkiṭil ōrāṟu tiṅkaḷā
matta mikuttiṭ ṭiraṭṭiya tāyiṭil
nittal uyirkkoru tiṅkaḷil ōcaiyē`,
    english: `770: Breath--Astrology
Put your hand on forehead
And look,
If you see the breath rhythm unchanged
Well and good;
If you see it enlarged,
Death awaits in six months;
If you see it doubled,
In a month shalt life depart.`,
    elaborationTamil: `: ஒருவன் தனது வாழ்நாள் எல்லையை அளந்து அறிந்து கொள்ள எண்ணுபவன் தனது கையை தலையின்மேல் வைத்ததும் இயல்பான எடையாய்த் தோன்றினால் அவனது வாழ்நாளுக்கு நன்மை மிகுந்த எடையுள்ளதாய் தோன்றினால் அவனது வாழ்நாள் ஆறு மாதங்கள் மட்டுமே மேலும் இரண்டு மடங்கு அதிக எடை உள்ளதாய் தோன்றினால் அவனது வாழ்நாள் ஒரு மாதம் மட்டுமே.`,
  },
  {
    id: 772, tantraId: 3, verseNumber: 771,
    tamil: `ஓசையும் ஈசனும் ஒக்கும் உணர்வின்கண்
ஓசை யிறந்தவர் ஈசனை உள்குவர்
ஓசை யிறந்தவர் நெஞ்சினுள் ஈசனும்
ஓசை யுணர்ந்த உணர்விது வாமே`,
    transliteration: `ōcaiyum īcaṉum okkum uṇarviṉkaṇ
ōcai yiṟantavar īcaṉai uḷkuvar
ōcai yiṟantavar neñciṉuḷ īcaṉum
ōcai yuṇarnta uṇarvitu vāmē`,
    english: `771: Transcend Nada and Realize God
Nada and God are one in Consciousness
Only they who transcended Nada
Will on God centre;
God appears in the heart
Of them who Nada transcend
This the truth I realized
And so merged in Nada.`,
    elaborationTamil: `: உள்ளத்தில் உண்டாகும் எண்ணத்தின் ஓசையில் இறைவனை உணர்ந்து எண்ணம் இல்லாத நிலையை கடந்தவர் ஈசனை நினைத்து அவருடனே கலந்திருப்பார் அவ்வாறு கலந்திருப்பவர் நெஞ்சினுள் ஈசன் உணர்வு வடிவாய் நிற்பன்.`,
  },
  {
    id: 773, tantraId: 3, verseNumber: 772,
    tamil: `ஆமே அழிகின்ற வாயுவை நோக்கிடில்
நாமே உறைகின்ற நன்மை யளித்திடும்
பூமேல் உறைகின்ற போதகம் வந்திடுந்
தாமே யுலகில் தலைவனு மாமே`,
    transliteration: `āmē aḻikiṉṟa vāyuvai nōkkiṭil
nāmē uṟaikiṉṟa naṉmai yaḷittiṭum
pūmēl uṟaikiṉṟa pōtakam vantiṭun
tāmē yulakil talaivaṉu māmē`,
    english: `772: Course Breath Upward and See Light of Jnana
The breath that is in vain spent
If turned upward to flow
Will give the good that of fixity of mind comes;
The Jnana that comes from cranial spaces will beam;
And the yogi becomes Lord of earth.`,
    elaborationTamil: `: உடம்பின் வெளியே சென்று அழிகின்ற மூச்சுக்காற்றை அகயோகத்தின் மூலம் கவனித்து நோக்கினால் உண்ணாக்கில் அமிர்தம் சுரந்து நன்மை செய்யும். சகஸ்ரதளத்தில் இருக்கும் ஆயிரம் இதழ்த்தாமரைக்கு மேல் இருக்கும் ஞானம் கைகூடும். அந்த ஞானம் கைகூடினால் உலகின் தலைவனான சிவனாய் இருப்பதை உணரலாம்.`,
  },
  {
    id: 774, tantraId: 3, verseNumber: 773,
    tamil: `தலைவ னிடம்வலஞ் சாதிப்பார் இல்லை
தலைவ னிடம்வல மாயிடில் தையல்
தலைவ னிடம்வலந் தன்வழி யஞ்சில்
தலைவ நிடம்வலந் தன்வழி நூறே`,
    transliteration: `talaiva ṉiṭamvalañ cātippār illai
talaiva ṉiṭamvala māyiṭil taiyal
talaiva ṉiṭamvalan taṉvaḻi yañcil
talaiva niṭamvalan taṉvaḻi nūṟē`,
    english: `773: Importance of Nadi Suddhi for Longevitiy
None there the Jiva who practices Nadi Suddhi,
Breathing from left to right and right to left;
He who does it visions Sakti;
The senses five his way come;
To a hundred years, he sure lives.`,
    elaborationEnglish: `Nadi suddhi (purification) is an important practice in yogic breathing. It consists in breathing from the. left nostril to the right, and from the right to the left in alternation. Practised carefully, it enables the mastery of the senses and confers the vision of Sakti. The yogi can live a hundred years.

Nadisuddhi - a Taniric term: “‘Purification of the nerves. When done by ‘‘mantras’’, it is known as Samanu, and when done by physical exercises like ‘dhauti’, it is known as Nirmanu” (N.N. Bhattacharya P.452 ibid.)`,
    elaborationTamil: `: மூச்சுக் காற்றை இடகலை பிங்கலை நாடிகளின் வழியாக உள்ளெடுத்து சுழுமுனை நாடி வழியே எடுத்துச் சென்று தலை உச்சியிலுள்ள சிவனை அடையும் பிராணாயாமத்தைச் சரியாய் செய்பவர்கள் யாரும் இல்லை. இவ்வாறு சாதனை செய்து கைகூடினால் சக்தியாய் இருக்கும் சிவனை உணரலாம். இந்தப் பயிற்சியை நாள் தோறும் ஐந்து நாழிகைகள் செய்தால் நூறு வயது தாண்டியும் வாழலாம்.`,
  },
  
  {
    id: 775, tantraId: 3, verseNumber: 774,
    tamil: `ஏறிய வாறினில் எண்பது சென்றிடுந்
தேறிய ஏழிற் சிறக்கும் வகையெண்ணில்
ஆறொரு பத்தாய் அமர்ந்த இரண்டையுந்
தேறியே நின்று தெளியிவ் வகையே`,
    transliteration: `ēṟiya vāṟiṉil eṇpatu ceṉṟiṭun
tēṟiya ēḻiṟ ciṟakkum vakaiyeṇṇil
āṟoru pattāy amarnta iraṇṭaiyun
tēṟiyē niṉṟu teḷiyiv vakaiyē`,
    english: `774: Exhalation Measure for Ages 80 and 60
If Prana flows outward
To matra six in length,
Eighty the age you live up to;
If seven, sixty;
These two know clearly.`,
    elaborationEnglish: `If the prana goes outwards in six matra length, eighty shall be the age of the subject. If it flows in seven matras outward, then he will live up to sixty years. When it is cight matras outward, fifty shall be his age. If nine, thirty three; if ten, twenty cight; if fifteen, twenty five; and so on.`,
    elaborationTamil: `: மூச்சுக்காற்று ஆறு விரற்கடை அளவு வெளியேற்றினால் வாழ்நாள் எண்பது ஆண்டாகும். ஏழு விரற்கடை அளவு வெளியேற்றினால் வாழ்நாள் அறுபது ஆண்டாகும். இவ்விரண்டு வகையையும் ஆராய்ந்து உணர்ந்து தெளிவாயாக.`,
  },
{
    id: 776, tantraId: 3, verseNumber: 775,
    tamil: `இவ்வகை எட்டும் இடம்பெற ஓடிடில்
அவ்வகை ஐம்பதே யென்ன அறியலாஞ்
செவ்வகை ஒன்பதுஞ் சேரவே நின்றிடின்
முவ்வகை யாமது முப்பத்து மூன்றே`,
    transliteration: `ivvakai eṭṭum iṭampeṟa ōṭiṭil
avvakai aimpatē yeṉṉa aṟiyalāñ
cevvakai oṉpatuñ cēravē niṉṟiṭiṉ
muvvakai yāmatu muppattu mūṉṟē`,
    english: `775: Exhalation for Ages 50 and 33
If to eight matras Prana runs out
Through nostril left
Fifty the age; know you;
If nine, leaving three matras inside,
Thirty and three but the age.`,
    elaborationTamil: `: மூச்சுக்காற்று எட்டு விரற்கடை அளவு சுவாசம் நீண்டு வெளியேரினால் ஆயுள் ஐம்பது வருடமாகும். மூச்சுக்காற்று ஒன்பது விரற்கடை அளவு சுவாசம் நீண்டு இயங்குமானால் ஆயுள் முப்பத்து மூன்று வருடமாகும்.`,
  },
  {
    id: 777, tantraId: 3, verseNumber: 776,
    tamil: `மும்மூன்றும் ஒன்றும் முடிவுற நின்றிடிற்
எண்மூன்றும் நாலும் இடவகை யாய்நிற்கும்
ஐம்மூன்றும் ஓடி அகலவே நின்றிடிற்
பன்மூன்றொ டீராறு பார்க்கலு மாமே`,
    transliteration: `mummūṉṟum oṉṟum muṭivuṟa niṉṟiṭiṟ
eṇmūṉṟum nālum iṭavakai yāyniṟkum
aimmūṉṟum ōṭi akalavē niṉṟiṭiṟ
paṉmūṉṟo ṭīrāṟu pārkkalu māmē`,
    english: `776: Exhalation for Ages 28 and 25
If in matra ten, it flows out in nostril left
Twenty and eight the life here below;
If fifteen,
Then for twenty and five years only do you see him.`,
    elaborationEnglish: `Then for twenty and five years only do you see him. .`,
    elaborationTamil: `: மூச்சுக்காற்று பத்து விரற்கடை அளவு சுவாசம் நீண்டு இயங்குமானால் ஆயுள் இருபத்தி எட்டு வருடமாகும். மூச்சுக்காற்று பதினைந்து விரற்கடை அளவு சுவாசம் நீண்டு இயங்குமானால் ஆயுள் இருபத்தைந்தது வருடமாகும்.`,
  },
  {
    id: 778, tantraId: 3, verseNumber: 777,
    tamil: `பார்க்கலு மாகும் பகல்முப் பதுமாகில்
ஆக்கலு மாகுமவ் வாறிரண் டுள்ளிட்டுப்
போக்கலு மாகும் புகலற ஒன்றெனில்
தேக்கலு மாகுந் திருந்திய பத்தே`,
    transliteration: `pārkkalu mākum pakalmup patumākil
ākkalu mākumav vāṟiraṇ ṭuḷḷiṭṭup
pōkkalu mākum pukalaṟa oṉṟeṉil
tēkkalu mākun tiruntiya pattē`,
    english: `777: Kumbhaka of Ten Matras Leads to Concentration
Breathing inward in measure twelve
The ten may you retain inside
And direct into oneness upward;
Thus may you practise
The entire day of thirty naligas!`,
    elaborationEnglish: `If the yogi practises retention of ten matras for an entire day of twelve hours, he shall achieve oneness. He will reach the stage of directing the breath into muladhara.

Naligai is a time measure. Two and half naligais make an hour.`,
    elaborationTamil: `: மூச்சுக்காற்று பகல் முப்பது நாழிகையும் இடநாடி வழியே சென்றால் ஆயுள் பன்னிரண்டாண்டு ஆகும். அதனை அனுபவமாகவும் காண முடியும். இடையே மாற்றம் இல்லாமல் ஒருநாள் முழுதும் (அறுபது நாழிகை) மூச்சுக்காற்று இடை நாடி வழியே உள்வந்து வெளிச் சென்றால் ஆயுள் இனி பத்தாண்டு என்று அறியலாம்.`,
  },
  {
    id: 779, tantraId: 3, verseNumber: 778,
    tamil: `ஏயிரு நாளும் இயல்புற ஓடிடிற்
பாயிரு நாலும் பகையற நின்றிடும்
தேய்வுற மூன்றுந் திகழவே நின்றிடில்
ஆயுரு வாறென் றளக்கலு மாமே`,
    transliteration: `ēyiru nāḷum iyalpuṟa ōṭiṭiṟ
pāyiru nālum pakaiyaṟa niṉṟiṭum
tēyvuṟa mūṉṟun tikaḻavē niṉṟiṭil
āyuru vāṟeṉ ṟaḷakkalu māmē`,
    english: `778: Effect of Ten-Matra Kumbhaka for Three Days
If for two days continuous,
The ten matra of Prana is inside retained,
It will no obstacle from apana encounter;
If for three days this is maintained glowing
Then may you be certain
The ascension through Centers Six come soon.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-778-Third-Tantra-14.-Cycle-of-Time.mp3',
    elaborationEnglish: `If he practises thus for two days continuously, the downward streaming apana vayu will not trouble him. On the third day it shall begin the ascension through the six adharas. AMES giycd`,
    elaborationTamil: `: மூச்சுக்காற்று ஒரு நாடியின் வழியாகவே இருநாட்கள் சென்றால் கன்மேந்திரியத்ததின் வழியாக கீழே செல்லும் அபானன் என்னும் பகைக்காற்று தடைபட்டு மூச்சுக் காற்றுடன் மூன்று நாட்கள் இணைந்தது நிலை பெற்று இருந்தால் ஆயுள் வளர்ச்சி அடையும்.`,
  },
  
  {
    id: 780, tantraId: 3, verseNumber: 779,
    tamil: `அளக்கும் வகைநாலும் அவ்வழியே ஓடில்
விளக்கும் ஒருநாலு மெய்ப்பட நிற்கும்
துளக்கும் வகையைந்துந் தூய்நெறி ஓடில்
களக்க மறமூன்றிற் காணலு மாமே`,
    transliteration: `aḷakkum vakainālum avvaḻiyē ōṭil
viḷakkum orunālu meyppaṭa niṟkum
tuḷakkum vakaiyaintun tūyneṟi ōṭil
kaḷakka maṟamūṉṟiṟ kāṇalu māmē`,
    english: `779: Vision of the First Three Adharas in the Fourth and Fifth
Day
If thus the practice is for days four continued,
The four petalled Muladhara will visioned be;
If further continued,
On the fifth day,
The Second and Third adharas visioned art.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-779-Third-Tantra-14.-Cycle-of-Time.mp3',
    elaborationTamil: `: வாழ்நாளை அளந்தது தெரிந்து கொள்ளும் வகையில் நான்கு நாள்கள் பிராணவாயு இடைகலை வழியே இயங்கினால் நான்கு ஆண்டுகள் உயிர் உடலில் இருக்கும். ஐந்து நாள் அவ்வாறு இயங்கினால் தெளிவாக மூன்றாண்டு உயிர் உடலில் இருக்கும்.`,
  },
{
    id: 781, tantraId: 3, verseNumber: 780,
    tamil: `காணலு மாகுங் கருதிய பத்தோடிற்
காணலு மாகுங் கலந்த இரண்டையும்
காணலு மாகுங் கலப்பற மூவைந்தேற்
காணலு மாகுங் கருத்துற ஒன்றே`,
    transliteration: `kāṇalu mākuṅ karutiya pattōṭiṟ
kāṇalu mākuṅ kalanta iraṇṭaiyum
kāṇalu mākuṅ kalappaṟa mūvaintēṟ
kāṇalu mākuṅ karuttuṟa oṉṟē`,
    english: `780: Collective Vision of Five Adharas on the Fifteenth Day
When ten days thus pass
Two more adharas (Fourth and Fifth)
May visioned together be;
On the fifteenth day,
Shall be the collective vision
On the five together.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-780-Third-Tantra-14.-Cycle-of-Time.mp3',
    elaborationTamil: `: மூச்சுக்காற்று பத்து நாள் இடைநாடி வழியே சென்றால் உயிர் உடலில் இரண்டு ஆண்டு கலந்து இருக்கும். மூச்சுக்காற்று பதினைந்து நாள் இடைநாடி வழியே சென்றால் வாழ்நாள் ஓர் ஆண்டு என்பதை தெரிந்து கொள்ளலாம்.`,
  },
  {
    id: 782, tantraId: 3, verseNumber: 781,
    tamil: `கருதும் இருபதிற் காண ஆறாகும்
கருதிய ஐயைந்திற் காண்பது மூன்றாம்
கருதும் இருப துடனாறு காணிற்
கருதும் இரண்டெனக் காட்டலு மாமே`,
    transliteration: `karutum irupatiṟ kāṇa āṟākum
karutiya aiyaintiṟ kāṇpatu mūṉṟām
karutum irupa tuṭaṉāṟu kāṇiṟ
karutum iraṇṭeṉak kāṭṭalu māmē`,
    english: `781: Visions of the 20th, 25th and 26th Days
On the twentieth day
The Sixth Adhara (Ajna) will visioned be;
On the twenty-fifth day
The Three Mandalas (Sun, Moon and Fire) will visioned be;
On the twenty-sixth day
The Two, Siva and Sakti, will visioned be.`,
    elaborationEnglish: `The Two, Siva and Sakti, will visioned be.`,
    elaborationTamil: `மூச்சுக்காற்று இருபது நாள் இடைநாடி வழியே இயங்கினால் வாழ்நாள் ஆறு மாதம் ஆகும். இருபத்தைந்து நாள் இயங்கினால் மூன்று மாதம் ஆகும். இருபத்தாறு நாள் இயங்கினால் இரண்டு மாதம் ஆகும்.`,
  },
  {
    id: 783, tantraId: 3, verseNumber: 782,
    tamil: `காட்டலு மாகுங் கலந்திரு பத்தேழில்
காட்டலு மாகுங் கலந்தெழும் ஒன்றெனக்
காட்டலு மாகுங் கலந்திரு பத்தெட்டிற்
காட்டலு மாகுங் கலந்தஈ ரைந்தே`,
    transliteration: `kāṭṭalu mākuṅ kalantiru pattēḻil
kāṭṭalu mākuṅ kalanteḻum oṉṟeṉak
kāṭṭalu mākuṅ kalantiru patteṭṭiṟ
kāṭṭalu mākuṅ kalantaī raintē`,
    english: `782: Visions of 27th and 28th Day
On the twenty-seventh day
May well be revealed the One Being Supreme
That collectively rises in centers all;
On the twenty-eighth day
May revealed be
The ten centers together
In vision Collective rare.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-782-Third-Tantra-14.-Cycle-of-Time.mp3',
    elaborationEnglish: `On the twenty-seventh day will be seen the One Supreme Being that pervades all the adharas. On the twenty-eighth day, the Space will be visioned.`,
    elaborationTamil: `: மூச்சுக்காற்று இருபத்தேழு நாள் இடகலைநாடி வழியே சென்றால் அதன்பிறகு ஒரு மாதம் வாழ்நாள் என்பதை மெய்ப்பித்துக் காட்டமுடியும். இருபத்தெட்டுநாள் சென்றால் அதன்பின் பத்து நாள்களே வாழ்நாள் என்று மெய்ப்பித்துக் காட்டமுடியும்.`,
  },
  {
    id: 784, tantraId: 3, verseNumber: 783,
    tamil: `ஈரைந்தும் ஐந்தும் இருமூன்றும் எட்டுக்கும்
பாரஞ்சி நின்ற பகைபத்து நாளாகும்
வாரஞ்செய் கின்ற வகையாறஞ் சாமாகில்
ஓரஞ்சொ டொன்றொன் றெனவொன்று நாளே`,
    transliteration: `īraintum aintum irumūṉṟum eṭṭukkum
pārañci niṉṟa pakaipattu nāḷākum
vārañcey kiṉṟa vakaiyāṟañ cāmākil
ōrañco ṭoṉṟoṉ ṟeṉavoṉṟu nāḷē`,
    english: `783: On the 29th Day and 30th Day
If the journey upwards resumes
Ten the days that apana stands as impediment;
If the journey takes thirty days
Seven the days that take the apana to leave.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-783-Third-Tantra-14.-Cycle-of-Time.mp3',
    elaborationEnglish: `On the thirty-first dey of the journey upward, Three the days that still delay the union On thirty-second day that Prana takes to reach, Two the days that are still in the way.

On the thirty-first day there will still be three days’ delay for union with God. On the thirty-second day there will still be an impediment for two more days.`,
    elaborationTamil: `மூச்சுக்காற்று இடகலை நாடியின் வழியே 28 நாட்களுக்கு சென்றாலும் 29 நாட்களுக்கு சென்றாலும் அதன் பிறகு ஆயுள் பத்து நாட்களே ஆகும். ஆனால் 30 நாட்களுக்கு அவ்வாறு சென்றுவிட்டால் அதன் பிறகு ஆயுள் வெறும் ஏழு நாட்களே ஆகும்.`,
  },
  {
    id: 785, tantraId: 3, verseNumber: 784,
    tamil: `ஒன்றிய நாள்கள் ஒருமுப்பத் தொன்றாகிற்
கன்றிய நாலுங் கருத்துற மூன்றாகுஞ்
சென்றுயிர் நாலெட்டுஞ் சேரவே நின்றிடின்
மன்றியல் பாகு மனையில் இரண்டே`,
    transliteration: `oṉṟiya nāḷkaḷ orumuppat toṉṟākiṟ
kaṉṟiya nāluṅ karuttuṟa mūṉṟākuñ
ceṉṟuyir nāleṭṭuñ cēravē niṉṟiṭiṉ
maṉṟiyal pāku maṉaiyil iraṇṭē`,
    english: `784: On the 31st Day and 32nd Day
On the thirty-first day of the journey upward,
Three the days that still delay the union
On thirty-second day that Prana takes to reach,
Two the days that are still in the way.`,
    elaborationTamil: `: மூச்சுக்காற்று இடகலை நாடி வழியாக முப்பத்தொரு நாள் சென்றால் வாழ்நாள் மூன்று நாட்கள் மட்டுமே. முப்பத்திரண்டு நாள் சென்றால் இரண்டு நாளில் அவ்வுயிர் உடலை விட்டுச்செல்லும். சென்றவுடன் அவர் வாழ்ந்த இல்லத்தில் பலர் கூடி ஒலிக்கின்ற இயல்பு தோன்றும்.`,
  },
  {
    id: 786, tantraId: 3, verseNumber: 785,
    tamil: `மனையிலஒன் றாகும் மாதமு மூன்றுஞ்
சுனையில்ஒன் றாகத் தொனித்தனன் நந்தி
வினையற வோங்கி வௌிச்செய்து நின்றால்
தனையுற நின்ற தலைவனு மாமே`,
    transliteration: `maṉaiyilaoṉ ṟākum mātamu mūṉṟuñ
cuṉaiyiloṉ ṟākat toṉittaṉaṉ nanti
viṉaiyaṟa vōṅki vauicceytu niṉṟāl
taṉaiyuṟa niṉṟa talaivaṉu māmē`,
    english: `785: Jiva's Union in God on 33rd Day
Thus when Prana reaches the cranial heights
In a month and three days;
From within the fountain of nectar
Nandi bellows aloud;
If in the space within He reveals Himself,
You shall truly be one in Lord.`,
    elaborationTamil: `: உயிர் முதலில் உடலோடு சேர்ந்து தாயின் வயிற்றில் ஒன்பது மாதம் உருப்பெற்று வளர்ந்து பத்தாம் மாதம் நீரில் மிதந்து பத்தாம் மாத இறுதியில் அவ்விடத்தை விட்டு திருவருள் உணர்வோடு வெளியே வந்து வினைகளை எல்லாம் தீர்த்து தான் யார் என்பதை உணர்ந்து நின்றால் உலகிற்கு தலைவனாகவும் கூடும் என்று நந்தி பெருமான் கூறியுள்ளார்.`,
  },
  {
    id: 787, tantraId: 3, verseNumber: 786,
    tamil: `ஆரு மறியார் அளக்கின்ற வன்னியை
ஆரு மறியார் அளக்கின்ற வாயுவை
ஆரு மறியார் அழிகின்ற அப்பொருள்
ஆரு மறியார் அறிவறிந் தேனே`,
    transliteration: `āru maṟiyār aḷakkiṉṟa vaṉṉiyai
āru maṟiyār aḷakkiṉṟa vāyuvai
āru maṟiyār aḻikiṉṟa apporuḷ
āru maṟiyār aṟivaṟin tēṉē`,
    english: `786: Greatness of Kundalini Yoga
None knows Kundalini that spans high
None knows the science of breath control
They who know it not perish away
I knew the truth that none know.`,
    elaborationEnglish: `They who know it not perish away I knew the truth that none know.`,
    elaborationTamil: `: உயிர் வாழ்தற்கும் வாழ்நாளை அளந்து அறிதற்கும் காரணமான கருவிகள் மூலாக்கினி பிராணவாயு இவற்றின் பெருமைகளை அறிகின்றவர் உலகில் எவரும் இல்லை. அதனால் அவற்றை யோகத்தின் மூலம் ஒழுங்குபட நிறுத்தாத காரணத்தில் விரைவில் உடலை விட்டு நீங்குகின்ற உயிரின் பெருமையையும் அறிகின்றவர் உலகில் எவரும் இல்லை. யாம் இறைவனின் திருவருளால் அவ்விரண்டையும் அறியப் பெற்றேன்.`,
  },
  {
    id: 788, tantraId: 3, verseNumber: 787,
    tamil: `அறிவது வாயுவொ டைந்தறி வாய
அறிவா வதுதான் உலகுயி ரத்தின்
பிறிவுசெய் யாவகை பேணியுள் நாடிற்
செறிவது நின்று திகழு மதுவே`,
    transliteration: `aṟivatu vāyuvo ṭaintaṟi vāya
aṟivā vatutāṉ ulakuyi rattiṉ
piṟivucey yāvakai pēṇiyuḷ nāṭiṟ
ceṟivatu niṉṟu tikaḻu matuvē`,
    english: `787: God as Knowledge
The Lord is the Knowledge
He stood as knowledge of elements five--air and the rest;
He stood as knowledge pervading world all and life
Inseparate from them;
If sought within,
That knowledge will in pervasive richness glow.`,
    elaborationTamil: `: பிராணவாயுவின் இயக்கத்தை அறிந்து கொண்டால் நிலையாக இருக்கும் ஐம்பொறிகளாகிய 1. பார்த்தல் 2. கேட்டல் 3. தொடுஉணர்ச்சி 4. சுவை 5. முகர்தல் என்று சொல்லப்படுவது எதுவோ அதுவே, உலகில் உயிர் என்று அறியப்படும், அவ்வுயிர் உலகினின்றும் பிரிந்து போகாதவாறு அதற்குரிய முறைகளை அறிந்து, அந்த வழியிலே உயிரை பேணிக் காத்தால் உயிர் உடம்பில் நிலைபெற்று இருக்கும்.`,
  },
  {
    id: 789, tantraId: 3, verseNumber: 788,
    tamil: `அதுவரு ளும்மரு ளான துலகம்
பொதுவரு ளும்புக ழாளர்க்கு நாளு
மதுவரு ளும்மலர் மங்கையர் செல்வி
இதுவருள் செய்யும் இறையவ னாமே`,
    transliteration: `atuvaru ḷummaru ḷāṉa tulakam
potuvaru ḷumpuka ḻāḷarkku nāḷu
matuvaru ḷummalar maṅkaiyar celvi
ituvaruḷ ceyyum iṟaiyava ṉāmē`,
    english: `788: Sakti Grants Grace
That God who is knowledge--All thus
Grants this world that is unreal;
For the goodly ones of high praise
He grants the vision of His Dancing Hall;
The Sakti that grants all this
Is the fragrant flower-bedecked Grace
That is the Consort of Lord.`,
    elaborationEnglish: `God, who’ is All-Knowledge, grants this world that is unreal. For yogis he grants the vision of His Dancing Feet. This is the work of His sakti, the fragrant flower-bedecked Grace, that is the Lord’s consort.`,
    elaborationTamil: `: சிவம் அருளிச்செய்த இவ்வுலகத்தில் அனைத்து உயிர்க்கும் பொதுவாக உலக இன்பத்தையும் உயர்ந்தோர்க்கு சிறப்பாக பேரின்பத்தை தந்து சிவானந்தத் தேனாகிய சக்தியை கொடுத்து ஆயுளை அதிகரித்து அருளைப்புரிவது இறைவனே.`,
  },
  {
    id: 790, tantraId: 3, verseNumber: 789,
    tamil: `பிறப்பது சூழ்ந்த பெருந்தகை நந்தி
குறிப்பது கூடிய கோலக் குரம்பைப்
பழப்பதி யாவது பற்றறும் பாசம்
அழப்படி செய்வார்க் ககலு மதியே`,
    transliteration: `piṟappatu cūḻnta peruntakai nanti
kuṟippatu kūṭiya kōlak kurampaip
paḻappati yāvatu paṟṟaṟum pācam
aḻappaṭi ceyvārk kakalu matiyē`,
    english: `789: Nandi Grants Eternal Wisdom
This body is full of desire,
Ancient mansion haunted by repetitive births;
Rend the bonds of desire asunder,
Make the fetters flee, howling;
Nandi Great will grant His Wisdom Eternal.`,
    elaborationEnglish: `This body is full of desires. It is an ancient mansion haunted by repetitive births. Rend the bonds of desires asunder. Make the Pasa flee, howling, Nandi Great will grant His Wisdom Eternal.
“Sakti is Grace” This is Saivite thought`,
    elaborationTamil: `: உயிர்கள் பிறத்தல் வேண்டும் என நந்தி திருவுள்ளக் குறிப்புக் கொண்டருளினன். அக்குறிப்பினால் மாயையால் இவ்வுடம்பு உயிர்களுக்கு அமைந்தது. இவ்வுடல் தொன்று தொட்டு தொடர்ந்து வருவது பாசம் என்னும் பற்று அறுப்பதற்க்கான கருவியாக உள்ளது. இந்த அழகிய உடல் பிஞ்சு, காய், செங்காய் என்று ஆகி முடிவில் பழமாய்ப் பழுத்து விழுந்து அழிந்து விடும். விழுவதற்குள் பாசங்களில் ஆழ்ந்து போகாமல் பாசங்களை விலகும்படி செய்து அதற்குரிய முறைகளில் பழகினால் பாசம் விலகி மெய்யுணர்வு பெருகி ஞானம் மிகும்.`,
  },
  {
    id: 791, tantraId: 3, verseNumber: 790,
    tamil: `வெள்ளிவெண் திங்கள் விளங்கும் புதனிடம்
ஒளிய மந்தன் இரவிசெவ் வாய்வலம்
வள்ளிய பொன்னே வளரும் பிறையிடந்
தெள்ளிய தேய்பிறை தான்வல மாமே`,
    transliteration: `veḷḷiveṇ tiṅkaḷ viḷaṅkum putaṉiṭam
oḷiya mantaṉ iravicev vāyvalam
vaḷḷiya poṉṉē vaḷarum piṟaiyiṭan
teḷḷiya tēypiṟai tāṉvala māmē`,
    english: `790: Days of the Week and the Course of Breath
Through Left and Right Nadis
On Fridays, Mondays and Wednesdays
Prana dominates in the nadi that is to left;
On Saturdays, Sundays and Tuesdays
It courses high in the right;
On Thursdays
Prana flows in the left
In the waxing moon's fortnight;
And in the right in the waning moon's fortnight.`,
    elaborationEnglish: `left (ida) nadi. On Tuesdays, Saturdays and Sundays it tuns high on the right nadi (Pingala). On Thursday, prana rises high in the left in the waxing moon’s fortnight; and in the right in the waning moon’s fortnight.`,
    elaborationTamil: `: வெள்ளி திங்கள் புதன் கிழமைகளில் இட நாடி வழியாக மூச்சு இயங்க வேண்டும். சனி ஞாயிறு செவ்வாய்க் கிழமைகளில் வல நாடி வழியே மூச்சு இயங்க வேண்டும். வளர்பிறை வியாழக் கிழமைகளில் இடநாடியிலும் தேய்பிறை வியாழக் கிழமைகளில் வலது நாடியிலும் மூச்சு இயங்க வேண்டும். இவ்வாறு இயங்குவது உடல் நலத்திற்கு ஏற்ற இயற்கையான பிராண இயக்கமாகும்.`,
  },
  {
    id: 792, tantraId: 3, verseNumber: 791,
    tamil: `வெள்ளிவெண் திங்கள் விளங்கும் புதன்மூன்றுந்
தள்ளி இடத்தே தயங்குமே யாமாகில்
ஒள்ளிய காயத்துக் கூன மிலையென்று
வள்ளல் நமக்கு மகிழ்ந்துரைத் தானே`,
    transliteration: `vauḷiveṇ tiṅkaḷ viḷaṅkum putaṉmūṉṟun
taḷḷi iṭattē tayaṅkumē yāmākil
oḷḷiya kāyattuk kūṉa milaiyeṉṟu
vaḷḷal namakku makiḻnturait tāṉē`,
    english: `791: Breath Rhythm For Glowing Health
If on Fridays, Mondays and Wednesdays
Breathing dominates in nostril left,
The body will no harm know
And it will in health glow;
Thus did Lord Nandi tell us,
In manner delectable.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-791-Third-Tantra-16.-State-of-Breath-in-a-Week.mp3',
    elaborationEnglish: `Good results follow, if the is as above. The body will glow in health.`,
    elaborationTamil: `: இயல்பாகவோ அல்லது பயிற்சியினாலோ திங்கள் புதன் வெள்ளிக் கிழமைகளில் மூச்சு இடைகலை வழியாக நடைபெற்றால் ஞானத்தைப் பெறுதற்கு வாயிலாகிய உடம்பிற்கு எந்த ஒரு குறையும் அழிவும் உண்டாகாது என்று அருள் வள்ளலாகிய நந்தி பெருமான் அனைவருக்கும் மகிழ்ந்து அருளினார்.`,
  },
  {
    id: 793, tantraId: 3, verseNumber: 792,
    tamil: `செவ்வாய் வியாழஞ் சனிஞாயி றேஎன்னும்
இவ்வா றறிகின்ற யோகி இறைவனே
ஒவ்வாத வாயு வலத்துப் புரியவிட்
டவ்வா றறிவார்க்கவ் வானந்த மாமே`,
    transliteration: `cevvāy viyāḻañ caṉiñāyi ṟēeṉṉum
ivvā ṟaṟikiṉṟa yōki iṟaivaṉē
ovvāta vāyu valattup puriyaviṭ
ṭavvā ṟaṟivārkkav vāṉanta māmē`,
    english: `792: Yogi Corrects the Breath Rhythm
Contra,
Tuesdays, Thursdays, Saturdays and Sundays
Breath flows high on the nostril right;
The Yogi who knows this is God indeed;
If this rhythm in the days stated
Does obtain not,
Let the Yogi force it into nostril right by skill subtle;
Then shall he know nothing but joy.`,
    elaborationEnglish: `If this is not obtained, the yogi can by appropriate breathing exercise correct the flow, so that the proper is maintained.`,
    elaborationTamil: `: செவ்வாய்க் கிழமை தேய்பிறை வியாழக்கிழமை சனிக் கிழமை ஞாயிற்றுக் கிழமை ஆகிய நாட்களில் மூச்சை வலப்பக்க நாடி வழியே அறிந்து கொள்ளும் யோகி இறைவன் ஆவான். இந்த நாட்களில் மூச்சு இட நாடியில் நடந்தால் அதை மாற்றி வல நாடியில் புரிய வேண்டும். அப்போது ஆனந்தம் கூடும்.`,
  },
  {
    id: 794, tantraId: 3, verseNumber: 793,
    tamil: `மாறி வருமிரு பான்மதி வெய்யவன்
ஏறி இழியுந் இடைபிங் கலையிடை
ஊறும் உயிர்நடு வேயுயி ருக்கிரந்
தேறி அறிமின் தெரிந்து தௌிந்தே`,
    transliteration: `māṟi varumiru pāṉmati veyyavaṉ
ēṟi iḻiyun iṭaipiṅ kalaiyiṭai
ūṟum uyirnaṭu vēyuyi rukkiran
tēṟi aṟimiṉ terintu tauintē`,
    english: `793: Changing Rhythm on Sundays and Mondays
in Alternate Fortnights
If on a Sunday in a fortnight
The breath runs high on the right nostril,
In the fortnight next it runs high on the left;
If on a Monday in a fortnight
The breath runs high on the left nostril
In the fortnight next it runs low on the right;
Thus do they alternate from fortnight to fortnight
If this rhythm thus obtains,
Prana its strength derives;
Know well this
And according regulate breathing.`,
    elaborationEnglish: `The breath alters from fortnight to fortnight, on two days —- Sunday and Monday. If on a Sunday in one fortnight the breath runs high on the right, it will run high on the left in the next fortnight. If on a Monday in one fortnight breath runs high on the left nostril, then in the next fortnight it runs high on the right nostril.`,
    elaborationTamil: `: சந்திரனும் சூரியனும், இடகலை பிங்கலை நாடிகளில் மாறி மாறி இயங்கும். இடகலை வழியே ஏறிப் பிங்கலை வழியே இறங்கும். பிங்கலை வழியே ஏறி இடகலை வழியே இறங்கும். நடு நாடியில் மூச்சு ஊர்ந்து போகும். நாசிகள் வழியே இயங்கும் மூச்சில் சிவம் உள்ளது என்பதை அறிந்து தெளியலாம்.`,
  },
  {
    id: 795, tantraId: 3, verseNumber: 794,
    tamil: `உதித்து வலத்திடம் போகின்ற போது
அதிர்த்தஞ்சி யோடுத லாமகன் றாரும்
உதித்தது வேமிக வோடிடு மாகில்
உதித்த விராசி யுணர்ந்துகொ ளுற்றே`,
    transliteration: `utittu valattiṭam pōkiṉṟa pōtu
atirttañci yōṭuta lāmakaṉ ṟārum
utittatu vēmika vōṭiṭu mākil
utitta virāci yuṇarntuko ḷuṟṟē`,
    english: `794: How to Regulate When Breath Rhythm Changes Course
The breath that rises in the Nadi Right
While its course into the Left changed
May a sudden jolt know
And in fear trembling flow;
Then leave the practice and rest a while;
If on the Right itself it flows
Faster than in rhythm appropriate
Then know the speed and suitable regulate.`,
    elaborationEnglish: `This is the correct and if this is obtained, prana derives proper strength. [f it is not obtained, it is for the yogi to correct it from time to time and bring the back to the norms indicated. However, this correction is:quite a feat. Sometimes in directing the breath’s course from -the right to the left, the body may experience a sudden jolt and trembling fear. In that case let the. yogi léave the -practice and rest awhile.`,
    elaborationTamil: `: பிராணன் வலப்பக்கம் தோன்றி இடப்பக்கம் ஓடும் போது ஒரு பக்கம் கனமாகவும் ஒரு பக்கம் மெல்லியதாகவும் இருக்கும். இரு பக்கமும் கணமாகவும் மெல்லியதாகவும் மாறி மாறி பிராணன் ஒடுவது இயற்கையாக உள்ளது என்பதை உணர்ந்து அறிந்துகொள்ளலாம்.`,
  },
  {
    id: 796, tantraId: 3, verseNumber: 795,
    tamil: `நடுவுநில் லாமல் இடம்வலம் ஓடி
அடுகின்ற வாயுவை அந்தணன் கூடி
இடுகின்ற வாறுசென் றின்பணி சேர
முடிகின்ற தீபத்தின் முன்னுண்டென் றானே`,
    transliteration: `naṭuvunil lāmal iṭamvalam ōṭi
aṭukiṉṟa vāyuvai antaṇaṉ kūṭi
iṭukiṉṟa vāṟuceṉ ṟiṉpaṇi cēra
muṭikiṉṟa tīpattiṉ muṉṉuṇṭeṉ ṟāṉē`,
    english: `795: Yogi Who Regulates Breath Will See Finite Light
The Prana runs helter-skelter
To Right and to Left;
If Yogi gathers it proper
And regulates to reach Kundalini,
He shall stand before the Finite Light;
Thus He said, Nandi Holy.`,
    elaborationTamil: `: மூச்சுக்காற்று நடுநாடியாகிய சுழுமுனையில் நிற்காமல் இடப்பக்கமாகவும் வலப்பக்கமாகவும் மாறி மாறி இயங்குகின்ற போது உலகியல் வாழ்க்கையில் கிடந்து வருத்தப்பட நேரிடும். யோகியானவன் மூச்சுக்காற்றை நாடிகள் கூடுகின்ற நடுநாடியின் சுழுமுனையில் குண்டலினியோடு சேர்க்க நடுநாடியின் உச்சியில் தீபத்தின் ஒளி தோன்றும் என்று நந்தி அருளினான்.`,
  },
  {
    id: 797, tantraId: 3, verseNumber: 796,
    tamil: `ஆயும் பொருளும் அணிமலர் மேலது
வாயு விதமும் பதினா றுளவலி
போய மனத்தைப் பொருகின்ற வாதாரம்
ஆயவு நாளு முகுர்த்தமு மாமே`,
    transliteration: `āyum poruḷum aṇimalar mēlatu
vāyu vitamum patiṉā ṟuḷavali
pōya maṉattaip porukiṉṟa vātāram
āyavu nāḷu mukurttamu māmē`,
    english: `796: Choose Appropriate Time for Piercing Adharas
The Lord that you search
Is on the Flower Above seated;
Sixteen the Ways of breath control;
The Breath coursing upward in strength
With mind in concentration united,
Pierce the adharas;
The days apt for thus reaching the Centers
And the hour apropriate, know you well.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-796-Third-Tantra-16.-State-of-Breath-in-a-Week.mp3',
    elaborationEnglish: `The art of rousing the kundalini and coursing the prana through the six adharas to reach the thousand-petalled flower above is a consummate one that requires knowledge of the sixteen ways of breath control and intense thought concentration. There are also days and hours appropriate for rousing the kundalini. For these, the Guru will be the guide.`,
    elaborationTamil: `: யோகிகள் உள் நோக்கி தியானம் செய்து ஆராயும் பொருள் முழுமுதற்சிவனாகும், ஆராய்ந்த சிவன் நம் அழகான கண் மலர்களுக்கு மேலே உள்ளான். பதினாறு மாத்திரை அளவு செய்யும் மூச்சுப் பயிற்சியின் மூலம் சுவாசத்தை மாற்றி அமைத்தால் அந்த சிவனை நன்கு உணரலாம். அவ்வாறு உணர்ந்தால் வாழ் நாட்களைக் கூறுபடுத்தி வழங்கும் நாள், கிழமை, மாதம், ஆண்டு முகூர்த்தம் ஆகியவை காரணப்பொருளாக இருந்து உயிரின் ஆயுளை அதிகரிக்கும்.`,
  },
  {
    id: 798, tantraId: 3, verseNumber: 797,
    tamil: `வாரத்திற் சூலம் வரும்வழி கூறுங்கால்
நேரொத்த திங்கள் சனிகிழக் கேயாகும்
பாரொத்த சேய்புதன் உத்தரம் பானுநாள்
நேரொத்த வெள்ளி குடக்காக நிற்குமே`,
    transliteration: `vārattiṟ cūlam varumvaḻi kūṟuṅkāl
nērotta tiṅkaḷ caṉikiḻak kēyākum
pārotta cēyputaṉ uttaram pāṉunāḷ
nērotta vauḷi kuṭakkāka niṟkumē`,
    english: `797: Directional Dangers in Days of the Week
On different days of week
The Soola lies in directions different
On Mondays and Saturdays it is in east;
On Tuesdays and Wednesdays in north
On Sundays and Fridays in west.`,
    elaborationTamil: `திங்கள் சனிக்கிழமைகளில் கிழக்கே சூலம் ஆகும். செவ்வாய் புதன் கிழமைகளில் வடக்கே சூலம் ஆகும். ஞாயிறு வெள்ளிக் கிழமைகளில் மேற்கே சூலம் ஆகும். குறிப்பு: சூரியனின் தீட்சண்யம் குவியும் திசைக்கு சூலம் என்று பெயர் வைத்தார்கள். அந்த திசையில் சூடு அதிகமாக இருக்கும். பயணம் செய்தால் சூட்டினால் உடல் நிலை பாதிக்கும் என்ற காரணத்தால் சூலம் என்று குறிப்பிட்டு அந்த திசையில் பயணிக்க வேண்டாம் என்று சொன்னார்கள்.`,
  },
  {
    id: 799, tantraId: 3, verseNumber: 798,
    tamil: `தெக்கண மாகும் வியாழத்துச் சேர்த்திசை
அக்கணி சூலமு மாமிடம் பின்னாகில்
துக்கமும் இல்லை வலமுன்னே தோன்றிடின்
மிக்கது மேல்வினை மேன்மேல் விளையுமே`,
    transliteration: `tekkaṇa mākum viyāḻattuc cērtticai
akkaṇi cūlamu māmiṭam piṉṉākil
tukkamum illai valamuṉṉē tōṉṟiṭiṉ
mikkatu mēlviṉai mēṉmēl viḷaiyumē`,
    english: `798: Dangers None if Breath Runs High in Right Nostril
On Thursdays menacing trident is in direction south;
Little effect Soola has
If breath to Left flows low,
No harm befalls if Right dominates;
Much good may actually swell.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-798-Third-Tantra-17.-State-of-Misfortune-in-a-Week.mp3',
    elaborationEnglish: `This dangerous-effect of sula can, however, be counteracted by the appropriate alternations in the breathing Thus sula has no effect if the flow of breath from the left nostril is low and if the flow from the right nostril is high. In fact, such a may even actually be beneficial. The practitioner in breath can. apply the necessary corrections.

After kundalini has been roused and the adharas have been pierced, the yogi arrives at a stage when he seeks to drink of the divine nectar that flows from the astral sphere within. For this there is a certain technique known as ‘kechari mudra.’`,
    elaborationTamil: `வியாழக் கிழமையன்று சூலம் தெற்கு திசையில் அமையும். சூலம் நாம் செல்லும் திசைக்கு இடப் பக்கமாகவோ அல்லது பின்பக்கமாகவோ இருந்தால் நன்மை விளையும். சூலம் நாம் செல்லும் திசைக்கு வலப்பக்கமாகவோ அல்லது முன் பக்கமாகவோ இருந்தால் மேலும் மேலும் தீமை அதிகரிக்கும். குறிப்பு: சூரியனின் தீட்சண்யம் குவியும் திசைக்கு சூலம் என்று பெயர் வைத்தார்கள். அந்த திசையில் சூடு அதிகமாக இருக்கும். பயணம் செய்தால் சூட்டினால் உடல் நிலை பாதிக்கும் என்ற காரணத்தால் சூலம் என்று குறிப்பிட்டு அந்த திசையில் பயணிக்க வேண்டாம் என்று சொன்னார்கள்.`,
  },
  {
    id: 800, tantraId: 3, verseNumber: 799,
    tamil: `கட்டக் கழன்று கீழ்நான்று வீழாமல்
அட்டத்தைக் கட்டி அடுப்பை அணைகோலி
விட்டத்தைப் பூட்டி மேற்பையைத் தாட்கோத்து
நட்ட மிருக்க நமனில்லை தானே`,
    transliteration: `kaṭṭak kaḻaṉṟu kīḻnāṉṟu vīḻāmal
aṭṭattaik kaṭṭi aṭuppai aṇaikōli
viṭṭattaip pūṭṭi mēṟpaiyait tāṭkōttu
naṭṭa mirukka namaṉillai tāṉē`,
    english: `799: How to Practise it
Control the spiration
And see that breath is wasted not;
Bind it tight,
Dam the source of Kundalini at Muladhara,
Lock the chimney up in the mouth;
Bolt the cavity above with thy tongue's tip
And sit erect in yoga Samadhi
No more shall be death for you.`,
    elaborationEnglish: `The keche:. yoga is the most important technique in kundalini yoga. It contains the breath within and sees that it is not wasted. The source of kundalini in the muladhara is dammed up and stopped so that breath does not escape downwards

as apana. Similarly, the breath-escape of the prana in the mouth’s upper cavity is locked with the tongue’s tip. Having bolted’ the escapes below and above, the yogi sits erect in samadhi.

1) Although the word yoga, is used here-in connection with kechari by Tirumular, the classical works like Hatha Yoga Pradipika Gheranda Samhita and Siva Samhita (iv,12-15) refer to the as a mudra. The word mudra means ‘to seal,’ ‘close,’ or ‘lock up.” The mudra is a technique for locking the breath within the body. After the practitioner has purified his and gained control of his breath, the technique of mudra is imparted to him by the Guru. Mudras are sometimes referred to as ‘bandha’ which means to ‘bind, fix or restrain.’ “Hatha yoga Pradipika and Gheranda Samhita refer to 25 mudras; Siva Samhita refers to 10 mudras.

The word, kechari, has nothing to do with ‘kesari’ which means lion. As in Tamil both the words are written with the same spelling, some commentators have interpreted it as the lion posture or asana. Kechati means roaming through space or flying. Hence it is also called or ‘sky chakra.’

Hatha Yoga Pradipika describes it as follows: “The kechari mudra is accomplished by thrusting the tongue into the gullet, by turning it’ over on itself and keeping the eyesight in the middle of the eyebrows. To accomplish this, the tongue is lengthened by cutting the fraenum linguae, moving and pulling it. When it can reach the space between the eyebrows, then kechari can be accomplished. Taking a sharp, smooth, and clean instrument, of the shape of a cactus leaf, the fraenum of the tongue should be cut a little (as

much as a hair’s thickness) at a time. Then rock salt and yellow (both powdered) should be rubbed in. On the 7th day, it should be again cut a hair’s breadth. One should go on doing thus, regularly for six months. At the end of six months the fraenum of the tongue will be completely cut. Turning the tongue upwards, it is fixed on the three ways (esophagus, wind pipe and palate). Thus it makes the kechari mudra.”’

Compare Ghéeranda Samhita 25-280); “Cut the lower tendon of the tongue, and move the tongue constantly; rub it with fresh butter, and draw it out (to lengthen it) with an iron instrument. By practising this always, the tongue becomes long; and when it reaches the space between the - eyebrows, then the kechari is accomplished. Then the tongue being lengthend, practise turning it upwards and backwards so as to touch the palate, till at length it reaches the holes of the nostrils opening into the mouth.-Close those holes with the tongue (thus stopping inspiration), and fix the gaze on the space between the eyebrows. This is called kechari.`,
    elaborationTamil: `மூச்சுக் காற்று கீழே இறங்காமல் அண்ணாக்கில் அதைக் கட்டிவிட வேண்டும். அபான வாயு குதம் வழியாகவோ அல்லது குறி வழியாகவோ வெளியேறாமல் குதத்தைச் சுருக்கி நிறுத்த வேண்டும். இரு கண் பார்வைகளையும் ஒன்றாக்கிவிட வேண்டும். உள்ளத்தைச் சுழுமுனை வழியே பாயும் மூச்சில் கொண்டு நிறுத்த வேண்டும். உடலைத் தாண்டிய இந்த நிலையை ஒருவன் அடைந்து விட்டால் அவன் காலத்தைக் கடந்து விடலாம். அவனுக்கு ஒரு மரணம் இல்லை.`,
  },
  {
    id: 801, tantraId: 3, verseNumber: 800,
    tamil: `வண்ணான் ஒலிக்குஞ் சதுரப் பலகைமேற்
கண்ணாறு மோழை படாமற் கரைகட்டி
விண்ணாறு பாய்ச்சிக் குளத்தை நிரப்பினால்
அண்ணாந்து பார்க்க அழுக்கற்ற வாறே`,
    transliteration: `vaṇṇāṉ olikkuñ caturap palakaimēṟ
kaṇṇāṟu mōḻai paṭāmaṟ karaikaṭṭi
viṇṇāṟu pāyccik kuḷattai nirappiṉāl
aṇṇāntu pārkka aḻukkaṟṟa vāṟē`,
    english: `800: Technique of Kecari Yoga
On the square plank of Muladhara,
Where Jiva the washerman performs the cleansing act,
Erect bunds that the sluices leak not (apana);
And then let in the heavenly stream for the lake to fill;
Thus sit looking skyward
Be thou rid of impurity, all.`,
    elaborationEnglish: `Jiva, the washerman, performs the cleansing act on the square plank (four-petalled muladhara). There the yogi erects a bund so that the apana does not escape through the sluice. He then lets in the prana stream upward to fill the body-lake within.

Thus he sits looking skyward and courses the breath through the spinal cavity of sushumna alternating from left to right and vice versa. Kechari (otherwise Kechari) is spiritual attainment which enables one to overcome death.`,
    elaborationTamil: `: வண்ணான் (துணி துவைப்பவர்) துணியை கல்லில் அடித்து துவைக்கும் போது ஆடையில் இருக்கும் அழுக்கு போவது போல உயிர் முன் பக்கம் உள்ள தன் மூளையை தியானம் மூலம் வரும் சிவயோக ஒளியினால் மோத வேண்டும். இரண்டு கண்களின் பார்வைகளையும் மாறி மாறிப் பார்ப்பதால் சிரசின் உள்ளே தெரியும் இரண்டு பக்கத்துக்கும் இடையே உள்ள சஹஸ்ரதளம் என்னும் குளத்தை தியானத்தின் மூலம் வந்த ஒளியைக் கொண்டு நிரப்ப வேண்டும். அதற்குப் பிறகு நெற்றிக்கு மேலே நிமிர்ந்து பார்த்தால் அந்த உயிர் தன் குற்றங்கள் அனைத்தும் நீங்கித் தூய்மை அடைந்து விடுவான்.`,
  },
  {
    id: 802, tantraId: 3, verseNumber: 801,
    tamil: `இடக்கை வலக்கை இரண்டையும் மாற்றித்
துதிக்கையால் உண்பார்க்குச் சோரவும் வேண்டாம்
உறக்கத்தை நீக்கி உணரவல் லார்க்கட்
கிறக்கவும் வேண்டாம் இருக்கலு மாமே`,
    transliteration: `iṭakkai valakkai iraṇṭaiyum māṟṟit
tutikkaiyāl uṇpārkkuc cōravum vēṇṭām
uṟakkattai nīkki uṇaraval lārkkaṭ
kiṟakkavum vēṇṭām irukkalu māmē`,
    english: `801: Immortality in Yoga Way
Alternating breath's course from left to right and vice versa,
They who can force breath through spinal Sushumna
Shall know tiring none;
They can abolish sleep for ever
And attain God-awareness;
They die not;
Immortal they shall be.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-801-Third-Tantra-18.-Yoga-of-Cosmic-Energy.mp3',
    elaborationEnglish: `The yogi who does this knows neither weariness nor sleep. He will be alert all day and night in divine consciousness.`,
    elaborationTamil: `: இடகலை பிங்கலை நாடிகள் வழியே மூச்சுக் காற்று இயங்குவதை மாற்றிச் சுழுமுனை வழியே மூச்சுக்காற்றை செலுத்தும் கலையை ஒருவன் அறிந்து கொண்டு விட்டால் அவருக்குத் சோர்வு ஏற்படாது. உறங்கும் காலத்தில் உறக்கத்தை விட்டு பயிற்சி செய்து வந்தால் ஒருவனுக்கு இறப்பு இல்லாமல் நீண்ட காலம் வாழலாம்.`,
  },
  {
    id: 803, tantraId: 3, verseNumber: 802,
    tamil: `ஆய்ந்துரை செய்யில் அமுதநின் றூறிடும்
வாய்ந்துரை செய்யும் வருகின்ற காலத்து
நீந்துரை செய்யில் நிலாமண் டலமதாய்ப்
பாய்ந்துரை செய்தது பாலிக்கு மாறே`,
    transliteration: `āynturai ceyyil amutaniṉ ṟūṟiṭum
vāynturai ceyyum varukiṉṟa kālattu
nīnturai ceyyil nilāmaṇ ṭalamatāyp
pāynturai ceytatu pālikku māṟē`,
    english: `802: Nectar in Kecari Mudra
If skillfully rubbed by the tongue's tip
The mystic nectar will begin to ooze;
When it comes, with care manage it
That you may swim in Moon's Region mystic;
And that which flowed and roared
May preserved be.`,
    elaborationEnglish: `If the tongue’s tip is turned backwards to lock up the cavity in the gullet, and then skilfully rubbed, the nectar will begin to coze from the moon’s region. Some authorities advocate cutting the fraenum to facilitate this process. Tirumular, however. does not mention it. Both these methods seem to have been in practice.`,
    elaborationTamil: `: யோக நூல்களை ஆராய்ந்து அதனை முறையோடு செய்தால் உடம்பிலிருந்து அமுதம் சுரக்கும். அந்த அமுதம நாடிகளில் பாய்கின்றபோது ஓர் ஒலியை எழுப்பும். அந்த ஒலி சந்திர மண்டலமாக விளங்கி நரை, திரை, பிணி, மூப்பு இல்லாமல் நம்மைப் பாதுகாக்கும்.`,
  },
  {
    id: 804, tantraId: 3, verseNumber: 803,
    tamil: `நாவின் நுனியை நடுவே சிவிறிடிற்
சீவனும் அங்கே சிவனும் உறைவிடம்
மூவரு முப்பத்து மூவருந் தோன்றுவர்
சாவதும் இல்லை சதகோடி யூனே`,
    transliteration: `nāviṉ nuṉiyai naṭuvē civiṟiṭiṟ
cīvaṉum aṅkē civaṉum uṟaiviṭam
mūvaru muppattu mūvarun tōṉṟuvar
cāvatum illai catakōṭi yūṉē`,
    english: `803: Vision of Gods in Kecari Mudra
Fan tongue's tip upward in palate centre;
There abides Jiva and Siva;
The Gods Three, and Devas three and thirty crores
Will there appear;
No death shall there be;
A million, billion years this fleshly body will be.`,
    elaborationTamil: `: நான்கு வகை யோகங்களுள் ஒன்றான அடயோக முறைப்படி நல்லாசனத்தில் அமர்ந்து நாக்கின் நுனியை அண்ணாக்கில் உரசினால் பிரணவ மந்திரம் கேட்கும். அந்த சாதகம் செய்யும் உயிருடன் சிவனும் கலந்து சேர்ந்து அதன் உடலையே தனக்கு விருப்பமான உறைவிடமாக கொண்டு தங்குவார். அங்கே மும்மூர்த்திகளும் முப்பத்து முக்கோடி தேவர்களும் தோன்றுவார்கள். அந்த உயிருக்கு நூறு கோடி ஆண்டுகளுக்கு மரணம் என்பதே இருக்காது.`,
  },
  {
    id: 805, tantraId: 3, verseNumber: 804,
    tamil: `ஊனூறல் பாயும் உயர்வரை உச்சிமேல்
வானூறல் பாயும் வகையறி வாரில்லை
வானூறல் பாயும் வகையறி வாளர்க்குத்
தேனூறல் உண்டு தௌியலு மாமே`,
    transliteration: `ūṉūṟal pāyum uyarvarai uccimēl
vāṉūṟal pāyum vakaiyaṟi vārillai
vāṉūṟal pāyum vakaiyaṟi vāḷarkkut
tēṉūṟal uṇṭu tauiyalu māmē`,
    english: `804: Transform Fleshly Stream Into Heavenly Stream
From the lofty peaks of the cranium
Flows the stream that is of the flesh;
It is a heavenly stream;
They know not how to make it so;
They who know that art
Will swill the divine nectar
And be forever, doubt free.`,
    elaborationTamil: `: ஊனால் ஆன உடம்பின் நெற்றி நடுவில் ஓர் ஓளி உள்ளது, அதனை தலை உச்சிக்கு மேல் உள்ள வான மண்டலத்தோடு சேர்க்கும் வகைகளை அறிபவர்கள் யாரும் இல்லை. வான மண்டலத்தோடு சேர்க்கும் வகைகளை தெரிந்து கொண்டு அவ்ஒளியை வான மண்டலத்தோடு சேர்ப்பவர்கள் அங்கு ஊறும் தேன் போன்ற அமுதத்தை உண்டு தெளிவு பெற்று அதன் சிறப்பை உணர்வார்கள்.`,
  },
  {
    id: 806, tantraId: 3, verseNumber: 805,
    tamil: `மேலையண் ணவில் விரைந்திரு காலிடிற்
காலனும் இல்லை கதவுந் திறந்திடும்
ந்யாலம் அறிய நரைதிரை மாறிடும்
பாலனு மாவான் பராநந்தி ஆணையே`,
    transliteration: `mēlaiyaṇ ṇavil viraintiru kāliṭiṟ
kālaṉum illai katavun tiṟantiṭum
nyālam aṟiya naraitirai māṟiṭum
pālaṉu māvāṉ parānanti āṇaiyē`,
    english: `805: Kecari Mudra Leads to Youthfulness
If you can send the breath twain
Into the mouth's upper cavity
You shall then know death none;
And the gates of nectar will open be;
Greying and wrinkling will disappear
For all to see;
Young will the Yogi be
True this, I say, in the name of Nandi Holy.`,
    elaborationTamil: `அண்ணாக்கின் அருகில் உள்ள பகுதியில் இடகலை பிங்கலை என்னும் இரு நாடிகளின் வழியே இயங்கும் மூச்சுக்காற்றை பயிற்சியின் மூலம் பொருத்தினால் யமன் பயம் இல்லை. உடலுக்கு அழிவு இருக்காது. மேலுலகத்து வாயிற் கதவு திறக்கும். நரை திரைகளும் மாறிவிடும். அதன்பின் யோகி உலகம் அறிய இளமைத் தோற்றத்தையும் உடையவனாவான். இது குருவான இறைவன் மேல் ஆணையாகச் சொல்லுகின்ற உண்மை.`,
  },
  {
    id: 807, tantraId: 3, verseNumber: 806,
    tamil: `நந்தி முதலாக நாமேலே யேறிட்டுச்
சந்தித் திருக்கில் தரணி முழுதாளும்
பந்தித் திருக்கும் பகலோன் வௌியாகச்
சிந்தித் திருப்பவர் தீவினை யாளரே`,
    transliteration: `nanti mutalāka nāmēlē yēṟiṭṭuc
cantit tirukkil taraṇi muḻutāḷum
pantit tirukkum pakalōṉ vauiyākac
cintit tiruppavar tīviṉai yāḷarē`,
    english: `806: Leakage of Restrained Breath Leads to Evil
Consequences
With Nandi to guide
If we upward ascend
We shall meet Lord;
We shall then hold sway over world all;
They who let the restrained breath out
Through the Sun Nadi
And yet meditating sit
Art verily to Evil Fate decreed.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-806-Third-Tantra-18.-Yoga-of-Cosmic-Energy.mp3',
    elaborationTamil: `குருநாதர் காட்டிய வழியில் நாக்கின் நுனியை அண்ணாக்கில் ஏறும்படிச் செய்து அங்கே நடுநாடியின் உச்சியில் கூடி இருக்க வேண்டும். அதனைச் செய்கின்ற யோகி உலகத்தார் யாவரையும் ஆட்கொள்கின்ற திருவருட் செல்வம் உடையவன் ஆவான். அந்த யோகத்தை மேற்கொள்ளாது உலகியலில் அறிவை நினைத்துக்கொண்டிருப்போர் பிறப்பு இறப்புத் துன்புக்கு ஆட்படும் தீவினையராவர் ஆவார்.`,
  },
  {
    id: 808, tantraId: 3, verseNumber: 807,
    tamil: `தீவினை யாடத் திகைத்தங் கிருந்தவர்
நாவினை நாடின் நமனுக் கிடமில்லை
பாவினை நாடிப் பயனறக் கண்டவர்
தேவினை யாடிய தீங்கரும் பாமே`,
    transliteration: `tīviṉai yāṭat tikaittaṅ kiruntavar
nāviṉai nāṭiṉ namaṉuk kiṭamillai
pāviṉai nāṭip payaṉaṟak kaṇṭavar
tēviṉai yāṭiya tīṅkarum pāmē`,
    english: `807: Perfect Practice of Kecari Leads to Immortality
They who sat bewildered
Overwhelmed by Karma Evil,
Let them perform the Karma of Tongue
(That Kecari Yoga prescribes);
Then no more is there room for death;
They who seek proliferating Karma
And render life useless,
Will remain unto sugarcane
Of its juicy sweetness pressed away.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-807-Third-Tantra-18.-Yoga-of-Cosmic-Energy.mp3',
    elaborationEnglish: `Those who realize that. karmas are useless Do the divine work and Enjoy sweetness like that of the sugarcane juice.`,
    elaborationTamil: `: பாவச் செயல்களைச் செய்ததனால் பிறப்பு இறப்புக்கு உட்பட்டு தீ வினைகள் நம்மை வருத்தும் பொழுது அதனை போக்க வழி தெரியாமல் இருப்பவர்கள் நாவின் நுனியால் உண்ணாக்குத் தொளையை அடைக்கும் பயிற்சியாகிய கேசரி யோகத்தைப் பயின்றால் எமனை வென்று விடலாம். பரந்த வினைகளை எல்லாம் ஆராய்ந்து அவற்றால் விளையும் பயன்கள் ஒன்றும் இல்லை என நன்கு அறிந்தவர்கள் தெய்வப் பணியில் ஈடுபட்டு கிடைக்கும் திருவருளை இனிய கரும்பு சுவைப்பது போல் அதன் இனிமையைச் சுவைப்பர்.`,
  },
  {
    id: 809, tantraId: 3, verseNumber: 808,
    tamil: `தீங்கரும் பாகவே செய்தொழி லுள்ளவர்
ஆங்கரும் பாக அடையநா வேறிட்டுக்
கோங்கரும் பாகிய கோணை நிமிர்த்திட
ஊங்கரும் பாகியே ஊனீர் வருமே`,
    transliteration: `tīṅkarum pākavē ceytoḻi luḷḷavar
āṅkarum pāka aṭaiyanā vēṟiṭṭuk
kōṅkarum pākiya kōṇai nimirttiṭa
ūṅkarum pākiyē ūṉīr varumē`,
    english: `808: Erect Posture for Kecari Mudra
The Yogis who thus divine sweetness experienced
If in a bud-like formation
Send tongue upward
Their spinal chord erect as a stiff rod
Then will trickle nectar from within
And body becomes sweet as sugarcane.`,
    elaborationEnglish: `Mantras 808-810, 813 & 814 - When the yogi twirls the tongue into the cavity of the gullet through which saliva flows and drinks of the nectar that wells up, chanting all the time "Sivaya nama" in silence, verily the body becomes sweet as sugarcane. The water that kechari mudra brings streams pellucid as from the Ganga. The yogi is then in rapport with the mystic moon shedding the 16 kalas. He sees the kala worlds within the divine mansion shedding argent rays. He visions Sakti too, as a Divine Fawn enveloped by kalas. There, She silts, enriching the ambrosia stream.`,
    elaborationTamil: `: கேசரியோகப் பயிற்சியால் வினைகள் சுழன்ற உடம்பினை இனித்த கரும்பு போல் ஆக்கிக்கொண்டவர்கள் நாவின் நுனியை மேல் நோக்கிக் குவித்துச் செலுத்தி கோங்கரும்பை போன்ற குண்டலியின் வளைவை நேராக்கினால் இந்த உடலிலேயே அமுதத்தைக் காணலாம்.`,
  },
  {
    id: 810, tantraId: 3, verseNumber: 809,
    tamil: `ஊனீர் வழியாக வுண்ணாவை யேறிட்டுத்
தேனீர் பருகிச் சிவாய நமவென்று
கானீர் வரும்வழி கங்கை தருவிக்கும்
வானீர் வரும்வழி வாய்ந்தறி வீரே`,
    transliteration: `ūṉīr vaḻiyāka vuṇṇāvai yēṟiṭṭut
tēṉīr parukic civāya namaveṉṟu
kāṉīr varumvaḻi kaṅkai taruvikkum
vāṉīr varumvaḻi vāyntaṟi vīrē`,
    english: `809: Chant Sivayanama as You Swill Nectar
Upward twirl
Tongue's interior
Through which saliva flows
And drink of nectar welling up
And remain chanting "Sivaya Nama;"
The waters that breath brings
Streams as unto Ganga flow;
Learn this Way
To the flow of the Heavenly nectar.`,
    elaborationEnglish: `To the flow of the Heavenly nectar. The mantra Namah”’ makes its appearance here. The word ‘“‘pariyanga’’ literally means bed-stead; here, it refers to the “‘vamacara’’ branch of tantricism, which advocates the ““‘panca makara’’, the five Ms: mamsa, mithuna, mina, mudra, and madhu.`,
    elaborationTamil: `: கேசரி யோகத்தைச் செய்து நாவின் வழியாக உண்ணாக்கை மேலே செலுத்தி அங்கு ஊற்றெடுக்கும் அமுதத்தை பருகி சிவாய நம என்ற ஐந்து எழுத்துக்களை சிந்தனை செய்பவர்களுக்கு ஓர் ஒளி வெள்ளம் நீர் வெள்ளம் போல முகத்தின் முன்பு பெருகும். (வியர்வை போல்) காற்றும், நீரும் உலாவும் இடமாகிய இந்த உடம்பு ஆகாய கங்கையை உம்மிடம் வரச்செய்யும். அந்த வான கங்கையை பெற்று அறிந்து கொள்ளுங்கள்.`,
  },
  {
    id: 811, tantraId: 3, verseNumber: 810,
    tamil: `வாய்ந்தறிந் துள்ளே வழிபாடு செய்தவர்
காய்ந்தறி வாகக் கருணை பொழிந்திடும்
பாய்ந்தறிந் துள்ளே படிக்கத வொன்றிட்டுக்
கூய்ந்தறிந் துள்ளுறை கோயிலு மாமே`,
    transliteration: `vāyntaṟin tuḷḷē vaḻipāṭu ceytavar
kāyntaṟi vākak karuṇai poḻintiṭum
pāyntaṟin tuḷḷē paṭikkata voṉṟiṭṭuk
kūyntaṟin tuḷḷuṟai kōyilu māmē`,
    english: `810: A Cave Temple Within
Knowing way appropriate
Those who worshipped thus within
Will receive shower of Grace
That is Jnana ripe;
If they but know how to bolt the door within
And check the flowing stream,
Well then may they become
Abiding cave temples within.`,
    elaborationTamil: `: சிவனை மனதில் உணர்ந்து வழிபாடு செய்தவர்களின் அறியாமையை சக்தி ஒலி ஒளி வடிவாக வந்து சுட்டெரித்து வெளிப்படுவாள். கேசரி முத்திரையினால் அந்த ஒளி ஒலிகளில் மனத்தைப் பதித்து அதன் மீது தியானம் செய்தால் அந்த யோகியின் உடலே ஓர் கோயிலாகி விடும்.`,
  },
  {
    id: 812, tantraId: 3, verseNumber: 811,
    tamil: `கோயிலின் உள்ளே குடிசெய்து வாழ்பவர்
தாயினும் நல்லார் தரணி முழுதுக்குங்
காயினும் நல்லவர் காய்ந்தவர் தம்முளுந்
தீயினுந் தீயரத் தீவினை யாளர்க்கே`,
    transliteration: `kōyiliṉ uḷḷē kuṭiceytu vāḻpavar
tāyiṉum nallār taraṇi muḻutukkuṅ
kāyiṉum nallavar kāyntavar tammuḷun
tīyiṉun tīyarat tīviṉai yāḷarkkē`,
    english: `811: God's Attributes
He who takes His abode within that temple
Is kindlier than mother for world entire
Good is He, even when harsh,
He is within them too,
Whom He deals harsh;
For those of evil deeds,
He is deadlier than fire itself.`,
    elaborationTamil: `: உள்ளத்தைக் கோயிலாகக் கொண்டு சிவபெருமானுடன் குடியிருந்து வாழ்பவர். எல்லாவுலகங்களுக்கும் திருவருள் செய்வதில் தாயினும் நல்லவராவர். பிறர் இவர் மீது கோபம் கொண்டாலும் இவர் நன்மையே செய்வார். தீவினையாளர்களின் தீவினைத் துன்பம் போக நோய்க்கு மருந்துபோல் தீவினையாளர்களுக்கு துன்பத்தை கொடுத்து தீயினும் கொடியராவர்.`,
  },
  
  {
    id: 813, tantraId: 3, verseNumber: 812,
    tamil: `தீவினை யாளர்த்தஞ் சென்னியி லுள்ளவன்
பூவினை யாளர்த்தம் பொற்பதி யானவன்
பாவினை யாளர்த்தம் பாகவத் துள்ளவன்
மாவினை யாளர்த்தம் மதியிலுள் ளானே`,
    transliteration: `tīviṉai yāḷarttañ ceṉṉiyi luḷḷavaṉ
pūviṉai yāḷarttam poṟpati yāṉavaṉ
pāviṉai yāḷarttam pākavat tuḷḷavaṉ
māviṉai yāḷarttam matiyiluḷ ḷāṉē`,
    english: `812: God's Abodes
He is seated at the Forehead Center
Of those who perform yoga with Kundalini Fire;
He is in the Golden City
Of those who reach the Flower of cranial spaces;
He is in the imagination
Of those who sing of Him;
He is in the intelligence
Of those who perform deeds rare.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-812-Third-Tantra-18.-Yoga-of-Cosmic-Energy.mp3',
    elaborationTamil: `: தன்னை வழிபடும் நல்வினை இல்லாதவர்க்கும் அவர் தலையில் மறைந்தே இறைவன் இருக்கின்றான். தன்னை ஏதேனும் ஒரு வழியில் வெளிப்பக்கமாக வைத்து வழிபடுகின்றவர்களுக்கும் அவ்வழியாய் நின்று இறைவன் அருள் செய்கின்றான். தன்னை மானசீகமாய் ஆதாரங்களில் வைத்து பாவிக்கின்றவர்கட்கு அப்பாவனையிலே இறைவன் விளங்குகின்றான். யோகத்தைச் செய்கின்றவர்களுக்கு அவர்களது உணர்வு வடிவாய் இறைவன் நிற்கின்றான்.`,
  },
{
    id: 814, tantraId: 3, verseNumber: 813,
    tamil: `மதியி நெழுங்கதிர் போலப் பதினாறாய்ப்
பதிமனை நூறு நூற் றிருபத்து நாலாய்க்
கதிமனை யுள்ளே கணைகள் பரப்பி
எதிர்மலை யாமல் இருந்தனன் தானே`,
    transliteration: `matiyi neḻuṅkatir pōlap patiṉāṟāyp
patimaṉai nūṟu nūṟ ṟirupattu nālāyk
katimaṉai yuḷḷē kaṇaikaḷ parappi
etirmalai yāmal iruntaṉaṉ tāṉē`,
    english: `813: He Sat Supreme
He sat like the Moon
Beaming Kalas Sixteen;
In His Mansion that is body,
Art Kala worlds two hundred and twenty four;
And within that Divine Mansion shedding rays,
He sat Supreme in accord within.`,
    elaborationTamil: `: சந்திரனில் இருந்து வரும் கதிர்கள் பதினாறு. அது போல் கழுத்துப் பகுதி விசுத்திச் சக்கரத்தில் இருந்து வரும் கதிர்கள் பதினாறாய் இருந்தும், உடம்பில் அந்தந்த இடங்களின் அதிபதியாய் 224 கதிர்களாய் இருந்தும், இயங்கும் இல்லமாகிய உடம்பினுள் வினைகளாய் உள்ள பகைவர்களை அவ்யோகியர் எதிர்சென்று போர் புரியாதவாறு தனது அருளாற்றலாகிய கணைகளைப் பொழிந்து கொண்டு இருக்கின்றான்.`,
  },
  {
    id: 815, tantraId: 3, verseNumber: 814,
    tamil: `இருந்தனள் சத்தியு மக்கலை சூழ
இருந்தனள் கன்னியு மந்நடு வாக
இருந்தனள் மானேர் முகநில வார
இருந்தனள் தானும் அமுதம் பொழிந்தே`,
    transliteration: `iruntaṉaḷ cattiyu makkalai cūḻa
iruntaṉaḷ kaṉṉiyu mannaṭu vāka
iruntaṉaḷ māṉēr mukanila vāra
iruntaṉaḷ tāṉum amutam poḻintē`,
    english: `814: In Praise of Sakti
There sat Sakti
Kalas enveloping Her too;
There She sat, the Virgin in the midst;
There She sat, the Divine Fawn,
Her Visage shedding rays soft;
There She sat,
Herself too streaming ambrosia down.`,
    elaborationTamil: `: விசுத்திச்சக்கரத்தின் 16 கதிர்களின் நடுவே இறைவனின் சக்தி திருவருளோடு இருக்கின்றாள். மான்போல் விழிகளும் சந்திரன் போல் திருமுகமும் கொண்டு உடலில் இருந்து அமுதத்தைப் பொழிந்துகொண்டு அவற்றோடு தானும் இருக்கின்றாள்.`,
  },
  {
    id: 816, tantraId: 3, verseNumber: 815,
    tamil: `பொழிந்த இருவெள்ளி பொன்மண் ணடையில்
வழிந்துள் ளிருந்தது வான்முத லங்குக்
கழிந்தது போகாமற் காக்கவல் லார்க்குக்
கொழுந்தது வாகுண்- குணமது தனே`,
    transliteration: `poḻinta iruvauḷi poṉmaṇ ṇaṭaiyil
vaḻintuḷ ḷiruntatu vāṉmuta laṅkuk
kaḻintatu pōkāmaṟ kākkaval lārkkuk
koḻuntatu vākuṇ- kuṇamatu taṉē`,
    english: `815: Guard Nectar From Flowing Out
Within the Golden Regions of Cranium
The sparkling nectar flows in cascades silvery;
There it was inside,
In the astral sphere above;
They who can guard it from flowing out,
Will become eternal young;
That its blessing, for sure, for sure.`,
    elaborationEnglish: `Mantras 815 & 816 - From within the golden region of the cranium the sparkling nectar flows in silvery cascades. The yogi who can guard it from flowing out will remain eternally young. Inside the astral sphere from where the nectar flows is Sakti, the tender vine of goodness and haunting fragrance, in unity with Siva, the Treasure House of tattva jnana.`,
    elaborationTamil: `திருவருளால் உடம்பில் உள்ள வெண்ணிறமான அமிர்தம் பொன்நிறமான மண்போல் இருக்கும் மூலத்திடம் சேர்ந்தால் அங்குப் பெருகி வழிந்து நிறைந்திருந்து உடம்புக்கு உறுதி தரும். ஐம்பூதங்களால் ஆன உடம்பில் கழிவுகள் ஏற்பாடாது. இது போல் உடம்பை காக்க வல்லவர்களுக்கு உடம்பு இளமையுடன் கொழுந்து போல் என்றும் பொலிவுடன் இருக்கும்.`,
  },
  {
    id: 817, tantraId: 3, verseNumber: 816,
    tamil: `குணமது வாகிய கோமள வல்லி
மணமது வாக மகிழ்ந்தங் கிருக்கில்
தனமது வாகிய தத்துவ ஞானம்
இனமது வாக இருந்தனன் தானே`,
    transliteration: `kuṇamatu vākiya kōmaḷa valli
maṇamatu vāka makiḻntaṅ kirukkil
taṉamatu vākiya tattuva ñāṉam
iṉamatu vāka iruntaṉaṉ tāṉē`,
    english: `816: With Sakti Stood Siva
If Sakti that is unto a tender Vine of Goodness
Resides within in fragrant delight;
Then Lord that is a treasure-house of Tattva Jnana
Also stood in amity within.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-816-Third-Tantra-18.-Yoga-of-Cosmic-Energy.mp3',
    elaborationEnglish: `Then Lord that is a treasure-house of Tattva Jnana Also stood in amity within.`,
    elaborationTamil: `: ஒரு பொருளுக்கும் அப்பொருளின் குணத்திற்கும் உள்ள சம்பந்தம் பிரிக்க முடியாது. அது போல ஆன்மாவின் குணமாய் ஒன்றாய் இருக்கும் திருவருள் சக்தி யோகத்தால் வெளிப்பட்டு யோகியோடு என்றும் உடனாய் சிவனோடு சேர்ந்து இருக்கும். கேசரி யோகம் அளிக்கும் உண்மை ஞானத்தின் வழியாகச் சிவனும் அவனிடத்தினின்றும் நீங்காதிருப்பான்.`,
  },
  {
    id: 818, tantraId: 3, verseNumber: 817,
    tamil: `இருந்த பிராணனும் உள்ளே எழுமாம்
பரிந்தஇத் தண்டுடன் அண்டம் பரிய
விரிந்தஅப் பூவுடன் மேலெழ வைக்கின்
மலர்ந்தது மண்டலம் வாழலு மாமே`,
    transliteration: `irunta pirāṇaṉum uḷḷē eḻumām
parintait taṇṭuṭaṉ aṇṭam pariya
virintaap pūvuṭaṉ mēleḻa vaikkiṉ
malarntatu maṇṭalam vāḻalu māmē`,
    english: `817: Prana Reaches Moon's Region
Prana within if made to rise,
Through Sushumna cavity
To blossoming Lotus at cranial heights,
Then opened Moon's Mystic Region;
And there may you for long live.`,
    elaborationEnglish: `There in that moon’s region the yogi can sit for an indefinite, length of time.`,
    elaborationTamil: `: கேசரி யோகப் பயிற்சியால் மூலாதாரத்தில் உள்ள பிராணனை உள்ளே நடுநாடியின் வழியாக மேல் எழுப்பி தலை உச்சியில் உள்ள சஹஸ்ரதளத்தில் சேர்க்க ஆயிரம் இதழ் தாமரை நன்கு விரிந்து உடலுடன் நெடுங்காலம் வாழலாம்.`,
  },
  {
    id: 819, tantraId: 3, verseNumber: 818,
    tamil: `மண்டலத் துள்ளே மனவொட்டி யாணத்தைக்
கண்டகத் தங்கே கருதியே கீழ்க்கட்டிப்
பண்டகத் துள்ளே பகலே ஔியாகக்
குண்டலக் காதனுங் கூத்தொழிந் தானே`,
    transliteration: `maṇṭalat tuḷḷē maṉavoṭṭi yāṇattaik
kaṇṭakat taṅkē karutiyē kīḻkkaṭṭip
paṇṭakat tuḷḷē pakalē auiyākak
kuṇṭalak kātaṉuṅ kūttoḻin tāṉē`,
    english: `818: Practise Uddiyana Bandha
As Prana stand in Mystic Moon's Region
Practise Uddiyana Bandha,
And dam the course of downward Apana;
Then in dazzling brightness of sun
The Lord with Kundala in his ear lobe
Stands transfixed in their awareness,
His dance having ceased to a stop.`,
    elaborationEnglish: `Uddiyana is a mudra. It literally means ‘flying up or soaring;’ being so galled because the great bird, prana, tied to it, flies without being fatigued. The belly above the navel is passed backwards towards the spine. The portions above and below the navel should be drawn backwards towards the spine. Of all the bandhas, uddiyana is the best; for, by binding it firmly, liberation comes spontaneously. — Hatha Yoga Pradipika, pp.54-59. Compare Gheranda Samhita, pp.10-11; Siva Samhiia.

A Practice that aids in the successful performance of kechari mudra is ‘uddiyana bandha. In fact, this is a preliminary exercise to the performance of kechari mudra.`,
    elaborationTamil: `: ஞான எண்ணத்துள் மனம் ஒடுங்கும் நிலை உள்ளதை உணர்ந்து கேசரி யோகத்தின் மூலம் கீழே செல்ல விடாமல் வைத்தால் உடம்பில் பகலில் உள்ள ஒளி போல குண்டலம் அணிந்த சிவபெருமான் தன் ஐந்தொழில்களை விட்டு அசைவின்றி அங்கே இருப்பான்.`,
  },
  {
    id: 820, tantraId: 3, verseNumber: 819,
    tamil: `ஒழிகின்ற வாயுவும் உள்ளே அமருங்
கழிகின்ற வாயுவுங் காக்கலு மாகும்
வழிகின்ற காலத்து வட்டக் கழலைப்
பழிகின்ற காலத்துப் பையகற் றீரே`,
    transliteration: `oḻikiṉṟa vāyuvum uḷḷē amaruṅ
kaḻikiṉṟa vāyuvuṅ kākkalu mākum
vaḻikiṉṟa kālattu vaṭṭak kaḻalaip
paḻikiṉṟa kālattup paiyakaṟ ṟīrē`,
    english: `819: When to do Uddiyana Bandha
The exhaling breath will inside retained be;
The retained breath will from escape prevented be;
In due time,
From the Moon's Region starts ambrosial flow;
When it ceases,
Undo the Uddiyana Bandha.`,
    elaborationEnglish: `By drawing in the mulasthana (anus), uddiyana bandha should be performed. The flow of the air should be directed to the sushumna by closing the ida and the pingala. The prana then becomes calm and latent by this means. — Vide Hatha Yoga Pradipika, pp.69-77.`,
    elaborationTamil: `: வெளியில் செல்லும் மூச்சுக்காற்றை கேசரி யோகத்தின் மூலம் உள்ளே வைத்தால் வெளியே வராமல் உடம்பில் இருக்கின்ற அந்த மூச்சுக்காற்று உடம்பில் இருந்து உயிர் வெளியே செல்லாமல் காக்கும். வரும் காலத்தில் குண்டலி சக்தியின் தலையில் உள்ள பிரமரந்திரத்தை அடைய கற்றுக் கொள்வீர்கள்.`,
  },
  {
    id: 821, tantraId: 3, verseNumber: 820,
    tamil: `பையினி நுள்ளே படிக்கத வொன்றிடின்
மெய்யினி நுளே விளங்கும் ஒளியதாங்
கையினுள் வாயுக் கதித்தங் கெழுந்திடின்
மையணி கோயில் மணிவிளக் காமே`,
    transliteration: `paiyiṉi nuḷḷē paṭikkata voṉṟiṭiṉ
meyyiṉi nūḷē viḷaṅkum auiyatāṅ
kaiyiṉuḷ vāyuk katittaṅ keḻuntiṭiṉ
maiyaṇi kōyil maṇiviḷak kāmē`,
    english: `820: Open a Wicket Gate Within and See Light
Within the body-bag
If you but open a wicket gate,
The Lightwill shine inside;
If breath that is controlled spurts there upwards
Then will this dark body
As a temple lamp lustrous bejewelled be.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-820-Third-Tantra-18.-Yoga-of-Cosmic-Energy.mp3',
    elaborationEnglish: `It is after this that the yogi can open the ‘‘wicket gate’’ (fourth door) above and Jey the prana slowly stream upwards to sahasrara.`,
    elaborationTamil: `: உடலில் உள்ள மூலாதாரக் கதவு குதம் (எருவாய்) ஆகும். அதை கேசரி யோகத்தின் மூலம் இருகால்களால் அணைத்து சுருக்கினால் அபானன் அமுக்கப்படும். அபானன் தன் திசையை மாற்றிக் கொண்டு மேல் நோக்கிப் போகும். உயிர்ப்பை மாற்றி மேலே செல்லும் போது உடல் ஒளியுடன் விளங்கும். அபானன் நாடியினுள் மேலே எழும் போது மலங்கள் நிறைந்த உயிர் ஒளி உடையதாக இருக்கும்.`,
  },
  {
    id: 822, tantraId: 3, verseNumber: 821,
    tamil: `விளங்கிடும் வாயுவை மேலெழ உன்னி
நலங்கிடுங் கண்டத்து நாபியி நுள்ளே
வணங்கிடு மண்டலம் வாய்த்திடக் கும்பிச்
சுணங்கிட நின்றவை சொல்லலு மாமே`,
    transliteration: `viḷaṅkiṭum vāyuvai mēleḻa uṉṉi
nalaṅkiṭuṅ kaṇṭattu nāpiyi nuḷḷē
vaṇaṅkiṭu maṇṭalam vāyttiṭak kumpic
cuṇaṅkiṭa niṉṟavai collalu māmē`,
    english: `821: Inexplicable Experiences of Kecari Yoga
Course Prana upward
And retain breath through Kumbhaka
In the mystic regions of Fire and Sun
Around navel and throat;
And there be fixed in thought
What stood there, how possible to say?`,
    elaborationEnglish: `In doing so the breath should still be retained in kumbhaka, in the region of fire and sun around the navel and throat, and thought should be transfixed there. The experience that follows is indeed indescribable.`,
    elaborationTamil: `: உடலின் அடிவயிற்றில் தொப்புளுக்கு பின்புறம் இருக்கின்ற மூச்சுக்காற்றை மேல்நோக்கி செலுத்தி முகவாயைக் கழுத்தோடு சேர்த்து ஜாலந்திர பந்தம் என்கிற முறையில் சுருக்கிக் கொண்டு யோகத்தில் எண்ணங்களை நெற்றிக்கு நடுவில் வைத்து அமர்ந்திருந்தால் தலை உச்சியிலிருந்து சுரக்கும் அமிர்தமானது அடி வயிற்றுக்கு சென்று அங்கிருக்கும் நெருப்பில் பொசுங்கிப் போகாமல் நெற்றியிலேயே நிலைத்து நிற்கும். அவ்வாறு அமிர்தம் நின்றால் கிடைக்கும் பெரும் பயன்களைச் சொல்லவும் முடியாது.`,
  },
  {
    id: 823, tantraId: 3, verseNumber: 822,
    tamil: `சொல்லலு மாயிடு மாகத்து வாயுவுஞ்
சொல்லலு மாகு மண்ணீர்க் கடினமுஞ்
சொல்லலு மாகும் இவையஞ்சுங் கூடிடிற்
சொல்லலு மாந்தூர தெரிசனந் தானே`,
    transliteration: `collalu māyiṭu mākattu vāyuvuñ
collalu māku maṇṇīrk kaṭiṉamuñ
collalu mākum ivaiyañcuṅ kūṭiṭiṟ
collalu māntūra tericaṉan tāṉē`,
    english: `822: Distant Vision of Five-Element Combination
Well may described be air in the body
Well may described be earth and water
Well may described be all these elements five;
But when all these together combine,
Well may then be
The power of Vision in cranium distant.`,
    elaborationTamil: `பாடல் #821 இல் உள்ளபடி நெற்றியில் அமிர்தம் நிலைத்து நின்றால் கிடைக்கும் பயன்களைச் சொல்லப்போனால் பஞ்ச பூதங்களான ஆகாயம், காற்று, நிலம், நீர், நெருப்பு ஆகிய ஐந்தும் தமது உடலுக்குள்ளேயே அடங்கி இருப்பதை கண்டு கொண்ட யோகியர்கள் அண்டசராசரங்களில் பஞ்ச பூதங்களாக கலந்து நிற்கும் இறை சக்தியே தமக்குள்ளும் பஞ்ச பூதங்களாகக் கலந்து இருக்கின்றது என்பதை உணர்வார்கள். அந்த இறை சக்தியைத் தமக்குள்ளேயே தரிசிக்க முடியும் என்பதையும் சொல்லலாம்.`,
  },
  {
    id: 824, tantraId: 3, verseNumber: 823,
    tamil: `தூர தரிசனஞ் சொல்லுவன் காணலாங்
காராருங் கண்ணி கடைன்யான முட்பெய்தி
ஏராருந் தீபத் தெழிற்சிந்தை வைத்திடிற்
பாரா ருலகம் பகன்முன்ன தாமே`,
    transliteration: `tūra taricaṉañ colluvaṉ kāṇalāṅ
kārāruṅ kaṇṇi kaṭaiṉyāṉa muṭpeyti
ērārun tīpat teḻiṟcintai vaittiṭiṟ
pārā rulakam pakaṉmuṉṉa tāmē`,
    english: `823: Nature of Distant Divine Vision
That Distant Vision I shall here describe:
Having attained Grace of Sakti of collyruim eyes
If thought is centered on the Divine Light that is Lord
Then may you vision worlds all
As in day-light bright.`,
    elaborationEnglish: `Mantras 822 & 823 - There, the combined vision of the five elements results in the distant vision. This distant vision consists in attaining the grace of Sakti in the first instance, and then when thought is centered deeper, the divine light of the Lord appears; and all worlds too appear as in bright daylight.`,
    elaborationTamil: `பாடல் #822 இல் உள்ளபடி அண்ட சராசரங்கள் அனைத்திலும் கலந்திருக்கும் இறை சக்தியைத் தமக்குள் கலந்திருக்கும் பஞ்ச பூதங்களாகக் கண்டு தரிசிக்க முடிந்த யோகியர்கள் ஞானக் கண்ணைப் பெற்று தமக்குள் இருக்கும் இறை சக்தியை தீபத்தில் ஏற்றி வைத்த ஜோதியைப் போல ஒளி உருவமாகக் கண்டு தரிசித்து தமது எண்ணங்களை அதன் மேலேயே வைத்து தியானித்திருந்தால் அண்டசராசரங்கள் அனைத்தையும் தாம் உட்கார்ந்த இடத்தில் இருந்தே முழு சூரிய வெளிச்சத்தில் காணும் பகல் காட்சி போல தெள்ளத் தெளிவாகக் காணலாம்.`,
  },
  {
    id: 825, tantraId: 3, verseNumber: 824,
    tamil: `முன்னெழு நாபிக்கு முந்நால் விரற்கீழே
பன்னெழு வேதப் பகலொளி யுண்டென்னும்
நன்னெழு நாதத்து நற்றீபம் வைத்திடத்
தன்னெழு கோயில் தலைவனு மாமே`,
    transliteration: `muṉṉeḻu nāpikku munnāl viraṟkīḻē
paṉṉeḻu vētap pakaloḷi yuṇṭeṉṉum
naṉṉeḻu nātattu naṟṟīpam vaittiṭat
taṉṉeḻu kōyil talaivaṉu māmē`,
    english: `824: Reach Nada Through Kundalini
Twelve finger measure below the navel
The light bright as day (Kundalini)
Thus say Vedas;
If with that Light
The Nada Lamp above is lighted
You become the Master
Of Mansion that rises within you.`,
    elaborationTamil: `: உடலில் கொப்புழில் இருந்து பன்னிரண்டு விரல் கீழே வேதத்தில் கூறியது போல் பகல் போல் ஓளி இருக்கிறது. கேசரியோகத்தின் மூலம் அந்த ஓளிப் பிழம்பிலிருந்து வெளிப்பட்டு எழுந்து வரும் ஓங்காரத்தை இடைவிடாது சிந்தித்தால் சிவபெருமான் எழுந்தருளியிருக்கும் திருக்கோயிலாக இவ்வுடல் அமையும்.`,
  },
  {
    id: 826, tantraId: 3, verseNumber: 825,
    tamil: `பூசு வனவெல்லாம் பூசிப் புலர்த்திய
வாச நறுங்குழல் மாலையுஞ் சாத்திக்
காயக் குழலி கலவி யொடுங்கலந்
தூசித் துளையுறத் தூங்காது போகமே`,
    transliteration: `pūcu vaṉavellām pūcip pularttiya
vāca naṟuṅkuḻal mālaiyuñ cāttik
kāyak kuḻali kalavi yoṭuṅkalan
tūcit tuḷaiyuṟat tūṅkātu pōkamē`,
    english: `825: Pleasures of Sex Union Will Abide
If Breath Control is Properly Practiced
Anointing her body with unguents diverse
Bedecking her tresses with flowers fragrant
Do you enjoy the damsel in passion's union;
If you but know how to shoot
Prana breath through the Spinal Cavity
Your enjoyment never ceases.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-825-Third-Tantra-19.-Yoga-with-Sexual-Partner.mp3',
    elaborationTamil: `உடம்பில் பூசுவதற்கு ஏதுவான வாசனை திரவியங்களையெல்லாம் பூசிக்கொண்டு நீராடி காயவைத்த நறுமணம் கமழும் கூந்தலில் வாசனையுள்ள மலர்களையும் மாலையாகச் சூடிக்கொண்டு மனதை மயக்குகின்ற மங்கையோடு கலவியில் ஒன்றாகக் கலந்து இருக்கின்ற போதும் ஊசியில் நூல் கோர்ப்பது போல நெற்றிக்கு நடுவில் உள்ள சுழுமுனை நாடியின் உச்சித்துளை வழியே மூச்சுக்காற்றை செலுத்திக் கொண்டே இருக்கின்ற யோகியர்களுக்கு போகம் எப்போதும் அழியாது. குறிப்பு: ஆணும் பெண்ணும் ஒருவருடன் ஒருவர் போகத்தில் இருக்கும் போது அதை யோகமாக எப்படி மாற்றுவது என்பதை விளக்குவதே பரியாங்க யோகமாகும்.`,
  },
  {
    id: 827, tantraId: 3, verseNumber: 826,
    tamil: `போகத்தை யுன்னவே போகாது வாயுவு
மோகத்தை வெள்ளியு மீளும் வியாழத்தில்
சூதொத்த மென்முலை யாளுநற் சூதனுந்
தாதிற் குழைந்து தலைகண்ட வாறே`,
    transliteration: `pōkattai yuṉṉavē pōkātu vāyuvu
mōkattai vauḷiyu mīḷum viyāḻattil
cūtotta meṉmulai yāḷunaṟ cūtaṉun
tātiṟ kuḻaintu talaikaṇṭa vāṟē`,
    english: `826: If Breath is Controlled Delicious Enjoyment
For Partners in Sex Union Results
When they seek enjoyment
The breath stands still;
The full breasted damsel and the goodly man
Stand in union exalted;
As liquid silver and gold
Their passion's emissions
In rapture commingles.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-826-Third-Tantra-19.-Yoga-with-Sexual-Partner.mp3',
    elaborationTamil: `: பாடல்#825 ல் கூறியபடி தலை உச்சியில் சகஸ்ரதளத்தில் பேரறிவு பொருந்திய சிவனை எண்ணியபடி ஓர் ஆடவன் போகத்தில் ஈடுபட்டால் அவனது காம வாயு விரைவாக அதன் வேலையை செய்யாமல் நீரின் தன்மை கொண்ட அவன் சுக்கிலம் பெண்ணின் சுரோணிதத்தில் கலக்காது. மயக்கும் சூதாடும் கருவியைப் போன்ற ஸ்தனங்கள் உடைய பெண்ணும் உடல் என்னும் தேரைச் செலுத்தும் ஆடவனும் செய்த இந்தக் கூட்டுறவால் வெளிப்பட்ட சுக்கிலமும் சுரோணிதமும் ஒளியாய் மாறித் தலையில் சென்று தன் தலையில் நாதமாகிய சிவனும் ஒலியான சக்தியும் விளங்குவதைக் காண்பான்.`,
  },
  {
    id: 828, tantraId: 3, verseNumber: 827,
    tamil: `கண்டனுங் கண்டியுங் காதல்செய் யோகத்து
மாண்டலங் கொண்டிரு பாலும் வௌிநிற்கும்
வண்டியை மேற்கொண்டு வானீர் உருட்டிடத்
தண்டொரு காலுந் தளராது அங்கமே`,
    transliteration: `kaṇṭaṉuṅ kaṇṭiyuṅ kātalcey yōkattu
māṇṭalaṅ koṇṭiru pālum vauiniṟkum
vaṇṭiyai mēṟkoṇṭu vāṉīr uruṭṭiṭat
taṇṭoru kālun taḷarātu aṅkamē`,
    english: `827: Duration of Enjoyment Lengthens
If Breath is Controlled
In the copulatory yoga that is practised
By the hero and the heroine
Upward they drive the coach of breath
That has its wheels in regions right and left;
There they collect the waters of the heaven
And never the organs tiring know.`,
    elaborationEnglish: `In that conjugal yoga thus practised, the yogi drives the two-wheeled coach of breath upward. His organ knows no weariness, and he collects the “’waters of the heaven.”`,
    elaborationTamil: `: பாடல்# 801 ல் உள்ள படி ஒரு தலைவனும் தலைவியும் யோகத்தில் போகம் செய்யும் போது வலது இடது நாசிகளின் வழியே ஏறி இறங்கும் மூச்சுக்காற்றின் வழியே மேலே சென்று தலையின் மேலே சஸ்ரதளத்தில் உள்ள ஒலி ஓளிகளை கைவருமாறு செய்தால் முதுகுத்தண்டு எப்போதும் தளராது. தளராததாகவே உடலுக்கும் அழிவில்லை.`,
  },
  {
    id: 829, tantraId: 3, verseNumber: 828,
    tamil: `அங்கப் புணர்ச்சியு மாகின்ற தத்துவ
மங்கத்தில் விந்து வருகின்ற போகத்துப்
பங்கப் படாமற் பரிகரித் துத்தம்மைத்
தங்கிக் கொடுக்கத் தலைவனு மாமே`,
    transliteration: `aṅkap puṇarcciyu mākiṉṟa tattuva
maṅkattil vintu varukiṉṟa pōkattup
paṅkap paṭāmaṟ parikarit tuttammait
taṅkik koṭukkat talaivaṉu māmē`,
    english: `828: Restraint of Semen Flow Through Breath Control
This the meaning of that union;
When in the sex act semen flows
The yogi lets it not;
But checks it
And attains within;
And a Master he then becomes.`,
    elaborationTamil: `: போகத்தின் போது உடலிலிருந்து நீரின் தன்மை கொண்ட சுக்கிலம் வெளியே செல்லும். அவ்வாறு செல்ல விடாமல் யோகத்தால் பாதுகாத்து வெற்றி கொண்டவன் யோகிகளுக்குத் தலைவனாய் இருப்பான்.`,
  },
  {
    id: 830, tantraId: 3, verseNumber: 829,
    tamil: `தலைவனு மாயிடுந் தன்வழி ஞானந்
தலைவனு மாயிடுந் தன்வழி போகந்
தலைவனு மாயிடுந் தன்வழி யுள்ளே
தலைவனு மாயிடுந் தன்வழி அஞ்சே`,
    transliteration: `talaivaṉu māyiṭun taṉvaḻi ñāṉan
talaivaṉu māyiṭun taṉvaḻi pōkaṉ
talaivaṉu māyiṭun taṉvaḻi yuḷḷē
talaivaṉu māyiṭun taṉvaḻi añcē`,
    english: `829: Effect of Restraint of Semen Flow
He becomes master of Jnana all
He becomes master of enjoyment all
He becomes master of himself
He becomes master of senses five.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-829-Third-Tantra-19.-Yoga-with-Sexual-Partner.mp3',
    elaborationEnglish: `Mantras 828 & 829 - This then is the meaning of that mudra; in the conjugal act the yogi lets not the semen flow, but checks it and holds it within. Verily he becomes the master. He becomes master of jnana. He becomes master of enjoyment. He becomes master of himself. He becomes master of the five senses.`,
    elaborationTamil: `: பாடல் #828 ல் உள்ளபடி வெற்றி பெற்ற தலைவன் தன் ஆன்மாவை அறிந்தவன் ஆவான். அவனைச் சிவயோகம் தானே வந்தடையும். தன்னைத் தானே வசப்படுத்தி ஆளும் திறமை அவனுக்கு வரும். ஐந்து பூதங்களும் அவன் வசமாகி அவன் விருப்பப்படி நடக்கும்.`,
  },
  {
    id: 831, tantraId: 3, verseNumber: 830,
    tamil: `அஞ்சு கடிகைமேல் ஆறாங் கடிகையில்
துஞ்சுவ தொன்றத் துணைவி துணைவன்பால்
நெஞ்சு நிறைந்தது வாய்கொளா தென்றது
பஞ்ச கடிகை பரியங்க யோகமே`,
    transliteration: `añcu kaṭikaimēl āṟāṅ kaṭikaiyil
tuñcuva toṉṟat tuṇaivi tuṇaivaṉpāl
neñcu niṟaintatu vāykoḷā teṉṟatu
pañca kaṭikai pariyaṅka yōkamē`,
    english: `830: Sex Union Through the Pariyanga Lasts Five Ghatikas
and is Bliss
This is Pariyanga Yoga
That lasts five ghatikas;
Beyond in the sixth
The damsel sleeps in the arms of lover
In union blissful
That fills the heart
And passes description.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-830-Third-Tantra-19.-Yoga-with-Sexual-Partner.mp3',
    elaborationEnglish: `The union lasts for five naligas (two and half hours). Then in the sixth naliga the damsel goes to sleep in the arms of the yogi lover, in blissful union that "fills" her heart in an experience that defies description.`,
    elaborationTamil: `: பரியங்க யோகம் ஐந்து நாழிகைப் பொழுது மட்டுமே செய்ய வேண்டும். அதற்கு மேலும் பயின்றால் ஆறாவது நாழிகையில் துணைவி துணைவன்பால் கொள்ளும் போகம் அதிகமாகி நெஞ்சம் பூரித்து சிற்றின்பத்தில் ஆழ்ந்துவிடுவார். ஐந்து நாழிகைப் பொழுது போகத்தில் யோகம் செய்வது மட்டுமே பரியாங்க யோகமாகும்.`,
  },
  {
    id: 832, tantraId: 3, verseNumber: 831,
    tamil: `பரியங்க யோகத்துப் பஞ்ச கடிகை
அரியஇவ் வியோகம் அடைந்தவர்க் கல்லது
சரிவளை முன்கைச்சி சந்தனக் கொங்கை
உருவித் தழுவ ஒருவற்கொண் ணாதே`,
    transliteration: `pariyaṅka yōkattup pañca kaṭikai
ariyaiv viyōkam aṭaintavark kallatu
carivaḷai muṉkaicci cantaṉak koṅkai
uruvit taḻuva oruvaṟkoṇ ṇātē`,
    english: `831: Successful Practitioners Alone Can Resort to Pariyanga
Yoga
Unless it be,
He had in success practised
The Pariyanga yoga
Of five ghatika length
No yogi shall
A woman embrace.`,
    elaborationEnglish: `Mantras 831 & 832 - Let no yogi embrace a woman unless he has successfully practiced this technique of the five naliga duration. If it is asked who is the yogi that had accomplished this audacious practice, the answer is, "Lord Siva that wears the heavenly Ganga on his matted locks." Siva, the Supreme Yogi, embraced Sakti of ambrosial-sweet voice, thinking and not thinking of the act.`,
    elaborationTamil: `ஐந்து நாழிகைகள் மன உறுதியோடு இறைவனை நினைத்துக் கொண்டே மிகவும் கடினமான பரியங்க யோகத்தை செய்தவர்களுக்கு மட்டுமே இறைவனை தமக்குள் உணரும் பெரும்பேறு கிடைக்கும். மற்றவர்கள் விரக தாபத்தில் கையிலிருக்கும் வளையல்கள் நழுவும் அளவிற்கு மெலிந்த தேகத்துடன் சந்தனம் போன்ற வாசனையும் மிருதுவும் உடைய கொங்கைகளை கொண்ட மாதர்களைத் தழுவிப் பெறும் சிற்றின்பத்திலேயே மூழ்கி இருப்பார்கள்.`,
  },
  {
    id: 833, tantraId: 3, verseNumber: 832,
    tamil: `ஒண்ணாத யோகத்தை உற்றவ ராரென்னில்
விண்ணந்த கங்கை விரிசடை வைத்தவன்
பண்ணார் அமுதினைப் பஞ்ச கடிகையில்
எண்ணா மெனஎண்ணி இருந்தான் இருந்தே`,
    transliteration: `oṇṇāta yōkattai uṟṟava rāreṉṉil
viṇṇanta kaṅkai viricaṭai vaittavaṉ
paṇṇār amutiṉaip pañca kaṭikaiyil
eṇṇā meṉaeṇṇi iruntāṉ iruntē`,
    english: `832: Lord Siva Practised Pariyanga Yoga
Who may you ask,
Is He that achieved this audacious Yoga;
The lord is He that wears heavenly Ganga on His matted lock;
For ghatika* five
He embraced Sakti of speech ambrosial sweetness
Thinking and thinking not of the act performed.`,
    elaborationEnglish: `He embraced Sakti of speech ambrosiai sweetness Thinking and thinking not of the act performed.`,
    elaborationTamil: `அவ்வளவு எளிதில் செய்துவிட முடியாத மிகவும் கடினமான பரியங்க யோகத்தை செய்து இறைவனைத் தமக்குள் உணர்ந்தவர்கள் யார் என்றால் விண்ணுலகிலிருந்து வலிமையோடு பொழியும் கங்கையைத் தமது தலையின் சடையில் தாங்கிக் கொண்டு நஞ்சாக இருந்தாலும் அதை உலக நன்மைக்காக ஏற்றுக்கொள்பவனாகிய இறைவனைப் போன்றவர்கள். ஏனெனில் அவர்கள் இனிக்கின்ற சிற்றின்பம் வேண்டாமென்று ஐந்து நாழிகைக்குள் இறைவனை மட்டுமே நினைத்து யோகத்தில் இருந்தவர்கள்.`,
  },
  {
    id: 834, tantraId: 3, verseNumber: 833,
    tamil: `ஏய்ந்த பிராயம் இருபது முப்பதும்
வாய்ந்த குழலிக்கு மன்னர்க்கு மானந்தம்
வாய்ந்த குழலியோ டைந்து மலர்ந்திடச்
சோர்ந்தன சித்தமுன்ய் சோர்வில்லை வெள்ளிக்கே`,
    transliteration: `ēynta pirāyam irupatu muppatum
vāynta kuḻalikku maṉṉarkku māṉantam
vāynta kuḻaliyō ṭaintu malarntiṭac
cōrntaṉa cittamuṉy cōrvillai vauḷikkē`,
    english: `833: The Age of the Couple for Pariyanga Yoga
For practise of this yoga,
Twenty the age apt for damsel
And thirty for lover;
Then does high rapture ensue;
The five senses of woman desert her,
Her mind exhausted becomes,
When she climax reaches;
But no weariness the man knows
Neither does his silvery emission flow.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-833-Third-Tantra-19.-Yoga-with-Sexual-Partner.mp3',
    elaborationEnglish: `For practise of this yoga the apt age for the woman is twenty, and for the yogi, thirty. Then high rapture ensures. The five senses of the woman desert her. She swoons and reaches the climax. But the yogi knows no weariness, nor does his silvery fluid get ejected.`,
    elaborationTamil: `: பரியங்க யோகம் செய்வதற்கு ஏற்ற வயது பெண்ணுக்கு இருபதும் ஆணுக்கு முப்பதும் ஆகும். இந்த யோகம் கைவந்தவர்கள் இருவருக்கும் ஆனந்தம் உண்டாகும். பெண்ணின் ஐம் பொறிகளும் இன்பத்தில் மலர்ந்திடும். ஆணுக்கு சுக்கில நீக்கம் ஏற்படாது.`,
  },
  {
    id: 835, tantraId: 3, verseNumber: 834,
    tamil: `வெள்ளி யுருகிப் பொன்வழி ஓடாமே
கள்ளத்தட் டானார் கரியிட்டு மூடினார்
கொள்ளி பறியக் குழல்வழி யேசென்று
வள்ளியுண் ணாவில் அடக்கிவைத் தாரே`,
    transliteration: `vauḷi yurukip poṉvaḻi ōṭāmē
kaḷḷattaṭ ṭāṉār kariyiṭṭu mūṭiṉār
koḷḷi paṟiyak kuḻalvaḻi yēceṉṟu
vaḷḷiyuṇ ṇāvil aṭakkivait tārē`,
    english: `834: Only Those Who Have Practised Kecari Can Resort to
Pariyanga
Lest the silvery liquid into the golden flow,
The artful goldsmith (practitioner) covered it up with yogic breath
The sparks (Kundalini) that flew travelled up by the way of Spinal tube
There above,
He contained them with tongue's tip (Kecari).`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-834-Third-Tantra-19.-Yoga-with-Sexual-Partner.mp3',
    elaborationEnglish: `Only those who have practised kechari mudra successfully can take to pariyanga yoga. The yogi is an artful goldsmith. He does not allow the liquid silver semen to run into the liquid gold (sronita). As the goldsmith covers the melting metal with carbon, the yogi covers up the seminal flow with his breath control. The sparks that fly in this alchemic process by way of the spinal tube reach above; there it is contained by the tongue’s tip or kechari mudra.`,
    elaborationTamil: `தங்கத்தில் நகை செய்யும் பொற்கொல்லர்கள் திருட்டுத்தனமாக வெள்ளியில் உட்புற பாகங்களை செய்து அது உருகி தங்கத்தோடு கலந்து விடாமல் இருக்க கரியினால் மூடிப் புடம்போட்டு அதை நெருப்பில் சுத்தப்படுத்தி அதன் மேலே தங்கத்தை வார்த்து நகை செய்து தங்கத்தை மிச்சம் பிடிப்பார்கள். அதுபோலவே பரியங்க யோகம் செய்வதில் திறமையான யோகியர்கள் தனது துணையுடன் போகத்தில் இருக்கும் போது துணையை ஏமாற்றி சுக்கிலத்தை வெளியேற்றி விடாமல் இறைவனின் மேல் நாட்டம் வைத்து சுக்கிலம் வெளியேறாமல் தடுத்து அடி வயிற்றின் நெருப்பினால் தமது சுக்கிலத்தை சுத்தப்படுத்தி சுழுமுனை நாடி வழியே மேலேற்றிச் சென்று சகஸ்ரதளத்தில் சேமிக்கிறார்கள். சகஸ்ரதளத்தில் சேர்க்கப்பட்ட சுக்கிலம் அமிர்தமாக மாறி உள் நாக்கில் வந்து விழும்போது அது மறுபடியும் வயிற்றில் சென்று நெருப்பினால் பொசுங்கிப் போகாமல் அந்த அமிர்தத்தை யோக முறையில் தங்களது உள் நாக்கிலேயே அடக்கி வைத்து விடுகின்றார்கள்.`,
  },
  {
    id: 836, tantraId: 3, verseNumber: 835,
    tamil: `வைத்த இருவருந் தம்மின் மகிழ்ந்துடன்
சித்தங் கலங்காது செய்கின்ற ஆனந்தம்
பத்து வகைக்கும் பதினெண் கணத்துக்கும்
வித்தக னாய்நிற்கும் வெங்கதி ரோனே`,
    transliteration: `vaitta iruvarun tammiṉ makiḻntuṭaṉ
cittaṅ kalaṅkātu ceykiṉṟa āṉantam
pattu vakaikkum patiṉeṇ kaṇattukkum
vittaka ṉāyniṟkum veṅkati rōṉē`,
    english: `835: Pariyanga Yogi is Exalted
The Yogi who is in ecstatic joy
Unexcited performs this yoga with woman
Becomes radiant like the sun,
An acknowledged master in directions ten,
And of Ganas of groups eighteen.`,
    elaborationEnglish: `If the yogi, though experiencing ecstatic joy, performs this mudra unexcited, he becomes radiant as the sun, an acknowledged master in ten directions and head of the eighteen Gana hordes.`,
    elaborationTamil: `: பரியங்க யோகப் பயிற்சி கைவந்த இருவரும் மகிழ்ச்சியுடன் சிறிதும் எண்ணம் கலங்காமல் இறை எண்ணத்துடன் பரியங்க யோகத்தை செய்தால் அவர்கள் பத்து திசைகளுக்கும் தலைவனான பதினெட்டு வகைத் தேவர்களுக்கும் தலைவனான செங்கதிரவன் போல் இருப்பார்கள்.`,
  },
  {
    id: 837, tantraId: 3, verseNumber: 836,
    tamil: `வெங்கதி ருக்குஞ் சனிக்கும் இடைநின்ற
நங்கையைப் புல்லிய நம்பிக்கோ ரானந்தந்
தங்களிற் பொன்னிடை வெள்ளிதா ழாமுனந்
தங்களிற் செவ்வாய் புதைத்திருந் தாரே`,
    transliteration: `veṅkati rukkuñ caṉikkum iṭainiṉṟa
naṅkaiyaip pulliya nampikkō rāṉantan
taṅkaḷiṟ poṉṉiṭai vauḷitā ḻāmuṉan
taṅkaḷiṟ cevvāy putaittirun tārē`,
    english: `836: Pariyanga Yogi Practiced With Kecari Yoga Also
Espousing Wisdom that is denoted by Budha*, (Mercury)
Who stands middle of sun and saturn
The youthful Yogi who embraced the damsel
Knew joy infinite;
Lest the male silvery liquid flow not
Ahead of female golden one
He had his red mouth buried in the Mystic Moon.
(Note: This Budha spelling is the author's dub on Buddha)`,
    elaborationEnglish: `While the yogi practises it, he does not allow the silvery liquic to flow. He should ‘’bury his red mouth in the moon” (practise kechari yoga). 1)A play on the word ‘budha,” Wednesday is in the middle of the week from Sunday to Saturday.

2)He practised kechari yoga simultaneously.

There is much esoterism in these verses. The names of the planets are used in a double sense.`,
    elaborationTamil: `: இருளும் வெளிச்சமும் கலந்து இருக்கும் அதிகாலை நேரத்தில் துணைவனும் துணைவியும் போகத்தின் போது சிற்றின்பத்தில் இருந்தாலும் துணைவன் தனது சுக்கிலத்தையும் துணைவி தனது சுரோணிதத்தையும் வெளிப்படுத்தாமலேல்யே மனதை ஒருமைப்படுத்தி இறையருளில் மட்டுமே மனதைப் பதித்து வைத்து செய்வது பரியங்க யோகமாகும்.`,
  },
  {
    id: 838, tantraId: 3, verseNumber: 837,
    tamil: `திருத்திப் புதனைத் திருத்தல்செய் வார்க்குக்
கருத்தழ காலே கலந்தங் கிருக்கில்
வருத்தமு மில்லையா மங்கை பங்கற்குந்
துருத்தியுள் வெள்ளியஞ் சோரா தெழுமே`,
    transliteration: `tiruttip putaṉait tiruttalcey vārkkuk
karuttaḻa kālē kalantaṅ kirukkil
varuttamu millaiyā maṅkai paṅkaṟkun
turuttiyuḷ vauḷiyañ cōrā teḻumē`,
    english: `837: Pariyanga Yoga is Yogic Wisdom That Retains the Semen
They who perfect wisdom
And embrace woman in wisdom's beauty
Will know grief none,
Though by woman's side he be;
The liquid silver remains unspent
And flows not into the vaginal bag of woman.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-837-Third-Tantra-19.-Yoga-with-Sexual-Partner.mp3',
    elaborationEnglish: `He, who, in perfect wisdom, embraces a woman knows no grief. Although he is by the woman's side, the silvery semen does not flow into the vaginal track.`,
    elaborationTamil: `துணைவனும் துணைவியும் போகத்தில் இருக்கும்போது அந்த இன்பத்திலேயே மூழ்கிவிடாமல் அறிவை மாற்றி இறைவன் மேல் வைத்து மனத்தைத் தூய்மையுடன் எண்ணிப் பார்க்கும் சிறந்த அழகோடு பரியங்க யோகம் செய்பவர்களுக்கு உலகியல் துன்பம் உண்டாகாது. இறைவியைத் தம்மில் பாதியாகக் கொண்ட இறைவனது அருளால் சுக்கிலம் வெளியே வந்து விழாமல் உள்ளுக்குள்ளேயே மேல்நோக்கி எழுந்து செல்லும்.`,
  },
  {
    id: 839, tantraId: 3, verseNumber: 838,
    tamil: `எழுகின்ற தீயை முன்னே கொண்டு சென்றிட்டால்
மெழுகுரு கும்பரி செய்திடும் மெய்யே
உழுகின்ற தில்லை ஔியை அறிந்தபின்
விழுகின்ற தில்லை வௌியறி வார்க்கே`,
    transliteration: `eḻukiṉṟa tīyai muṉṉē koṇṭu ceṉṟiṭṭāl
meḻukuru kumpari ceytiṭum meyyē
uḻukiṉṟa tillai auiyai aṟintapiṉ
viḻukiṉṟa tillai vauiyaṟi vārkkē`,
    english: `838: Freedom From Sexual Union is Attained by Pariyanga
Yoga
This body that melts like wax over fire
(By sexual union)
Will no more indulge in it,
When wisdom dawns;
To those who have attained Wisdom of Void
The liquid silver no exit knows.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-838-Third-Tantra-19.-Yoga-with-Sexual-Partner.mp3',
    elaborationEnglish: `His body, which in sexual union milts like wax on fire, will no more indulge in it when wisdom dawns. They who have attained the wisdom of Space will know no exit of the liquid silver.`,
    elaborationTamil: `: மூலாதாரத்திலிருந்து சுவாதிட்டானம் வழியாக காமாக்கினியை புருவ நடுவுக்கு கொண்டு சென்று அங்குள்ள சிவனை அறிந்த பின் அனலின் முன் மெழுகு உருகுவது போன்று சாதகர்க்கு உடம்பு ஜோதியாய் மாறிவிடும். ஜோதியாய் ஆன பின் புருவ நடுவைத் தாண்டி தலைக்கு மேல் பெருவெளியை அறிந்தவர்களுக்கு உடல் உலகியலில் வீழ்வது இல்லை.`,
  },
  {
    id: 840, tantraId: 3, verseNumber: 839,
    tamil: `வௌியை அறிந்து வௌியி னடுவே
ஔியை அறியி நுளிமுறி யாமே
தௌிவை அறிந்து செழுநந்தி யாலே
வௌியை அறிந்தனன் மேலறி யேனே`,
    transliteration: `vauiyai aṟintu vauiyi ṉaṭuvē
auiyai aṟiyi nuḷimuṟi yāmē
tauivai aṟintu ceḻunanti yālē
vauiyai aṟintaṉaṉ mēlaṟi yēṉē`,
    english: `839: Vision of Void in Pariyanga Yoga
When You know the Void
And the light in that Void
Your mind shall be strong as a chistle of bronze;
After having tasted of the nectar
I saw the Void
With goodly Nandi guiding;
Beyond, I knew not.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-839-Third-Tantra-19.-Yoga-with-Sexual-Partner.mp3',
    elaborationEnglish: `When the yogi knows the Space and the light in the Space, then the mind shall become strong as bronze. The vision of the Space comes after tasting of the nectar through the kechari yoga with the guidance of Nandi.`,
    elaborationTamil: `பரவெளியாகிய ஆகாயத்தை அறிந்து அதன் நடுவில் உள்ள அருள் ஒளியை உணர்ந்து அதில் விளங்குகின்ற அருளொளியையும் அவ்வொளியால் தெளிவான மெய்ப்பொருளையும் குரு நந்தி பெருமான் அருளால் உணர்ந்தேன். பரியாங்க யோகத்தில் இதற்கு மேல் அறியத் தக்கது ஒன்று இருப்பதாக எனக்குத் தெரியவில்லை.`,
  },
  {
    id: 841, tantraId: 3, verseNumber: 840,
    tamil: `மேலாந் தலத்தில் விரிந்தவ ராரெனின்
மாலாந் திசைமுகன் மாநந்தி யாயவர்
நாலா நிலத்தி நடுவான வப்பொருள்
மேலா யுரைத்தனர் மின்னிடை யாளுக்கே`,
    transliteration: `mēlān talattil virintava rāreṉiṉ
mālān ticaimukaṉ mānanti yāyavar
nālā nilatti naṭuvāṉa vapporuḷ
mēlā yuraittaṉar miṉṉiṭai yāḷukkē`,
    english: `840: Pariyanga Yoga was Expounded by Sadasiva to Sakti
Who are those that rank high above?
Mal, Brahma and Nandi (Rudra) art they;
In the Fourth is that Sadasiva,
Who to the slender-waisted Sakti
This expounded.`,
    elaborationTamil: `: இல்லறத்தில் இருப்பவர்களில் பரியாங்க யோகத்தின் மூலமாக அனைத்தும் இறைவன் ஒருவனே என்ற உணர்வைப் பெற்றிருந்தவர்கள் யாரவது உள்ளார்களா என்றால் திருமால், பிரம்மா, உருத்திரன், நந்தி, சிவகணங்கள் இவர்கள் எல்லாம் துய தலைவனாகிய சிவனை உணர்ந்து அவனே பரம்பொருள் என்று தங்களது துணைவியருக்கு உணர்த்தினர்.`,
  },
  {
    id: 842, tantraId: 3, verseNumber: 841,
    tamil: `மின்னிடை யாளுமின் னாளனுங் கூட்டத்துப்
பொன்னிடை வட்டத்தின் உள்ளே புகப்பெய்து
தன்னொடு தன்னை தலைப்பெய்ய வல்லாரேன்
மண்ணிடைப் பல்லூழி வாழலு மாமே`,
    transliteration: `miṉṉiṭai yāḷumiṉ ṉāḷaṉuṅ kūṭṭattup
poṉṉiṭai vaṭṭattiṉ uḷḷē pukappeytu
taṉṉoṭu taṉṉai talaippeyya vallārēṉ
maṇṇiṭaip pallūḻi vāḻalu māmē`,
    english: `841: Immortality for Those Who Unite in Sivasakti in Cranium
If you can get to Sakti and Siva
Inside the Golden Circle within (Cranium)
And then join them in union,
You may live on earth
A million, trillion years.`,
    elaborationTamil: `: பரியாங்க யோகத்தின் மூலம் மின்னல் போன்ற இடையை உடைய சக்தியையும் அவளை ஆள்பவனாகிய சிவனையும் அவர்கள் கூட்டத்துடன் பொன்னொளி கொண்ட ஆகாயத்தில் நிலை பெறும்படி செய்து அக்கூட்டத்தில் யோகி ஆன்மாவாகிய தன்னையும் பார்த்தால் இவ்வுலகத்தில் நெடுங்காலம் வாழ்வார்.`,
  },
  {
    id: 843, tantraId: 3, verseNumber: 842,
    tamil: `வாங்க லிறுதலை வாங்கலில் வாங்கிய
வீங்க வலிக்கும் விரகறி வாரில்லை
வீங்க வலிக்கும் விரகறி வாளரும்
ஓங்கிய தன்னை உதம்பண்ணி னாரே`,
    transliteration: `vāṅka liṟutulai vāṅkalil vāṅkiya
vīṅka valikkum virakaṟi vārillai
vīṅka valikkum virakaṟi vāḷarum
ōṅkiya taṉṉai utampaṇṇi ṉārē`,
    english: `842: Yogis Offered Themselves Entire to God
Inhaling, exhaling and retaining the breath inhaled
—None knows its technique of control
And those of skill who know it
Offered themselves to Lord entire.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-842-Third-Tantra-19.-Yoga-with-Sexual-Partner-2.mp3',
    elaborationTamil: `துணைவி பெற்றுக்கொள்ளும் துணைவனின் சுக்கிலத்தை வெளியே நீக்காமல் பரியங்க யோகத்தின் மூலம் உள்வாங்கிக் கொள்ளும் முறையில் சுக்கிலத்தை உடம்பினுள் ஆற்றலாய் மாற்றுகின்ற வழியை அறிகின்றவர் ஒருவரும் இல்லை. அவ்வழியை அறிந்தவர் இறைவனை அடையும் வழியை அறிந்தவராவார்.`,
  },
  {
    id: 844, tantraId: 3, verseNumber: 843,
    tamil: `உதமறிந் தங்கே ஒருசுழிப் பட்டாற்
கதமறிந் தங்கே கபாலங் கறுக்கும்
இதமறிந் தென்றும் இருப்பாள் ஒருத்தி
பதமறிந் தும்முளே பார்க்கடிந் தாளே`,
    transliteration: `utamaṟin taṅkē orucuḻip paṭṭāṟ
katamaṟin taṅkē kapālaṅ kaṟukkum
itamaṟin teṉṟum iruppāḷ orutti
patamaṟin tummuḷē pārkkaṭin tāḷē`,
    english: `843: Yoga Dispels Worldly Longings
Knowing the way of self-oblation,
If they get into the Mystic Circle
Of Siva and Sakti,
They reach the True Way;
And dark their hair turns
In youthfulness eternal,
And the One Sakti will inward abide;
In due accord
Dispelling worldly longings all.`,
    elaborationEnglish: `The yogi who reaches the circle of Siva and Sakti will. despise all worldly longings. That Sakti is seated with Siva on the lotus above. That lotus knows neither land nor water; no stalk; no roof. Yet that lotus blossoms.`,
    elaborationTamil: `: போகத்தை அனுபவிக்கத் தகுதியான வழியை அறிந்து அதை நன்கு பயின்றால் தலையிலுள்ள உரோமம் கறுக்கும் சாதகருக்கு தேவையான நன்மை கருதி சக்தியும் அவனை அறிந்து செயல் புரிவாள். சாதகரின் காலத்தை அறிந்து அவரின் உணர்வில் உள்ள உலகியல் எண்ணத்தை போக்கி அருள்வாள்.`,
  },
  {
    id: 845, tantraId: 3, verseNumber: 844,
    tamil: `பாரில்லை நீரில்லை பங்கயம் ஒன்றுண்டு
தாரில்லை வேரில்லை தாமரை பூத்தது
ஊரில்லை காணும் ஔியது ஒன்றுண்டு
கீழில்லை மேலில்லை கேள்வியிற் பூவே`,
    transliteration: `pārillai nīrillai paṅkayam oṉṟuṇṭu
tārillai vērillai tāmarai pūttatu
ūrillai kāṇum auiyatu oṉṟuṇṭu
kīḻillai mēlillai kēḷviyiṟ pūvē`,
    english: `844: Lotus Cranial
There is a lotus
That neither land nor water knows;
No stalk, no root, the lotus blossomed yet!
City there was none; yet Light there is one!
Neither above nor below is a flower, none had heard of.`,
    elaborationEnglish: `There is a city above; there is a light above; but no habitation. The flower that has "neither the above nor the below" is a flower none has heard of. The lotus is in Hinduism a symbol of many things, here of the cranium.`,
    elaborationTamil: `: தலை உச்சியில் ஆயிரம் இதழ்த் தாமரை ஒன்று உண்டு. அது ஞான வெளியில் இருப்பதால் அங்கு நிலமோ நீரோ இல்லை. இந்தத்தாமரை வேர் இல்லாமல் மலர்ந்தே உள்ளது. அதனால் அதற்கு மொட்டும் இல்லை. அது ஒளியால் நிரம்பி உள்ளது. ஒளி எங்கும் பரவி இருப்பதால் அதற்கு குறிப்பிட்ட இடத்தில் தான் இருக்கும் என்று இல்லை. ஓளிக்கு காரணம் இந்த தாமரையே என்றாலும் அதற்கு அடியும் இல்லை நுனியும் இல்லை.`,
  },
  {
    id: 846, tantraId: 3, verseNumber: 845,
    tamil: `உடலிற் கிடந்த வுறுதிக் குடிநீர்க்
கடலிற் சிறுகிணற் றேற்றமிட் டாலொக்கும்
உடலில் ஒருவழி ஒன்றுக் கிறைக்கில்
நடலைப் படாதுயிர் நாடலு மாமே`,
    transliteration: `uṭaliṟ kiṭanta vuṟutik kuṭinīrk
kaṭaliṟ ciṟukiṇaṟ ṟēṟṟamiṭ ṭālokkum
uṭalil oruvaḻi oṉṟuk kiṟaikkil
naṭalaip paṭātuyir nāṭalu māmē`,
    english: `845: Effect of Urine Therapy in Yoga
The urinary liquid within the body
Is unto a picot of small well;
Dipped into sea vast
If that is fed once a day
In way appropriate,
Life will know distress none;
Well may you seek it.`,
    elaborationEnglish: `The practice is referred to in Hatha Yoga Pradipika, pp.82-96, as quoted in Theos Bernard’s ‘‘Hatha Yoga,” pp.71:72; “In the doctrine of. the sect of Kapalikas, the ‘amaroli’ is the drinking of the cool mid-stream leaving the first, as it is a mixture of too much bile, and the last which is useless. He who drinks amari, snuffs it daily, practises ‘vajroli’ is called practising amaroli.’’ Auri (Tamil) is with amari (Sanskrit), meaning deathlessness.

For a controversy on this practice see Weekly of India,’’ July 24, 1977, p.24. The Prime Minister of India, Sri Morarji Desai, recently revealed that he practises this with good effect.`,
    elaborationTamil: `குடிக்க முடியாத உப்பு நீரைக் கொண்ட கடலுக்கு அருகே ஒரு சிறு கிணறு தோண்டி ஏற்றம் இறைத்தால் சுத்தமான குடிநீர் வருவதைப் போலவே உயிர்களின் உடல் கழிவு உப்புக்கள் நிறைந்த சிறுநீருக்கு அருகிலேயே ஆற்றல் மிக்க அமுரி நீர் இருக்கிறது. அதை சிறுநீருடன் கலந்து வெளியேற்றி வீணாக்காமல் மேல் நோக்கி சுழுமுனை நாடிவழியே எடுத்துச் சென்றால் என்றும் அழியாமல் உயிர் நிலைத்து நிற்கும்.`,
  },
  {
    id: 847, tantraId: 3, verseNumber: 846,
    tamil: `தௌிதரும் இந்தச் சிவநீர் பருகில்
ஔிதரு மோராண்டில் ஊனமொன் றில்லை
வளியுறும் எட்டின் மனமும் ஒடுங்குங்
களிதருங் காயங் கனகம தாமே`,
    transliteration: `tauitarum intac civanīr parukil
auitaru mōrāṇṭil ūṉamoṉ ṟillai
vaḷiyuṟum eṭṭiṉ maṉamum oṭuṅkuṅ
kaḷitaruṅ kāyaṅ kaṉakama tāmē`,
    english: `846: Goodly Effects of Amuri Dharana
If this divine water clear is inside taken
The body glows in a year;
No harm befalls it;
Prana control will realised be;
The mind will center in Letter "A" (Pranava)
And will uplifted be
And the body into gold will turned be.`,
    elaborationEnglish: `Mantra 846 & 850 - Nandi called it the hero's recipe, heaven's liquor, and Sakti's potion. It is a medicine of radiant light. If taken in the way appropriate, it helps prana control and thought concentration. The body will turn golden and the mind will become uplifted.`,
    elaborationTamil: `: தெளிவைத் தரும் இந்த சிவநீரான அமுரி நீரை பருகினால் ஓரு வருட காலத்தில் அறிவு மிக தெளிவாகும். உடலில் உள்ள நோய் இளைப்பு முதலிய அனைத்து குறைகளும் நீங்கும். இந்த நீர் மூச்சுக்காற்றுடன் கலந்து உடலில் மேலே ஏறுவதை எட்டு ஆண்டுகள் பயிற்சி செய்தால் மனம் கீழ் செல்லாமல் எப்போதும் மேலேயே நிற்கும் அதனால் மன ஒருமை உண்டாகும். சிவ இன்பத்திற்குரிய இவ்உடம்பு பொன் போல அழகு பெற்று விளங்கும்.`,
  },
  {
    id: 848, tantraId: 3, verseNumber: 847,
    tamil: `நூறு மிளகு நுகருஞ் சிவத்தினீர்
மாறும் இதற்கு மருந்தில்லை மாந்தர்கள்
தேறில் இதனைத் தௌியுச்சி கப்பிடின்
மாறும் இதற்கு மறுமயி ராமே`,
    transliteration: `nūṟu miḷaku nukaruñ civattiṉīr
māṟum itaṟku maruntillai māntarkaḷ
tēṟil itaṉait tauiyucci kappiṭiṉ
māṟum itaṟku maṟumayi rāmē`,
    english: `847: Consume 100--Pepper Measure (drops) a Day
Drink of this divine-water
A hundred pepper measure
No medicine beyond this, know men;
But rub it clear on crest of head
Your greying vanishes away
And fresh black hair shoots forth.`,
    elaborationEnglish: `If a hundred pepper measures of this ‘“‘divine water’ (presumably a pepper measure is a drop) are drunk everyday, the body requires no other medicine. If it is rubbed on the crown of the head, grey hair vanishes and fresh black hair shoots forth.`,
    elaborationTamil: `நூறு மிளகு அளவு சிவ அமுரி நீரை மூச்சுக்காற்றோடு கலந்து அதனை சுழுமுனை நாடியின் உச்சித் துளைக்குக் கொண்டு சேர்த்தால் உடல் பொன் மேனியாக மாறி ஒளிபெற்றுத் திகழும். நரைகூடிய வெள்ளை முடிகளும் மிகவும் கருமையாக மாறும். யோகிக்கு இதை விட சிறந்த மருந்து வேறொன்றும் இல்லை.`,
  },
  {
    id: 849, tantraId: 3, verseNumber: 848,
    tamil: `கரையரு கேநின்ற கானல் உவரி
வரைவரை என்பர் மதியிலா மாந்தர்
நுரைதிரை நீக்கி நுகரவல் லார்க்கு
நரைதிரை மாறு நமனுமங் கில்லையே`,
    transliteration: `karaiyaru kēniṉṟa kāṉal uvari
varaivarai eṉpar matiyilā māntar
nuraitirai nīkki nukaraval lārkku
naraitirai māṟu namaṉumaṅ killaiyē`,
    english: `848: Only the Ignorant Dissuade the Practice
The water on the banks of body
Is unto a mirage on the sea
Away, Away, from it--thus they say
The men who know not truth;
They who can drink the midstream
Rid of foam and wave
That arises first and last,
Will immortal be;
And all greying and wrinkling disappears.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-848-Third-Tantra-20.-Yoga-of-Semen.mp3',
    elaborationEnglish: `Urine, "the water on the banks fo the body of the body is like a mirage on the sea." Thus say those who do not know the truth. They who can drink the midstream of their urine, rid of foam and wave, omitting the first and last portions, will become immortal.`,
    elaborationTamil: `: கடற்கரையின் அருகே சேரும் அலைகளின் நுரைகலந்த உப்புநீர் எதற்கும் உதவாது அதை ஒதுக்கிவிட வேண்டும் என்று அறிவில்லாத மனிதர்கள் கூறுவார்கள். ஆனால் அந்த அலைகளின் நுரைகலந்த உப்புநீரிலிந்து நுரையையும் அழுக்கையும் நீக்கிவிட்டு சுத்தமான உப்பாக்கி அதை உணவில் கலந்து சுவையோடு உண்ணத் தெரியும் அறிவுள்ள மனிதர்கள் வீணாக்க மாட்டார்கள். அதுபோலவே உயிர்களின் உடலின் கழிவு உப்புக்கள் நிறைந்த சிறுநீர் எதற்கும் பயன்படாது அதை வெளியேற்றிவிடு என்பவர்கள் அறிவில்லாத மனிதர்கள். அந்த உப்புக்கள் நிறைந்த சிறுநீர்ப் பைக்கு அருகிலேயே இருக்கும் சுக்கிலத்தை அடி வயிற்று நெருப்பால் சுத்தமாக்கி சுழுமுனை நாடி வழியே மேலேற்றிச் சென்று சகஸ்ரதளத்தில் சேர்க்கும் வழியறியந்த அறிவுள்ள யோகியர் அதை வீணாக்காமல் செய்தால் அவர்களின் நரை முடிகள் கருத்து சுருங்கிய தோல்கள் இளைமை பெற்று முதுமையை வென்று என்றும் இறப்பில்லாமல் பேரின்பத்தில் வாழ்வார்கள்.`,
  },
  {
    id: 850, tantraId: 3, verseNumber: 849,
    tamil: `அளக நன்னுத லாயோ ரதிசயங்
களவு காயங் கலந்தஇந் நீரிலே
மிளகு நெல்லியும் மஞ்சளும் வேம்பிடில்
இளகும் மேனி இருளுங் கபாலமே`,
    transliteration: `aḷaka naṉṉuta lāyō raticayaṅ
kaḷavu kāyaṅ kalantain nīrilē
miḷaku nelliyum mañcaḷum vēmpiṭil
iḷakum mēṉi iruḷuṅ kapālamē`,
    english: `849: Effect of Mixing Ingredients
Oh! damsel of flowing tresses and slender forehead!
Hear you a miracle this!
In this Water hidden in the body
Mix pepper, amla, turmeric, and neem
Soft will your body be;
And dark thine hair on head.`,
    elaborationEnglish: `If it is mixed with certain ingredients like pepper, amla, turmeric and neem, the body becomes miraculously soft.`,
    elaborationTamil: `: அழகிய கூந்தலை உடையவளே ஒரு அதிசயம் உள்ளது. இந்த உடலில் மறைவாக உள்ள அமுரி நீர் உடலில் மேலே சென்று சிரத்தை அடையும் போது மிளகு, நெல்லி, மஞ்சள், வேப்பம் பருப்பு இவற்றைக் கலந்து நனறாக அரைத்துத் தலையில் தேய்த்துக் குளித்தால் உடல் மேன்மை அடையும். தலை மயிர் கறுப்பாக ஆகும்.`,
  },
  {
    id: 851, tantraId: 3, verseNumber: 850,
    tamil: `வீர மருந்தென்றும் விண்ணோர் மருந்தென்றும்
நாரி மருந்தென்றும் நந்தி அருள்செய்தான்
ஆதி மருந்தென் றறிவார் அகலிடஞ்
சோதி மருந்திது சொல்லவொண் ணாதே`,
    transliteration: `vīra marunteṉṟum viṇṇōr marunteṉṟum
nāri marunteṉṟum nanti aruḷceytāṉ
āti marunteṉ ṟaṟivār akaliṭañ
cōti maruntitu collavoṇ ṇātē`,
    english: `850: Greatness of Amuri Dharana
He the Nandi called it: the Hero's recipe, Heaven's exlixir, and Sakti's potion
Some know it as the Medicament Primus
It is specific that is of radiant light
Hard to describe to world at large.`,
    elaborationTamil: `உயிர்களின் உடலிலுள்ள சிவ நீரான அமுரி நீரை வீரியத்தால் உண்டாகும் வீர மருந்து என்றும் தேவர்கள் பருகும் அமிர்தம் என்றும் மங்கையருடனான போகத்திற்கு உதவும் மருந்து என்றும் குருவாகிய இறைவன் அருளிக் கூறினார். அனைத்திற்கும் தலையான முதல் மருந்து இதுவே என்று யோகியர்கள் அறிவார்கள். அப்படி அறிந்தவர்களின் உள்ளுக்குள் ஜோதி மயமாக இருக்கும் இந்த பெருமை மிக்க மருந்தின் அருமை பெருமைகளை வார்த்தைகளால் விவரித்து சொல்ல முடியாது.`,
  },
  {
    id: 852, tantraId: 3, verseNumber: 851,
    tamil: `எய்து மதிக்கலை சூக்கத்தி லேறியே
எய்துவ தூலம் இருவகைப் பக்கத்துள்
எய்துங் கலைபோல ஏறி இறங்குமாந்
துய்யது சூக்கத்து தூலத்த காயமே`,
    transliteration: `eytu matikkalai cūkkatti lēṟiyē
eytuva tūlam iruvakaip pakkattuḷ
eytuṅ kalaipōla ēṟi iṟaṅkumān
tuyyatu cūkkattu tūlatta kāyamē`,
    english: `851: When Breath Turns Subtle
When Prana ascends to Moon's Kala
It turns subtle (Sukshma)
The two breaths through Ida and Pingala run gross;
They rise and fall unto the kalas that wax and wane;
Pure is that Sukshma (Subtle)
Gross is that runs in the body.`,
    elaborationEnglish: `The Prana that we breathe, ida and pingala, is gross. It rises and falls like the moon that waxes and wanes. But when this prana, ziter the practice of kechari mudra, ascends to the mivon's kala, it becomes sukshma or subtle. The subtle prana is pure.

The 16 Kalas of the Moon are the 16 phases New Moon andthe Full Moon are each counted as two); the 12 Kalas of the Sun are the months; Agni as such has no Kalas, but the ten Agnis are apparently treated as 10 Kalas. s. mG wy cr`,
    elaborationTamil: `: எண்ணங்கள் தூல உடலில் இருந்து சூட்சும உடலுக்கு ஏறியும் சூட்சும உடலில் இருந்து தூல உடலுக்கு இறங்கியும் வரும். இது சந்திரனின் வளர்பிறை தேய்பிறை போன்று இருக்கும். சூட்சும உடல் தூய்மை அடைவதற்கு ஏற்ப தூல உடம்பும் தூய்மை அடையும்.`,
  },
  {
    id: 853, tantraId: 3, verseNumber: 852,
    tamil: `ஆகின்ற சந்திரன் சூரியன் அங்கியுள்
ஆகின்ற ஈரெட்டா டாறிரண் டீரைந்துள்
ஏகின்ற வக்கலை யெல்லா மிடைவழி
ஆகின்ற யோகி அறிந்த அறிவே`,
    transliteration: `ākiṉṟa cantiraṉ cūriyaṉ aṅkiyuḷ
ākiṉṟa īreṭṭā ṭāṟiraṇ ṭīraintuḷ
ēkiṉṟa vakkalai yellā miṭaivaḻi
ākiṉṟa yōki aṟinta aṟivē`,
    english: `852: Yogi Experiences Kalas of Moon, Sun and Fire
Sixteen the Kalas of Moon
Twelve of the Sun
And Ten of the Fire
The Yogi experiences them all
In the upward journey of Prana through Sushumna
And all that becomes his mystic knowledge.`,
    elaborationEnglish: `In that journey in kundalini yoga, the ten kalas of fire are first absorbed by the 12 kalas of the sun. Together the kalas of the sun and fire are absorbed in the 16 kalas of the moo.. Thus the kalas of three different origins merge into one. Tuto them finally merge the four kalas of kundalini in the cranium top. There in the sahasrara, the yogi pays homage at the Feet of the Lord. Those who have learned to merge the kalas of fire and sun in the kalas of the moon, verily become. masters of themselves.`,
    elaborationTamil: `உயிர்களின் உடலில் இருக்கும் சந்திர மண்டலத்திற்கு (இடதுபக்க மூச்சுக்காற்று) பதினாறு கலைகள் உண்டு. சூரிய மண்டலத்திற்கு (வலது பக்க மூச்சுக்காற்று) பன்னிரண்டு கலைகள் உண்டு. அக்கினி மண்டலத்திற்கு (குண்டலினி) பத்துக் கலைகள் உள்ளன. இடது பக்க முச்சுக்காற்றையும் வலது பக்க முச்சுக்காற்றையும் உபயோகித்து அகயோகப் பயிற்சியால் நடுநாடியாகிய சுழுமுனையின் வழியே குண்டலினியை மேல்நோக்கிச் செலுத்துவது எப்படி என்பதை யோகியர்கள் நன்றாக அறிந்து கொண்டிருக்கிறார்கள். குறிப்பு: கலைகள் என்பது என்னவெனில் மூச்சுக்காற்று எப்படி தானாக உள்ளேயும் வெளியேயும் எப்படி சென்று வருகின்றது என்பதை குறிப்பதாகும்.`,
  },
  {
    id: 854, tantraId: 3, verseNumber: 853,
    tamil: `ஆறாத தாங்கலை ஆதித்தன் சந்திரன்
நாறா நலங்கினார் ஞாலங் கவர்க்கொளப்
பேறாங் கலைமுற்றும் பெருங்கால் ஈரெட்டு
மாறாக் கதிர்க்கொள்ளு மற்றங்கி கூடவே`,
    transliteration: `āṟāta tāṅkalai ātittaṉ cantiraṉ
nāṟā nalaṅkiṉār ñālaṅ kavarkkoḷap
pēṟāṅ kalaimuṟṟum peruṅkāl īreṭṭu
māṟāk katirkkoḷḷu maṟṟaṅki kūṭavē`,
    english: `853: Kalas of Fire Merge into Sun, Which in Turn Merge into
Those of Moon
The twelve Kalas of Sun
Absorb Kalas ten of Fire
Together are they absorbed
In Sixteen Kalas of Moon;
Those who have thus learnee to merge
In Moon's Kala
Verily become Masters of Earth,
All Kalas entire filled.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-853-Third-Tantra-21.-Yoga-of-Moon-Region.mp3',
    elaborationEnglish: `Mantras 853 - 857 - In that journey in kundalini yoga, the ten kalas of fire are first absorbed by the 12 kalas of the sun. Together the kalas of the sun and fire are absorbed in the 16 kalas of the moon. Thus the kalas of three different origins merge into one. Into them finally merge the four kalas of kundalini in the cranium top. There in sahasrara, the yogi pays homage at the Feet of the Lord. Those who have learned to merge the kalas of fire and sun in the kalas of the moon, verily become masters of themselves.`,
    elaborationTamil: `: சூரியன் பன்னிரண்டு கலைகளோடு சந்திரனது பதினாறு கலைகளையும் அக்கினியோடு சேர்க்க அறிந்து கொண்டவர் உலகம் விரும்பும் பேறுகளை அடைவர்.`,
  },
  {
    id: 855, tantraId: 3, verseNumber: 854,
    tamil: `பத்தும் இரண்டும் பகலோன் உயர்க்கலை
பத்தினொ டாறும் உயர்க்கலை பான்மதி
ஒத்தநல் அங்கிய தெட்டெட் டுயர்க்கலை
அத்திறன் நின்றமை ஆய்ந்துகொள் வீரே`,
    transliteration: `pattum iraṇṭum pakalōṉ uyarkkalai
pattiṉo ṭāṟum uyarkkalai pāṉmati
ottanal aṅkiya teṭṭeṭ ṭuyarkkalai
attiṟaṉ niṉṟamai āyntukoḷ vīrē`,
    english: `854: Kalas of Sun, Moon and Fire Enumerated
Twelve the Kalas of Sun
Sixteen the Kalas of Moon
Ten the Kalas of Fire
Thus are the Kalas in number,
Know you well and true.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-854-Third-Tantra-21.-Yoga-of-Moon-Region.mp3',
    elaborationTamil: `சூரியகலை உயர்ந்து செல்லும் அளவு பன்னிரண்டு ஆகும். சந்திரக்கலை செல்லும் அளவு பதினாறு ஆகும். சூரியகலையும் சந்திரகலையும் சேர்ந்து குண்டலினியாகிய அக்கினியை உயர்த்திச் செல்வது மொத்தம் அறுபத்து நான்கு ஆகும். இவை மூன்றையும் குருநாதரின் வழிகாட்டுதலில் யோக முறைப்படி செய்து ஆராய்ந்து அறிந்து கொள்ளுங்கள்.`,
  },
  {
    id: 856, tantraId: 3, verseNumber: 855,
    tamil: `எட்டெட் டனலின் கலையாகும் ஈராறுட்
சுட்டப் படுங்கதி ரோனுக்குஞ் சூழ்கலை
கட்டப் படுமீ ரெட்டா மதிக்கலை
ஒட்டப் படாஇவை ஒன்றோடொன் றாவே`,
    transliteration: `eṭṭeṭ ṭaṉiliṉ kalaiyākum īrāṟuṭ
cuṭṭap paṭuṅkati rōṉukkuñ cūḻkalai
kaṭṭap paṭumī reṭṭā matikkalai
oṭṭap paṭāivai oṉṟōṭoṉ ṟāvē`,
    english: `855: The Disparate Kalas Merge into One
Ten the Kalas of Fire
Twelve of the scorching Sun
Sixteen that emanate from Moon;
All these Kalas which alike are not,
Into oneness merge.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-855-Third-Tantra-21.-Yoga-of-Moon-Region.mp3',
    elaborationTamil: `அக்கினிக் கலைகள் அறுபது நான்கு. சூரியனின் கலைகள் பன்னிரண்டு. சந்திரனின் கலைகள் பதினாறு இவை அனைத்தும் ஒன்றை ஒன்று சூழ்ந்து இருந்தாலும் தனித்தனியாகவே விளங்கிக் கொண்டிருக்கும்.`,
  },
  {
    id: 857, tantraId: 3, verseNumber: 856,
    tamil: `எட்டெட்டும் ஈராறும் ஈரெட்டுந் தீக்கதிர்
சுட்டிட்ட சோமனில் தோன்றுங் கலையெனக்
கட்டப் படுந்தார கைகதிர் நாலுள
கட்டிட்ட தொண்ணூற்றொ டாறுங் கலாதியே`,
    transliteration: `eṭṭeṭṭum īrāṟum īreṭṭun tīkkatir
cuṭṭiṭṭa cōmaṉil tōṉṟuṅ kalaiyeṉak
kaṭṭap paṭuntāra kaikatir nāluḷa
kaṭṭiṭṭa toṇṇūṟṟo ṭāṟuṅ kalātiyē`,
    english: `856: Kalas Enumerated in Total, Including Those of Jiva and
Tattva
Ten, twelve and sixteen
Are Kalas that appear in Agni, Sun and Moon;
And Four art Kalas of the Star (Jiva)
The fettering Tattvas six and ninety too
Are Kalas to count.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-856-Third-Tantra-21.-Yoga-of-Moon-Region.mp3',
    elaborationTamil: `: அக்கினிக்கு அறுபத்து நான்கு சூரியனுக்குப் பன்னிரண்டு சந்திரனுக்குப் பதினாறு என கலைகள் 92 ம் சேர்ந்துள்ள மூலாதாரத்தில் நட்சத்திரக் கலை நான்கு உள்ளன. இவ்வாறு மூலாதாரத்துடன் இணைக்கப்பட்டுள்ள கலைகள் மொத்தம் தொண்ணூற்றாறு ஆகும்.`,
  },
  {
    id: 858, tantraId: 3, verseNumber: 857,
    tamil: `எல்லாக் கலையும் இடைபிங் கலைநடுச்
சொல்லா நடுநாடி யூடே தொடர்மூலஞ்
செல்லா எழுப்பிச் சிரத்துடன் சேர்தலால்
நல்லோர் திருவடி நண்ணிநிற் போரே`,
    transliteration: `ellāk kalaiyum iṭaipiṅ kalainaṭuc
collā naṭunāṭi yūṭē toṭarmūlañ
cellā eḻuppic cirattuṭaṉ cērtalāl
nallōr tiruvaṭi naṇṇiniṟ pōrē`,
    english: `857: Rouse All Kalas and Reach God
All Kalas from the Left and Right Nadis
Pass through the Central Nadi;
Kindle the Kundalini Fire in Muladhara;
They reach the Cranium at top,
To pay homage at Feet of the Goodly One.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-857-Third-Tantra-21.-Yoga-of-Moon-Region.mp3',
    elaborationTamil: `: சந்திர மண்டலமாகிய இடகலை மற்றும் சூரிய மண்டலமாகிய பிங்கலை நாடிகளின் வழியே உள்ளிழுக்கப்படும் எல்லா மூச்சுக்காற்றும் இயல்பாகவே கீழ் நோக்கி செல்லக்கூடியவை. அவற்றைத் தடுத்து நடுவில் இருக்கும் சுழுமுனை நாடி வழியே அவற்றை மேல் நோக்கி எடுத்துச் சென்று உச்சந்தலையில் உள்ள சகஸ்ரதளத்தில் சேர்த்து இறைவனின் மேல் எண்ணத்தை வைத்து இருக்கும் யோகியர்கள் எப்போதும் இறப்பின்றி இறைவனின் திருவடிகளையே பற்றிக்கொண்டு பேரின்பத்தில் திளைத்து இருப்பார்கள்.`,
  },
  {
    id: 859, tantraId: 3, verseNumber: 858,
    tamil: `அங்கியிற் சின்னக் கதிரிரண் டாட்டத்துத்
தங்கிய தாரகை யாகுஞ் சசிபானு
வங்கிய தாரகை யாகும் பரையொளி
தங்கு நவசக்ர மாகுந் தரணிக்கே`,
    transliteration: `aṅkiyiṟ ciṉṉak katiriraṇ ṭāṭṭattut
taṅkiya tārakai yākuñ cacipāṉu
vaṅkiya tārakai yākum paraiyoḷi
taṅku navacakra mākun taraṇikkē`,
    english: `858: Nine Kalas of Nava Chakra
Two each of Kalas,
Fire, Star, Moon and Sun,
And Kala of Parai
Who is unto a Star
Together are the nine beams of Parai`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-858-Third-Tantra-21.-Yoga-of-Moon-Region.mp3',
    elaborationEnglish: `The four kalas of kundalini belong to the 'energy-body star'. Two kalas each for the star, fire, moon and sun, and one kala of Parai who is unto a star, together form the nine lights of Parai in the navel chakra.`,
    elaborationTamil: `சந்திர யோகத்தில் இடகலை பிங்கலை நாடிகளின் வழியே உள்ளிழுக்கப்படும் மூச்சுக்காற்று மூலாதாரத்தில் உள்ள நெருப்பின் மேல் பட்டு மூலாதாரத்தின் அசைவினால் தோன்றும் ஒளிக்கீற்றுக்கள் சூரியன் சந்திரன் என்னும் இரண்டு நட்சத்திரங்களாக மாறுகிறது. இந்த நட்சத்திரங்களாக மாறிய ஒளிக்கீற்றைகளை மூச்சுக்காற்றுடன் உடலில் உள்ள ஏழு சக்கரங்களையும் தாண்டி எட்டாவது சக்கரமாகிய துவாதசந்தவெளியையும் தாண்டி ஒன்பதாவது பரவெளியில் கொண்டு சென்று அங்கு உள்ள பரவொளியுடன் கலந்து விட்டால் உலகத்தை இயக்கும் இறைவனது பேரொளியின் அம்சமாக இருக்கலாம். குறிப்பு: அண்டத்தில் உள்ளது பிண்டத்திலும் உள்ளது எனும் சொல்லுக்கு ஏற்ப உலகம் என்று நாம் அழைக்கும் சூரிய குடும்பத்தில் இருக்கின்ற ஒன்பது கிரகங்களும் இன்னும் பல நட்சத்திரங்களும் நமது உடலிலேயே இருக்கின்றன. இவை அனைத்தையும் ஒளி உருவமாக இருந்து இயக்கும் இறைசக்தியே நமது உடலில் சகஸ்ரதளத்தில் ஜோதி வடிவாக தங்கி இருக்கின்றது. இதை நாம் யோகப் பயிற்சியின் மூலம் இயக்க ஆரம்பித்தால் உலகங்கள் அனைத்தையும் இயக்கும் இறை சக்தியாகவே நாமும் மாறிவிடுவோம்.`,
  },
  {
    id: 860, tantraId: 3, verseNumber: 859,
    tamil: `தரணி சலங்கனல் கால்தக்க வானம்
அரணிய பானு அருந்திங்கள் அங்கி
முரணிய தாரகை முன்னிய ஒன்பான்
பிரணவ மாகும் பெருநெறி தானே`,
    transliteration: `taraṇi calaṅkaṉal kāltakka vāṉam
araṇiya pāṉu aruntiṅkaḷ aṅki
muraṇiya tārakai muṉṉiya oṉpāṉ
piraṇava mākum peruneṟi tāṉē`,
    english: `859: Constituents of Pranava
Earth, Water, Fire, Air, Space
Sun, Moon, Agni and Star
These nine constitute Pranava
The Way that is Great.`,
    elaborationTamil: `உயிர்களின் உடலில் இருக்கும் நிலம், நீர், நெருப்பு, காற்று, ஆகாயம் ஆகிய பஞ்ச பூத அம்சங்கள் இடகலை பிங்கலை வழியே சுழன்று கொண்டிருக்கும் சூடான மற்றும் குளிர்ந்த மூச்சுக்காற்று மூலாதாரத்திலுள்ள குண்டலினியிலிருந்து தோன்றும் ஒளிக்கீற்றுக்கள் என மொத்தம் ஒன்பது வகையான அம்சங்களும் பிரணவமாகிய இறை சக்தியின் அம்சங்களாகும். இவற்றை உபயோகித்து செய்யும் யோகமே இறைவனை அடைவதற்கு உதவும் மிகப்பெரிய மார்க்கமாகும்.`,
  },
  {
    id: 861, tantraId: 3, verseNumber: 860,
    tamil: `தாரகை மின்னுஞ் சசிதேயும் பக்கத்துத்
தாரகை மின்னா சசிவளர் பக்கத்துத்
தாரகை பூவிற் சகலத்தி யோனிகள்
தாரகைத் தாரகை தானாஞ் சொரூபமே`,
    transliteration: `tārakai miṉṉuñ cacitēyum pakkattut
tārakai miṉṉā cacivaḷar pakkattut
tārakai pūviṟ cakalatti yōṉikaḷ
tārakait tārakai tāṉāṉy corūpamē`,
    english: `860: Transformation into Star of Stars
When moon wanes, the stars twinkle bright
When moon waxes, they do not
Unto stars (innumerable) are Jivas of universe,
Unto Star of Stars is the Divine Manifestness.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-860-Third-Tantra-21.-Yoga-of-Moon-Region.mp3',
    elaborationEnglish: `When moon waxes, they do not Unto stars (innumerable) are Jivas of universe, Unto Star of Stars is the Divine Manifestation.`,
    elaborationTamil: `வானத்து நட்சத்திரங்கள் சந்திரனின் தேய்பிறை சமயத்தில் பிரகாசமாக மின்னும். அதுவே சந்திரனின் வளர்பிறை சமயத்தில் நட்சத்திரங்களின் ஒளி சந்திரனின் பிரகாசமான ஒளியில் மங்கிவிடும். அதுபோலவே சந்திர யோகம் செய்கின்ற யோகியர்கள் தமது மூச்சுக்காற்றை கீழ் நோக்கி எடுத்துச் சென்று குண்டலினியில் கலக்கும்போது அதில் பிரகாசமான ஒளிக்கீற்றுக்கள் உருவாகும். அதை ஒளிக்கீற்றை மேல் நோக்கி சகஸ்ரதளத்திற்கு எடுத்துச் செல்லும்போது சகஸ்ரதள ஜோதியின் பிரகாசமான ஒளியில் மங்கிவிடும். சந்திர யோகம் செய்து குண்டலினியில் உருவாகும் ஒளிக்கீற்றுக்களை சகஸ்ரதள ஜோதியில் சென்று சேர்க்கும் யோகியர்களிடம் பிரகாசிக்கும் ஜோதி உலகத்தில் அனைத்தையும் உருவாக்கும் பேரொளி ஜோதியான இறைவனின் சொரூபம் (ஒளி உருவம்) ஆகும்.`,
  },
  {
    id: 862, tantraId: 3, verseNumber: 861,
    tamil: `முற்பதி னைஞ்சின் முளைத்துப் பெருத்திடும்
பிற்பதி னைஞ்சிற் பெருத்துச் சிறுத்திடும்
அப்பதி னைஞ்சும் அறியவல் லார்க்கட்குச்
செப்பரி யாங்கழல் சேர்தலு மாமே`,
    transliteration: `muṟpati ṉaiñciṉ muḷaittup peruttiṭum
piṟpati ṉaiñciṟ peruttuc ciṟuttiṭum
appati ṉaiñcum aṟiyaval lārkkaṭkuc
ceppari yāṅkaḻal cērtalu māmē`,
    english: `861: Mystery of Fifteen Kalas of Moon
In the waxing fortnight Kalas shoot and expand
In the waning fortnight they shrink and small become;
They who can know the mystery of Kalas Fifteen
May well reach the Feet of Lord
Of glory indescribable.`,
    elaborationEnglish: `1) Out of sixteen, fifteen are the eternal kalas of the moon. One kala remains there always. That kala is nothing but chit itself. We call Her, Tripurasundari. It is understcod by this, that in order to rouse the kundalini, one should practise in the lunar fortnight alone, and not in the solar one.’’ — Commentary of verse 32 of Anandalahari, as quoted in “The Serpent Power’’ by Sir John Woodroffe, pp.234-235.`,
    elaborationTamil: `: சந்திரன் முதல் பதினைந்து நாட்கள் சிறிது சிறிதாக வளர்ந்து பெளர்ணமியில் முழுமை அடையும். அதன்பிறகு பதினைந்து நாட்கள் சிறிது சிறிதாகத் தேய்ந்து அமாவாசையில் முழுமையாக மறைந்துவிடும். அதுபோலவே சந்திர யோகம் செய்யும் யோகியருக்கு குண்டலினியில் ஒளிக்கீற்றுக்கள் தோன்றி பெரிய நட்சத்திரமாக வளர்ந்து பின்பு சகஸ்ரதளத்தில் சென்று முழுமையாக மறைந்துவிடும். இந்த பதினைந்து நிலைகளையும் உணர்ந்து அறிந்துகொள்ளக்கூடிய யோகியர்கள் வார்த்தைகளில் கூறிவிடமுடியாத மகத்துவத்தைக் கொண்ட இறைவனின் திருவடிகளை தமக்குள் கண்டு அடைவார்கள்.`,
  },
  {
    id: 863, tantraId: 3, verseNumber: 862,
    tamil: `அங்கி எழுப்பி யருங்கதிர் ஊட்டத்துத்
தங்குஞ் சசியால் தாமம்ஐந் தைந்தாகிப்
பொங்கிய தாரகை யாம்புலன் போக்கறத்
திங்கள் கதிரங்கி சேர்க்கின்ற யோகமே`,
    transliteration: `aṅki eḻuppi yaruṅkatir ūṭṭattut
taṅkuñ caciyāl tāmamain taintākip
poṅkiya tārakai yāmpulaṉ pōkkaṟat
tiṅkaḷ katiraṅki cērkkiṉṟa yōkamē`,
    english: `862: Chandra Yoga Described
Rouse Kalas of Fire,
Merge them in Sun,
Merge all in Moon,
Merge Jiva Star
Of senses and sense organs rid,
That verily is Chandra yoga.`,
    elaborationEnglish: `This in short, is chandra yoga. Through kundalini yoga rouse the kalas of fire. Merge there in the kalas of the sun. Merge them in the moon's kalas. Finally merge them all in jiva, of senses and sense organs rid. This verse describes the Kalas and how they should be handled.`,
    elaborationTamil: `அகயோகம் மூலம் மூலாதாரத்திலுள்ள குண்டலினியை எழுப்பிய பிறகு அந்த அக்கினியை அருமையான சூரிய மண்டலத்தில் தங்குகின்ற சந்திர கலையாகிய வாயுவோடு சேர்த்து நட்சத்திர ஒளியாக மாறுவதற்கு பத்து நாட்களும் அதன் பிறகு நட்சத்திரமாக மாறிய ஒளிக்கீற்றுக்களை சந்திர சூரிய அக்கினி மண்டலங்களோடு சேர்த்து மனதை ஒருமுகப்படுத்தி ஐந்து புலன்களையும் அதனதன் வழியில் செல்ல விடாமல் தடுத்து இறைவனின் மேல் எண்ணங்களை வைத்து சகஸ்ரதளத்தை அடைவதற்கு ஐந்து நாட்களும் ஆக மொத்தம் பதினைந்து நாட்கள் பாடல் #861 இல் கூறியுள்ளபடி உணர்ந்து அறிந்து கொண்டு செய்வதே சந்திர யோகமாகும்.`,
  },
  {
    id: 864, tantraId: 3, verseNumber: 863,
    tamil: `ஒன்றிய ஈரெண் கலையும் உடலுற
நின்றது கண்டும் நினைக்கிலர் நீதர்கள்
கன்றிய காலன் கருத்துழி வைத்தபின்
சென்றதில் வீழ்வர் திகைப்பொழி யாரே`,
    transliteration: `oṉṟiya īreṇ kalaiyum uṭaluṟa
niṉṟatu kaṇṭum niṉaikkilar nītarkaḷ
kaṉṟiya kālaṉ karuttuḻi vaittapiṉ
ceṉṟatil vīḻvar tikaippoḻi yārē`,
    english: `863: Know Sixteen Kalas Within Body
They know not the Kalas sixteen within the body
They seek not to reach them
The despicable men!
When Death his trap lays
Then there they fall,
Forever bewildered.`,
    elaborationTamil: `வானத்திலிருக்கின்ற வளர் பிறை தேய் பிறை சந்திர மாற்றங்களின் பதினாறு கலைகளும் உயிர்களின் உடலுக்குள்ளேயும் இருப்பதைக் கண்டுகொண்ட பிறகும் அதை வைத்துக்கொண்டு இறைவனை நினைத்து சந்திரயோகம் செய்து பிறவி இல்லாத பெருவாழ்வை அடைய முயற்சி செய்யாத கீழான குணமுடையவர்களை கண்ட எமன் இனி இவர்கள் வாழ்ந்து என்ன பயன் என்று அவர்கள் இறந்து அடுத்த பிறவி எடுக்கும்படி மரணப்பிடியில் சிக்க வைக்கிறார். கீழான குணமுடையவர்களும் அதில் சென்று வீழ்ந்து மீண்டும் பிறவிச் சுழற்சியில் மாட்டிக்கொண்டு எப்படி தப்பிப்பது என்று திகைத்துக்கொண்டு இருக்கிறார்கள்.`,
  },
  {
    id: 865, tantraId: 3, verseNumber: 864,
    tamil: `அங்கி மதிகூட வாகும் கதிரொளி
அங்கி கதிர்க்கூட வாகு மதியொளி
அங்கி சசிகதிர் கூடவத் தாரகை
தங்கி யதுவே சகலமு மாமே`,
    transliteration: `aṅki matikūṭa vākum katiroḷi
aṅki katirkkūṭa vāku matiyoḷi
aṅki cacikatir kūṭavat tārakai
taṅki yatuvē cakalamu māmē`,
    english: `864: In Chandra Yoga Jiva-Star Merges in Siva
When Fire-Kalas pass through Moon's Nadi
The Sun receives them;
Kalas of Fire and Sun together merge in Moon's Kala;
When Kundalini Fire unites in Siva
The Kalas of the Star merge;
And the Jiva who resides in Star,
Becomes life all.`,
    elaborationTamil: `குண்டலினியாகிய மூலாக்கினியில் சந்திர கலையாகிய இடகலை மூச்சுக்காற்று இணையும்போது அது சூரிய ஒளிக்கீற்றைப் பெறுகிறது. மூலாக்கினியில் சூரிய கலையாகிய பிங்கலை மூச்சுக்காற்று இணையும் போது அது சந்திர ஒளிக்கீற்றைப் பெறுகிறது. இப்படி மாறிப் பெற்ற இரண்டு ஒளிக்கீற்றுக்களும் சுழுமுனையில் ஒன்றாக இணையும் போது அது நட்சத்திர மண்டலங்களாக மாறுகின்றது. இந்த நட்சத்திர மண்டலங்கள் உயிர்களின் உடலிலுள்ள ஒன்பது மண்டலங்களையும் தாண்டி பரவெளியில் இறை சக்தியோடு ஒன்றினையும் போது அனைத்துமாகிய இறைவனாகவே யோகியர்கள் ஆகிவிடுகின்றனர்.`,
  },
  {
    id: 866, tantraId: 3, verseNumber: 865,
    tamil: `ஈராறு பெண்கலை எண்ணிரண் டாண்கலை
பேராமற் புக்குப் பிடித்துக் கொடுவந்து
நேராகத் தோன்றும் நெருப்புற வேபெய்யில்
ஆராத ஆனந்தம் ஆனந்த மானதே`,
    transliteration: `īrāṟu peṇkalai eṇṇiraṇ ṭāṇkalai
pērāmaṟ pukkup piṭittuk koṭuvantu
nērākat tōṉṟum neruppuṟa vēpeyyil
ārāta āṉantam āṉanta māṉatē`,
    english: `865: Chandra Yoga in Kundalini Yoga
Twelve the female Kalas (of Sun)
Sixteen the male Kalas (of Moon)
Seize them both sitting unmoved,
And consign them to the Kundalini Fire,
In that yoga wells up the ecstasy beyond recount.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-865-Third-Tantra-21.-Yoga-of-Moon-Region.mp3',
    elaborationTamil: `: பன்னிரண்டு கலைகள் கொண்ட சூரியக்கலை பெண் கலை ஆகும். பதினாறு கலைகள் கொண்ட சந்திரக்கலை ஆண் கலை ஆகும், இரண்டு கலைகளையும் பயிற்சியினால் மூலாக்னியில் ஒரு நிலைப்படுத்தினால் அங்கு தெவிட்டாத திருவடி இன்பம் கிடைக்கும்.`,
  },
  {
    id: 867, tantraId: 3, verseNumber: 866,
    tamil: `காணும் பரிதியின் காலை இடத்திட்டு
மாணும் மதியதன் காலை வலத்திட்டுப்
பேணியே யிவ்வாறு பிழையாமற் செய்வீரேல்
ஆணி கலங்காதவ் வாயிரத் தாண்டே`,
    transliteration: `kāṇum paritiyiṉ kālai iṭattiṭṭu
māṇum matiyataṉ kālai valattiṭṭup
pēṇiyē yivvāṟu piḻaiyāmaṟ ceyvīrēl
āṇi kalaṅkātav vāyirat tāṇṭē`,
    english: `866: Practice Nadi Suddhi
Course breath running in Sun's Nadi in the right
To the Moon's Nadi in the left,
And vice versa,
If you can do this erring not
You may live a thousand years
This body well preserved be.`,
    elaborationTamil: `: குரு கற்பித்த வழியில் தவறில்லாமல் சூரியக் கலையில் வலது பக்க மூக்கு வழியாக இயங்கும் மூச்சுக்காற்றை இடது பக்கம் இயங்கச் செய்தும் சந்திரக் கலையில் இடது பக்க மூக்கு வழியாக இயங்கும் மூச்சுக்காற்றை வலது பக்கம் இயங்கச் செய்து வந்தால் ஆயிரம் ஆண்டுகள் சென்றாலும் உடல் தளர்ச்சி அடையாமல் இருக்கும்.`,
  },
  {
    id: 868, tantraId: 3, verseNumber: 867,
    tamil: `பாலிக்கும் நெஞ்சம் பறையோசை ஒன்பதில்
ஆலிக்கும் அங்கே அமரர் பராபரன்
மேலைக்கு முன்னே விளக்கொளி யாய்நிற்குங்
காலைக்குச் சங்கு கதிரவன் தானே`,
    transliteration: `pālikkum neñcam paṟaiyōcai oṉpatil
ālikkum aṅkē amarar parāparaṉ
mēlaikku muṉṉē viḷakkoḷi yāyniṟkuṅ
kālaikkuc caṅku katiravaṉ tāṉē`,
    english: `867: The Aspirant Hears Nada Sound in the Ninth Center
In that Ninth Center,
Your heart shall resound
To the triumphant beatings of Sound Divine;
There Lord that is Supreme of Celestials all,
Is in exaltation high,
There you shall stand as Starry Light;
And the Sun shall blow the conch
To announce your arrival.`,
    elaborationEnglish: `Mantras 867 & 868 - As this merger takes place in the ninth centre of the moon's sphere, the yogi's heart responds in high exultation to the triumphant beatings of the divine sound of nada. The juva stands there as a stellar light. There, traversing beyond the sun and moon, he meets the Lord.`,
    elaborationTamil: `சந்திர யோகம் செய்யும் யோகியர்கள் தமது குண்டலினி சக்தியை ஆறு ஆதார சக்கரங்கள் ஏழாவது சகஸ்ரதளம் எட்டாவது துவாதசாந்த வெளியைத் தாண்டிய ஒன்பதாவதான பரவெளியில் வீற்றிருக்கும் இறை சக்தியோடு கலக்கும்போது அந்த இறை சக்தியைத் தமக்குள் தேவ நாதமாக கேட்டு உணர்ந்து அந்த இறை சக்தியிலேயே மனதை ஒருமுகப்படுத்தி தியானத்தைத் தொடர்ந்தால் விரைவில் பரவெளியையும் தாண்டிய அண்டசராசரங்களில் இருந்து கொண்டு அனைத்து உலகங்களுக்கும் தினமும் காலையில் தோன்றி ஒளியைக் கொடுக்கின்ற மாபெரும் சூரியனைப் போன்ற இறைவனின் பேரொளி உருவத்தை தூய்மையான சங்கைப் போன்ற வெண்மை நிற ஜோதியாகத் தமக்குள் தரிசனம் செய்வார்கள்.`,
  },
  {
    id: 869, tantraId: 3, verseNumber: 868,
    tamil: `கதிரவன் சந்திரன் காலம் அளக்கும்
பொதிரவ னுள்ளே பொழிமழை நிற்கும்
அதிரவ னண்டப் புறஞ்சென் றடர்ப்ப
எதிரவ நீச நிடமது தானே`,
    transliteration: `katiravaṉ cantiraṉ kālam aḷakkum
potirava ṉuḷḷē poḻimaḻai niṟkum
atirava ṉaṇṭap puṟañceṉ ṟaṭarppa
etirava nīca niṭamatu tāṉē`,
    english: `868: Beyond Nada Sphere is Lord
The Sun and Moon but measure Time;
Into him who has great become,
Rains the nectar of Grace;
When he travels beyond the spheres
And knocks,
There he meets Lord
In His very Abode.`,
    elaborationTamil: `சூரிய கலை சந்திர கலை ஆகிய இரண்டு நாடிகளும் உயிர்களின் உடலுக்கான காலத்தை அளக்கும் கருவிகளாகும். சூரிய கலை சந்திர கலை இரண்டும் தனித் தனியாக இருக்கும் வரை உயிர்கள் காலத்துக்கு கட்டுப் பட்டவையாகும். சந்திர யோகத்தால் இரு நாடிகளையும் மாற்றி சுழுமுனை வழியே மேலே கொண்டு செல்கிற யோகியின் உடலில் சூரிய கலையும் சந்திர கலையும் சகஸ்ரதளத்தில் ஒன்று சேரும் போது அங்கே அமுதம் விளையும். அங்கிருந்து தலைக்கு மேல் உள்ள துவாதசாந்த வெளியில் இறை சக்தியை ஒலியாக கேட்டு அதையும் தாண்டிய பரவெளியில் இறை சக்தியை ஒளியாக தரிசித்து அதையும் தாண்டிய அண்ட வெளியே சிவனது இருப்பிடம் என்பதை உணரலாம்.`,
  },
  {
    id: 870, tantraId: 3, verseNumber: 869,
    tamil: `உந்திக் கமலத் துதித்தெழுஞ் சோதியை
அந்திக்கு மந்திர மாரும் அறிகிலார்
அந்திக்கு மந்திர மாரும் அறிந்தபின்
தந்தைக்கு முன்னே மகன்பிறந் தானே`,
    transliteration: `untik kamalat tutitteḻuñ cōtiyai
antikku mantira mārum aṟikilār
antikku mantira mārum aṟintapiṉ
tantaikku muṉṉē makaṉpiṟan tāṉē`,
    english: `869: Knowledge of Aum Takes to Lord's Presence
The Light of Aum that rises in the navel-lotus
Is Mantra Finite;
None know this;
When they know that mantra secret,
Then is the Son that is Jiva
In the presence of Father that is God.`,
    elaborationEnglish: `There is the light of Aum that rises from the navel lotus. It is the mantra finite and if that mantra secret is known, the son, that is jiva, stands before the Father, that is God.`,
    elaborationTamil: `மூலாதாரத்தில் தூங்கிக் கொண்டிருக்கும் குண்டலினியை எழுப்பி ஜோதியாக மணிப்பூரக சக்கரத்தில் செயல்பட வைத்து ஒவ்வொரு சக்கரங்களாக மேலே எழுப்பிச் சென்று சகஸ்ரதளத்தில் சேர்க்கும் சந்திரயோகப் பயிற்சிக்கு உறுதுணையாக இருக்கும் பிரணவ மந்திரத்தை யாரும் அறிந்திருக்கவில்லை. அந்த மந்திரத்தை குருவின் மூலம் அறிந்து உணர்ந்த யோகியர்கள் அனைத்துலகிற்கும் தந்தையான இறைவனுக்கு முன்பு மகனாக இருக்கும் தங்களின் ஆத்ம ஜோதியை தரிசிப்பார்கள்.`,
  },
  {
    id: 871, tantraId: 3, verseNumber: 870,
    tamil: `ஊதியம் ஏதும் அறியார் உரைப்பினும்
ஓதியும் ஏதும் அறியாத ஊமர்கள்
ஆதியும் அந்தமும் அந்திக்க வல்லீரேல்
வேதியன் அங்கே வௌிப்படுந் தானே`,
    transliteration: `ūtiyam ētum aṟiyār uraippiṉum
ōtiyum ētum aṟiyāta ūmarkaḷ
ātiyum antamum antikka vallīrēl
vētiyaṉ aṅkē vauippaṭun tāṉē`,
    english: `870: Greatness of Kundalini Yoga
It profits not to tell,
They listen not to advice,
They are deaf-mutes;
If you but learn how to merge,
The Primal Kundalini with the Being Finite
The Holy One will before you appear.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-870-Third-Tantra-21.-Yoga-of-Moon-Region.mp3',
    elaborationEnglish: `The Primal Kundalini with the Being Finite The Holy One will before you appear.`,
    elaborationTamil: `நூல்களைக் கற்றாலும் அவற்றின் பயனை சிறிதும் உணராத அறிவிலிகள் நூல்களின் பயனை மற்றவர்கள் கூறினாலும் உணரமாட்டார்கள். குண்டலி சத்தியை அது தோன்றுகின்ற மணிபூரகத்தில் உணர்தலோடு மட்டுமில்லாது அதன் முடிவாகிய சந்திர மண்டலத்தில் சேர்த்தால் அங்கு சிவன் வெளிபடுவான்.`,
  },
  {
    id: 872, tantraId: 3, verseNumber: 871,
    tamil: `பாம்பு மதியைத் தினலுறும் பாம்பினைத்
தங்கு கதிரையஞ் சோதித் தனலுறும்
பாம்பு மதியும் பகைதீர்த் துடங்கொளீஇ
நீண்-கல் கொடானே நெடுந்தகை யானே`,
    transliteration: `pāmpu matiyait tiṉaluṟum pāmpiṉait
taṅku katiraiyañ cōtit taṉaluṟum
pāmpu matiyum pakaitīrt tuṭaṅkoḷīi
nīṇ-kal koṭāṉē neṭuntakai yāṉē`,
    english: `871: Merging Moon's Kalas in Kundalini
The Kundalini serpent consumes Kalas of Moon
The Fire consumes Kalas of Sun, too
If you can resolve the conflict of Serpent and Moon
Merging the Kalas of Moon in Kundalini
The Lord will leave you not, ever ever.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-871-Third-Tantra-21.-Yoga-of-Moon-Region.mp3',
    elaborationEnglish: `She (kundalini) runs to sahasrara and bites the chandra…Then nectar begins to flow - vide commentary on verse 32 of Anandalahiri, as quoted in "The Serpent Power" by Sir John Woodroffe, p.235. The kundalini that moves up "devours the moon." Let not the yogi sleep until the serpent throws it out. When it throws it out, the mind becomes luminous as the full moon. Then the yogi may sleep.`,
    elaborationTamil: `சந்திர யோகப் பயிற்சியின் மூலம் குண்டலினியாகிய பாம்பை உறக்கத்திலிருந்து எழுப்பிவிட்டால் அது நித்தமும் சந்திர கலையை உண்டு அதுவும் பத்தாதென்று சூடாகிய தீங்கைக் கொடுக்கும் சூரிய கலையையும் உண்டு வளரும். குண்டலினிக்கு இரையாக கலைகள் இருப்பதால் இரண்டும் பகையாளிகள் போல இருந்தாலும் சந்திர யோகப் பயிற்சியினால் குண்டலினியை ஒவ்வொரு மண்டலமாக மேலேற்றிச் சென்று கடைசியில் ஒன்பதாவதான பரவெளியில் இருக்கும் சந்திர மண்டலத்தோடு ஒன்று சேர்த்துவிட்டால் குண்டலினியும் கலைகளும் தமது பகையைத் தீர்த்து ஒன்றாகிவிடும். அதன் பிறகு மாபெரும் கருணையாளனான இறைவன் யோகியை விட்டு என்றும் நீங்காமல் இருப்பான். உட்கருத்து: சந்திர யோகப் பயிற்சியில் மூச்சுக்காற்றின் மூலமே குண்டலினியை வளர்த்து ஏழு சக்கரங்கள் எட்டாவது துவாதசாந்த வெளியைத் தாண்டிய ஒன்பதாவது பரவெளியில் இருக்கும் சந்திர மண்டலத்தோடு கலந்துவிட்டால் அதன் பிறகு யோகியர்களுக்கு மூச்சுக்காற்றோ உணவோ தேவையின்றி எவ்வளவு காலமும் இறைவனுடன் பேரின்பத்தில் இருக்கலாம்.`,
  },
  {
    id: 873, tantraId: 3, verseNumber: 872,
    tamil: `அயின்றது வீழ்வள வுந்துயில் இன்றிப்
பயின்ற சசிவீழ் பொழுதில் துயின்று
நயந்தரு பூரணை உள்ள நடத்தி
வியந்தரு பூரணை மேவுன்ய் சசியே`,
    transliteration: `ayiṉṟatu vīḻvaḷa vuntuyil iṉṟip
payiṉṟa cacivīḻ poḻutil tuyiṉṟu
nayantaru pūraṇai uḷḷa naṭatti
viyantaru pūraṇai mēvuṉy caciyē`,
    english: `872: Kundalini Devours and Throws Out Moon
The Kundalini that moved up
Devours Moon
Sleep not until it throws it out;
When the Moon comes out
Then may you take your sleep;
Your mind shall then luminous as full moon be
Then the Mystic Moon inside
Will shed its dazzling Kalas full.`,
    elaborationTamil: `குண்டலினியுடன் மேலே சென்ற சந்திரன் தலையின் மீது நிற்கும் குண்டலினியை உறங்காமல் கவனிக்கும். அதன் பின் கீழே சந்திரன் இறங்கிய போது உறங்கும். நன்மையைத் தரும் ஒளியை மனத்தில் இருக்கச் செய்தால் அப்போது முழுமையாகத் சந்திரக்கலை யோகியிடம் பொருந்தும்.`,
  },
  {
    id: 874, tantraId: 3, verseNumber: 873,
    tamil: `சசியுதிக் குமஅள வுந்துயி இன்றிச்
சசியுதித் தானேல் தனதூண் அருந்திச்
சசிசரிக் கின்றள வுந்துயி லாமற்
சசிசரிப் பிங்கட்டன் கண்டுயில் கொண்டதே`,
    transliteration: `caciyutik kumaaḷa vuntuyi iṉṟic
caciyutit tāṉēl taṉatūṇ aruntic
cacicarik kiṉṟaḷa vuntuyi lāmaṟ
cacicarip piṅkaṭṭaṉ kaṇṭuyil koṇṭatē`,
    english: `873: Time for Sleeping and Eating When Moon is Devoured by
Kundalini
Sleep not until the Moon comes out;
Eat not until Moon rises;
Sleep not until Moon moves;
Sleep the Yogi may
When but the Moon moves.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-873-Third-Tantra-21.-Yoga-of-Moon-Region.mp3',
    elaborationEnglish: `1) This reminds us of a parallel of the Sastraic injunction not to sleep and eat when there is a lunar (or solar) eclipse; when Rahu, the serpent, is said to devour the moon (or sun) for a time.`,
    elaborationTamil: `சந்திர யோகத்தில் குண்டலினியைச் சந்திர மண்டலத்தில் சேர்க்கும் வரையில் சோர்வு இன்றி யோகத்தில் முயன்று அதைச் சேர்த்தபின் உள் நாக்கில் பெருகும் அமிர்தத்தைப் பருகி வேறு எதுவும் தேவையின்றி மூச்சுக்காற்று சந்திர கலை இயங்காமல் சூரிய கலை இயங்கும் பொழுது உறங்குதல் வேண்டும்.`,
  },
  {
    id: 875, tantraId: 3, verseNumber: 874,
    tamil: `ஊழி பிரியா திருக்கின்ற யோகிகள்
நாழிகை யாக நமனை அளப்பர்க்கள்
ஊழி முதலாய் உயர்வார் உலகினில்
தாழவல் லார்.க் இச் சசிவன்ன ராமே`,
    transliteration: `ūḻi piriyā tirukkiṉṟa yōkikaḷ
nāḻikai yāka namaṉai aḷapparkkaḷ
ūḻi mutalāy uyarvār ulakiṉil
tāḻaval lār.k ic cacivaṉṉa rāmē`,
    english: `874: By Chandra Yoga Death is Conquered
The Yogis who thus practise incessant
Conquer Death;
They will live in this world aeons beyond;
They are worthy of our obeisance,
They who, this Moon's Yoga in success practises.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-874-Third-Tantra-21.-Yoga-of-Moon-Region.mp3',
    elaborationEnglish: `Mantras 874 & 875 - The yogi who practises chandra yoga will conquer death. He visions the past, present and future and until the moon drops back from kundalini, time comes to a stop.`,
    elaborationTamil: `ஊழிக் காலங்கள் பல சென்றாலும் அழியாமல் உலகிலே வாழ்கின்ற யோகிகள் தாம் யோகத்தில் இருக்கின்ற நாழிகையையே தமது ஆயுளின் அளவுகோலாகக் கொண்டு எமனை எதிர்த்து நிற்பார்கள். ஆனால் சந்திர யோகத்தைப் பின்பற்றும் யோகியர்கள் ஊழிக்கு முதல்வனாய் உள்ள இறைவனே தாமாகி என்றும் இந்த உலகில் மீண்டும் வந்து பிறக்காத உயர் நிலையை அடைவார்கள்.`,
  },
  {
    id: 876, tantraId: 3, verseNumber: 875,
    tamil: `தண்மதி பானுச் சரிபூமி யேசென்று
மண்மதி காலங்கள் மூன்றும் வழிகண்டு
வெண்மதி தோன்றிய நாளில் விளைந்தபின்
தண்மதி வீழ்வள விற்கண மின்றே`,
    transliteration: `taṇmati pāṉuc caripūmi yēceṉṟu
maṇmati kālaṅkaḷ mūṉṟum vaḻikaṇṭu
veṇmati tōṉṟiya nāḷil viḷaintapiṉ
taṇmati vīḻvaḷa viṟkaṇa miṉṟē`,
    english: `875: The Yogi Sees Vision of Past, Present and Future
They traverse Spheres of Sun and Moon
And see vision of Past, Present and Future earth;
And in that Full Moon day the nectar ripens;
Until the Moon drops back from Kundalini,
Time stands to a stop.`,
    elaborationEnglish: `Compare Shelly in into eternity, where recorded time seems but a point.”’`,
    elaborationTamil: `குளிர்ந்த நிலவும் சூரியனும் சரிபாதியாக பூமிக்கு வெளிச்சத்தைக் கொடுத்து மண்ணுலகில் மூன்றுவித காலங்களையும் அறிந்து கொள்வதற்கு வழியாக இருக்கின்றன. அதுபோலவே உயிர்களின் உடலில் சந்திர கலையும் சூரிய கலையும் விண்ணுலகின் உண்மை ஞானத்தை அறிந்து கொள்வதற்கு வழியாக இருக்கின்றன. இவை இரண்டையும் கொண்டு சந்திர யோகத்தின் மூலம் குண்டலினியை மேலேற்றிச் சென்று சந்திர மண்டலத்தில் சேர்த்து இறை சக்தியாகிய தூய வெண்ணிற ஜோதியைத் தரிசித்து விட்டால் அளவில் குறைவின்றி குளிர்ந்த அமிர்தம் எப்போதும் கிடைத்துக் கொண்டே இருக்கும்.`,
  },
  {
    id: 877, tantraId: 3, verseNumber: 876,
    tamil: `வளர்க்கின்ற ஆதித்தன் தங்கலை யாறுந்
தளர்க்கின்ற சந்திரன் தங்கலை யாறு
மலர்ந்தெழு பன்னிரண் டங்குலம் ஓடி
அலர்ந்து விழுந்தமை யாரறி வாரே`,
    transliteration: `vaḷarkkiṉṟa ātittaṉ taṅkalai yāṟun
taḷarkkiṉṟa cantiraṉ taṅkalai yāṟu
malarnteḻu paṉṉiraṇ ṭaṅkulam ōṭi
alarntu viḻuntamai yāraṟi vārē`,
    english: `876: Moon Drops Out With 12 Kalas From Kundalini's Mouth
The waxing Kalas six of Sun
The waning Kalas six of Moon
Woke to life to twelve angula running
And then the Moon droped out
Who knows this!`,
    elaborationEnglish: `When the waxing kalas six of the sun, and the waning kalas six of the moon wake to life, twelve angulas running, that is the indication that the moon has dropped out of kundalini’s mouth. :`,
    elaborationTamil: `வளர்கின்ற சூரியக்கலை ஆறும் தேய்கின்ற சந்திரக்கலை ஆறும் மூச்சுக்காற்றாய் வழக்கமாக தொண்டைக்கு கீழே எட்டு அங்குலமும் சந்திர யோகப் பயிற்சியில் தொண்டைக்கு மேலே நான்கு அங்குலமும் ஓடி சகஸ்ரதளத்தில் சேர்ந்து மலர்ந்து பின் அங்கிருந்து உடலெங்கும் விரிந்து பரவும் யோக முறையை யாரும் அறியவில்லை.`,
  },
  {
    id: 878, tantraId: 3, verseNumber: 877,
    tamil: `ஆமுயிர்த் தேய்மதி நாளே யெனல்விந்து
போம்வழி எங்கணும் போகாது யோகிக்குக்
காமுற இன்மையிற் கட்டுண்ணு மூலத்தில்
ஓமதி யத்துள்விட் டுரையுணர் வாலே`,
    transliteration: `āmuyirt tēymati nāḷē yeṉalvintu
pōmvaḻi eṅkaṇum pōkātu yōkikkuk
kāmuṟa iṉmaiyiṟ kaṭṭuṇṇu mūlattil
ōmati yattuḷviṭ ṭuraiyuṇar vālē`,
    english: `877: He Conquers Bindu
If Yogi thus achieves this goal
In the day of Full Moon
The Yogi's semen flows not where it lists;
Devoid of passions, it firm collects in Muladhara;
Chanting Aum in heart's silentness,
He remains Pure, Awareness filled.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-877-Third-Tantra-21.-Yoga-of-Moon-Region.mp3',
    elaborationTamil: `சந்திர யோகத்தைச் செய்கின்ற யோகியர்கள் முழு நிலவு வருவதற்குள் தங்களது பயிற்சியை சரியாகச் செய்து முடித்துவிட்டால் அதன் பிறகு வரும் தேய்பிறை நாட்களில் அவர்களின் சுக்கிலம் வழக்கம் போல கீழிறங்கி எதன் மூலமும் வெளியேறிவிடாமல் காம எண்ணங்கள் சிறிதும் இன்றி மூலாதாரத்திலேயே கட்டுப்பட்டு நிற்கும். யோகியர்களும் மூச்சுக்காற்றை ஓங்கார மந்திரத்தோடு சேர்த்து சந்திர மண்டலத்தில் கலந்த பிறகு தமது எண்ணங்களை அதிலேயே நிலைக்க வைத்து அனைத்து உணர்வுகளையும் தாண்டிய நிலையில் இருப்பார்கள்.`,
  },
  {
    id: 879, tantraId: 3, verseNumber: 878,
    tamil: `வேறுறச் செங்கதிர் மெய்க்கலை யாறொடுஞ்
சூறுற நாங்குந் தொடர்ந்துற வேநிற்கும்
ஈறிலி நங்கலை யீரைந்தொ டேமதித்
தாறுட் கலையுள் அகலுவா வாமே`,
    transliteration: `vēṟuṟac ceṅkatir meykkalai yāṟoṭuñ
cūṟuṟa nāṅkun toṭarntuṟa vēniṟkum
īṟili naṅkalai yīrainto ṭēmatit
tāṟuṭ kalaiyuḷ akaluvā vāmē`,
    english: `878: The Emitted Moon has 16 Kalas Ultimately
To the Six waxing Kalas of the fiery Sun
Will be the Four Kalas of Fire
To these ten Kalas goodly
Will be the Six Kalas of Moon
Thus are they Kalas Sixteen
In the Full Moon emitted.`,
    elaborationEnglish: `Ultimately, the moon reappears, now with six waxing kalas of the sun, six kalas of the moon and four kalas of kundalini, thus making sixteen kalas in all, of the full moon.`,
    elaborationTamil: `குண்டலினியிலிருந்து வேர் பிடித்து மேலெழும்பும் செம்மையான கதிர்களைக் கொண்ட உண்மை ஞானத்தைக் கொடுக்கும் ஆறு சூரிய கலைகளோடு வெப்பத்தை கொடுக்கும் நான்கு அக்கினி கலைகள் கலந்து தொடர்ந்து வரும். அதனோடு ஈடு இணையில்லாத இறைவனை அடைய உதவும் பத்து நன்மை தரும் கலைகளோடு குளிர்ச்சியைக் கொடுக்கும் ஆறு சந்திர கலைகளும் கலந்து மொத்தம் 16 கலைகளும் ஒன்றாகச் சேர்ந்து சந்திர மண்டலத்தை அடையும் போது யோகியர்கள் அனைத்து உணர்வுகளையும் விட்டு விலகி இறைவனைப் பற்றி மட்டுமே எண்ணிக்கொண்டு இருக்கும் பேரானந்த நிலையை அடைவார்கள்.`,
  },
  {
    id: 880, tantraId: 3, verseNumber: 879,
    tamil: `உணர்விந்து சோணி உறவினன் வீசும்
புணர்விந்து வீசுங் கதிரிற் குறையில்
உணர்வும் உடம்பும் உவையொக்க நிற்கில்
உணர்வும் உடம்பும் ஒருகால் விடாவே`,
    transliteration: `uṇarvintu cōṇi uṟaviṉaṉ vīcum
puṇarvintu vīcuṅ katiriṟ kuṟaiyil
uṇarvum uṭampum uvaiyokka niṟkil
uṇarvum uṭampum orukāl viṭāvē`,
    english: `879: Sun's Kala in Sex Union
In the mingling of male semen and woman's fluid
Emits Sun's Kala,
If Sun's Kala is low, semen ejects quick;
When mind and body balanced stand
Never will they let semen flow.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-879-Third-Tantra-21.-Yoga-of-Moon-Region.mp3',
    elaborationTamil: `உணர்வுக்கு வாயிலாக உள்ள ஒளியும் ஒலியும் ஒன்றாக கலக்க சூரியக்கலையின் கதிர்கள் குறையுமானால் ஒளி தலைக்கு மேலே தோன்றும். ஒளியாகிய சூட்சும உடம்பும் உணர்வும் ஒன்றான பின் யோகிக்கு உடம்பு அழியாது.`,
  },
  {
    id: 881, tantraId: 3, verseNumber: 880,
    tamil: `விடாத மனம்பவ னத்தொடு மேவி
நடாவு சிவசங்கின் நாதங் கொளுவிக்
கடாவிடா ஐம்புலன் கட்டுண்ணும் வீடு
படாதன இன்பம் பருகார் அமுதமே`,
    transliteration: `viṭāta maṉampava ṉattoṭu mēvi
naṭāvu civacaṅkiṉ nātaṅ koḷuvik
kaṭāviṭā aimpulaṉ kaṭṭuṇṇum vīṭu
paṭātaṉa iṉpam parukār amutamē`,
    english: `880: Effects of Chandra Yoga
If with mind centered they course their breath,
In direction of Nada sound
That from Siva's Conch emanates,
The five senses that run blind
Will their restraint meet;
And the interminable bliss of delectable Nectar
Leaves them not ever.`,
    elaborationTamil: `தன் விருப்பத்திற்கு ஆடும் மனம் சந்திர யோகம் செய்யும் யோகியர்களுக்கு வசப்பட்டு மூச்சுக்காற்றோடு இணைந்து கொண்டு நடு நாடி வழியே மேலேறும் போது சகஸ்ரதளத்தில் இறை சப்தங்களின் உயர்ந்த சங்கொலி கேட்கும். மதம் பிடித்த யானை போல அலையும் ஐந்து புலன்களும் யோகியின் வசப்பட்டு அவர்களின் எண்ணத்திற்கு ஏற்ப உடலுக்குள் கட்டுப்பட்டு இயங்கும். எப்போதும் திகட்டிவிடாத பேரின்பத்தை கொடுக்கும் அமிர்தம் அவர்களின் உள்நாக்கில் ஊற அவர்கள் அதை எப்போதும் பருகிக் கொண்டே இருப்பார்கள்.`,
  },
  {
    id: 882, tantraId: 3, verseNumber: 881,
    tamil: `அமுதப் புனல்வரு மாற்றங் கரைமேற்
குமிழிக் குட்சுட ரைந்தையுங் கூட்டிச்
சமையத்தண் டோ ட்டித் தரிக்கவல் லார்க்கு
நமன் இல்லை நற்கலை நாள்இல்லை தானே`,
    transliteration: `amutap puṉalvaru māṟṟaṅ karaimēṟ
kumiḻik kuṭcuṭa raintaiyuṅ kūṭṭic
camaiyattaṇ ṭō ṭṭit tarikkaval lārkku
namaṉ illai naṟkalai nāḷillai tāṉē`,
    english: `881: Greatness of Chandra Yoga
On the banks of River
Where waters of Nectar flow
Course the Five Pranas
Through central Sushumna,
They who thus remain,
Death do not have;
Good their Kalas arr;
Time-bound they are not.`,
    elaborationTamil: `உடலில் புருவ மத்திக்குக் கீழே இருக்கும் எல்லைக் கோட்டைத் தாண்டி உள்நாக்கில் பொழியும் அமிர்தத்தோடு புருவ மத்திக்கு மேலே இருக்கின்ற அறிவு, ஆற்றல், ஓசை, ஒளி, உயிர் ஆகிய ஐந்து சுடர்களையும் ஒன்று படுத்தி அதனுடன் மூலாதாரத்திலிருந்து எழுப்பிய குண்டலினி சக்தியை நடு நாடியாகிய சுழுமுனையின் வழியே மேலேற்றிக் கொண்டு வந்து ஒன்றாகக் கலந்து அதிலேயே எண்ணங்களை வைத்து தியானத்தில் இருக்கக் கூடிய யோகியர்களுக்கு என்றும் இறப்பு இல்லை. அவர்களுக்கு ஆயுளின் மூச்சுக்காற்று அளவுகளும் நாள் கணக்குகளும் இல்லை.`,
  },
  {
    id: 883, tantraId: 3, verseNumber: 882,
    tamil: `உண்ணீ ரமுத முறுமூ றலைத்திறந்
தெண்ணீர் இணையடித் தாமரைக் கேசெலத்
தெண்ணீர்ச் சமாதி யமர்ந்துதீ ராநலங்
கண்ணாற் றொடேசென்று கால்வழி மாறுமே`,
    transliteration: `uṇṇī ramuta muṟumū ṟalaittiṟan
teṇṇīr iṇaiyaṭit tāmaraik kēcelat
teṇṇīrc camāti yamarntutī rānalaṅ
kaṇṇāṟ ṟoṭēceṉṟu kālvaḻi māṟumē`,
    english: `882: Alternating Breath to Samadhi End
Opening the springs where Nectar wells up
They walk toward the Lotus Feet cool as water;
Sitting in undisturbed Samadhi;
Coursing through the Spinal channel
They alter the breathing right and left.`,
    elaborationEnglish: `The yogi who continues opens up the springs of necter 2 walks to the Lotus Feet of the Lord that are cool as water. There he sits in undisturbed samadhi, coursing through the spina! channel and breathing through nadis right ‘and left in alternation.`,
    elaborationTamil: `சந்திர யோகம் புரியும் யோகியர்களே உங்களின் குண்டலினியை எழுப்பி சகஸ்ரதளத்தில் சேர்ப்பதன் மூலம் புருவ மத்தியில் இருக்கும் அமிர்தம் விளையும் ஊற்றைத் திறந்து எப்போதும் வற்றாத அமிர்தத்தைப் பருகுங்கள். அதன் பிறகு இறைவனின் ஈடுஇணையில்லாத தாமரை மலர் போன்ற திருவடிகளை மட்டுமே எண்ணிக்கொண்டு வேறு எதன் மீதும் எண்ணங்களை செலுத்தாமல் வெளிப்புற உலகத்தின் எதுவும் பாதிக்காத சமாதி நிலையில் அமர்ந்து ஞானக்கண் வழியே அனைத்தையும் கண்டு மூச்சுக்காற்றை வெளியிலிருந்து எடுத்துக் கொள்ளாமல் உள்ளுக்குள்ளேயே இயக்கத்தை மாற்றி எப்போதும் திகட்டாத பேரானந்தத்தில் திளைத்து இருங்கள்.`,
  },
  {
    id: 884, tantraId: 3, verseNumber: 883,
    tamil: `மாறு மதியும் மதித்திரு மாறின்றித்
தாறு படாமல் தண்டோ டே தலைப்படில்
ஊறு படாதுடல் வேண்டும் உபாயமும்
பாறு படாஇன்பம் பார்மிசை பொங்குமே`,
    transliteration: `māṟu matiyum matittiru māṟiṉṟit
tāṟu paṭāmal taṇṭō ṭē talaippaṭil
ūṟu paṭātuṭal vēṇṭum upāyamum
pāṟu paṭāiṉpam pārmicai poṅkumē`,
    english: `883: Benefits of Yoga
If breaths of Moon (Ida) and Sun (Pingala)
Course their way through Spinal channel unhindered,
Thine body imperishable shall be;
And abiding joys well up here below,
This the Way of Yoga True.`,
    elaborationEnglish: `Imperishable becomes his body and abiding his joy. This is the true way that chandra yoga leads to.`,
    elaborationTamil: `இடநாடி வழியாகவும் வலநாடி வழியாகவும் இயங்குகின்ற தம் இயல்பான மூச்சுக்காற்றிலிருந்து மாறுகின்ற சந்திர கலையும் சூரிய கலையும் யோகத்திற்குரிய முறையில் மாறுபடாமலும் தடை படாமலும் குறைவின்றி சீராக நடுநாடியான சுழுமுனையின் வழியே சென்று தலை உச்சியைத் தாண்டியுள்ள சந்திர மண்டலத்தை அடைந்தால் எதனாலும் பாதிக்கப்படாத அழியாத உடலை அடையும் வழியும் எப்போதும் திகட்டாமல் அளவின்றி பெருகும் பேரின்பமும் இந்த உலகத்திலேயே கிடைக்கும்.`,
  },
];
